internal static class StockUnits
{
    public static readonly string[] Units = new string[] { "g", "kg", "ml", "L", "pcs" };
}

internal static class UnitMath
{
    public enum UnitFamily { Mass, Volume, Count, Unknown }

    public static UnitFamily Family(string? unit)
    {
        if (string.IsNullOrWhiteSpace(unit)) return UnitFamily.Count;
        string u = unit.Trim().ToLowerInvariant();
        if (u == "g" || u == "gram" || u == "grams" || u == "kg" || u == "kilogram" || u == "kilograms")
            return UnitFamily.Mass;
        if (u == "ml" || u == "millilitre" || u == "millilitres" || u == "l" || u == "liter" || u == "litre" || u == "litres")
            return UnitFamily.Volume;
        if (u == "pcs" || u == "pc" || u == "piece" || u == "pieces" || u == "portion" || u == "portions")
            return UnitFamily.Count;
        return UnitFamily.Unknown;
    }

    public static decimal Factor(string? unit)
    {
        if (string.IsNullOrWhiteSpace(unit)) return 1m;
        string u = unit.Trim().ToLowerInvariant();
        if (u == "kg" || u == "kilogram" || u == "kilograms" || u == "l" || u == "liter" || u == "litre" || u == "litres")
            return 1000m;
        return 1m;
    }

    public static decimal? Convert(decimal qty, string? fromUnit, string? toUnit)
    {
        if (string.IsNullOrWhiteSpace(fromUnit) && string.IsNullOrWhiteSpace(toUnit)) return qty;
        if (string.Equals(fromUnit?.Trim(), toUnit?.Trim(), StringComparison.OrdinalIgnoreCase)) return qty;

        var fFrom = Family(fromUnit);
        var fTo = Family(toUnit);
        if (fFrom != fTo || fFrom == UnitFamily.Unknown) return null;

        decimal baseQty = qty * Factor(fromUnit);
        return baseQty / Factor(toUnit);
    }

    public static string Canonical(string? unit)
    {
        if (string.IsNullOrWhiteSpace(unit)) return "pcs";
        string u = unit.Trim().ToLowerInvariant();
        if (u == "g" || u == "gram" || u == "grams") return "g";
        if (u == "kg" || u == "kilogram" || u == "kilograms") return "kg";
        if (u == "ml" || u == "millilitre" || u == "millilitres") return "ml";
        if (u == "l" || u == "liter" || u == "litre" || u == "litres") return "L";
        return "pcs";
    }

    public static string[] CompatibleUnits(string? unit)
    {
        var fam = Family(unit);
        if (fam == UnitFamily.Mass) return new[] { "g", "kg" };
        if (fam == UnitFamily.Volume) return new[] { "ml", "L" };
        return new[] { "pcs" };
    }
}

