			SyncQueue = (File.Exists(syncQueueFile) ? (JsonSerializer.Deserialize<List<Sale>>(File.ReadAllText(syncQueueFile), JsonOptions) ?? new List<Sale>()) : new List<Sale>());
			if (File.Exists(countersFile))
			{
				Dictionary<string, int> dictionary = JsonSerializer.Deserialize<Dictionary<string, int>>(File.ReadAllText(countersFile), JsonOptions);
				if (dictionary != null && dictionary.TryGetValue("Order", out var value) && dictionary.TryGetValue("Bill", out var value2) && dictionary.TryGetValue("Payment", out var value3) && dictionary.TryGetValue("Date", out var value4))
				{
					CounterDate = DateTime.Now.ToString("yyyyMMdd");
					int num = int.Parse(CounterDate);
					if (value4 == num)
					{
						OrderCounter = value;
						BillCounter = value2;
						PaymentCounter = value3;
						return;
					}
				}
			}
			CounterDate = DateTime.Now.ToString("yyyyMMdd");
			OrderCounter = 0;
			BillCounter = 0;
			PaymentCounter = 0;
