		public void MigrateCatalogImages()
		{
			if (!RegisterSettings.IsMainPc)
			{
				return;
			}
			bool changedProducts = false;
			bool changedFamilies = false;
			try
			{
				Directory.CreateDirectory(CatalogImageStore.Root);
				var prods = Products.ToList();
				for (int i = 0; i < prods.Count; i++)
				{
					var p = prods[i];
					if (!string.IsNullOrWhiteSpace(p.ImagePath))
					{
						var resolved = CatalogImageStore.Resolve(p.ImagePath);
						if (resolved != null)
						{
							var fileName = Path.GetFileName(resolved);
							var targetPath = Path.Combine(CatalogImageStore.Root, fileName);
							if (!File.Exists(targetPath) && File.Exists(resolved))
							{
								File.Copy(resolved, targetPath, overwrite: true);
							}
							if (p.ImagePath != fileName)
							{
								prods[i] = p with { ImagePath = fileName };
								changedProducts = true;
							}
						}
					}
				}
				if (changedProducts)
				{
					SaveProducts(prods);
				}
				var fams = Families.ToList();
				for (int i = 0; i < fams.Count; i++)
				{
					var f = fams[i];
					if (!string.IsNullOrWhiteSpace(f.ImagePath))
					{
						var resolved = CatalogImageStore.Resolve(f.ImagePath);
						if (resolved != null)
						{
							var fileName = Path.GetFileName(resolved);
							var targetPath = Path.Combine(CatalogImageStore.Root, fileName);
							if (!File.Exists(targetPath) && File.Exists(resolved))
							{
								File.Copy(resolved, targetPath, overwrite: true);
							}
							if (f.ImagePath != fileName)
							{
								fams[i] = f with { ImagePath = fileName };
								changedFamilies = true;
							}
						}
					}
				}
				if (changedFamilies)
				{
					SaveFamilies(fams);
				}
				if (changedProducts || changedFamilies)
				{
					LogAudit("System", "Image migration", "Migrated catalog images to shared folder");
				}
			}
			catch
			{
			}
		}

