		public void AddSale(Sale sale)
		{
			if (Features.MultiBranch && !string.IsNullOrWhiteSpace(Features.CurrentBranch))
			{
				Sale sale2 = sale._003CClone_003E_0024();
				sale2.Branch = Features.CurrentBranch;
				sale = sale2;
			}
			if (!string.IsNullOrWhiteSpace(Features.CloudSyncDevice))
			{
				Sale sale3 = sale._003CClone_003E_0024();
				sale3.Device = Features.CloudSyncDevice;
				sale = sale3;
			}
			Sales.Add(sale);
			suppressWatcher = true;
			File.WriteAllText(file, JsonSerializer.Serialize(Sales, JsonOptions));
			suppressWatcher = false;
			FireWebhook(sale);
			EnqueueSync(sale);
		}

		public bool HasSale(Sale sale)
		{
			return Sales.Any((Sale s) => s.PaymentNumber == sale.PaymentNumber && s.Time == sale.Time && s.Total == sale.Total);
		}

		public void SaveSales()
		{
			suppressWatcher = true;
			File.WriteAllText(file, JsonSerializer.Serialize(Sales, JsonOptions));
			suppressWatcher = false;
		}

		public void EnqueueSync(Sale sale)
		{
			if (Features.CloudSync)
			{
				SyncQueue.Add(sale);
				if (SyncQueue.Count > 2000)
				{
					SyncQueue.RemoveRange(0, SyncQueue.Count - 2000);
				}
				SaveSyncQueue();
			}
		}

		public void SaveSyncQueue()
		{
			suppressWatcher = true;
			try
			{
				File.WriteAllText(syncQueueFile, JsonSerializer.Serialize(SyncQueue, JsonOptions));
			}
			catch
			{
			}
			suppressWatcher = false;
		}

		private void FireWebhook(Sale sale)
		{
			string url = Features.WebhookUrl;
			if (string.IsNullOrWhiteSpace(url))
			{
				return;
			}
			string payload;
			try
			{
				payload = JsonSerializer.Serialize(new
				{
					@event = "sale.completed",
					payment_number = sale.PaymentNumber,
					time = sale.Time.ToString("yyyy-MM-ddTHH:mm:ss"),
					total = sale.Total,
					payment_type = sale.PaymentType,
					@operator = sale.Operator,
					branch = sale.Branch,
					table = sale.Table,
					order_type = sale.OrderType,
					discount = sale.Discount,
					tip = sale.Tip
				});
			}
			catch
			{
				return;
			}
			Task.Run(async () =>
			{
				try
				{
					using HttpClient hc = new HttpClient
					{
						Timeout = TimeSpan.FromSeconds(5.0)
					};
					await hc.PostAsync(url, new StringContent(payload, Encoding.UTF8, "application/json"));
				}
				catch
				{
				}
			});
		}

		public void AddPrepTime(int minutes)
		{
			PrepTimes.Add(new PrepRecord
			{
				Time = DateTime.Now,
				Minutes = minutes
			});
			if (PrepTimes.Count > 500)
			{
				PrepTimes = PrepTimes.Skip(PrepTimes.Count - 500).ToList();
			}
			suppressWatcher = true;
			try
			{
				File.WriteAllText(prepFile, JsonSerializer.Serialize(PrepTimes, JsonOptions));
			}
			catch
			{
			}
			suppressWatcher = false;
		}

