internal static class StockEngine
{
        private static List<RecipeItem>? FindRecipe(PosStore store, string product)
    {
        if (store == null || string.IsNullOrWhiteSpace(product)) return null;
        if (store.Recipes.TryGetValue(product, out var direct) && direct != null && direct.Count > 0)
            return direct;
        var match = store.Recipes.FirstOrDefault(kv => string.Equals(kv.Key, product, StringComparison.OrdinalIgnoreCase));
        if (match.Value != null && match.Value.Count > 0) return match.Value;
        int paren = product.IndexOf('(');
        if (paren > 0)
        {
            string baseProd = product.Substring(0, paren).Trim();
            if (store.Recipes.TryGetValue(baseProd, out var baseDirect) && baseDirect != null && baseDirect.Count > 0)
                return baseDirect;
            match = store.Recipes.FirstOrDefault(kv => string.Equals(kv.Key, baseProd, StringComparison.OrdinalIgnoreCase));
            if (match.Value != null && match.Value.Count > 0) return match.Value;
        }
        return null;
    }

    public static void Apply(PosStore store, IEnumerable<(string Product, decimal Quantity)> lines, string by, string reference, bool reverse)
    {
        if (store == null || !store.Features.StockManagement) return;

        bool changed = false;
        string kind = reverse ? "refund" : "sale";

        foreach (var line in lines)
        {
            if (string.IsNullOrWhiteSpace(line.Product) || line.Quantity == 0m) continue;

            var recipeItems = FindRecipe(store, line.Product);
            if (recipeItems != null && recipeItems.Count > 0)
            {
                foreach (var ri in recipeItems)
                {
                    var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ri.Ingredient, StringComparison.OrdinalIgnoreCase));
                    if (ing == null) continue;

                    decimal itemQty = ri.Quantity;
                    if (!string.IsNullOrWhiteSpace(ri.Unit))
                    {
                        var converted = UnitMath.Convert(itemQty, ri.Unit, ing.Unit);
                        if (converted.HasValue) itemQty = converted.Value;
                    }

                    decimal totalDeduction = line.Quantity * itemQty;
                    decimal delta = reverse ? totalDeduction : -totalDeduction;

                    if (!string.IsNullOrEmpty(reference) && reference != "0" &&
                        store.StockMovements.Any(m => m.Kind == kind && m.Ref == reference && string.Equals(m.Item, ing.Name, StringComparison.OrdinalIgnoreCase)))
                    {
                        continue;
                    }

                    ing.Stock += delta;
                    store.StockMovements.Add(new StockMovement(DateTime.Now, kind, ing.Name, delta, ing.Stock, reference, by));
                    changed = true;
                }
            }
            else
            {
                var ps = store.ProductStocks.FirstOrDefault(p => string.Equals(p.Product, line.Product, StringComparison.OrdinalIgnoreCase));
                if (ps != null && ps.Tracked)
                {
                    decimal delta = reverse ? line.Quantity : -line.Quantity;

                    if (!string.IsNullOrEmpty(reference) && reference != "0" &&
                        store.StockMovements.Any(m => m.Kind == kind && m.Ref == reference && string.Equals(m.Item, ps.Product, StringComparison.OrdinalIgnoreCase)))
                    {
                        continue;
                    }

                    ps.Stock += delta;
                    store.StockMovements.Add(new StockMovement(DateTime.Now, kind, ps.Product, delta, ps.Stock, reference, by));
                    changed = true;
                }
            }
        }

        if (changed)
        {
            try
            {
                store.SaveIngredients(store.Ingredients);
                store.SaveProductStocks(store.ProductStocks);
                store.SaveStockMovements(store.StockMovements);
            }
            catch (IOException ex)
            {
                if (store.Features.AuditLog)
                    store.LogAudit(by, "Stock save error", ex.Message);
            }
        }
    }

    public static List<StockAlert> Low(PosStore store)
    {
        var alerts = new List<StockAlert>();
        if (store == null) return alerts;

        foreach (var ing in store.Ingredients)
        {
            if (ing.MinStock > 0m && ing.Stock <= ing.MinStock)
            {
                var usedBy = store.Recipes
                    .Where(kv => kv.Value.Any(ri => string.Equals(ri.Ingredient, ing.Name, StringComparison.OrdinalIgnoreCase)))
                    .Select(kv => kv.Key)
                    .ToList();
                string products = usedBy.Count > 0 ? string.Join(", ", usedBy.Take(3)) : "Stock";
                alerts.Add(new StockAlert(products, ing.Name, ing.Stock, ing.MinStock));
            }
        }

        foreach (var ps in store.ProductStocks)
        {
            if (ps.Tracked && ps.MinStock > 0m && ps.Stock <= ps.MinStock)
            {
                alerts.Add(new StockAlert(ps.Product, ps.Product, ps.Stock, ps.MinStock));
            }
        }

        return alerts;
    }

    public static decimal RecipeCost(PosStore store, string product)
    {
        var items = FindRecipe(store, product);
        if (items == null || items.Count == 0) return 0m;
        decimal total = 0m;
        foreach (var ri in items)
        {
            var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ri.Ingredient, StringComparison.OrdinalIgnoreCase));
            if (ing != null)
            {
                decimal qty = ri.Quantity;
                if (!string.IsNullOrWhiteSpace(ri.Unit))
                {
                    var converted = UnitMath.Convert(qty, ri.Unit, ing.Unit);
                    if (converted.HasValue) qty = converted.Value;
                }
                total += qty * ing.Cost;
            }
        }
        return total;
    }

    public static bool HasRecipe(PosStore store, string product)
    {
        var items = FindRecipe(store, product);
        return items != null && items.Count > 0;
    }
}

