		public static void Apply(FeatureSettings f)
		{
			Mode = (string.Equals(f.Theme, "light", StringComparison.OrdinalIgnoreCase) ? SkinMode.Light : SkinMode.Dark);
			(SkinQuality Quality, string Reason) tuple = Resolve(f.GraphicsQuality);
			SkinQuality item = tuple.Quality;
			string item2 = tuple.Reason;
			Quality = item;
			QualityReason = item2;
			f.ResolvedQuality = ((Quality == SkinQuality.High) ? "high" : "lite");
			f.ResolvedReason = QualityReason;
		}

		public static (SkinQuality Quality, string Reason) Resolve(string? choice)
		{
			string text = (choice ?? "auto").Trim().ToLowerInvariant();
			if (text == "high")
			{
				return (Quality: SkinQuality.High, Reason: "High — chosen manually");
			}
			if (text == "lite")
			{
				return (Quality: SkinQuality.Lite, Reason: "Lite — chosen manually");
			}
			return Detect();
		}

		public static IDisposable Preview(string? theme, string? quality)
		{
			SkinScope result = new SkinScope(Mode, Quality, QualityReason);
			Mode = (string.Equals(theme, "light", StringComparison.OrdinalIgnoreCase) ? SkinMode.Light : SkinMode.Dark);
			(SkinQuality Quality, string Reason) tuple = Resolve(quality);
			SkinQuality item = tuple.Quality;
			string item2 = tuple.Reason;
			Quality = item;
			QualityReason = item2;
			return result;
		}

		internal static void Restore(SkinMode mode, SkinQuality quality, string reason)
		{
			Mode = mode;
			Quality = quality;
			QualityReason = reason;
		}

		public static void Animate(int ms, Action<double> step, Action? done = null)
		{
			if (!IsHigh || ms <= 0)
			{
				step(1.0);
				done?.Invoke();
				return;
			}
			if (animStep != null)
			{
				Action<double> action = animStep;
				Action? action2 = animDone;
				animStep = null;
				animDone = null;
				animTimer?.Stop();
				action(1.0);
				action2?.Invoke();
			}
			animStep = step;
			animDone = done;
			animTick = 0;
			animTicks = Math.Max(1, ms / 15);
			if (animTimer == null)
			{
				animTimer = new Timer
				{
					Interval = 15
				};
			}
			animTimer.Tick -= AnimTick;
			animTimer.Tick += AnimTick;
			step(0.0);
			animTimer.Start();
		}

		private static void AnimTick(object? sender, EventArgs e)
		{
			animTick++;
			double num = Math.Min(1.0, (double)animTick / (double)animTicks);
			double obj = 1.0 - Math.Pow(1.0 - num, 3.0);
			animStep?.Invoke(obj);
			if (!(num < 1.0))
			{
				animTimer?.Stop();
				Action? action = animDone;
				animStep = null;
				animDone = null;
				action?.Invoke();
			}
		}

		public static void SlideWindow(Form f, int dx = 22)
		{
			if (!IsHigh || f.IsDisposed)
			{
				return;
			}
			Point target = f.Location;
			Point from = new Point(target.X + dx, target.Y);
			f.Location = from;
			Animate(150, (double t) =>
			{
				if (!f.IsDisposed)
				{
					f.Location = new Point((int)Math.Round((double)from.X + (double)(target.X - from.X) * t), target.Y);
				}
			});
		}

		public static (SkinQuality Quality, string Reason) Detect()
		{
			int processorCount = Environment.ProcessorCount;
			double num = TotalRamGb();
			if (IsWindows7())
			{
				return (Quality: SkinQuality.Lite, Reason: "Lite — Windows 7 (low-spec POS target)");
			}
			try
			{
				if (SystemInformation.TerminalServerSession)
				{
					return (Quality: SkinQuality.Lite, Reason: "Lite — Remote Desktop session");
				}
			}
			catch
			{
			}
			if (processorCount < 2)
			{
				return (Quality: SkinQuality.Lite, Reason: $"Lite — only {processorCount} logical core(s)");
			}
			if (num > 0.0 && num < 4.0)
			{
				return (Quality: SkinQuality.Lite, Reason: $"Lite — only {num:0.#} GB RAM");
			}
			return (Quality: SkinQuality.High, Reason: $"High — {processorCount} cores, {num:0.#} GB RAM");
		}

		private static double TotalRamGb()
		{
			try
			{
				MemoryStatusEx lpBuffer = new MemoryStatusEx
				{
					dwLength = (uint)Marshal.SizeOf(typeof(MemoryStatusEx))
				};
				if (GlobalMemoryStatusEx(ref lpBuffer))
				{
					return (double)lpBuffer.ullTotalPhys / 1024.0 / 1024.0 / 1024.0;
				}
			}
			catch
			{
			}
			return 0.0;
		}

		private static bool IsWindows7()
		{
			try
			{
				OsVersionInfo versionInfo = new OsVersionInfo
				{
					dwOSVersionInfoSize = Marshal.SizeOf(typeof(OsVersionInfo))
				};
				if (RtlGetVersion(ref versionInfo) == 0)
				{
					return versionInfo.dwMajorVersion == 6 && versionInfo.dwMinorVersion == 1;
				}
			}
			catch
			{
			}
			try
			{
				Version version = Environment.OSVersion.Version;
				return version.Major == 6 && version.Minor == 1;
			}
			catch
			{
			}
			return false;
		}

		[DllImport("kernel32.dll", SetLastError = true)]
		[return: MarshalAs(UnmanagedType.Bool)]
		private static extern bool GlobalMemoryStatusEx(ref MemoryStatusEx lpBuffer);

		[DllImport("ntdll.dll", CharSet = CharSet.Unicode)]
		private static extern int RtlGetVersion(ref OsVersionInfo versionInfo);

		public static Color Shade(Color c, double t)
		{
			if (t >= 0.0)
			{
				return Color.FromArgb((int)((double)(int)c.R + (double)(255 - c.R) * t), (int)((double)(int)c.G + (double)(255 - c.G) * t), (int)((double)(int)c.B + (double)(255 - c.B) * t));
			}
			double num = 1.0 + t;
			return Color.FromArgb((int)((double)(int)c.R * num), (int)((double)(int)c.G * num), (int)((double)(int)c.B * num));
		}

		public static Color Step(Color c, double t)
		{
			return Shade(c, IsLight ? (0.0 - t) : t);
		}

		public static void FlatStates(Button button)
		{
			int width = button.Width;
			int height = button.Height;
			int num = Math.Max(6, Math.Min(width, height) / 24);
			if (width > num * 2 && height > num * 2)
			{
				button.Region = new Region(RoundRect(new Rectangle(0, 0, width, height), num));
			}
			Color baseColor = (button.BackColor.IsEmpty || button.BackColor == SystemColors.Control)
				? Skin.SidebarItem
				: button.BackColor;
			button.Tag = baseColor;
			bool isHover = false;
			bool isDown = false;
			bool updatingInternal = false;
			Color? disabledFore = null;

			button.BackColorChanged += (s, e) =>
			{
				if (!updatingInternal && !isHover && !isDown)
				{
					if (!button.BackColor.IsEmpty && button.BackColor != SystemColors.Control)
					{
						baseColor = button.BackColor;
						button.Tag = baseColor;
					}
				}
			};

			button.MouseEnter += (object _, EventArgs _) =>
			{
				if (button.Enabled)
				{
					isHover = true;
					Color c = (button.Tag is Color tc && tc != SystemColors.Control && !tc.IsEmpty) ? tc : baseColor;
					updatingInternal = true;
					button.BackColor = Step(c, 0.1);
					updatingInternal = false;
				}
			};
			button.MouseDown += (object _, MouseEventArgs e) =>
			{
				if (e.Button == MouseButtons.Left && button.Enabled)
				{
					isDown = true;
					Color c = (button.Tag is Color tc && tc != SystemColors.Control && !tc.IsEmpty) ? tc : baseColor;
					updatingInternal = true;
					button.BackColor = Step(c, 0.17);
					updatingInternal = false;
				}
			};
			button.MouseUp += (object _, MouseEventArgs _) =>
			{
				if (button.Enabled)
				{
					isDown = false;
					Color c = (button.Tag is Color tc && tc != SystemColors.Control && !tc.IsEmpty) ? tc : baseColor;
					updatingInternal = true;
					button.BackColor = isHover ? Step(c, 0.1) : c;
					updatingInternal = false;
				}
			};
			button.MouseLeave += (object _, EventArgs _) =>
			{
				if (button.Enabled)
				{
					isHover = false;
					isDown = false;
					Color backColor = (button.Tag is Color tc && tc != SystemColors.Control && !tc.IsEmpty) ? tc : baseColor;
					updatingInternal = true;
					button.BackColor = backColor;
					updatingInternal = false;
				}
			};
			button.EnabledChanged += (object _, EventArgs _) =>
			{
				if (button.Tag is Color color)
				{
					if (button.Enabled)
					{
						button.BackColor = color;
						if (disabledFore.HasValue)
						{
							Color valueOrDefault = disabledFore.GetValueOrDefault();
							button.ForeColor = valueOrDefault;
							disabledFore = null;
						}
						button.Cursor = Cursors.Hand;
					}
					else
					{
						disabledFore = button.ForeColor;
						button.BackColor = MixToward(color, Background, 0.65);
						button.ForeColor = TextDisabled;
						button.Cursor = Cursors.Default;
					}
				}
			};
		}

		public static void SetFlatBase(Button button, Color back)
		{
			button.Tag = back;
			if (button.Enabled)
			{
				button.BackColor = back;
			}
		}

		public static Color MixToward(Color from, Color to, double t)
		{
			return Color.FromArgb((int)((double)(int)from.R + (double)(to.R - from.R) * t), (int)((double)(int)from.G + (double)(to.G - from.G) * t), (int)((double)(int)from.B + (double)(to.B - from.B) * t));
		}

		public static void FillSurface(Graphics g, Rectangle r, Color baseColor, int radius = 0)
		{
			if (r.Width <= 0 || r.Height <= 0)
			{
				return;
			}
			if (!IsHigh)
			{
				using (SolidBrush brush = new SolidBrush(baseColor))
				{
					if (radius > 0)
					{
						using (GraphicsPath path = RoundRect(r, radius))
						{
							g.FillPath(brush, path);
							return;
						}
					}
					g.FillRectangle(brush, r);
					return;
				}
			}
			using LinearGradientBrush brush2 = new LinearGradientBrush(new Rectangle(r.X, r.Y, Math.Max(1, r.Width), Math.Max(1, r.Height)), Shade(baseColor, 0.1), Shade(baseColor, -0.06), LinearGradientMode.Vertical);
			if (radius > 0)
			{
				using (GraphicsPath path2 = RoundRect(r, radius))
				{
					g.FillPath(brush2, path2);
					return;
				}
			}
			g.FillRectangle(brush2, r);
		}

		public static void CardDepth(Graphics g, Rectangle r, int radius)
		{
			if (!IsHigh || r.Width < 8 || r.Height < 8)
			{
				return;
			}
			using Pen pen = new Pen(Highlight, 1f);
			using Pen pen2 = new Pen(Shadow, 1f);
			using GraphicsPath path = RoundRect(new Rectangle(r.X, r.Y, r.Width - 1, r.Height - 1), radius);
			g.DrawPath(pen, path);
			Rectangle rectangle = Rectangle.Inflate(r, -2, -2);
			if (rectangle.Width > 4 && rectangle.Height > 4)
			{
				using (GraphicsPath path2 = RoundRect(new Rectangle(rectangle.X, rectangle.Y, rectangle.Width - 1, rectangle.Height - 1), Math.Max(2, radius - 2)))
				{
					g.DrawPath(pen2, path2);
					return;
				}
			}
		}

		public static GraphicsPath RoundRect(Rectangle r, int radius)
		{
			int num = Math.Max(1, Math.Min(radius * 2, Math.Min(r.Width, r.Height)));
			GraphicsPath graphicsPath = new GraphicsPath();
			if (num <= 2)
			{
				graphicsPath.AddRectangle(r);
				return graphicsPath;
			}
			graphicsPath.AddArc(r.X, r.Y, num, num, 180f, 90f);
			graphicsPath.AddArc(r.Right - num, r.Y, num, num, 270f, 90f);
			graphicsPath.AddArc(r.Right - num, r.Bottom - num, num, num, 0f, 90f);
			graphicsPath.AddArc(r.X, r.Bottom - num, num, num, 90f, 90f);
			graphicsPath.CloseFigure();
			return graphicsPath;
		}
	}

internal sealed class SkinScope : IDisposable
	{
		private readonly SkinMode mode;

		private readonly SkinQuality quality;

		private readonly string reason;

		private bool done;

		public SkinScope(SkinMode mode, SkinQuality quality, string reason)
		{
			this.mode = mode;
			this.quality = quality;
			this.reason = reason;
		}

		public void Dispose()
		{
			if (!done)
			{
				done = true;
				Skin.Restore(mode, quality, reason);
			}
		}
	}

internal sealed class AppearancePreview : Control
	{
		private string theme = "dark";

		private string quality = "auto";

		public AppearancePreview()
		{
			DoubleBuffered = true;
			SetStyle(ControlStyles.ResizeRedraw, value: true);
		}

		public void Set(string theme, string quality)
		{
			this.theme = theme;
			this.quality = quality;
			Invalidate();
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			Graphics graphics = e.Graphics;
			graphics.SmoothingMode = SmoothingMode.AntiAlias;
			using (Skin.Preview(theme, quality))
			{
				Rectangle clientRectangle = ClientRectangle;
				using (SolidBrush brush = new SolidBrush(Skin.Background))
				{
					graphics.FillRectangle(brush, clientRectangle);
				}
				int num = Math.Max(22, clientRectangle.Height / 5);
				using (SolidBrush brush2 = new SolidBrush(Skin.AppBar))
				{
					graphics.FillRectangle(brush2, 0, 0, clientRectangle.Width, num);
				}
				using (Pen pen = new Pen(Skin.AppBarBorder))
				{
					graphics.DrawLine(pen, 0, num - 1, clientRectangle.Width, num - 1);
				}
				using (SolidBrush brush3 = new SolidBrush(Skin.Accent))
				{
					graphics.FillEllipse(brush3, 8, num / 2 - 5, 10, 10);
				}
				using (SolidBrush brush4 = new SolidBrush(Skin.Text))
				{
					graphics.FillRectangle(brush4, 24, num / 2 - 4, 44, 7);
				}
				int num2 = num / 2 - 7;
				int num3 = Math.Max(10, num - 2 * (num / 2 - 7));
				Skin.FillSurface(graphics, new Rectangle(76, num2, 34, num3), Skin.NavActive, num3 / 2);
				using (SolidBrush brush5 = new SolidBrush(Skin.Accent))
				{
					graphics.FillRectangle(brush5, 86, num / 2 - 2, 14, 4);
				}
				for (int i = 0; i < 2; i++)
				{
					Skin.FillSurface(graphics, new Rectangle(114 + i * 34, num2, 30, num3), Skin.Kpi, num3 / 2);
				}
				int num4 = Math.Max(34, clientRectangle.Width / 9);
				Skin.FillSurface(graphics, new Rectangle(clientRectangle.Width - num4 - 60, num / 2 - 8, num4, 16), Skin.Kpi, 4);
				using (SolidBrush brush6 = new SolidBrush(Skin.Accent))
				{
