				int num8 = Math.Max(60, clientRectangle.Width / 4);
				Rectangle r = new Rectangle(clientRectangle.Width - num8 - 12, num6, num8, num7);
				Skin.FillSurface(graphics, r, Skin.Panel, 6);
				if (Skin.IsHigh)
				{
					Skin.CardDepth(graphics, r, 6);
