			}
			ClientSize = new Size(ClientSize.Width, ClientSize.Height + offset);
		}

		protected static void ApplyPillRegion(Control c, int radius)
		{
			Region region = c.Region;
			c.Region = new Region(Skin.RoundRect(new Rectangle(0, 0, c.Width, c.Height), radius));
			region?.Dispose();
		}

		protected virtual void Back()
		{
			if (OnBackAction != null)
			{
				OnBackAction();
			}
			else
			{
				Close();
			}
		}

		protected virtual void Done()
		{
			Back();
		}
	}

internal sealed class SkinPanel : Panel
	{
		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public bool Gradient = true;

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public Color? Fill { get; set; }

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public int Radius { get; set; }

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public Color? Edge { get; set; }

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public bool Depth { get; set; }

		public SkinPanel()
		{
			DoubleBuffered = true;
			SetStyle(ControlStyles.ResizeRedraw, value: true);
		}

		protected override void OnPaintBackground(PaintEventArgs e)
		{
			Color color = Fill ?? BackColor;
			if (Radius <= 0)
			{
				if (!Skin.IsHigh || !Gradient)
				{
					e.Graphics.Clear(color);
				}
				else
				{
					Skin.FillSurface(e.Graphics, ClientRectangle, color);
				}
			}
			else
			{
				e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
				Skin.FillSurface(e.Graphics, ClientRectangle, color, Radius);
			}
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			if (Radius <= 0)
			{
				return;
			}
			e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
			if (Depth)
			{
				Skin.CardDepth(e.Graphics, ClientRectangle, Radius);
			}
			Color? edge = Edge;
			if (!edge.HasValue)
			{
				return;
			}
			Color valueOrDefault = edge.GetValueOrDefault();
			using Pen pen = new Pen(valueOrDefault, 1f);
			using GraphicsPath path = Skin.RoundRect(new Rectangle(0, 0, Width - 1, Height - 1), Radius);
			e.Graphics.DrawPath(pen, path);
		}
	}

internal sealed class VectronMark : Control
	{
		private double progress = 1.0;

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public double Progress
		{
			get
			{
				return progress;
			}
			set
			{
				progress = Math.Max(0.0, Math.Min(1.0, value));
				Invalidate();
			}
		}

		public VectronMark()
		{
			DoubleBuffered = true;
			SetStyle(ControlStyles.SupportsTransparentBackColor, value: true);
			SetStyle(ControlStyles.ResizeRedraw, value: true);
			BackColor = Color.Transparent;
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			Graphics graphics = e.Graphics;
			graphics.SmoothingMode = SmoothingMode.AntiAlias;
			int num = Math.Min(Width, Height);
			if (num >= 8)
			{
				Color accent = Skin.Accent;
				Rectangle rectangle = new Rectangle((Width - num) / 2, (Height - num) / 2, num - 1, num - 1);
				float num2 = (float)rectangle.X + (float)num / 2f;
				float num3 = (float)rectangle.Y + (float)num / 2f;
				using (Pen pen = new Pen(accent, Math.Max(1.6f, (float)num / 20f)))
				{
					float sweepAngle = (float)(360.0 * progress);
					graphics.DrawArc(pen, rectangle, -90f, sweepAngle);
				}
				float num4 = (float)num * 0.28f * (float)progress;
				using (Pen pen2 = new Pen(accent, Math.Max(2.2f, (float)num / 11f))
				{
					StartCap = LineCap.Round,
					EndCap = LineCap.Round,
					LineJoin = LineJoin.Round
				})
				{
					graphics.DrawLine(pen2, num2 - (float)num * 0.24f, num3 - (float)num * 0.2f, num2, num3 + num4);
					graphics.DrawLine(pen2, num2 + (float)num * 0.24f, num3 - (float)num * 0.2f, num2, num3 + num4);
				}
				if (progress >= 0.999)
				{
					Hud.Brackets(graphics, rectangle, Skin.Shade(accent, -0.25), Math.Max(4, num / 6), 1);
				}
			}
		}
	}

