internal static class Hud
	{
		public static void Brackets(Graphics g, Rectangle r, Color color, int arm = 16, int inset = 5)
		{
			using Pen pen = new Pen(color, 1f);
			float num = (float)(r.Left + inset) + 0.5f;
			float num2 = (float)(r.Top + inset) + 0.5f;
			float num3 = (float)(r.Right - 1 - inset) + 0.5f;
			float num4 = (float)(r.Bottom - 1 - inset) + 0.5f;
			g.DrawLine(pen, num, num2, num + (float)arm, num2);
			g.DrawLine(pen, num, num2, num, num2 + (float)arm);
			g.DrawLine(pen, num3 - (float)arm, num2, num3, num2);
			g.DrawLine(pen, num3, num2, num3, num2 + (float)arm);
			g.DrawLine(pen, num, num4, num + (float)arm, num4);
			g.DrawLine(pen, num, num4 - (float)arm, num, num4);
			g.DrawLine(pen, num3 - (float)arm, num4, num3, num4);
			g.DrawLine(pen, num3, num4 - (float)arm, num3, num4);
		}
	}

internal sealed class HudPanel : Panel
	{
		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public Color? Edge { get; set; }

		public HudPanel()
		{
			DoubleBuffered = true;
		}

		protected override void OnPaintBackground(PaintEventArgs e)
		{
			if (!Skin.IsHigh)
			{
				base.OnPaintBackground(e);
			}
			else
			{
				Skin.FillSurface(e.Graphics, ClientRectangle, BackColor);
			}
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			Color? edge = Edge;
			if (edge.HasValue)
			{
				Color valueOrDefault = edge.GetValueOrDefault();
				using Pen pen = new Pen(valueOrDefault, 1f);
				e.Graphics.DrawRectangle(pen, 0, 0, Width - 1, Height - 1);
				Hud.Brackets(e.Graphics, ClientRectangle, Skin.Accent, 18, 6);
			}
		}
	}

