			{
				Location = new Point(30, 296),
				Size = new Size(320, 36),
				BackColor = panelLight,
				ForeColor = Skin.Text,
				BorderStyle = BorderStyle.FixedSingle,
				UseSystemPasswordChar = true,
				TabIndex = 1
			};
			passwordBox.KeyDown += (object _, KeyEventArgs e) =>
			{
