				{
					loginForm.TryLogin(operators, operatorList, passwordBox, pinMode);
				}
			};
			Panel opRail = new Panel
			{
				Location = new Point(30, 250),
				Size = new Size(320, 2),
				BackColor = mint,
				Visible = false
			};
			Panel pwRail = new Panel
			{
				Location = new Point(30, 332),
				Size = new Size(320, 2),
				BackColor = mint,
				Visible = false
			};
			operatorList.GotFocus += (object _, EventArgs _) =>
			{
				operatorList.BackColor = border;
				opRail.Visible = true;
			};
			operatorList.LostFocus += (object _, EventArgs _) =>
			{
				operatorList.BackColor = panelLight;
				opRail.Visible = false;
			};
			passwordBox.GotFocus += (object _, EventArgs _) =>
			{
				passwordBox.BackColor = border;
				pwRail.Visible = true;
			};
			passwordBox.LostFocus += (object _, EventArgs _) =>
			{
				passwordBox.BackColor = panelLight;
				pwRail.Visible = false;
			};
			Button loginButton = new Button
			{
				Text = (pinMode ? Tr.T("Enter") : Tr.T("Login")),
				Location = new Point(30, 382),
				Size = new Size(320, 48),
				BackColor = mint,
				ForeColor = Skin.OnAccent,
				FlatStyle = FlatStyle.Flat,
				TabIndex = 2,
				Cursor = Cursors.Hand
			};
			loginButton.FlatAppearance.BorderSize = 0;
			loginButton.MouseDown += (object _, MouseEventArgs e) =>
			{
				if (e.Button == MouseButtons.Left)
				{
					loginButton.BackColor = pressed;
				}
			};
			loginButton.MouseUp += (object _, MouseEventArgs _) =>
			{
				loginButton.BackColor = mint;
			};
			loginButton.MouseLeave += (object _, EventArgs _) =>
			{
				loginButton.BackColor = mint;
			};
			loginButton.Click += (object _, EventArgs _) =>
			{
				loginForm.TryLogin(operators, operatorList, passwordBox, pinMode);
			};
			skinPanel.Controls.AddRange(new Control[11]
			{
				mark, label, label2, panel2, label3, operatorList, label4, passwordBox, loginButton, opRail,
				pwRail
			});
			Controls.Add(skinPanel);
			AcceptButton = loginButton;
			Shown += (object _, EventArgs _) =>
			{
				passwordBox.Focus();
				if (Skin.IsHigh)
				{
					Skin.Animate(420, (double t) =>
					{
						mark.Progress = t;
					});
				}
			};
		}

		private void TryLogin(List<OperatorAccount> operators, ComboBox operatorList, TextBox passwordBox, bool pinMode)
		{
			if (operatorList.SelectedIndex >= 0)
			{
				OperatorAccount operatorAccount = operators[operatorList.SelectedIndex];
				if (!string.IsNullOrWhiteSpace(operatorAccount.Password) && operatorAccount.Password != passwordBox.Text)
				{
					MessageBox.Show(pinMode ? Tr.T("Incorrect PIN.") : Tr.T("Incorrect password."), Tr.T("Login"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					return;
				}
				LoggedInOperator = operatorAccount;
				DialogResult = DialogResult.OK;
				Close();
			}
		}
	}

internal sealed class NetworkSettingsForm : SettingsSubForm
	{
		private static async Task<string?> ScanForMainPcShareAsync()
		{
			List<string> subnets = new List<string>();
			try
			{
				foreach (var ni in System.Net.NetworkInformation.NetworkInterface.GetAllNetworkInterfaces())
				{
					if (ni.OperationalStatus != System.Net.NetworkInformation.OperationalStatus.Up) continue;
					if (ni.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Loopback) continue;
					var ipProps = ni.GetIPProperties();
					foreach (var ua in ipProps.UnicastAddresses)
					{
						if (ua.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
						{
							string ip = ua.Address.ToString();
							if (ip.StartsWith("127.")) continue;
							int lastDot = ip.LastIndexOf('.');
							if (lastDot > 0)
							{
								string prefix = ip.Substring(0, lastDot + 1);
								if (!subnets.Contains(prefix)) subnets.Add(prefix);
							}
						}
					}
				}
			}
			catch {}

			if (subnets.Count == 0)
			{
				subnets.Add("192.168.1.");
				subnets.Add("192.168.0.");
			}

			string? foundIp = null;
			foreach (var prefix in subnets)
			{
				var candidates = Enumerable.Range(1, 254).Select(i => prefix + i).ToList();
				for (int i = 0; i < candidates.Count; i += 32)
				{
					var batch = candidates.Skip(i).Take(32);
					var tasks = batch.Select(async host =>
					{
						using var h = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromMilliseconds(450) };
						try
						{
							string u = $"http://{host}:8080/api/kiosk/bootstrap";
							var str = await h.GetStringAsync(u);
							if (str.Contains("restaurant_name") || str.Contains("ok")) return host;
						}
						catch {}
						return null;
					}).ToList();

					var results = await Task.WhenAll(tasks);
					foundIp = results.FirstOrDefault(r => !string.IsNullOrEmpty(r));
					if (foundIp != null) break;
				}
				if (foundIp != null) break;
			}

			if (string.IsNullOrEmpty(foundIp)) return null;

			string uncIp = $@"\\{foundIp}\client database";
			if (Directory.Exists(uncIp)) return uncIp;

			try
			{
				var hostEntry = System.Net.Dns.GetHostEntry(foundIp);
				if (!string.IsNullOrEmpty(hostEntry.HostName))
				{
					string uncHost = $@"\\{hostEntry.HostName}\client database";
					if (Directory.Exists(uncHost)) return uncHost;
				}
			}
			catch {}

			return uncIp;
		}


		public NetworkSettingsForm(Color background, Color panelLight, Color mint, RegisterSettings settings, Action<RegisterSettings> save)
		{
			NetworkSettingsForm networkSettingsForm = this;
			Text = Tr.T("Network settings");
			Breadcrumb = "Settings / Devices / Network";
			StartPosition = FormStartPosition.CenterParent;
			ClientSize = new Size(480, 280);
			BackColor = background;
			ForeColor = Skin.Text;
			Font = new Font("Segoe UI", 10f);
			FormBorderStyle = FormBorderStyle.FixedDialog;
			MaximizeBox = false;
			Label label = new Label
			{
				Text = Tr.T("Network configuration"),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 16f),
				Location = new Point(20, 16)
			};
			Label label2 = new Label
			{
				Text = Tr.T("PC Mode"),
				AutoSize = true,
				Location = new Point(20, 60)
			};
			RadioButton mainPc = new RadioButton
			{
				Text = Tr.T("Main PC (server) — hosts the database"),
				Location = new Point(20, 86),
				AutoSize = true,
				ForeColor = Skin.Text,
				Checked = settings.IsMainPc
			};
			RadioButton radioButton = new RadioButton
			{
				Text = Tr.T("Order PC (client) — connects to main PC"),
				Location = new Point(20, 116),
				AutoSize = true,
				ForeColor = Skin.Text,
				Checked = !settings.IsMainPc
			};
			Label label3 = new Label
			{
				Text = Tr.T("Network path (from main PC)"),
				AutoSize = true,
				Location = new Point(20, 158)
			};
			TextBox pathBox = new TextBox
			{
				Location = new Point(20, 184),
				Size = new Size(430, 30),
				BackColor = panelLight,
				ForeColor = Skin.Text,
				BorderStyle = BorderStyle.FixedSingle,
				Text = settings.NetworkPath
			};
			Button btnAutoDetect = new Button
			{
				Text = Tr.T("🔍 Auto-detect Main PC"),
				Location = new Point(260, 152),
				Size = new Size(190, 28),
				BackColor = panelLight,
				ForeColor = mint,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 9f),
				Enabled = !settings.IsMainPc,
				Cursor = Cursors.Hand
			};
			btnAutoDetect.FlatAppearance.BorderSize = 0;
			btnAutoDetect.Click += async (object _, EventArgs _) =>
			{
				btnAutoDetect.Enabled = false;
				btnAutoDetect.Text = Tr.T("Scanning...");
				try
				{
					string detected = await ScanForMainPcShareAsync();
					if (!string.IsNullOrEmpty(detected))
					{
						pathBox.Text = detected;
						btnAutoDetect.Text = Tr.T("✓ Found Main PC");
						MessageBox.Show(Tr.T("Main PC database detected at:\n") + detected, Tr.T("Auto-detect"), MessageBoxButtons.OK, MessageBoxIcon.Information);
					}
					else
					{
						btnAutoDetect.Text = Tr.T("🔍 Auto-detect Main PC");
						MessageBox.Show(Tr.T("Could not auto-detect Main PC on the local network.\nEnsure Vectron POS is open on the Main PC and 'client database' folder is shared on the network."), Tr.T("Auto-detect"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
					}
				}
				catch (Exception ex)
				{
					btnAutoDetect.Text = Tr.T("🔍 Auto-detect Main PC");
					MessageBox.Show(Tr.T("Detection error: ") + ex.Message, Tr.T("Auto-detect"), MessageBoxButtons.OK, MessageBoxIcon.Error);
				}
				finally
				{
					btnAutoDetect.Enabled = !mainPc.Checked;
				}
			};
			Label label4 = new Label
			{
				Text = Tr.T(@"Example: \\MAIN-PC\client database"),
				AutoSize = true,
				ForeColor = Skin.TextDim,
				Location = new Point(20, 220)
			};
			pathBox.Enabled = !settings.IsMainPc;
			mainPc.CheckedChanged += (object _, EventArgs _) =>
			{
				pathBox.Enabled = !mainPc.Checked;
				btnAutoDetect.Enabled = !mainPc.Checked;
			};
			Button button = new Button
			{
				Text = Tr.T("Save"),
				Location = new Point(330, 240),
				Size = new Size(120, 34),
				BackColor = mint,
				ForeColor = Skin.OnAccent,
				FlatStyle = FlatStyle.Flat
			};
			button.FlatAppearance.BorderSize = 0;
			button.Click += (object _, EventArgs _) =>
			{
				RegisterSettings obj = new RegisterSettings(settings.Currency, settings.TvaRate, settings.PricesIncludeTva, pathBox.Text.Trim(), mainPc.Checked);
				save(obj);
				networkSettingsForm.DialogResult = DialogResult.OK;
				networkSettingsForm.Close();
			};
			Controls.AddRange(new Control[9] { label, label2, mainPc, radioButton, label3, btnAutoDetect, pathBox, label4, button });
			doneBtn.Click += (s, e) => button.PerformClick();
			ShiftBodyDown(72);
			Rtl.Apply(this);
		}
	}

