		public PosForm()
		{
			Program.ActivePosForm = this;
			Skin.Apply(store.Features);
			OnScreenKeyboard.IsEnabled = () => store.Features.OnScreenKeyboard;
			Tr.Lang = (string.IsNullOrWhiteSpace(store.Features.Language) ? "en" : store.Features.Language);
			ApplyCurrencyCulture(store.RegisterSettings.Currency);
			Text = Tr.T("Vectron POS");
			StartPosition = FormStartPosition.Manual;
			BackColor = background;
			ForeColor = Skin.Text;
			Font = new Font("Segoe UI", 10f);
			FormBorderStyle = FormBorderStyle.None;
			WindowState = FormWindowState.Normal;
			Screen screen = Screen.PrimaryScreen ?? Screen.AllScreens[0];
			Location = screen.Bounds.Location;
			Size = screen.Bounds.Size;
			if (store.Operators.Any((OperatorAccount op) => !string.IsNullOrWhiteSpace(op.Password)))
			{
				using LoginForm loginForm = new LoginForm(background, panelLight, mint, store.Operators, store.Features.PinLogin);
				if (loginForm.ShowDialog(this) != DialogResult.OK || loginForm.LoggedInOperator == null)
				{
					Close();
					return;
				}
				currentOperator = loginForm.LoggedInOperator;
			}
			else
			{
				currentOperator = store.Operators[0];
			}
			products = store.Products;
			isOrderPc = !store.RegisterSettings.IsMainPc;
			if (!isOrderPc)
			{
				TcpPrintServer.Start();
			}
			FormClosing += (object _, FormClosingEventArgs _) =>
			{
				Program.ActivePosForm = null;
				TcpPrintServer.Stop();
			};
			FormClosing += (object _, FormClosingEventArgs _) =>
			{
				StopQrServer();
			};
			BuildUi();
			Rtl.Apply(this);
			ApplyOrderPcRestrictions();
			Auto86Sync();
			RenderProducts();
			RenderBasket();
			TicketLayout.CourseNames = store.CourseNames.ToArray();
			if ((store.Features.QROrdering || store.Features.ApiEnabled || store.Features.CloudSync || store.Features.KioskMode) && !isOrderPc)
			{
				StartQrServer();
			}
			StartBackupScheduler();
			StartCloudSyncScheduler();
			StartKioskAutoVoidScheduler();
			store.DataChanged += OnDataChanged;
			store.GuestAlertRaised += OnGuestAlertRaised;
			if (!Skin.IsHigh)
			{
				return;
			}
			Shown += (object _, EventArgs _) =>
			{
				if (brandMark != null && !brandMark.IsDisposed)
				{
					Skin.Animate(420, (double t) =>
					{
						brandMark.Progress = t;
					});
				}
				SkinPanel card = orderCard;
				if (card != null && !card.IsDisposed)
				{
					int target = card.Left;
					Skin.Animate(220, (double t) =>
					{
						if (!card.IsDisposed)
						{
							card.Left = target + (int)Math.Round((1.0 - t) * 26.0);
						}
					});
				}
			};
		}

		private void OnGuestAlertRaised()
		{
			if (IsDisposed || !IsHandleCreated)
			{
				return;
			}
			if (InvokeRequired)
			{
				try
				{
					try { System.Media.SystemSounds.Asterisk.Play(); } catch {}
					BeginInvoke(new Action(UpdateGuestAlertBar));
					return;
				}
				catch
				{
					return;
				}
			}
			UpdateGuestAlertBar();
		}

		private void UpdateGuestAlertBar()
		{
			List<GuestAlertItem> guestAlerts = store.GuestAlerts;
			guestBar.Visible = guestAlerts.Count > 0;
			if (guestAlerts.Count != 0)
			{
				GuestAlertItem guestAlertItem = guestAlerts[guestAlerts.Count - 1];
				if (guestAlertItem.Kind == "ready")
				{
					guestDeliverBtn.Visible = true;
					guestBar.BackColor = Skin.Success;
					guestLabel.Text = string.Format("  🎉 {0} / {1} — " + Tr.T("ORDER READY") + " ({2:HH:mm}){3}", guestAlertItem.Room, guestAlertItem.Table, guestAlertItem.Time, (guestAlerts.Count > 1) ? $"   +{guestAlerts.Count - 1} more" : "");
				}
				else if (guestAlertItem.Kind == "kiosk_order")
				{
					guestDeliverBtn.Visible = false;
					guestBar.BackColor = Skin.Accent;
					guestLabel.Text = string.Format(Tr.T("  🛎 KIOSK ORDER {0} AWAITING CONFIRMATION ({1:HH:mm}){2}"), guestAlertItem.Table, guestAlertItem.Time, (guestAlerts.Count > 1) ? $"   +{guestAlerts.Count - 1} more" : "");
				}
				else
				{
					guestDeliverBtn.Visible = false;
					guestBar.BackColor = Skin.Warning;
					guestLabel.Text = string.Format("  🔔 {0} / {1} — WAITER CALLED ({2:HH:mm}){3}", guestAlertItem.Room, guestAlertItem.Table, guestAlertItem.Time, (guestAlerts.Count > 1) ? $"   +{guestAlerts.Count - 1} more" : "");
				}
			}
		}

		private void OnDataChanged()
		{
			if (InvokeRequired)
			{
				BeginInvoke(new Action(OnDataChanged));
				return;
			}
			ApplyCurrencyCulture(store.RegisterSettings.Currency);
			products = store.Products;
			TicketLayout.CourseNames = store.CourseNames.ToArray();
			RenderProducts();
			RenderRooms();
			RenderBasket();
			salesLabel.Text = TodaySalesAmount();
			RefreshOpenOrders();
			UpdateQrBanner();
		}

		private void RefreshOpenOrders()
		{
			if (string.IsNullOrWhiteSpace(selectedRoom) || !(selectedTable != "No table selected"))
			{
				return;
			}
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder != null && !hasOpenOrder)
			{
				hasOpenOrder = true;
				basket.Clear();
				foreach (SoldLine item in openOrder.Items)
				{
					Product product = products.FirstOrDefault((Product p) => p.Name == item.Product);
					if (product != null)
					{
						int num = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) b) => b.Product == product && b.Note == item.Note && b.Modifiers == item.Modifiers && (!store.Features.SeatOrdering || b.Seat == item.Seat));
						if (num >= 0)
						{
							basket[num] = (product, basket[num].Count + item.Quantity, basket[num].Course, basket[num].Note, item.Seat, JoinMods(basket[num].Modifiers, item.Modifiers));
						}
						else
						{
							basket.Add((product, item.Quantity, item.Course, item.Note, item.Seat, item.Modifiers));
						}
					}
				}
				UpdateOrderButtons();
				RenderBasket();
				orderLabel.Text = OrderContextText();
			}
			else if (openOrder == null && hasOpenOrder)
			{
				hasOpenOrder = false;
				basket.Clear();
				UpdateOrderButtons();
				RenderBasket();
				orderLabel.Text = OrderContextText();
			}
		}

		private void ApplyOrderPcRestrictions()
		{
			payButton.Visible = !isOrderPc;
			UpdateOrderButtons();
		}

		private void UpdateOrderButtons()
		{
			noteButton.Visible = !isOrderPc && hasOpenOrder;
			splitBillButton.Visible = !isOrderPc && hasOpenOrder && store.Features.SplitBill;
			transferButton.Visible = hasOpenOrder && store.Features.TableTransfer;
			mergeButton.Visible = hasOpenOrder && store.Features.TableTransfer;
			repeatButton.Visible = store.Features.RepeatOrders;
			parkButton.Visible = store.Features.ParkOrders && (basket.Count > 0 || hasOpenOrder);
			dealsButton.Visible = store.Features.ComboDeals && store.ComboDeals.Count > 0;
			reprintButton.Visible = lastReceipt.HasValue;
			fireButton.Visible = false;
			delayFireButton.Visible = false;
			if (!store.Features.CourseManagement || !hasOpenOrder)
			{
				return;
			}
			OpenOrder order = store.GetOpenOrder(selectedRoom, selectedTable);
			if (order != null && order.Items.Any((SoldLine l) => l.Course > order.FiredCourse))
			{
				int n = order.Items.Where((SoldLine l) => l.Course > order.FiredCourse).Min((SoldLine l) => l.Course);
				fireButton.Text = Tr.T("Fire") + " " + CourseLabel(n);
				fireButton.Visible = true;
				delayFireButton.Visible = true;
			}
		}

