		private void LayoutWorkspace(Panel workspace, Panel menuPanel, Panel orderPanel)
		{
			int num = Math.Max(280, Math.Min(370, (int)((double)workspace.ClientSize.Width * 0.31)));
			int num2 = Math.Max(0, workspace.ClientSize.Width - num - 18);
			orderPanel.SetBounds(num2 + 18, 6, num, Math.Max(0, workspace.ClientSize.Height - 6));
			menuPanel.SetBounds(0, 0, num2, workspace.ClientSize.Height);
			orderPanel.Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Right;
			menuPanel.Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Left;
			if (orderPanel.Width > 30 && orderPanel.Height > 30)
			{
				ApplyPillRegion(orderPanel, 14);
			}
		}

		private static void StylePill(Button b)
		{
			b.FlatStyle = FlatStyle.Flat;
			b.FlatAppearance.BorderSize = 0;
			b.BackColor = Color.Transparent;
			b.ForeColor = Skin.NavText;
			b.Font = new Font("Segoe UI Semibold", 10f);
			b.Cursor = Cursors.Hand;
			b.TextAlign = ContentAlignment.MiddleCenter;
			b.UseVisualStyleBackColor = false;
			b.MouseEnter += (object _, EventArgs _) =>
			{
				object tag = b.Tag;
				if (!(tag is bool) || !(bool)tag)
				{
					b.BackColor = Skin.PillHover;
				}
			};
			b.MouseLeave += (object _, EventArgs _) =>
			{
				object tag = b.Tag;
				if (!(tag is bool) || !(bool)tag)
				{
					b.BackColor = Color.Transparent;
				}
			};
			b.MouseDown += (object _, MouseEventArgs e) =>
			{
				if (e.Button == MouseButtons.Left)
				{
					object tag = b.Tag;
					if (!(tag is bool) || !(bool)tag)
					{
						b.BackColor = Skin.Border;
					}
				}
			};
			b.MouseUp += (object _, MouseEventArgs _) =>
			{
				object tag = b.Tag;
				if (!(tag is bool) || !(bool)tag)
				{
					b.BackColor = Color.Transparent;
				}
			};
		}

		private static void ApplyPillRegion(Control c, int radius)
		{
			Region region = c.Region;
			c.Region = new Region(Skin.RoundRect(new Rectangle(0, 0, c.Width, c.Height), radius));
			region?.Dispose();
		}

