		private void RenderRooms()
		{
			roomButtons.Controls.Clear();
			foreach (Room room in store.Rooms)
			{
				bool flag = room.Name == store.Rooms[0].Name;
				Button button = ActionButton(Tr.T(room.Name), 0, 0, 145, 38, flag ? mint : Skin.Kpi);
				button.ForeColor = (flag ? Skin.OnAccent : Skin.TextDim);
				button.FlatAppearance.MouseOverBackColor = (flag ? Skin.AccentPressed : Skin.PillHover);
				ApplyPillRegion(button, 19);
				button.Click += (object _, EventArgs _) =>
				{
					selectedRoom = room.Name;
					selectedTable = Tr.T("No table selected");
					orderLabel.Text = OrderContextText();
					RenderTableMap(room);
				};
				roomButtons.Controls.Add(button);
			}
			if (floorPlanEdit && !HasPermission("Manage rooms"))
			{
				floorPlanEdit = false;
			}
			if (floorPlanEdit)
			{
				Button button2 = ActionButton("Done", 0, 0, 145, 40, Skin.Success);
				button2.Click += (object _, EventArgs _) =>
				{
					floorPlanEdit = false;
					RenderRooms();
					Room room2 = store.Rooms.FirstOrDefault((Room r) => r.Name == selectedRoom);
					if (room2 != null)
					{
						RenderTableMap(room2);
					}
				};
				roomButtons.Controls.Add(button2);
				Button button3 = ActionButton("Reset layout", 0, 0, 145, 40, Skin.Danger);
				button3.Click += (object _, EventArgs _) =>
				{
					Room room2 = floorMapRoom ?? ((store.Rooms.Count > 0) ? store.Rooms[0] : null);
					if (!(room2 == null) && MessageBox.Show(Tr.T("Reset table positions in") + " " + room2.Name + " " + Tr.T("to the default layout?\n(Table names are kept)"), Tr.T("Reset layout"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
					{
						if (store.FloorPlan.TryGetValue(room2.Name, out Dictionary<string, FloorTable> value))
						{
							foreach (FloorTable value2 in value.Values)
							{
								value2.X = null;
								value2.Y = null;
							}
							store.SaveFloorPlan();
							if (store.Features.AuditLog)
							{
								store.LogAudit(currentOperator.Name, "Floor plan", room2.Name + ": reset to default");
							}
						}
						RenderTableMap(room2);
					}
				};
				roomButtons.Controls.Add(button3);
			}
			roomButtons.BringToFront();
			if (store.Rooms.Count > 0)
			{
				RenderTableMap(store.Rooms[0]);
			}
		}

		private void RenderTableMap(Room room)
		{
			floorMapRoom = room;
			tableMap.Controls.Clear();
			Panel panel = new Panel
			{
				Location = new Point(4, 10),
				Size = new Size(3, 22),
				BackColor = mint
			};
			Label label = new Label
			{
				Text = Tr.T(room.Name),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 15f),
				Location = new Point(16, 8),
				ForeColor = Skin.Text
			};
			string text = (floorPlanEdit ? string.Format("{0} {1}  ·  {2}: {3}", room.TableCount, Tr.T("tables"), Tr.T("EDITING"), Tr.T("drag to move, double-click to rename")) : string.Format("{0} {1}", room.TableCount, Tr.T("tables")));
			Label label2 = new Label
			{
				Text = text,
				AutoSize = true,
				Font = new Font("Segoe UI", 9f),
				Location = new Point(18, 34),
				ForeColor = (floorPlanEdit ? Skin.Warning : Skin.TextDim)
			};
			tableMap.Controls.AddRange(new Control[3] { panel, label, label2 });
			for (int i = 1; i <= room.TableCount; i++)
			{
				int tableIndex = i;
				string tableName = TableName(room.Name, tableIndex);
				bool flag = store.GetOpenOrder(room.Name, tableName) != null;
				string text2 = (flag ? Tr.T("Taken") : Tr.T("Available"));
				Reservation reservation = (store.Features.Reservations ? store.Reservations.FirstOrDefault((Reservation r) => r.Status == "Booked" && r.Room == room.Name && r.Table == tableName && r.When.Date == DateTime.Today) : null);
				if (reservation != null && !flag)
				{
					text2 = $"{reservation.When:HH:mm} " + Tr.T("booked");
				}
				Color color;
				if (flag)
				{
					color = Skin.Danger;
				}
				else
				{
					color = ((reservation != null) ? Skin.WarningDeep : Skin.Kpi);
				}
				Button table = ActionButton(floorPlanEdit ? tableName : (tableName + "\n" + text2), 0, 0, 128, 72, color);
				table.Location = TableLocation(room.Name, tableIndex);
				table.ForeColor = ((flag || reservation != null) ? Skin.OnFill : Skin.Text);
				table.Font = new Font("Segoe UI Semibold", 10f);
				table.TextAlign = ContentAlignment.MiddleCenter;
				ApplyPillRegion(table, 12);
				if (floorPlanEdit)
				{
					Point dragStart = default;
					Point origLoc = default;
					bool dragMoved = false;
					DateTime lastLeftUp = DateTime.MinValue;
					table.MouseDown += (object _, MouseEventArgs e) =>
					{
						if (e.Button == MouseButtons.Right)
						{
							RenameTable(room, tableIndex, tableName, () =>
							{
								RenderTableMap(room);
							});
						}
						else if (e.Button == MouseButtons.Left)
						{
							dragStart = e.Location;
							origLoc = table.Location;
							dragMoved = false;
							table.BringToFront();
							table.Capture = true;
						}
					};
					table.MouseMove += (object _, MouseEventArgs _) =>
					{
						if (table.Capture)
						{
							Point location = tableMap.PointToClient(Cursor.Position) - new Size(dragStart);
							location.X = Math.Max(0, Math.Min(Math.Max(0, tableMap.ClientSize.Width - table.Width), location.X));
							location.Y = Math.Max(0, Math.Min(Math.Max(0, tableMap.ClientSize.Height - table.Height), location.Y));
							table.Location = location;
							if (Math.Abs(location.X - origLoc.X) > 4 || Math.Abs(location.Y - origLoc.Y) > 4)
							{
								dragMoved = true;
							}
						}
					};
					table.MouseUp += (object _, MouseEventArgs e) =>
					{
						if (e.Button == MouseButtons.Left)
						{
							table.Capture = false;
							if (dragMoved)
							{
								SaveTableSpot(room.Name, tableIndex, table.Location);
								lastLeftUp = DateTime.MinValue;
							}
							else
							{
								DateTime now = DateTime.Now;
								if (lastLeftUp != DateTime.MinValue && (now - lastLeftUp).TotalMilliseconds <= 450.0)
								{
									lastLeftUp = DateTime.MinValue;
									RenameTable(room, tableIndex, tableName, () =>
									{
										RenderTableMap(room);
									});
								}
								else
								{
									lastLeftUp = now;
								}
							}
						}
					};
				}
				else
				{
					table.Click += (object _, EventArgs _) =>
					{
						selectedRoom = room.Name;
						selectedTable = tableName;
						basket.Clear();
						activeSeat = 1;
						hasOpenOrder = false;
						OpenOrder openOrder = store.GetOpenOrder(room.Name, tableName);
						if ((object)openOrder != null)
						{
							hasOpenOrder = true;
							foreach (SoldLine item in openOrder.Items)
							{
								Product product = products.FirstOrDefault((Product p) => p.Name == item.Product);
								if (product != null)
								{
									int num = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) b) => b.Product == product && b.Note == item.Note && b.Modifiers == item.Modifiers && (!store.Features.SeatOrdering || b.Seat == item.Seat));
									if (num >= 0)
									{
										basket[num] = (product, basket[num].Count + item.Quantity, basket[num].Course, basket[num].Note, item.Seat, JoinMods(basket[num].Modifiers, item.Modifiers));
									}
									else
									{
										basket.Add((product, item.Quantity, item.Course, item.Note, item.Seat, item.Modifiers));
									}
								}
							}
						}
						UpdateOrderButtons();
						RenderBasket();
						orderLabel.Text = OrderContextText();
						ShowOrder();
					};
				}
				tableMap.Controls.Add(table);
			}
		}

		private string TableName(string roomName, int index)
		{
			if (!store.FloorPlan.TryGetValue(roomName, out Dictionary<string, FloorTable> value) || !value.TryGetValue(index.ToString(), out var value2) || string.IsNullOrWhiteSpace(value2.Name))
			{
				return Tr.T("Table") + " " + index;
			}
			return value2.Name;
		}

		private Point TableLocation(string roomName, int index)
		{
			if (store.FloorPlan.TryGetValue(roomName, out Dictionary<string, FloorTable> value) && value.TryGetValue(index.ToString(), out var value2))
			{
				int? num = value2.X;
				if (num.HasValue)
				{
					int valueOrDefault = num.GetValueOrDefault();
					num = value2.Y;
					if (num.HasValue)
					{
						int valueOrDefault2 = num.GetValueOrDefault();
						return new Point(valueOrDefault, valueOrDefault2);
					}
				}
			}
			int num2 = index - 1;
			return new Point(10 + num2 % 4 * 150, 48 + num2 / 4 * 98);
		}

		private FloorTable FloorEntry(string roomName, int index)
		{
			if (!store.FloorPlan.TryGetValue(roomName, out Dictionary<string, FloorTable> value))
			{
				value = (store.FloorPlan[roomName] = new Dictionary<string, FloorTable>());
			}
			if (!value.TryGetValue(index.ToString(), out var value2))
			{
				value2 = (value[index.ToString()] = new FloorTable());
			}
			return value2;
		}

		private void SaveTableSpot(string roomName, int index, Point location)
		{
			FloorTable floorTable = FloorEntry(roomName, index);
			floorTable.X = location.X;
			floorTable.Y = location.Y;
			store.SaveFloorPlan();
			if (store.Features.AuditLog)
			{
				store.LogAudit(currentOperator.Name, "Floor plan", $"{roomName}/{TableName(roomName, index)} → ({location.X},{location.Y})");
			}
		}

		private void RenameTable(Room room, int index, string currentName, Action refresh)
		{
			if (store.GetOpenOrder(room.Name, currentName) != null)
			{
				MessageBox.Show(Tr.T("This table has an open order - pay or transfer it before renaming."), Tr.T("Rename table"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			Form form = new Form
			{
				Text = Tr.T("Rename table"),
				Size = new Size(320, 170),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				TextBox textBox = new TextBox
				{
					Location = new Point(15, 15),
					Size = new Size(285, 30),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					Text = currentName
				};
				Button button = new Button
				{
					Text = Tr.T("Rename"),
					Location = new Point(15, 60),
					Size = new Size(135, 34),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.OK;
				};
				Button button2 = new Button
				{
					Text = Tr.T("Cancel"),
					Location = new Point(165, 60),
					Size = new Size(135, 34),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.Cancel;
				};
				form.Controls.AddRange(new Control[3] { textBox, button, button2 });
				form.AcceptButton = button;
				form.CancelButton = button2;
				if (form.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				string text = textBox.Text.Trim();
				if (string.IsNullOrWhiteSpace(text) || text == currentName)
				{
					return;
				}
				if (store.GetOpenOrder(room.Name, text) != null)
				{
					MessageBox.Show(text + " " + Tr.T("already has an open order."), Tr.T("Rename table"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					return;
				}
				for (int num = 1; num <= room.TableCount; num++)
				{
					if (num != index && TableName(room.Name, num) == text)
					{
						MessageBox.Show(Tr.T("Another table is already named") + " " + text + ".", Tr.T("Rename table"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
						return;
					}
				}
				FloorEntry(room.Name, index).Name = text;
				store.SaveFloorPlan();
				if (store.Features.AuditLog)
				{
					store.LogAudit(currentOperator.Name, "Rename", room.Name + ": " + currentName + " → " + text);
				}
				refresh();
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
		}

