		private void ShowView(Panel content, string title, Action? onBack = null)
		{
			SetActiveNav(null);
			mainHeader.Visible = false;
			workspacePanel.Visible = false;
			menuPanel.Visible = false;
			roomsPanel.Visible = false;
			viewPanel.Controls.Clear();
