			if (sub != null)
			{
				sub.OnBackAction = onBack ?? ShowSettings;
				sub.FormClosed += (s, e) => (onBack ?? ShowSettings)();
			}
			else
			{
				Form? form = content.Controls.OfType<Form>().FirstOrDefault();
				if (form != null)
				{
					form.FormClosed += (s, e) => (onBack ?? ShowSettings)();
				}
			}
			SkinPanel skinPanel = new SkinPanel
			{
				Dock = DockStyle.Top,
				Height = 64,
				BackColor = background,
				Gradient = false,
				Padding = new Padding(16, 0, 16, 0)
			};
			Panel value = new Panel
			{
				Location = new Point(4, 24),
				Size = new Size(3, 20),
				BackColor = mint
			};
			Label value2 = new Label
			{
				Text = Tr.T(title),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 17f),
				ForeColor = Skin.Text,
				Location = new Point(18, 20)
			};
			Button button = new Button
			{
				Text = Tr.T("← Back"),
				Location = new Point(viewPanel.ClientSize.Width - 120, 15),
				Size = new Size(104, 34),
				BackColor = Skin.Kpi,
				ForeColor = Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Anchor = (AnchorStyles.Top | AnchorStyles.Right),
				Cursor = Cursors.Hand
			};
			button.FlatAppearance.BorderSize = 0;
			button.FlatAppearance.MouseOverBackColor = Skin.PillHover;
			ApplyPillRegion(button, 17);
			button.Click += (object _, EventArgs _) =>
			{
				if (onBack != null)
				{
					onBack();
				}
				else
				{
					ShowOrder();
				}
			};
			Panel value3 = new Panel
			{
				Dock = DockStyle.Bottom,
				Height = 1,
				BackColor = Skin.Border
			};
			skinPanel.Controls.Add(value2);
			skinPanel.Controls.Add(value);
			skinPanel.Controls.Add(button);
			skinPanel.Controls.Add(value3);
			content.Dock = DockStyle.Fill;
			content.Padding = (title == "Settings" || sub != null) ? Padding.Empty : new Padding(16);
			content.BackColor = background;
			viewPanel.Controls.Add(content);
			if (title != "Settings" && sub == null)
			{
				viewPanel.Controls.Add(skinPanel);
			}
			viewPanel.Visible = true;
			viewPanel.BringToFront();
			Rtl.Apply(viewPanel);
		}

		private void Update86Banner()
		{
			if (auto86Banner == null) return;
			int count = store.Auto86.Count;
			if (count == 0 || !store.Features.Auto86)
			{
				auto86Banner.Visible = false;
			}
			else
			{
				string names = string.Join(", ", store.Auto86.Take(3));
				if (count > 3) names += $" +{count - 3} " + Tr.T("more");
				auto86Label.Text = $"⚠ {count} " + Tr.T("items out of stock (86'd):") + " " + names;
				auto86Banner.Visible = true;
			}
		}

		private void UpdateStockPill()
		{
			if (stockPill == null) return;
			if (!store.Features.InventoryAlerts)
			{
				stockPill.Visible = false;
				LayoutAppBar();
				return;
			}
			int low = StockEngine.Low(store).Count;
			if (low > 0)
			{
				stockPill.Text = $"● {low} " + Tr.T("low");
				int w = TextRenderer.MeasureText(stockPill.Text, stockPill.Font).Width + 24;
				stockPill.Size = new Size(Math.Max(84, w), 34);
				ApplyPillRegion(stockPill, 16);
				stockPill.Visible = true;
			}
			else
			{
				stockPill.Visible = false;
			}
			LayoutAppBar();
		}

