		private static string JoinMods(string a, string b)
		{
			if (string.IsNullOrWhiteSpace(a))
			{
				return b ?? "";
			}
			if (string.IsNullOrWhiteSpace(b))
			{
				return a;
			}
			return string.Join(", ", new string[2] { a, b }.Where((string s) => !string.IsNullOrWhiteSpace(s)));
		}

		private string CourseLabel(int n)
		{
			List<string> courseNames = store.CourseNames;
			if (n <= 0 || courseNames.Count < n || string.IsNullOrWhiteSpace(courseNames[n - 1]))
			{
				return $"C{n}";
			}
			return courseNames[n - 1];
		}

		private void EditBasketItemChips((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) item)
		{
			int idx = basket.IndexOf(item);
			if (idx < 0)
			{
				return;
			}
			Form dlg = new Form
			{
				Text = item.Product.Name + " - Quick options",
				Size = new Size(440, 460),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				List<string> list = (from m in (item.Modifiers ?? "").Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries)
					select m.Trim()).ToList();
				decimal oldPrice = ((IEnumerable<string>)list).Sum((Func<string, decimal>)ModPrice);
				FlowLayoutPanel flowLayoutPanel = new FlowLayoutPanel
				{
					Dock = DockStyle.Fill,
					FlowDirection = FlowDirection.TopDown,
					AutoScroll = true,
					WrapContents = false,
					BackColor = background,
					Padding = new Padding(10)
				};
				List<(Button btn, string name, bool on)> toggles = new List<(Button, string, bool)>();
				foreach (ModifierGroup modifierGroup in store.ModifierGroups)
				{
					flowLayoutPanel.Controls.Add(new Label
					{
						Text = modifierGroup.Name,
						AutoSize = true,
						Font = new Font("Segoe UI Semibold", 10f),
						ForeColor = mint,
						Margin = new Padding(0, 8, 0, 2)
					});
					foreach (ModifierOption option in modifierGroup.Options)
					{
						bool flag = list.Contains(option.Name);
						string name = option.Name;
						Button btn = new Button
						{
							Text = $"{option.Name}  {option.Price:+0.00;-0.00;}",
							AutoSize = true,
							FlatStyle = FlatStyle.Flat,
							Margin = new Padding(14, 3, 0, 3),
							BackColor = (flag ? mint : panelLight),
							ForeColor = (flag ? Skin.OnAccent : Skin.Text),
							TextAlign = ContentAlignment.MiddleCenter
						};
						btn.FlatAppearance.BorderSize = 0;
						(Button, string, bool) item2 = (btn, name, flag);
						toggles.Add(item2);
						btn.Click += (object _, EventArgs _) =>
						{
							int index = toggles.FindIndex(((Button btn, string name, bool on) t) => t.btn == btn);
							(Button, string, bool) tuple = toggles[index];
							toggles[index] = (tuple.Item1, tuple.Item2, !tuple.Item3);
							btn.BackColor = ((!tuple.Item3) ? mint : panelLight);
							btn.ForeColor = ((!tuple.Item3) ? Skin.OnAccent : Skin.Text);
						};
						flowLayoutPanel.Controls.Add(btn);
					}
				}
				flowLayoutPanel.Controls.Add(new Label
				{
					Text = Tr.T("Free note"),
					AutoSize = true,
					Font = new Font("Segoe UI Semibold", 10f),
					ForeColor = mint,
					Margin = new Padding(0, 12, 0, 2)
				});
				TextBox noteBox = new TextBox
				{
					Text = (item.Note ?? ""),
					Width = 370,
					BackColor = panelLight,
					ForeColor = Skin.Text,
					BorderStyle = BorderStyle.FixedSingle,
					Margin = new Padding(4, 2, 0, 2)
				};
				flowLayoutPanel.Controls.Add(noteBox);
				Button button = new Button
				{
					Text = Tr.T("Apply"),
					Size = new Size(110, 36),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat,
					Margin = new Padding(0, 14, 0, 0)
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					List<string> list2 = (from t in toggles
						where t.@on
						select t.name).ToList();
					decimal num = ((IEnumerable<string>)list2).Sum((Func<string, decimal>)ModPrice) - oldPrice;
					Product product = basket[idx].Product._003CClone_003E_0024();
					product.Price = Math.Max(0m, basket[idx].Product.Price + num);
					Product item3 = product;
					basket[idx] = (item3, basket[idx].Count, basket[idx].Course, noteBox.Text.Trim(), basket[idx].Seat, string.Join(", ", list2));
					dlg.DialogResult = DialogResult.OK;
				};
				flowLayoutPanel.Controls.Add(button);
				dlg.Controls.Add(flowLayoutPanel);
				dlg.ShowDialog();
				RenderBasket();
			}
			finally
			{
				if (dlg != null)
				{
					((IDisposable)dlg).Dispose();
				}
			}
			decimal ModPrice(string text)
			{
				return store.ModifierGroups.SelectMany((ModifierGroup g) => g.Options).FirstOrDefault((ModifierOption o) => o.Name == text)?.Price ?? 0m;
			}
		}

		private List<SoldLine> BasketToLines()
		{
			return basket.Select(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) item) => new SoldLine(item.Product.Name, item.Product.Family, item.Count, item.Product.Price, item.Product.Category, ResolvePrinter(item.Product), item.Note, item.Modifiers, 0m, "", Seat: item.Seat, Course: item.Course)).ToList();
		}

		private void LoadLinesIntoBasket(IEnumerable<SoldLine> lines)
		{
			foreach (SoldLine li in lines)
			{
				if (li.Quantity > 0)
				{
					Product product = products.FirstOrDefault((Product x) => x.Name == li.Product) ?? new Product(li.Product, li.Category, li.UnitPrice, "#777777", li.Family, "", li.PrinterDestination);
					Product product2;
					if (!(product.Price == li.UnitPrice))
					{
						product2 = product._003CClone_003E_0024();
						product2.Price = li.UnitPrice;
					}
					else
					{
						product2 = product;
					}
					Product prod = product2;
					int num = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) b) => b.Product.Name == prod.Name && b.Note == li.Note && b.Modifiers == li.Modifiers);
					if (num >= 0)
					{
						basket[num] = (prod, basket[num].Count + li.Quantity, basket[num].Course, basket[num].Note, basket[num].Seat, basket[num].Modifiers);
					}
					else
					{
						basket.Add((prod, li.Quantity, store.Features.CourseManagement ? li.Course : 0, li.Note, (store.Features.SeatOrdering && li.Seat > 0) ? li.Seat : (store.Features.SeatOrdering ? activeSeat : 0), li.Modifiers));
					}
				}
			}
			RenderBasket();
			UpdateOrderButtons();
		}

		private void RepeatLastOrder()
		{
			List<(string label, Sale sale)> candidates = new List<(string, Sale)>();
			HashSet<int> seen = new HashSet<int>();
			Add(store.Sales.LastOrDefault((Sale s) =>
			{
				if (!s.IsRefund && s.Table == selectedTable)
				{
					List<SoldLine> items = s.Items;
					if (items != null)
					{
						return items.Count > 0;
					}
					return false;
				}
				return false;
			}), "Last at " + selectedTable);
			Add(store.Sales.LastOrDefault((Sale s) =>
			{
				if (!s.IsRefund && s.Operator == currentOperator.Name)
				{
					List<SoldLine> items = s.Items;
					if (items != null)
					{
						return items.Count > 0;
					}
					return false;
				}
				return false;
			}), "My last sale");
			if (store.Features.CustomerDatabase)
			{
				foreach (Customer c in store.Customers)
				{
					Add(store.Sales.LastOrDefault((Sale s) =>
					{
						if (!s.IsRefund && s.CustomerName == c.Name)
						{
							List<SoldLine> items = s.Items;
							if (items != null)
							{
								return items.Count > 0;
							}
							return false;
						}
						return false;
					}), c.Name + "'s usual");
				}
			}
			if (candidates.Count == 0)
			{
				MessageBox.Show(Tr.T("No previous orders found yet."), Tr.T("Repeat order"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			Form dlg = new Form
			{
				Text = Tr.T("Repeat an order"),
				Size = new Size(460, 230),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Label label = new Label
				{
					Text = Tr.T("Loads the selected order into the basket (nothing prints until you press Order):"),
					AutoSize = true,
					MaximumSize = new Size(410, 0),
					Location = new Point(14, 12),
					ForeColor = Skin.TextDim
				};
				ComboBox combo = new ComboBox
				{
					FlatStyle = FlatStyle.Flat,
					Location = new Point(14, 52),
					Width = 410,
					DropDownStyle = ComboBoxStyle.DropDownList,
					BackColor = panelLight,
					ForeColor = Skin.Text
				};
				foreach (var (arg, sale) in candidates)
				{
					combo.Items.Add($"{arg}  •  {sale.Time:g}  •  {sale.Total:C}");
				}
				combo.SelectedIndex = 0;
				Button button = new Button
				{
					Text = Tr.T("Load into basket"),
					Location = new Point(14, 96),
					Size = new Size(180, 36),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					LoadLinesIntoBasket(candidates[combo.SelectedIndex].sale.Items);
					dlg.DialogResult = DialogResult.OK;
				};
				Button button2 = new Button
				{
					Text = Tr.T("Cancel"),
					Location = new Point(204, 96),
					Size = new Size(120, 36),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					dlg.DialogResult = DialogResult.Cancel;
				};
				dlg.Controls.AddRange(new Control[4] { label, combo, button, button2 });
				dlg.AcceptButton = button;
				dlg.CancelButton = button2;
				dlg.ShowDialog();
			}
			finally
			{
				if (dlg != null)
				{
					((IDisposable)dlg).Dispose();
				}
			}
			Sale? Add(Sale? s, string item)
			{
				if (s != null && seen.Add(s.PaymentNumber))
				{
					List<SoldLine> items = s.Items;
					if (items != null && items.Count > 0)
					{
						candidates.Add((item, s));
					}
				}
				return s;
			}
		}

		private void ShowParkRecall()
		{
			ListView list;
			using (Form form = new Form
			{
				Text = Tr.T("Park & recall"),
				Size = new Size(500, 440),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			})
			{
				Button button = new Button
				{
					Text = Tr.T("Park current order"),
					Location = new Point(14, 12),
					Size = new Size(200, 36),
					BackColor = Skin.WarningDeep,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				Label label = new Label
				{
					Text = Tr.T("Parks it off the table; recall it any time into the current table."),
					AutoSize = true,
					Location = new Point(222, 22),
					ForeColor = Skin.TextDim
				};
				list = new ListView
				{
					Location = new Point(14, 60),
					Size = new Size(455, 260),
					View = View.Details,
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FullRowSelect = true,
					GridLines = true,
					HeaderStyle = ColumnHeaderStyle.Nonclickable
				};
				list.Columns.AddRange(new ColumnHeader[4]
				{
					new ColumnHeader
					{
						Text = Tr.T("Parked"),
						Width = 130
					},
					new ColumnHeader
					{
						Text = Tr.T("From"),
						Width = 150
					},
					new ColumnHeader
					{
						Text = Tr.T("Items"),
						Width = 60
					},
					new ColumnHeader
					{
						Text = Tr.T("By"),
						Width = 90
					}
				});
				RefreshList();
				button.Click += (object _, EventArgs _) =>
				{
					List<SoldLine> list2;
					if (hasOpenOrder)
					{
						OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
						if (openOrder == null)
						{
							return;
						}
						list2 = openOrder.Items;
						store.RemoveOpenOrder(selectedRoom, selectedTable);
						hasOpenOrder = false;
					}
					else
					{
						list2 = BasketToLines();
					}
					if (list2.Count == 0)
					{
						MessageBox.Show(Tr.T("Nothing to park - the order is empty."), Tr.T("Park"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else
					{
						store.ParkedOrders.Add(new ParkedOrder($"P{DateTime.Now:yyyyMMddHHmmssfff}", selectedRoom, selectedTable, currentOperator.Name, DateTime.Now, list2));
						store.SaveParkedOrders(store.ParkedOrders);
						basket.Clear();
						activeSeat = 1;
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Park order", $"{selectedRoom}/{selectedTable}: {list2.Sum((SoldLine l) => l.Quantity)} items");
						}
						RenderBasket();
						UpdateOrderButtons();
						orderLabel.Text = OrderContextText();
						RefreshList();
					}
				};
				Button button2 = new Button
				{
					Text = Tr.T("Recall selected"),
					Location = new Point(14, 332),
					Size = new Size(160, 36),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					if (list.SelectedItems.Count == 0)
					{
						MessageBox.Show(Tr.T("Select a parked order first."), Tr.T("Recall"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else
					{
						string id = (string)list.SelectedItems[0].Tag;
						ParkedOrder parkedOrder = store.ParkedOrders.FirstOrDefault((ParkedOrder p) => p.Id == id);
						if (!(parkedOrder == null) && ((!hasOpenOrder && basket.Count <= 0) || MessageBox.Show(Tr.T("The current table has items. Add the parked order on top of them?"), Tr.T("Recall"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes))
						{
							LoadLinesIntoBasket(parkedOrder.Items);
							store.ParkedOrders.Remove(parkedOrder);
							store.SaveParkedOrders(store.ParkedOrders);
							if (store.Features.AuditLog)
							{
								store.LogAudit(currentOperator.Name, "Recall order", parkedOrder.Room + "/" + parkedOrder.Table + " → " + selectedRoom + "/" + selectedTable);
							}
							RefreshList();
						}
					}
				};
				Button button3 = new Button
				{
					Text = Tr.T("Discard"),
					Location = new Point(184, 332),
					Size = new Size(110, 36),
					BackColor = Skin.DangerStrong,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat
				};
				button3.FlatAppearance.BorderSize = 0;
				button3.Click += (object _, EventArgs _) =>
				{
					if (list.SelectedItems.Count != 0 && MessageBox.Show(Tr.T("Discard the selected parked order?"), Tr.T("Recall"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
					{
						string id = (string)list.SelectedItems[0].Tag;
						ParkedOrder parkedOrder = store.ParkedOrders.FirstOrDefault((ParkedOrder p) => p.Id == id);
						if (!(parkedOrder == null))
						{
							store.ParkedOrders.Remove(parkedOrder);
							store.SaveParkedOrders(store.ParkedOrders);
							RefreshList();
						}
					}
				};
				form.Controls.AddRange(new Control[5] { button, label, list, button2, button3 });
				form.ShowDialog();
				UpdateOrderButtons();
			}
			void RefreshList()
			{
				list.Items.Clear();
				foreach (ParkedOrder item in store.ParkedOrders.OrderByDescending((ParkedOrder p) => p.Time))
				{
					list.Items.Add(new ListViewItem(new string[4]
					{
						item.Time.ToString("dd/MM HH:mm"),
						item.Room + " / " + item.Table,
						item.Items.Sum((SoldLine i) => i.Quantity).ToString(),
						item.Operator
					})
					{
						Tag = item.Id
					});
				}
			}
		}

		private void ShowDealsDialog()
		{
			if (store.ComboDeals.Count == 0)
			{
				MessageBox.Show(Tr.T("No combo deals set up yet. Add them in Settings → Ordering → Manage combo deals."), Tr.T("Deals"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			Form dlg = new Form
			{
				Text = Tr.T("Combo deals"),
				Size = new Size(460, 360),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				ListView list = new ListView
				{
					Location = new Point(14, 14),
					Size = new Size(415, 230),
					View = View.Details,
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FullRowSelect = true,
					GridLines = true,
					HeaderStyle = ColumnHeaderStyle.Nonclickable
				};
				list.Columns.AddRange(new ColumnHeader[3]
				{
					new ColumnHeader
					{
						Text = Tr.T("Deal"),
						Width = 200
					},
					new ColumnHeader
					{
						Text = Tr.T("Price"),
						Width = 80
					},
					new ColumnHeader
					{
						Text = Tr.T("Includes"),
						Width = 130
					}
				});
				foreach (ComboDeal comboDeal2 in store.ComboDeals)
				{
					list.Items.Add(new ListViewItem(new string[3]
					{
						comboDeal2.Name,
						comboDeal2.Price.ToString("C"),
						string.Join(", ", comboDeal2.Items.Select((ComboComponent i) => $"{i.Qty}× {i.Product}"))
					})
					{
						Tag = comboDeal2.Name
					});
				}
				if (list.Items.Count > 0)
				{
					list.Items[0].Selected = true;
				}
				Button button = new Button
				{
					Text = Tr.T("Add to order"),
					Location = new Point(14, 260),
					Size = new Size(160, 36),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					if (list.SelectedItems.Count == 0)
					{
						MessageBox.Show(Tr.T("Select a deal first."), Tr.T("Deals"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else
					{
						string name = (string)list.SelectedItems[0].Tag;
						ComboDeal comboDeal = store.ComboDeals.FirstOrDefault((ComboDeal d) => d.Name == name);
						if (!(comboDeal == null))
						{
							int item = (store.Features.SeatOrdering ? activeSeat : 0);
							int courseManagement = (store.Features.CourseManagement ? 1 : 0);
							basket.Add((new Product(comboDeal.Name, "Deals", comboDeal.Price, "#C94C7A", "Deals"), 1, courseManagement, "", item, ""));
							foreach (ComboComponent comp in comboDeal.Items)
							{
								Product product = products.FirstOrDefault((Product x) => x.Name == comp.Product);
								if (!(product == null))
								{
									List<(Product Product, int Count, int Course, string Note, int Seat, string Modifiers)> list2 = basket;
									Product product2 = product._003CClone_003E_0024();
									product2.Price = 0m;
									list2.Add((product2, comp.Qty, courseManagement, "in " + comboDeal.Name, item, ""));
								}
							}
							RenderBasket();
							dlg.DialogResult = DialogResult.OK;
						}
					}
				};
				Button button2 = new Button
				{
					Text = Tr.T("Close"),
					Location = new Point(184, 260),
					Size = new Size(110, 36),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					dlg.DialogResult = DialogResult.Cancel;
				};
				dlg.Controls.AddRange(new Control[3] { list, button, button2 });
				dlg.AcceptButton = button;
				dlg.ShowDialog();
			}
			finally
			{
				if (dlg != null)
				{
					((IDisposable)dlg).Dispose();
				}
			}
		}

		private void QuickSaleStart()
		{
			if (basket.Count > 0 || hasOpenOrder)
			{
				if (MessageBox.Show(Tr.T("Clear the current order and start a quick sale?"), Tr.T("Quick sale"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes || (hasOpenOrder && MessageBox.Show(Tr.T("An order is open at the current table - it will stay open (not deleted). Continue?"), Tr.T("Quick sale"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes))
				{
					return;
				}
				basket.Clear();
				RenderBasket();
			}
			selectedRoom = "Counter";
			selectedTable = "Counter " + DateTime.Now.ToString("HHmm");
			activeSeat = 1;
			hasOpenOrder = false;
			ShowOrder();
			orderLabel.Text = OrderContextText();
			UpdateOrderButtons();
			barcodeBox?.Focus();
		}

