		private void LaunchKiosk()
		{
			if (kioskForm != null && !kioskForm.IsDisposed)
			{
				kioskForm.Activate();
				return;
			}
			kioskForm = new KioskForm(background, panelLight, mint, products.ToList(), ResolvePrinter, (List<SoldLine> lines) =>
			{
				string room = "Kiosk";
				string text = "Kiosk " + DateTime.Now.ToString("HHmmss");
				int num = store.NextOrderNumber();
				store.AddOpenOrder(new OpenOrder(room, text, "Kiosk", DateTime.Now, lines, "", num, num, "Takeaway", "", 0, Ready: false, 0, "Kiosk"));
				PrintTickets(lines, num, 0, "Takeaway", room, text);
				if (store.Features.AuditLog)
				{
					store.LogAudit("Kiosk", "Order sent", $"{text}: {lines.Sum((SoldLine l) => l.Quantity)} items, order #{num}");
				}
			});
			kioskForm.FormClosed += (object _, FormClosedEventArgs _) =>
			{
				kioskForm = null;
			};
			kioskForm.Show();
		}

		private void ShowCustomerDisplay()
		{
			if (custDisplay != null && !custDisplay.IsDisposed)
			{
				custDisplay.Activate();
				return;
			}
			custDisplay = new CustomerDisplayForm(background, mint);
			custDisplay.FormClosed += (object _, FormClosedEventArgs _) =>
			{
				custDisplay = null;
			};
			custDisplay.Show();
			custDisplay.SetOrder(selectedRoom + " / " + selectedTable, basket.Select(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) i) => ($"{i.Count} × {i.Product.Name}", i.Product.Price * (decimal)i.Count)).ToList(), NetTotal());
		}

