					FlatStyle = FlatStyle.Flat
				};
				button5.FlatAppearance.BorderSize = 0;
				button5.Click += (object _, EventArgs _) =>
				{
					if (list.SelectedItems.Count != 0)
					{
						ComboDeal comboDeal = store.ComboDeals.FirstOrDefault((ComboDeal x) => x.Name == (string)list.SelectedItems[0].Tag);
						if (!(comboDeal == null))
						{
							nameBox.Text = comboDeal.Name;
							priceBox.Value = comboDeal.Price;
							comps.Items.Clear();
							foreach (ComboComponent item in comboDeal.Items)
							{
								comps.Items.Add(new ListViewItem(new string[2]
								{
									item.Product,
									item.Qty.ToString()
								}));
							}
						}
					}
				};
				Button button6 = new Button
				{
					Text = Tr.T("Delete deal"),
					Location = new Point(394, 404),
					Size = new Size(132, 36),
					BackColor = Skin.DangerStrong,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat
				};
				button6.FlatAppearance.BorderSize = 0;
				button6.Click += (object _, EventArgs _) =>
				{
					if (list.SelectedItems.Count != 0 && MessageBox.Show(Tr.T("Delete the selected deal?"), Tr.T("Combo deals"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
					{
						string nm = (string)list.SelectedItems[0].Tag;
						store.ComboDeals.RemoveAll((ComboDeal d) => d.Name == nm);
						store.SaveComboDeals(store.ComboDeals);
						RefreshDeals();
						UpdateOrderButtons();
					}
				};
				form.Controls.AddRange(new Control[15]
				{
					list, label, nameBox, label2, priceBox, label3, comps, prodCombo, qtyBox, button,
					button2, button3, button4, button5, button6
				});
				form.ShowDialog();
				UpdateOrderButtons();
			}
			void RefreshDeals()
			{
				list.Items.Clear();
				foreach (ComboDeal comboDeal2 in store.ComboDeals)
				{
					list.Items.Add(new ListViewItem(new string[2]
					{
						comboDeal2.Name,
						comboDeal2.Price.ToString("C")
					})
					{
						Tag = comboDeal2.Name
					});
				}
			}
		}

		private void RenderBasket()
		{
			basketList.SuspendLayout();
			basketList.Controls.Clear();
			if (basket.Count == 0)
			{
				Label value = new Label
				{
					Text = Tr.T("No products selected yet"),
					AutoSize = true,
					ForeColor = Skin.TextSoft,
					Font = new Font("Segoe UI Semibold", 11f),
					Margin = new Padding(0, 14, 0, 2)
				};
				Label value2 = new Label
				{
					Text = Tr.T("Choose products from the menu."),
					AutoSize = true,
					ForeColor = Skin.TextFaint,
					Font = new Font("Segoe UI", 9f),
					Margin = new Padding(0, 0, 0, 8)
				};
				basketList.Controls.Add(value);
				basketList.Controls.Add(value2);
			}
			foreach (var item in basket)
			{
				int num = Math.Max(220, basketList.ClientSize.Width - 8);
				bool flag = !string.IsNullOrWhiteSpace(item.Note);
				bool flag2 = !string.IsNullOrWhiteSpace(item.Modifiers);
				Panel panel = new Panel
				{
					Width = num,
					Height = ((flag & flag2) ? 96 : ((flag | flag2) ? 78 : 58)),
					BackColor = panelLight,
					Margin = new Padding(0, 0, 0, 8),
					Padding = new Padding(12, 8, 8, 6)
				};
				int radius = Math.Max(6, panel.Height / 24);
				panel.Region = new Region(ButtonRoundRect(new Rectangle(0, 0, num, panel.Height), radius));
				string arg = ((store.Features.SeatOrdering && item.Seat > 0) ? $"[S{item.Seat}] " : "");
				Label label = new Label
				{
					Text = $"{arg}{item.Count} × {item.Product.Name}",
					AutoSize = true,
					Location = new Point(10, 8)
				};
				Label label2 = new Label
				{
					Text = $"{item.Product.Price:C} each  •  {item.Product.Price * (decimal)item.Count:C}",
					AutoSize = true,
					ForeColor = mint,
					Location = new Point(10, 30)
				};
				int num2 = 52;
				if (flag2)
				{
					Label value3 = new Label
					{
						Text = Tr.T("+ ") + item.Modifiers,
						AutoSize = true,
						ForeColor = Skin.ModifierText,
						Location = new Point(10, num2),
						Font = new Font("Segoe UI", 8f),
						MaximumSize = new Size(num - 130, 0)
					};
					panel.Controls.Add(value3);
					num2 += 18;
				}
				if (flag)
				{
					Label value4 = new Label
					{
						Text = Tr.T("✎ ") + item.Note,
						AutoSize = true,
						ForeColor = Skin.NoteText,
						Location = new Point(10, num2),
						Font = new Font("Segoe UI", 8f),
						MaximumSize = new Size(num - 130, 0)
					};
					panel.Controls.Add(value4);
				}
				int num3 = (hasOpenOrder ? (num - 66) : (num - 38));
				int num4 = num3;
				if (store.Features.CourseManagement)
				{
					int item2 = item.Course;
					string text = ((item2 > 0) ? CourseLabel(item2) : "C");
					int num5 = Math.Max(34, TextRenderer.MeasureText(text, new Font("Segoe UI Semibold", 8f)).Width + 14);
					num4 = num3 - 6 - num5;
					Button button = new Button
					{
						Text = text,
						Size = new Size(num5, 28),
						Location = new Point(num4, 13),
						FlatStyle = FlatStyle.Flat,
						BackColor = Skin.WarningDeep,
						ForeColor = Skin.OnFill,
						Font = new Font("Segoe UI Semibold", 8f)
					};
					button.FlatAppearance.BorderSize = 0;
					button.Click += (object _, EventArgs _) =>
					{
						int num6 = basket.IndexOf(item);
						if (num6 >= 0)
						{
							int item3 = ((basket[num6].Course >= 5) ? 1 : (basket[num6].Course + 1));
							basket[num6] = (basket[num6].Product, basket[num6].Count, item3, basket[num6].Note, basket[num6].Seat, basket[num6].Modifiers);
							RenderBasket();
						}
					};
					panel.Controls.Add(button);
					ApplyFlatStates(button);
				}
				num4 -= 40;
				Button button2 = new Button
				{
					Text = Tr.T("✎+"),
					Size = new Size(34, 28),
					Location = new Point(num4, 13),
					FlatStyle = FlatStyle.Flat,
					BackColor = Skin.InfoAlt,
					ForeColor = Skin.OnFill,
					Font = new Font("Segoe UI Semibold", 8f)
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					EditBasketItemChips(item);
				};
				panel.Controls.Add(button2);
				ApplyFlatStates(button2);
				if (hasOpenOrder)
				{
					Button button3 = new Button
					{
						Text = Tr.T("Cancel"),
						Size = new Size(56, 28),
						Location = new Point(num - 66, 13),
						FlatStyle = FlatStyle.Flat,
						BackColor = Skin.DangerStrong,
						ForeColor = Skin.OnFill
					};
					button3.FlatAppearance.BorderSize = 0;
					button3.Click += (object _, EventArgs _) =>
					{
						CancelItem(item.Product);
					};
					panel.Controls.Add(button3);
					ApplyFlatStates(button3);
				}
				else
				{
					Button button4 = new Button
					{
						Text = Tr.T("×"),
						Size = new Size(28, 28),
						Location = new Point(num - 38, 13),
						FlatStyle = FlatStyle.Flat,
						BackColor = Color.Transparent,
						ForeColor = Skin.TextSoft
					};
					button4.FlatAppearance.BorderSize = 0;
					button4.Click += (object _, EventArgs _) =>
					{
						basket.Remove(item);
						RenderBasket();
					};
					panel.Controls.Add(button4);
					ApplyFlatStates(button4);
				}
				panel.Controls.AddRange(new Control[2] { label, label2 });
				basketList.Controls.Add(panel);
			}
			if (basket.Count == 0)
			{
				basketDiscountPercent = 0m;
			}
			UpdateOrderButtons();
			RenderSeatBar();
			totalLabel.Text = NetTotal().ToString("C");
			custDisplay?.SetOrder(selectedRoom + " / " + selectedTable, basket.Select(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) i) => ($"{i.Count} × {i.Product.Name}", i.Product.Price * (decimal)i.Count)).ToList(), NetTotal());
			discountButton.Text = ((basketDiscountPercent > 0m) ? string.Format("{0} {1:0.#}%", Tr.T("Discount"), basketDiscountPercent) : Tr.T("Discount"));
			discountButton.Visible = store.Features.Discounts && (currentOperator == null || HasPermission("Discounts"));
			basketList.ResumeLayout();
		}

		private string OrderContextText()
		{
			string text = "";
			if (hasOpenOrder)
			{
				OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
				if ((object)openOrder != null && openOrder.Source.Length > 0)
				{
					text = "\n" + Tr.T("Source:") + " " + openOrder.Source;
				}
			}
			return Tr.T("Operator:") + " " + currentOperator.Name + BranchSuffix() + "\n" + Tr.T("Room:") + " " + Tr.T(selectedRoom) + "  •  " + Tr.T(selectedTable) + "\n" + Tr.T("Dine in") + text;
		}

		private void RenderSeatBar()
		{
			seatBar.Controls.Clear();
			if (!store.Features.SeatOrdering)
			{
				seatBar.Visible = false;
				return;
			}
			seatBar.Visible = true;
			int maxSeat = Math.Min(12, Math.Max(4, Math.Max(activeSeat, (basket.Count > 0) ? basket.Max(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) i) => i.Seat) : 0)));
			Label value = new Label
			{
				Text = Tr.T("SEAT"),
				AutoSize = true,
				ForeColor = Skin.TextDim,
				Location = new Point(0, 6),
				Font = new Font("Segoe UI", 8.5f)
			};
			seatBar.Controls.Add(value);
			int num = 36;
			for (int num2 = 1; num2 <= maxSeat; num2++)
			{
				int seatNo = num2;
				Button button = new Button
				{
					Text = num2.ToString(),
					Size = new Size(30, 24),
					Location = new Point(num, 2),
					FlatStyle = FlatStyle.Flat,
					BackColor = ((num2 == activeSeat) ? mint : panelLight),
					ForeColor = ((num2 == activeSeat) ? Skin.OnAccent : Skin.Text),
					Font = new Font("Segoe UI Semibold", 9f),
					Cursor = Cursors.Hand
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					activeSeat = seatNo;
					RenderSeatBar();
				};
				seatBar.Controls.Add(button);
				num += 34;
			}
			if (maxSeat < 12)
			{
				Button button2 = new Button
				{
					Text = Tr.T("+"),
					Size = new Size(26, 24),
					Location = new Point(num, 2),
					FlatStyle = FlatStyle.Flat,
					BackColor = Skin.Neutral,
					ForeColor = Skin.OnFill,
					Font = new Font("Segoe UI Semibold", 9f),
					Cursor = Cursors.Hand
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					activeSeat = Math.Min(12, maxSeat + 1);
					RenderSeatBar();
				};
				seatBar.Controls.Add(button2);
			}
		}

		private void AddProduct(Product product)
		{
			if (Is86(store, product.Name))
			{
				MessageBox.Show(product.Name + " " + Tr.T("is out of stock (86'd)."), Tr.T("86 board"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			if (store.Features.ProductVariants)
			{
				List<ProductVariant> list = store.ProductVariants.Where((ProductVariant v) => v.Product == product.Name).ToList();
				if (list.Count > 0)
				{
					Form vf = new Form
					{
						Text = product.Name + " — choose variant",
						Size = new Size(360, 130 + list.Count * 34),
						StartPosition = FormStartPosition.CenterParent,
						BackColor = background,
						ForeColor = Skin.Text,
						Font = new Font("Segoe UI", 10f),
						FormBorderStyle = FormBorderStyle.FixedDialog,
						MaximizeBox = false,
						MinimizeBox = false
					};
					try
					{
						ComboBox comboBox = new ComboBox
						{
							FlatStyle = FlatStyle.Flat,
							Location = new Point(20, 40),
							Size = new Size(300, 28),
							DropDownStyle = ComboBoxStyle.DropDownList,
							BackColor = panelLight,
							ForeColor = Skin.Text
						};
						foreach (ProductVariant item3 in list)
						{
							comboBox.Items.Add($"{item3.Name} — {item3.Price:C}");
						}
						comboBox.SelectedIndex = 0;
						Button button = new Button
						{
							Text = Tr.T("Add to order"),
							Location = new Point(20, 84),
							Size = new Size(140, 34),
							BackColor = mint,
							ForeColor = Skin.OnAccent,
							FlatStyle = FlatStyle.Flat
						};
						button.FlatAppearance.BorderSize = 0;
						button.Click += (object _, EventArgs _) =>
						{
							vf.DialogResult = DialogResult.OK;
						};
						vf.Controls.AddRange(new Control[3]
						{
							new Label
							{
								Text = Tr.T("This product has variants:"),
								AutoSize = true,
								Location = new Point(20, 14)
							},
							comboBox,
							button
						});
						vf.AcceptButton = button;
						if (vf.ShowDialog() != DialogResult.OK)
						{
							return;
						}
						ProductVariant productVariant = list[comboBox.SelectedIndex];
						Product product2 = product._003CClone_003E_0024();
						product2.Name = product.Name + " (" + productVariant.Name + ")";
						product2.Price = productVariant.Price;
						product2.Barcode = ((productVariant.Barcode.Length > 0) ? productVariant.Barcode : product.Barcode);
						product = product2;
					}
					finally
					{
						if (vf != null)
						{
							((IDisposable)vf).Dispose();
						}
					}
				}
			}
			decimal finalPrice = product.Price;
			if (store.Features.HappyHour && store.HappyHourRules.Count > 0)
			{
				DateTime now = DateTime.Now;
				string item = now.DayOfWeek.ToString();
				foreach (HappyHourRule happyHourRule in store.HappyHourRules)
				{
					if (happyHourRule.Days.Contains(item) && now.TimeOfDay >= happyHourRule.Start && now.TimeOfDay <= happyHourRule.End)
					{
						finalPrice = product.Price * (1m - happyHourRule.DiscountPercent / 100m);
						break;
					}
				}
			}
			string modifiers = "";
			if (store.Features.Modifiers && store.ModifierGroups.Count > 0)
			{
				List<(string, decimal)> list2 = new List<(string, decimal)>();
				Form modForm = new Form
				{
					Text = product.Name + " - Options",
					Size = new Size(400, 300),
					StartPosition = FormStartPosition.CenterParent,
					BackColor = background,
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 10f),
					FormBorderStyle = FormBorderStyle.FixedDialog,
					MaximizeBox = false,
					MinimizeBox = false
				};
				try
				{
					FlowLayoutPanel flowLayoutPanel = new FlowLayoutPanel
					{
						Dock = DockStyle.Fill,
						FlowDirection = FlowDirection.TopDown,
						AutoScroll = true,
						WrapContents = false,
						BackColor = background,
						Padding = new Padding(10)
					};
					List<(CheckBox, string, decimal)> list3 = new List<(CheckBox, string, decimal)>();
					foreach (ModifierGroup modifierGroup in store.ModifierGroups)
					{
						Label value = new Label
						{
							Text = modifierGroup.Name,
							AutoSize = true,
							Font = new Font("Segoe UI Semibold", 10f),
							ForeColor = mint,
							Margin = new Padding(0, 8, 0, 2)
						};
						flowLayoutPanel.Controls.Add(value);
						foreach (ModifierOption option in modifierGroup.Options)
						{
							CheckBox checkBox = new CheckBox
							{
								Text = $"{option.Name} (+{option.Price:C})",
								AutoSize = true,
								ForeColor = Skin.Text,
								Margin = new Padding(16, 2, 0, 2)
							};
							list3.Add((checkBox, option.Name, option.Price));
							flowLayoutPanel.Controls.Add(checkBox);
						}
					}
					Button button2 = new Button
					{
						Text = Tr.T("OK"),
						Size = new Size(100, 34),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat,
						Margin = new Padding(0, 10, 0, 0)
					};
					button2.FlatAppearance.BorderSize = 0;
					button2.Click += (object _, EventArgs _) =>
					{
						modForm.DialogResult = DialogResult.OK;
					};
					flowLayoutPanel.Controls.Add(button2);
					modForm.Controls.Add(flowLayoutPanel);
					if (modForm.ShowDialog() != DialogResult.OK)
					{
						return;
					}
					foreach (var (checkBox2, item2, num) in list3)
					{
						if (checkBox2.Checked)
						{
							list2.Add((item2, num));
							finalPrice += num;
						}
					}
					modifiers = string.Join(", ", list2.Select(((string name, decimal price) m) => m.name));
				}
				finally
				{
					if (modForm != null)
					{
						((IDisposable)modForm).Dispose();
					}
				}
			}
			string note = "";
			if (store.Features.ItemNotes)
			{
				Form noteForm = new Form
				{
					Text = Tr.T("Item note"),
					Size = new Size(400, 180),
					StartPosition = FormStartPosition.CenterParent,
					BackColor = background,
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 10f),
					FormBorderStyle = FormBorderStyle.FixedDialog,
					MaximizeBox = false,
					MinimizeBox = false
				};
				try
				{
					TextBox noteInput = new TextBox
					{
						Location = new Point(10, 10),
						Size = new Size(365, 30),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						BorderStyle = BorderStyle.FixedSingle
					};
					Button button3 = new Button
					{
						Text = Tr.T("OK"),
						Location = new Point(10, 50),
						Size = new Size(80, 30),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat
					};
					Button button4 = new Button
					{
						Text = Tr.T("Skip"),
						Location = new Point(100, 50),
						Size = new Size(80, 30),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						FlatStyle = FlatStyle.Flat
					};
					button3.FlatAppearance.BorderSize = 0;
					button4.FlatAppearance.BorderSize = 0;
					button3.Click += (object _, EventArgs _) =>
					{
						note = noteInput.Text;
						noteForm.DialogResult = DialogResult.OK;
					};
					button4.Click += (object _, EventArgs _) =>
					{
						noteForm.DialogResult = DialogResult.OK;
					};
					noteForm.Controls.AddRange(new Control[3] { noteInput, button3, button4 });
					noteForm.ShowDialog();
				}
				finally
				{
					if (noteForm != null)
					{
						((IDisposable)noteForm).Dispose();
					}
				}
			}
			int num2 = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) tuple2) => tuple2.Product.Name == product.Name && tuple2.Product.PrinterDestination == product.PrinterDestination && tuple2.Note == note && tuple2.Modifiers == modifiers && (!store.Features.SeatOrdering || tuple2.Seat == activeSeat));
			NumericUpDown wInput;
			Label wTotal;
			if (store.Features.WeightedItems && product.Weighted)
			{
				Form wf = new Form
				{
					Text = "Weight — " + product.Name,
					Size = new Size(340, 190),
					StartPosition = FormStartPosition.CenterParent,
					BackColor = background,
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 10f),
					FormBorderStyle = FormBorderStyle.FixedDialog,
					MaximizeBox = false,
					MinimizeBox = false
				};
				try
				{
					Label label = new Label
					{
						Text = $"Scale weight in kg ({product.Price:C}/kg):",
						AutoSize = true,
						Location = new Point(16, 16)
					};
					wInput = new NumericUpDown
					{
						Location = new Point(16, 46),
						Size = new Size(140, 30),
						Minimum = 0.001m,
						Maximum = 10000m,
						DecimalPlaces = 3,
						Increment = 0.05m,
						BackColor = panelLight,
						ForeColor = Skin.Text
					};
					wTotal = new Label
					{
						AutoSize = true,
						Location = new Point(16, 88),
						ForeColor = mint,
						Font = new Font("Segoe UI Semibold", 12f)
					};
					wInput.ValueChanged += (object _, EventArgs _) =>
					{
						UpdateW();
					};
					UpdateW();
					Button button5 = new Button
					{
						Text = Tr.T("Add"),
						Location = new Point(16, 122),
						Size = new Size(90, 32),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat
					};
					Button button6 = new Button
					{
						Text = Tr.T("Cancel"),
						Location = new Point(116, 122),
						Size = new Size(90, 32),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						FlatStyle = FlatStyle.Flat
					};
					button5.FlatAppearance.BorderSize = 0;
					button6.FlatAppearance.BorderSize = 0;
					button5.Click += (object _, EventArgs _) =>
					{
						wf.DialogResult = DialogResult.OK;
					};
					button6.Click += (object _, EventArgs _) =>
					{
						wf.DialogResult = DialogResult.Cancel;
					};
					wf.Controls.AddRange(new Control[5] { label, wInput, wTotal, button5, button6 });
					wf.AcceptButton = button5;
					if (wf.ShowDialog() != DialogResult.OK)
					{
						return;
					}
					decimal value2 = wInput.Value;
					finalPrice = Math.Round(finalPrice * value2, 2);
					note = (string.IsNullOrWhiteSpace(note) ? $"{value2:0.###} kg @ {product.Price:C}/kg" : $"{note} · {value2:0.###} kg");
					num2 = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) tuple2) => tuple2.Product.Name == product.Name && tuple2.Product.PrinterDestination == product.PrinterDestination && tuple2.Note == note && tuple2.Modifiers == modifiers && (!store.Features.SeatOrdering || tuple2.Seat == activeSeat));
				}
				finally
				{
					if (wf != null)
					{
						((IDisposable)wf).Dispose();
					}
				}
			}
			if (num2 >= 0)
			{
				basket[num2] = (new Product(product.Name, product.Category, finalPrice, product.Color, product.Family, product.ImagePath, product.PrinterDestination, product.Barcode, product.Weighted), basket[num2].Count + 1, basket[num2].Course, basket[num2].Note, basket[num2].Seat, basket[num2].Modifiers);
			}
			else
			{
				basket.Add((new Product(product.Name, product.Category, finalPrice, product.Color, product.Family, product.ImagePath, product.PrinterDestination, product.Barcode, product.Weighted), 1, store.Features.CourseManagement ? 1 : 0, note, store.Features.SeatOrdering ? activeSeat : 0, modifiers));
			}
			RenderBasket();
			void UpdateW()
			{
				wTotal.Text = $"= {Math.Round(wInput.Value * finalPrice, 2):C}";
			}
		}

		private void CancelItem(Product product)
		{
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder == null)
			{
				return;
			}
			SoldLine soldLine = openOrder.Items.FirstOrDefault((SoldLine i) => i.Product == product.Name);
			if (soldLine == null)
			{
				return;
			}
			if (!string.IsNullOrWhiteSpace(soldLine.PrinterDestination))
			{
				PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == soldLine.PrinterDestination);
				PrinterDestination printerDestination2 = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Cancel");
				if (printerDestination != null)
				{
					PrinterDestination destination = ((printerDestination2 != null) ? new PrinterDestination(printerDestination2.Name, printerDestination.WindowsPrinter, printerDestination2.Header, printerDestination2.Footer, printerDestination2.CutAfterPrint, printerDestination2.Layout, printerDestination2.LogoPath) : printerDestination);
					SoldLine item = new SoldLine("CANCEL: " + soldLine.Product, soldLine.Family, -soldLine.Quantity, soldLine.UnitPrice, soldLine.Category, soldLine.PrinterDestination);
					PrintCancelTicket(destination, new List<SoldLine>(1) { item });
				}
			}
			List<SoldLine> list = openOrder.Items.Where((SoldLine i) => i.Product != product.Name).ToList();
			store.RemoveOpenOrder(selectedRoom, selectedTable);
			if (list.Count > 0)
			{
				store.AddOpenOrder(new OpenOrder(selectedRoom, selectedTable, openOrder.Operator, openOrder.Created, list, openOrder.Note, openOrder.OrderNumber, openOrder.BillNumber, openOrder.OrderType, openOrder.CustomerName, openOrder.SeatCount));
			}
			basket.RemoveAll(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) tuple) => tuple.Product == product);
			hasOpenOrder = list.Count > 0;
			UpdateOrderButtons();
			RenderBasket();
			Room room = store.Rooms.FirstOrDefault((Room r) => r.Name == selectedRoom);
			if (room != null)
			{
				RenderTableMap(room);
			}
			MessageBox.Show(Tr.T("Item cancelled:") + " " + product.Name, Tr.T("Cancelled"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
		}

		private decimal Total()
		{
			return basket.Sum(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) item) => item.Product.Price * (decimal)item.Count);
		}

		private decimal DiscountAmount()
		{
			if (!(basketDiscountPercent <= 0m))
			{
				return Math.Round(Total() * basketDiscountPercent / 100m, 2);
			}
			return 0m;
		}

		private decimal NetTotal()
		{
			return Total() - DiscountAmount();
		}

