		private void PlaceOrder()
		{
			if (basket.Count == 0)
			{
				return;
			}
			(string, string)? tuple = ChooseOrderType();
			if (!tuple.HasValue)
			{
				return;
			}
			(string, string) value = tuple.Value;
			string item = value.Item1;
			string item2 = value.Item2;
			bool courseOn = store.Features.CourseManagement;
			List<SoldLine> list = basket.Select(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) tuple2) => new SoldLine(tuple2.Product.Name, tuple2.Product.Family, tuple2.Count, tuple2.Product.Price, tuple2.Product.Category, ResolvePrinter(tuple2.Product), tuple2.Note, tuple2.Modifiers, 0m, "", Seat: tuple2.Seat, Course: courseOn ? tuple2.Course : 0)).ToList();
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder != null)
			{
				List<SoldLine> list2 = openOrder.Items.Concat(list).ToList();
				store.RemoveOpenOrder(selectedRoom, selectedTable);
				store.AddOpenOrder(new OpenOrder(selectedRoom, selectedTable, currentOperator.Name, openOrder.Created, list2, openOrder.Note, openOrder.OrderNumber, openOrder.BillNumber, item, "", Math.Max(openOrder.SeatCount, list2.Max((SoldLine l) => l.Seat)), Ready: false, openOrder.FiredCourse, openOrder.Source, (!string.IsNullOrWhiteSpace(item2)) ? item2 : openOrder.DeliveryAddress));
			}
			else
			{
				int num = store.NextOrderNumber();
				store.AddOpenOrder(new OpenOrder(selectedRoom, selectedTable, currentOperator.Name, DateTime.Now, list, "", num, num, item, "", (list.Count > 0) ? list.Max((SoldLine l) => l.Seat) : 0, Ready: false, 0, "", item2));
			}
			FireNewLines(list, item);
			MessageBox.Show(string.Format(Tr.T("Order placed for {0}"), selectedTable) + $"\n{NetTotal():C}\n{item}", Tr.T("Order saved"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			basket.Clear();
			activeSeat = 1;
			hasOpenOrder = true;
			UpdateOrderButtons();
			RenderBasket();
			Room room = store.Rooms.FirstOrDefault((Room r) => r.Name == selectedRoom);
			if (room != null)
			{
				RenderTableMap(room);
			}
		}

		private void FireNewLines(List<SoldLine> newLines, string orderType)
		{
			OpenOrder order = store.GetOpenOrder(selectedRoom, selectedTable);
			if (order == null || !store.Features.CourseManagement)
			{
				PrintTickets(newLines, 0, 0, orderType);
			}
			else if (order.FiredCourse == 0)
			{
				if (!store.Features.HoldFire)
				{
					List<SoldLine> list = order.Items.Where((SoldLine l) => l.Course <= 1).ToList();
					if (list.Count != 0)
					{
						PrintTickets(list, 0, 0, order.OrderType);
						SetFiredCourse(order, 1);
					}
				}
			}
			else
			{
				List<SoldLine> list2 = newLines.Where((SoldLine l) => l.Course == 0 || l.Course <= order.FiredCourse).ToList();
				if (list2.Count > 0)
				{
					PrintTickets(list2, 0, 0, order.OrderType);
				}
			}
		}

		private void FireNextCourse()
		{
			OpenOrder order = store.GetOpenOrder(selectedRoom, selectedTable);
			if (order == null)
			{
				return;
			}
			int next = (from l in order.Items
				where l.Course > order.FiredCourse
				select l.Course).DefaultIfEmpty(0).Min();
			if (next <= 0)
			{
				return;
			}
			List<SoldLine> list = order.Items.Where((SoldLine l) => l.Course == next).ToList();
			if (list.Count != 0)
			{
				PrintTickets(list, 0, 0, order.OrderType);
				SetFiredCourse(order, next);
				if (store.Features.AuditLog)
				{
					store.LogAudit(currentOperator.Name, "Fire course", $"{selectedTable} course {next} ({list.Count} lines)");
				}
				UpdateOrderButtons();
			}
		}

		private void SetFiredCourse(OpenOrder order, int course)
		{
			store.RemoveOpenOrder(order.Room, order.Table);
			PosStore posStore = store;
			OpenOrder openOrder = order._003CClone_003E_0024();
			openOrder.FiredCourse = course;
			posStore.AddOpenOrder(openOrder);
		}

		private void ScheduleDelayFire()
		{
			if (store.GetOpenOrder(selectedRoom, selectedTable) == null)
			{
				return;
			}
			Form f = new Form
			{
				Text = Tr.T("Delay fire"),
				Size = new Size(320, 190),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Label label = new Label
				{
					Text = Tr.T("Send the next course automatically after:"),
					AutoSize = true,
					Location = new Point(16, 16)
				};
				NumericUpDown minutes = new NumericUpDown
				{
					Location = new Point(16, 46),
					Size = new Size(100, 30),
					Minimum = 1m,
					Maximum = 180m,
					Value = 5m,
					BackColor = panelLight,
					ForeColor = Skin.Text
				};
				Label label2 = new Label
				{
					Text = Tr.T("minutes"),
					AutoSize = true,
					Location = new Point(126, 49)
				};
				Button button = new Button
				{
					Text = Tr.T("Schedule"),
					Location = new Point(16, 92),
					Size = new Size(110, 34),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				Button button2 = new Button
				{
					Text = Tr.T("Cancel"),
					Location = new Point(136, 92),
					Size = new Size(90, 34),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.Cancel;
				};
				f.Controls.AddRange(new Control[5] { label, minutes, label2, button, button2 });
				f.AcceptButton = button;
				if (f.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				string table = selectedTable;
				string room = selectedRoom;
				System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer
				{
					Interval = (int)minutes.Value * 60000
				};
				timer.Tick += (object _, EventArgs _) =>
				{
					timer.Stop();
					delayFireTimers.Remove(timer);
					timer.Dispose();
					OpenOrder current = store.GetOpenOrder(room, table);
					if (current != null && current.Items.Any((SoldLine l) => l.Course > current.FiredCourse))
					{
						string text = selectedTable;
						string text2 = selectedRoom;
						selectedTable = table;
						selectedRoom = room;
						FireNextCourse();
						selectedTable = text;
						selectedRoom = text2;
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Delay fire", $"{table} fired after {(int)minutes.Value} min");
						}
					}
				};
				delayFireTimers.Add(timer);
				timer.Start();
				MessageBox.Show(string.Format("{0} {1} {2} {3} {4}.", Tr.T("Course will fire automatically in"), (int)minutes.Value, Tr.T("minutes"), Tr.T("for"), table), Tr.T("Delay fire"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

		private static bool Contains86(IEnumerable<string>? list, string name)
		{
			if (list == null || string.IsNullOrWhiteSpace(name)) return false;
			foreach (var item in list)
			{
				if (string.Equals(item, name, StringComparison.OrdinalIgnoreCase)) return true;
			}
			int paren = name.IndexOf('(');
			if (paren > 0)
			{
				string baseName = name.Substring(0, paren).Trim();
				foreach (var item in list)
				{
				if (string.Equals(item, baseName, StringComparison.OrdinalIgnoreCase)) return true;
				}
			}
			return false;
		}

		private static bool Is86(PosStore store, string name)
		{
			if (store == null || string.IsNullOrWhiteSpace(name)) return false;
			if (Contains86(store.EightySix, name))
			{
				return true;
			}
			if (store.Features.Auto86 && Contains86(store.Auto86, name))
			{
				return true;
			}
			return false;
		}

		private void Auto86Sync()
		{
			if (!store.Features.Auto86)
			{
				if (store.Auto86.Count > 0)
				{
					store.SaveAuto86(new List<string>());
					if (productGrid != null)
					{
						RenderProducts();
					}
				}
				Update86Banner();
				UpdateStockPill();
				return;
			}
			List<string> list = store.Auto86.ToList();
			bool flag = false;
			if (store.Recipes.Count > 0)
			{
				foreach (var (item, source) in store.Recipes)
				{
					if (string.IsNullOrWhiteSpace(item) || source == null || source.Count == 0) continue;
					bool depleted = source.Any((RecipeItem ri) =>
					{
						Ingredient ingredient = store.Ingredients.FirstOrDefault((Ingredient i) => string.Equals(i.Name, ri.Ingredient, StringComparison.OrdinalIgnoreCase));
						if (ingredient == null) return false;
						decimal needed = ri.Quantity;
						if (!string.IsNullOrWhiteSpace(ri.Unit))
						{
							var conv = UnitMath.Convert(needed, ri.Unit, ingredient.Unit);
							if (conv.HasValue) needed = conv.Value;
						}
						return needed > 0m ? (ingredient.Stock < needed) : (ingredient.Stock <= 0m);
					});
					bool inList = list.Any(x => string.Equals(x, item, StringComparison.OrdinalIgnoreCase));
					if (depleted && !inList)
					{
						list.Add(item);
						flag = true;
					}
					else if (!depleted && inList)
					{
						list.RemoveAll(x => string.Equals(x, item, StringComparison.OrdinalIgnoreCase));
						flag = true;
					}
				}
			}
			foreach (ProductStock ps in store.ProductStocks)
			{
				if (ps.Tracked)
				{
					if (StockEngine.HasRecipe(store, ps.Product))
					{
						continue;
					}
					bool depleted = ps.Stock <= 0m;
					bool inList = list.Any(x => string.Equals(x, ps.Product, StringComparison.OrdinalIgnoreCase));
					if (depleted && !inList)
					{
						list.Add(ps.Product);
						flag = true;
					}
					else if (!depleted && inList)
					{
						list.RemoveAll(x => string.Equals(x, ps.Product, StringComparison.OrdinalIgnoreCase));
						flag = true;
					}
				}
			}
			if (flag)
			{
				store.SaveAuto86(list);
				if (productGrid != null)
				{
					RenderProducts();
				}
			}
			Update86Banner();
			UpdateStockPill();
		}

		private void PrintBill()
		{
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder == null)
			{
				return;
			}
			_ = store.RegisterSettings.Currency;
			List<SoldLine> list = openOrder.Items.Select((SoldLine i) => new SoldLine(i.Product, i.Family, i.Quantity, i.UnitPrice, i.Category, i.PrinterDestination, "", "", 0m, "", 0, i.Seat)).ToList();
			list.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity);
			decimal discountAmount = DiscountAmount();
			PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Bill");
			if (printerDestination == null || string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
			{
				MessageBox.Show(Tr.T("No Bill printer configured.\nGo to Settings > Printer routing and set a printer for Bill."), Tr.T("Print bill"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			try
			{
				if (isOrderPc)
				{
					byte[] data = BuildEscPosBytes(printerDestination, list, selectedRoom, selectedTable, openOrder.Operator, openOrder.OrderNumber, openOrder.BillNumber, 0, "", basketDiscountPercent, discountAmount);
					TcpPrintClient.SendPrintJob(GetMainPcHost(), printerDestination.WindowsPrinter, data);
					return;
				}
				if (printerDestination.CutAfterPrint)
				{
					try
					{
						RawPrinter.PrintTicket(printerDestination, selectedRoom, selectedTable, openOrder.Operator, list, ResolvePrinterName(printerDestination), openOrder.OrderNumber, openOrder.BillNumber, 0, "", basketDiscountPercent, discountAmount);
						return;
					}
					catch (InvalidOperationException)
					{
					}
				}
				PrintWindowsTicket(printerDestination, list, openOrder.OrderNumber, openOrder.BillNumber, 0, "", basketDiscountPercent, discountAmount);
			}
			catch (Exception ex2)
			{
				MessageBox.Show(Tr.T("Could not print bill:") + " " + ex2.Message, Tr.T("Print bill"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}

