			void KeyClick(string text2)
			{
				if (!(text2 == "C"))
				{
					if (text2 == "<")
					{
						if (entry.Length > 0)
						{
							string text3 = entry;
							entry = text3.Substring(0, text3.Length - 1);
						}
					}
					else if (entry.Length < 3)
					{
						if (entry == "0")
						{
							entry = ((text2 == "0") ? entry : text2);
						}
						else
						{
							entry += text2;
						}
					}
				}
				else
				{
					entry = "";
				}
				RefreshPreview();
			}
			void RefreshPreview()
			{
				decimal num = (decimal.TryParse(entry, NumberStyles.Integer, CultureInfo.InvariantCulture, out var result) ? Math.Min(result, 100m) : 0m);
				percentValue.Text = (string.IsNullOrEmpty(entry) ? "0%" : (entry + "%"));
				decimal num2 = gross - Math.Round(gross * num / 100m, 2);
				resultValue.Text = num2.ToString("C");
			}
		}

