				decimal num27 = totalBeforeDiscount - discount + reference;
				reference2 = ((cashDiscPct > 0m && text6 == "Cash") ? Math.Round(num27 * cashDiscPct / 100m, 2) : 0m);
				reference3 = ((cardSurchPct > 0m && text6 == "Card") ? Math.Round(num27 * cardSurchPct / 100m, 2) : 0m);
			}
			decimal CeilCash(decimal step)
