		private void ShowPrinterManager()
		{
			if (!HasPermission("Settings"))
			{
				return;
			}
			Panel panel = new Panel
			{
				Dock = DockStyle.Fill
			};
			PrinterManagerForm printerManagerForm = new PrinterManagerForm(background, panelLight, mint, store.PrinterDestinations, (List<PrinterDestination> destinations) =>
			{
				store.SavePrinterDestinations(destinations);
			}, (PrinterDestination current, List<TicketComponentStyle> components) =>
			{
				int num = store.PrinterDestinations.IndexOf(current);
				if (num >= 0)
				{
					PrinterDestination printerDestination = current._003CClone_003E_0024();
					printerDestination.Layout = components;
					PrinterDestination value = printerDestination;
					List<PrinterDestination> list = store.PrinterDestinations.ToList();
					list[num] = value;
					store.SavePrinterDestinations(list);
				}
			});
			printerManagerForm.TopLevel = false;
			printerManagerForm.FormBorderStyle = FormBorderStyle.None;
			printerManagerForm.Dock = DockStyle.Fill;
			panel.Controls.Add(printerManagerForm);
			printerManagerForm.Show();
			ShowView(panel, "Printer routing", ShowSettings);
		}

		private void PrintPaymentReceipt(Sale sale, List<SoldLine> lines, decimal discountPercent, string room, string table)
		{
			PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Payment");
			if (printerDestination == null || string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
			{
				return;
			}
			TicketLayout.Tendered = sale.Tendered;
			TicketLayout.CashReceived = ((sale.CashAmount >= 0m) ? sale.CashAmount : 0m);
			TicketLayout.Rounding = sale.Rounding;
			try
			{
				if (isOrderPc)
				{
					byte[] data = BuildEscPosBytes(printerDestination, lines, room, table, sale.Operator, 0, sale.BillNumber, sale.PaymentNumber, "", discountPercent, sale.Discount);
					TcpPrintClient.SendPrintJob(GetMainPcHost(), printerDestination.WindowsPrinter, data);
					return;
				}
				if (printerDestination.CutAfterPrint)
				{
					try
					{
						RawPrinter.PrintTicket(printerDestination, room, table, sale.Operator, lines, ResolvePrinterName(printerDestination), 0, sale.BillNumber, sale.PaymentNumber, "", discountPercent, sale.Discount);
						return;
					}
					catch (InvalidOperationException)
					{
						PrintWindowsTicket(printerDestination, lines, 0, sale.BillNumber, sale.PaymentNumber, "", discountPercent, sale.Discount, room, table);
						return;
					}
				}
				PrintWindowsTicket(printerDestination, lines, 0, sale.BillNumber, sale.PaymentNumber, "", discountPercent, sale.Discount, room, table);
			}
			catch (Exception ex2)
			{
				MessageBox.Show(Tr.T("Could not print payment: ") + ex2.Message, Tr.T("Payment"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
			finally
			{
				TicketLayout.Tendered = 0m;
				TicketLayout.CashReceived = 0m;
				TicketLayout.Rounding = 0m;
			}
		}

