					DecimalPlaces = 2,
					Increment = 100m,
					Value = Math.Max(0m, Math.Min(100000000m, amount))
				};
				Button button3 = new Button
				{
					Text = Tr.T("✕"),
					Location = new Point(280, 6),
					Size = new Size(34, 30),
					FlatStyle = FlatStyle.Flat,
					BackColor = Skin.Danger,
					ForeColor = Skin.OnFill
				};
				button3.FlatAppearance.BorderSize = 0;
				button3.Click += (object _, EventArgs _) =>
				{
					chosen.Remove((box, amt));
					listFlow.Controls.Remove(row);
					Refresh();
				};
				box.SelectedIndexChanged += (object _, EventArgs _) =>
				{
					Refresh();
				};
				amt.ValueChanged += (object _, EventArgs _) =>
				{
					Refresh();
				};
				row.Controls.AddRange(new Control[3] { box, amt, button3 });
				listFlow.Controls.Add(row);
				chosen.Add((box, amt));
				Refresh();
			}
			void Refresh()
			{
				decimal num = chosen.Sum(((ComboBox Box, NumericUpDown Amount) c) => c.Amount.Value);
				remainingLabel.Text = $"Remaining: {due - num:C}   tendered: {num:C}";
				if (okBtn != null)
				{
					okBtn.Enabled = Math.Abs(num - due) < 0.005m && chosen.Count > 0;
				}
			}
		}

		private void PrintTickets(List<SoldLine> lines, int orderNumber = 0, int billNumber = 0, string orderType = "", string? room = null, string? table = null, string? operatorName = null, bool showWarnings = true, List<string>? printWarnings = null)
		{
			string room2 = room ?? selectedRoom;
			string table2 = table ?? selectedTable;
			string operatorName2 = operatorName ?? currentOperator.Name;
			OpenOrder openOrder = store.GetOpenOrder(room2, table2);
			int orderNumber2 = ((orderNumber > 0) ? orderNumber : (openOrder?.OrderNumber ?? 0));
			int billNumber2 = ((billNumber > 0) ? billNumber : (openOrder?.BillNumber ?? 0));
			List<string> list = new List<string>();
			bool flag = false;
			foreach (IGrouping<string, SoldLine> group in from line in lines
				where !string.IsNullOrWhiteSpace(line.PrinterDestination)
				group line by line.PrinterDestination)
			{
				PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination item) => string.Equals(item.Name, group.Key, StringComparison.OrdinalIgnoreCase)) ?? store.PrinterDestinations.FirstOrDefault((PrinterDestination item) => string.Equals(item.WindowsPrinter, group.Key, StringComparison.OrdinalIgnoreCase));
				if (printerDestination == null)
				{
					if (!list.Contains(group.Key))
					{
						list.Add(group.Key);
					}
					continue;
				}
				flag = true;
				try
				{
					List<SoldLine> list2 = group.ToList();
					if (!printerDestination.CutAfterPrint)
					{
						goto IL_028d;
					}
					int written;
					try
					{
						if (isOrderPc)
						{
							byte[] array = BuildEscPosBytes(printerDestination, list2, room2, table2, operatorName2, orderNumber2, billNumber2, 0, orderType);
							try
							{
								TcpPrintClient.SendPrintJob(GetMainPcHost(), printerDestination.WindowsPrinter, array);
							}
							catch
							{
								string text = "\\\\" + GetMainPcHost() + "\\" + printerDestination.WindowsPrinter;
								if (!RawPrinter.OpenPrinterLocal(text, out var printer, (IntPtr)0))
								{
									throw new InvalidOperationException("Cannot reach main PC printer.\n\nMake sure:\n1. The main PC is running\n2. The printer is shared\n3. Port 9100 is open\n\nTried: TCP :9100 and UNC " + text);
								}
								RawPrinter.DocumentInfo documentInfo = new RawPrinter.DocumentInfo
								{
									DocumentName = "Remote print",
									OutputFile = null,
									DataType = null
								};
								try
								{
									RawPrinter.StartDocPrinter(printer, 1, documentInfo);
									RawPrinter.StartPagePrinter(printer);
									RawPrinter.WritePrinter(printer, array, array.Length, out written);
									RawPrinter.EndPagePrinter(printer);
									RawPrinter.EndDocPrinter(printer);
								}
								finally
								{
									RawPrinter.ClosePrinter(printer);
								}
							}
						}
						else
						{
							RawPrinter.PrintTicket(printerDestination, room2, table2, operatorName2, list2, null, orderNumber2, billNumber2, 0, orderType);
						}
					}
					catch (InvalidOperationException)
					{
						goto IL_028d;
					}
					continue;
					IL_028d:
					if (isOrderPc)
					{
						byte[] array2 = BuildEscPosBytes(printerDestination, list2, room2, table2, operatorName2, orderNumber2, billNumber2, 0, orderType);
						try
						{
							TcpPrintClient.SendPrintJob(GetMainPcHost(), printerDestination.WindowsPrinter, array2);
						}
						catch
						{
							if (!RawPrinter.OpenPrinterLocal("\\\\" + GetMainPcHost() + "\\" + printerDestination.WindowsPrinter, out var printer2, (IntPtr)0))
							{
								throw new InvalidOperationException("Cannot reach main PC printer " + printerDestination.WindowsPrinter + ".\n\nMake sure the main PC is running and the printer is shared.");
							}
							RawPrinter.DocumentInfo documentInfo2 = new RawPrinter.DocumentInfo
							{
								DocumentName = "Remote print",
								OutputFile = null,
								DataType = null
							};
							try
							{
								RawPrinter.StartDocPrinter(printer2, 1, documentInfo2);
								RawPrinter.StartPagePrinter(printer2);
								RawPrinter.WritePrinter(printer2, array2, array2.Length, out written);
								RawPrinter.EndPagePrinter(printer2);
								RawPrinter.EndDocPrinter(printer2);
							}
							finally
							{
								RawPrinter.ClosePrinter(printer2);
							}
						}
					}
					else
					{
						PrintWindowsTicket(printerDestination, list2, orderNumber2, billNumber2, 0, orderType, 0m, 0m, room2, table2);
					}
				}
				catch (Exception ex2)
				{
					Warn(Tr.T("Could not print to") + " " + printerDestination.WindowsPrinter + ": " + ex2.Message, Tr.T("Printing"));
				}
			}
			if (list.Count > 0)
			{
				Warn(Tr.T("Printer destination not found:") + " " + string.Join(", ", list) + "\n" + Tr.T("These items were NOT printed on the order ticket.\n\nFix it in Settings > Printer routing,\nor re-select the destination in Settings > Manage families."), "Printing");
			}
			else if (!flag && lines.Count > 0)
			{
				Warn(Tr.T("No printer destination is set for these items - order ticket not printed.\n\nSet one in Settings > Manage families (printer routing)."), Tr.T("Printing"));
			}
			void Warn(string message, string caption)
			{
				if (showWarnings)
				{
					MessageBox.Show(message, caption, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				}
				else
				{
					printWarnings?.Add(message);
				}
			}
		}

		private void PrintCancelTicket(PrinterDestination destination, List<SoldLine> lines)
		{
			if (string.IsNullOrWhiteSpace(destination.WindowsPrinter))
			{
				return;
			}
			try
			{
				if (isOrderPc)
				{
					byte[] data = BuildEscPosBytes(destination, lines, selectedRoom, selectedTable, currentOperator.Name);
					TcpPrintClient.SendPrintJob(GetMainPcHost(), destination.WindowsPrinter, data);
					return;
				}
				if (destination.CutAfterPrint)
				{
					try
					{
						RawPrinter.PrintTicket(destination, selectedRoom, selectedTable, currentOperator.Name, lines, ResolvePrinterName(destination));
						return;
					}
					catch (InvalidOperationException)
					{
					}
				}
				PrintWindowsTicket(destination, lines);
			}
			catch (Exception ex2)
			{
				MessageBox.Show(Tr.T("Could not print cancel to") + " " + destination.WindowsPrinter + ": " + ex2.Message, Tr.T("Printing"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}

		private string ResolvePrinterName(PrinterDestination destination)
		{
			if (!isOrderPc || string.IsNullOrWhiteSpace(store.RegisterSettings.NetworkPath))
			{
				return destination.WindowsPrinter;
			}
			string text = store.RegisterSettings.NetworkPath.TrimEnd('\\').Split('\\')[0];
			return "\\\\" + text + "\\" + destination.WindowsPrinter;
		}

		private string GetMainPcHost()
		{
			return store.RegisterSettings.NetworkPath.TrimEnd('\\').Split('\\')[0];
		}

		private static byte[] BuildEscPosBytes(PrinterDestination destination, List<SoldLine> ticketLines, string room, string table, string operatorName, int orderNumber = 0, int billNumber = 0, int paymentNumber = 0, string orderType = "", decimal discountPercent = 0m, decimal discountAmount = 0m)
		{
			MemoryStream stream = new MemoryStream();
			try
			{
				Write("\u001b@");
				foreach (TicketComponentStyle item in TicketLayout.Components(destination))
				{
					if (item.Component == "Cutter")
					{
						Write("\u001bd\u0005\u001dV\0");
					}
					else if (item.Component == "Blank line")
					{
						stream.WriteByte(10);
					}
					else
					{
						if (item.Component == "Logo" && (string.IsNullOrWhiteSpace(destination.LogoPath) || !File.Exists(destination.LogoPath)))
						{
							continue;
						}
						string text = null;
						if (item.Component != "Logo")
						{
							text = TicketLayout.Text(item.Component, destination, room, table, operatorName, ticketLines, orderNumber, billNumber, paymentNumber, orderType, discountPercent, discountAmount);
							if (string.IsNullOrWhiteSpace(text))
							{
								continue;
							}
						}
						string alignment = item.Alignment;
						string s;
						if (alignment == "Center")
						{
							s = "\u001ba\u0001";
						}
						else
						{
							s = ((!(alignment == "Right")) ? "\u001ba\0" : "\u001ba\u0002");
						}
						Write(s);
						int fontSize = item.FontSize;
						var (b, b2) = ((byte, byte))((fontSize >= 22) ? ((fontSize >= 32) ? (4, 4) : ((fontSize < 26) ? (3, 2) : (3, 3))) : ((fontSize >= 15) ? ((fontSize < 18) ? (2, 1) : (2, 2)) : ((fontSize < 12) ? (1, 1) : (1, 2))));
						Write($"\u001d!{(char)b2}{(char)b}");
						Write("\u001b-" + (item.Underline ? '\u0001' : '\0'));
						if (item.Bold)
						{
							Write("\u001bE\u0001");
						}
						stream.WriteByte(10);
						if (item.Component == "Logo")
						{
							using Image image = Image.FromFile(destination.LogoPath);
							int num = ((item.FontSize >= 32) ? 576 : 384);
							double num2 = (double)num / (double)image.Width;
							int num3 = Math.Min((int)((double)image.Width * num2), num);
							int num4 = (int)((double)image.Height * num2);
							using Bitmap bmp = new Bitmap(image, new Size(num3, num4));
							byte[] array = RawPrinter.ImageToEscPosBytes(bmp);
							stream.Write(array, 0, array.Length);
						}
						else
						{
							Write(text);
						}
						stream.WriteByte(10);
						if (item.Bold)
						{
							Write("\u001bE\0");
						}
						Write("\u001b-\0");
						Write("\u001d!\u0001\u0001");
						Write("\u001ba\0");
					}
				}
				if (!TicketLayout.Components(destination).Any((TicketComponentStyle ticketComponentStyle) => ticketComponentStyle.Component == "Cutter") && destination.CutAfterPrint)
				{
					Write("\u001bd\u0005\u001dV\0");
				}
				return stream.ToArray();
			}
			finally
			{
				if (stream != null)
				{
					((IDisposable)stream).Dispose();
				}
			}
			void Write(string s2)
			{
				stream.Write(Encoding.ASCII.GetBytes(s2), 0, Encoding.ASCII.GetByteCount(s2));
			}
		}

		private void PrintWindowsTicket(PrinterDestination destination, List<SoldLine> ticketLines, int orderNumber = 0, int billNumber = 0, int paymentNumber = 0, string orderType = "", decimal discountPercent = 0m, decimal discountAmount = 0m, string? room = null, string? table = null)
		{
			string printerName = ResolvePrinterName(destination);
			using PrintDocument printDocument = new PrintDocument
			{
				PrinterSettings = 
				{
					PrinterName = printerName
				}
			};
			if (!printDocument.PrinterSettings.IsValid)
			{
				return;
			}
			printDocument.PrintPage += (object _, PrintPageEventArgs args) =>
			{
				if (args.Graphics == null)
				{
					return;
				}
				Graphics graphics = args.Graphics;
				int num = 20;
				int num2 = 20;
				int num3 = args.PageBounds.Width - num2 * 2;
				foreach (TicketComponentStyle item in TicketLayout.Components(destination))
				{
					if (!(item.Component == "Cutter"))
					{
						if (item.Component == "Blank line")
						{
							num += 20;
						}
						else if (!(item.Component == "Logo") || (!string.IsNullOrWhiteSpace(destination.LogoPath) && File.Exists(destination.LogoPath)))
						{
							FontStyle fontStyle = FontStyle.Regular;
							if (item.Bold)
							{
								fontStyle |= FontStyle.Bold;
							}
							if (item.Underline)
							{
								fontStyle |= FontStyle.Underline;
							}
							using Font font = new Font("Consolas", item.FontSize, fontStyle);
							if (item.Component == "Logo")
							{
								using Image image = Image.FromFile(destination.LogoPath);
								double num4 = (double)((item.FontSize >= 32) ? num3 : Math.Min(num3, 300)) / (double)image.Width;
								int num5 = (int)((double)image.Width * num4);
								int num6 = (int)((double)image.Height * num4);
								string alignment = item.Alignment;
								int num7 = ((alignment == "Center") ? (num2 + (num3 - num5) / 2) : ((!(alignment == "Right")) ? num2 : (num2 + (num3 - num5))));
								int num8 = num7;
								graphics.DrawImage(image, new Rectangle(num8, num, num5, num6));
								num += num6 + 2;
							}
							else
							{
								string text = TicketLayout.Text(item.Component, destination, room ?? selectedRoom, table ?? selectedTable, currentOperator.Name, ticketLines, orderNumber, billNumber, paymentNumber, orderType, discountPercent, discountAmount);
								if (!string.IsNullOrEmpty(text))
								{
									SizeF sizeF = graphics.MeasureString(text, font, num3);
									string alignment = item.Alignment;
									float num9 = ((alignment == "Center") ? ((float)num2 + ((float)num3 - sizeF.Width) / 2f) : ((!(alignment == "Right")) ? ((float)num2) : ((float)num2 + ((float)num3 - sizeF.Width))));
									float num10 = num9;
									graphics.DrawString(text, font, Brushes.Black, new RectangleF(num10, num, num3, sizeF.Height));
									num += (int)sizeF.Height + 2;
								}
							}
						}
					}
				}
			};
			printDocument.Print();
		}

		private static void ApplyCurrencyCulture(string currency)
		{
			string currencySymbol = currency switch
			{
				"EUR" => "€", 
				"USD" => "$", 
				"GBP" => "£", 
				"DZD" => "DA", 
				_ => currency, 
			};
			CultureInfo cultureInfo = new CultureInfo(Tr.CultureName);
			cultureInfo.NumberFormat.CurrencySymbol = currencySymbol;
			cultureInfo.NumberFormat.CurrencyPositivePattern = 3;
			cultureInfo.NumberFormat.CurrencyNegativePattern = 3;
			Thread.CurrentThread.CurrentCulture = cultureInfo;
			Thread.CurrentThread.CurrentUICulture = cultureInfo;
			CultureInfo.DefaultThreadCurrentCulture = cultureInfo;
			CultureInfo.DefaultThreadCurrentUICulture = cultureInfo;
			CultureInfo.CurrentCulture = cultureInfo;
			CultureInfo.CurrentUICulture = cultureInfo;
		}

		private string TodaySales()
		{
			return "TODAY  " + TodaySalesAmount();
		}

		private string TodaySalesAmount()
		{
			return store.Sales.Where((Sale sale) => sale.Time.Date == DateTime.Today).Sum((Sale sale) => sale.Total).ToString("C");
		}

		private void ShowSales()
		{
