				ShowView(panel, "Sales report", ShowSettings);
			}
		}

		private void RefundSale(Sale sale)
		{
			if (sale.IsRefund || sale.Items == null || sale.Items.Count == 0)
			{
				return;
			}
			if (sale.PaymentNumber > 0 && store.Sales.Any((Sale s) => s.RefundOf == sale.PaymentNumber))
			{
				MessageBox.Show(Tr.T("This sale already has a refund."), Tr.T("Refund"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			Form form = new Form
			{
				Text = Tr.T("Refund sale"),
				Size = new Size(460, 400),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Label label = new Label
				{
					Text = $"Refund items from sale {sale.Time:dd/MM HH:mm} • {sale.Table}",
					AutoSize = true,
					Location = new Point(15, 10),
					ForeColor = mint,
					MaximumSize = new Size(430, 0)
				};
				int num = 46;
				List<(CheckBox, SoldLine)> list = new List<(CheckBox, SoldLine)>();
				foreach (SoldLine item3 in sale.Items)
				{
					CheckBox item = new CheckBox
					{
						Text = $"{item3.Quantity}x {item3.Product} ({item3.UnitPrice * (decimal)item3.Quantity:C})",
						AutoSize = true,
						Location = new Point(20, num),
						ForeColor = Skin.Text,
						Checked = true
					};
					list.Add((item, item3));
					num += 28;
				}
				num += 10;
				bool flag = store.Features.GiftCards && HasPermission("Gift cards") && !string.IsNullOrWhiteSpace(sale.CustomerName) && store.Customers.Any((Customer c) => c.Name == sale.CustomerName);
				CheckBox checkBox = new CheckBox
				{
					Text = Tr.T("Issue as store credit (money stays on the customer account)"),
					AutoSize = true,
					Location = new Point(20, num),
