					Checked = false
				};
				if (flag)
				{
					form.Controls.Add(checkBox);
					num += 34;
				}
				Button button = new Button
				{
					Text = Tr.T("Refund selected"),
					Location = new Point(15, num),
					Size = new Size(190, 38),
					BackColor = Skin.Danger,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.OK;
				};
				Button button2 = new Button
				{
					Text = Tr.T("Cancel"),
					Location = new Point(220, num),
					Size = new Size(160, 38),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.Cancel;
				};
				form.ClientSize = new Size(460, num + 60);
				form.Controls.AddRange(new Control[3] { label, button, button2 });
				foreach (var item4 in list)
				{
					CheckBox item2 = item4.Item1;
					form.Controls.Add(item2);
				}
				form.AcceptButton = button;
				form.CancelButton = button2;
				if (form.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				List<SoldLine> list2 = list.Where(((CheckBox cb, SoldLine line) x) => x.cb.Checked).Select(((CheckBox cb, SoldLine line) x) => x.line).ToList();
				if (list2.Count == 0)
				{
					MessageBox.Show(Tr.T("Select at least one item to refund."), Tr.T("Refund"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return;
				}
				decimal num2 = list2.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity);
				if (MessageBox.Show(string.Format("{0}{1:C} for {2} item(s) from sale #{3} ({4})?", Tr.T("Refund "), num2, list2.Count, sale.PaymentNumber, sale.Table), Tr.T("Confirm refund"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
				{
					return;
				}
				List<SoldLine> list3 = list2.Select((SoldLine l) =>
				{
					SoldLine soldLine = l._003CClone_003E_0024();
					soldLine.Quantity = -l.Quantity;
					return soldLine;
				}).ToList();
