				PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Payment");
				PrinterDestination printerDestination2 = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Refund") ?? printerDestination;
				if (printerDestination != null && printerDestination2 != null)
				{
					PrinterDestination printerDestination3 = printerDestination2._003CClone_003E_0024();
					printerDestination3.WindowsPrinter = printerDestination.WindowsPrinter;
					printerDestination2 = printerDestination3;
				}
				if (printerDestination2 != null && !string.IsNullOrWhiteSpace(printerDestination2.WindowsPrinter))
				{
					try
					{
						if (isOrderPc)
						{
							byte[] data = BuildEscPosBytes(printerDestination2, list3, "", sale.Table, currentOperator.Name, 0, sale.BillNumber, sale3.PaymentNumber, "Refund");
							TcpPrintClient.SendPrintJob(GetMainPcHost(), printerDestination2.WindowsPrinter, data);
						}
						else if (printerDestination2.CutAfterPrint)
						{
							try
							{
								RawPrinter.PrintTicket(printerDestination2, "", sale.Table, currentOperator.Name, list3, ResolvePrinterName(printerDestination2), 0, sale.BillNumber, sale3.PaymentNumber, "Refund");
							}
							catch (InvalidOperationException)
							{
								PrintWindowsTicket(printerDestination2, list3, 0, sale.BillNumber, sale3.PaymentNumber, "Refund", 0m, 0m, "", sale.Table);
							}
						}
						else
						{
							PrintWindowsTicket(printerDestination2, list3, 0, sale.BillNumber, sale3.PaymentNumber, "Refund", 0m, 0m, "", sale.Table);
						}
					}
					catch (Exception ex2)
					{
						MessageBox.Show(Tr.T("Could not print refund:") + " " + ex2.Message, Tr.T("Refund"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
				}
				salesLabel.Text = TodaySalesAmount();
				MessageBox.Show(string.Format("{0} {1:C}\n{2} {3} {4}", Tr.T("Refunded"), num2, list2.Count, Tr.T("item(s) from"), sale.Table), Tr.T("Refund"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				ShowSales();
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
		}

