		private DayReportData? BuildDayReport(bool closeDay)
		{
			string text = (closeDay ? "Z REPORT" : "X REPORT");
			List<Sale> list = store.Sales.Where((Sale s) => s.Time.Date == DateTime.Today).ToList();
			if (list.Count == 0)
			{
				MessageBox.Show(string.Format(Tr.T("No sales today — {0} not available."), text), text, MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return null;
			}
			List<SoldLine> source = list.SelectMany((Sale s) => s.Items ?? new List<SoldLine>()).ToList();
			return new DayReportData
			{
				CloseDay = closeDay,
				Time = DateTime.Now,
				Operator = currentOperator.Name,
				Currency = store.RegisterSettings.Currency,
				Transactions = list.Count,
				ItemsSold = source.Sum((SoldLine l) => l.Quantity),
				Gross = list.Sum((Sale s) => s.Total),
				Discounts = list.Sum((Sale s) => s.Discount),
				Tips = list.Sum((Sale s) => s.Tip),
				ByPayment = (from s in list
					group s by (!string.IsNullOrWhiteSpace(s.PaymentType)) ? s.PaymentType : "Cash" into g
					select (Name: g.Key, Count: g.Count(), Total: g.Sum((Sale s) => s.Total)) into x
					orderby x.Total descending
					select x).ToList(),
				ByOperator = (from s in list
					group s by s.Operator into g
					select (Name: g.Key, Count: g.Count(), Total: g.Sum((Sale s) => s.Total)) into x
					orderby x.Total descending
					select x).ToList(),
				ByProduct = (from l in source
					group l by l.Product into g
					select (Name: g.Key, Qty: g.Sum((SoldLine l) => l.Quantity), Total: g.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity)) into x
					orderby x.Total descending
					select x).Take(10).ToList(),
				ByFamily = (from l in source
					group l by l.Family into g
					select (Name: g.Key, Qty: g.Sum((SoldLine l) => l.Quantity), Total: g.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity)) into x
					orderby x.Total descending
					select x).ToList()
			};
		}

		private bool ConfirmZReport(DayReportData data)
		{
			if (!data.CloseDay)
			{
				return true;
			}
			string text = string.Format(Tr.T("Close the day with a Z report?\n\n{0} transactions  •  {1} total"), data.Transactions.ToString(), $"{data.Gross:C}");
			if (store.ZReportPrintedToday())
			{
				text = text + "\n\n" + Tr.T("A Z report was already printed today.");
			}
			return MessageBox.Show(text, Tr.T("Z report"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes;
		}

		private void FinalizeDayReport(DayReportData data, string action)
		{
			string text = $"{data.Transactions} transactions  •  {data.Gross:N2} {data.Currency}";
			if (data.CloseDay)
			{
				store.RecordZReport(data.Transactions, data.Gross, currentOperator.Name);
				if (store.Features.AuditLog)
				{
					store.LogAudit(currentOperator.Name, "Z report", action + ": " + text);
				}
				MessageBox.Show(string.Format(Tr.T("Z report {0} — day closed.\n{1}"), action, text), Tr.T("Z report"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				if (store.Features.CloudSync && !string.IsNullOrWhiteSpace(store.Features.CloudSyncUrl))
				{
					UploadBackupToHome(showResult: true);
				}
			}
			else
			{
				if (store.Features.AuditLog)
				{
					store.LogAudit(currentOperator.Name, "X report", action + ": " + text);
				}
				MessageBox.Show(string.Format(Tr.T("X report {0} — day stays open.\n{1}"), action, text), Tr.T("X report"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
		}

		private List<ReportLine> BuildReportLines(DayReportData d, bool asPdf)
		{
			string cur = d.Currency;
			List<ReportLine> list = new List<ReportLine>();
			list.Add(new ReportLine(d.CloseDay ? Tr.T("Z REPORT") : Tr.T("X REPORT"), 2));
			list.Add(new ReportLine(d.CloseDay ? Tr.T("END OF DAY READ - DAY CLOSED") : Tr.T("MID-DAY READ - DAY STAYS OPEN"), 1));
			list.Add(new ReportLine(string.Format("{0:dd/MM/yyyy HH:mm}  {1} {2}", d.Time, Tr.T("Operator:"), d.Operator), 0));
			list.Add(new ReportLine("", 4));
			list.Add(new ReportLine(Tr.T("SUMMARY"), 1));
			list.Add(new ReportLine(string.Format("{0}   {1}", Tr.T("Transactions:"), d.Transactions), 0));
			list.Add(new ReportLine(string.Format("{0}     {1}", Tr.T("Items sold:"), d.ItemsSold), 0));
			list.Add(new ReportLine(string.Format("{0}          {1:N2} {2}", Tr.T("Gross:"), d.Gross, cur), 0));
			list.Add(new ReportLine(string.Format("{0}      {1:N2} {2}", Tr.T("Discounts:"), d.Discounts, cur), 0));
			list.Add(new ReportLine(string.Format("{0}           {1:N2} {2}", Tr.T("Tips:"), d.Tips, cur), 0));
			list.Add(new ReportLine("", 5));
			list.Add(new ReportLine(Tr.T("PAYMENT BREAKDOWN"), 1));
			list.Add(new ReportLine(string.Format("{0,-14} {1,-6} {2,10}", Tr.T("Type"), Tr.T("Sales"), Tr.T("Total")), 1));
			list.Add(new ReportLine("", 4));
			list.AddRange(d.ByPayment.Select(((string Name, int Count, decimal Total) p) => new ReportLine($"{Trunc(p.Name, 14),-14} {p.Count,-6} {p.Total:N2} {cur}", 0)));
			list.Add(new ReportLine("", 5));
			list.Add(new ReportLine(Tr.T("BY OPERATOR"), 1));
			list.Add(new ReportLine(string.Format("{0,-6} {1,-24} {2,10}", Tr.T("Sales"), Tr.T("Operator"), Tr.T("Total")), 1));
			list.Add(new ReportLine("", 4));
			list.AddRange(d.ByOperator.Select(((string Name, int Count, decimal Total) o) => new ReportLine($"{o.Count,-6} {Trunc(o.Name, 24),-24} {o.Total:N2} {cur}", 0)));
			list.Add(new ReportLine("", 5));
			list.Add(new ReportLine(Tr.T("TOP PRODUCTS"), 1));
			list.Add(new ReportLine(string.Format("{0,-6} {1,-24} {2,10}", Tr.T("Qty"), Tr.T("Product"), Tr.T("Total")), 1));
			list.Add(new ReportLine("", 4));
			list.AddRange(d.ByProduct.Select(((string Name, int Qty, decimal Total) p) => new ReportLine($"{p.Qty,-6} {Trunc(p.Name, 24),-24} {p.Total:N2} {cur}", 0)));
			list.Add(new ReportLine("", 5));
			list.Add(new ReportLine(Tr.T("BY FAMILY"), 1));
			list.Add(new ReportLine(string.Format("{0,-6} {1,-24} {2,10}", Tr.T("Qty"), Tr.T("Family"), Tr.T("Total")), 1));
			list.Add(new ReportLine("", 4));
			list.AddRange(d.ByFamily.Select(((string Name, int Qty, decimal Total) f) => new ReportLine($"{f.Qty,-6} {Trunc(f.Name, 24),-24} {f.Total:N2} {cur}", 0)));
			list.Add(new ReportLine("", 5));
			list.Add(new ReportLine("", 4));
			list.Add(new ReportLine(string.Format("{0}: {1:dd/MM/yyyy HH:mm}   {2}", asPdf ? Tr.T("Exported") : Tr.T("Printed"), DateTime.Now, d.CloseDay ? Tr.T("Day closed") : Tr.T("Day stays open")), 3));
			return list;
			static string Trunc(string s, int n)
			{
				if (s.Length > n)
				{
					return s.Substring(0, n - 1) + "...";
				}
				return s;
			}
		}

		private void PrintDayReport(bool closeDay)
		{
			DayReportData dayReportData = BuildDayReport(closeDay);
			if (dayReportData == null || !ConfirmZReport(dayReportData))
			{
				return;
			}
			string en = (closeDay ? "Z REPORT" : "X REPORT");
			PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Payment") ?? store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Bill");
			if (printerDestination == null || string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
			{
				MessageBox.Show(Tr.T("No printer configured for reports.\nSet a Payment or Bill printer in Settings > Printer routing."), Tr.T(en), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			List<ReportLine> renderLines = BuildReportLines(dayReportData, asPdf: false);
			try
			{
				using PrintDocument printDocument = new PrintDocument
				{
					PrinterSettings = 
					{
						PrinterName = printerDestination.WindowsPrinter
					}
				};
				if (!printDocument.PrinterSettings.IsValid)
				{
					MessageBox.Show(Tr.T("Printer not available."), Tr.T(en), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					return;
				}
				printDocument.PrintPage += (object _, PrintPageEventArgs args) =>
				{
					if (args.Graphics == null)
					{
						return;
					}
					Graphics graphics = args.Graphics;
					int num = 20;
					int num2 = 20;
					int num3 = args.PageBounds.Width - num2 * 2;
					using Font font = new Font("Consolas", 14f, FontStyle.Bold);
					using Font font2 = new Font("Consolas", 10f, FontStyle.Bold);
					using Font font3 = new Font("Consolas", 10f);
					using Font font4 = new Font("Consolas", 8f);
					using Pen pen = new Pen(Color.Gray);
					foreach (ReportLine item in renderLines)
					{
						switch (item.Style)
						{
						case 2:
							graphics.DrawString(item.Text, font, Brushes.Black, num2, num);
							break;
						case 1:
							graphics.DrawString(item.Text, font2, Brushes.Black, num2, num);
							break;
						case 3:
							graphics.DrawString(item.Text, font4, Brushes.Gray, num2, num);
							break;
						case 4:
							graphics.DrawLine(pen, num2, num + 4, num2 + num3, num + 4);
							break;
						default:
							graphics.DrawString(item.Text, font3, Brushes.Black, num2, num);
							break;
						case 5:
							break;
						}
						num += (int)ReportLineStyles.Height(item.Style);
					}
				};
				printDocument.Print();
				FinalizeDayReport(dayReportData, "printed");
			}
			catch (Exception ex)
			{
				MessageBox.Show(Tr.T("Could not print report: ") + ex.Message, Tr.T(en), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}

		private void ExportDayReportPdf(bool closeDay)
		{
			DayReportData dayReportData = BuildDayReport(closeDay);
			if (dayReportData == null || !ConfirmZReport(dayReportData))
			{
				return;
			}
			string en = (closeDay ? "Z REPORT" : "X REPORT");
			using SaveFileDialog saveFileDialog = new SaveFileDialog
			{
				Title = "Export report as PDF",
				Filter = "PDF file|*.pdf",
				FileName = string.Format("{0}-report-{1:yyyy-MM-dd-HHmm}.pdf", closeDay ? "Z" : "X", DateTime.Now)
			};
			if (saveFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			try
			{
				TicketPdf.Save(saveFileDialog.FileName, BuildReportLines(dayReportData, asPdf: true));
				FinalizeDayReport(dayReportData, "exported to PDF");
			}
			catch (Exception ex)
			{
				MessageBox.Show(Tr.T("Could not export PDF: ") + ex.Message, Tr.T(en), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}

