				Dock = DockStyle.Fill
			};
			OperatorPickerForm operatorPickerForm = new OperatorPickerForm(background, panelLight, mint, store.Operators);
			operatorPickerForm.OperatorSelected += (OperatorAccount op) =>
			{
				currentOperator = op;
				UpdateBranchBadge();
				greetingLabel.Text = GreetingText();
				orderLabel.Text = OrderContextText();
				ApplyPermissions();
				ShowOrder();
			};
			operatorPickerForm.TopLevel = false;
			operatorPickerForm.FormBorderStyle = FormBorderStyle.None;
			operatorPickerForm.Dock = DockStyle.Fill;
			panel.Controls.Add(operatorPickerForm);
			operatorPickerForm.Show();
			ShowView(panel, "Select operator");
			SetActiveNav(pillOperator);
		}

		private void ShowOperatorManager()
		{
			if (HasPermission("Manage operators"))
			{
				Panel panel = new Panel
				{
					Dock = DockStyle.Fill
				};
				OperatorManagerForm operatorManagerForm = new OperatorManagerForm(background, panelLight, mint, store.Operators, (List<OperatorAccount> updatedOperators) =>
				{
					store.SaveOperators(updatedOperators);
				});
				operatorManagerForm.TopLevel = false;
				operatorManagerForm.FormBorderStyle = FormBorderStyle.None;
				operatorManagerForm.Dock = DockStyle.Fill;
				panel.Controls.Add(operatorManagerForm);
				operatorManagerForm.Show();
				ShowView(panel, "Manage operators", ShowSettings);
			}
		}

		private string GreetingText()
		{
			int hour = DateTime.Now.Hour;
			string text;
			if (hour < 12)
			{
				text = Tr.T("Good morning");
			}
			else
			{
				text = ((hour < 18) ? Tr.T("Good afternoon") : Tr.T("Good evening"));
			}
			return text + ", " + currentOperator.Name + BranchSuffix();
		}

		private bool HasPermission(string permission)
		{
			if (!currentOperator.Permissions.Contains("All permissions"))
			{
				return currentOperator.Permissions.Contains(permission);
			}
			return true;
		}

		private void ApplyPermissions()
		{
			pillRooms.Visible = HasPermission("Manage rooms");
			pillSettings.Visible = HasPermission("Settings");
			clockInOutBtn.Available = store.Features.ClockInOut;
			stockBtn.Available = store.Features.StockManagement;
			kdsNavButton.Available = store.Features.KitchenDisplay;
			eightySixNavButton.Available = store.Features.EightySixBoard;
			reservationsNavButton.Available = store.Features.Reservations && HasPermission("Reservations");
			scheduleNavButton.Available = store.Features.Scheduling && HasPermission("Manage operators");
			giftCardsNavButton.Available = store.Features.GiftCards && HasPermission("Gift cards");
			purchasesNavButton.Available = store.Features.Purchasing && HasPermission("Purchasing");
			drawerNavButton.Available = store.Features.CashDrawer && HasPermission("Cash drawer");
			LayoutAppBar();
			UpdateQrBanner();
		}

		private void UpdateQrBanner()
		{
			if (IsDisposed || !IsHandleCreated)
			{
				return;
			}
			if (InvokeRequired)
			{
				try
				{
					BeginInvoke(new Action(UpdateQrBanner));
					return;
				}
				catch
				{
					return;
				}
			}
			bool flag = (store.Features.QROrdering || store.Features.KioskMode) && !isOrderPc;
			qrPanel.Visible = flag;
			if (flag)
			{
				int num = Enumerable.Count(store.OpenOrders, (OpenOrder o) =>
				{
					string source = o.Source;
					return (source == "QR" || source == "Kiosk") ? true : false;
				});
				qrLabel.Text = $"  Guest orders live — {EffectiveGuestUrl()} — {num} open order(s), tap to manage";
			}
		}

		private void UpdateNavVisibility()
		{
			ApplyPermissions();
		}

		private void UpdateTabs(FlowLayoutPanel tabs)
		{
			foreach (Button control in tabs.Controls)
			{
				bool flag = control.Tag as string == category;
				control.BackColor = (flag ? mint : Skin.Kpi);
				control.ForeColor = (flag ? Skin.OnAccent : Skin.TextDim);
				control.FlatAppearance.MouseOverBackColor = (flag ? Skin.AccentPressed : Skin.PillHover);
			}
		}

		private void SplitBill()
		{
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder == null || openOrder.Items.Count == 0)
			{
				return;
			}
			Form form = new Form
			{
				Text = Tr.T("Split bill"),
				Size = new Size(500, 380),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Label label = new Label
				{
					Text = Tr.T("Select the items this person pays for:"),
					AutoSize = true,
					Location = new Point(15, 10),
					ForeColor = mint
				};
				List<(CheckBox cb, SoldLine line)> itemChecks = new List<(CheckBox, SoldLine)>();
				int num = 40;
				if (store.Features.SeatOrdering && openOrder.Items.Any((SoldLine i) => i.Seat > 0))
				{
					List<int> list = (from s in (from i in openOrder.Items
							where i.Seat > 0
							select i.Seat).Distinct()
						orderby s
						select s).ToList();
					if (list.Count > 1)
					{
						Label value = new Label
						{
							Text = Tr.T("Select by seat:"),
							AutoSize = true,
							Location = new Point(20, num + 4),
							ForeColor = Skin.TextDim
						};
						form.Controls.Add(value);
						int num2 = 130;
						int num3 = 0;
						foreach (int item4 in list)
						{
							if (num2 > 430)
							{
								num2 = 130;
								num3++;
							}
							int seatNo = item4;
							Button button = new Button
							{
								Text = Tr.T("S") + item4,
								Size = new Size(44, 26),
								Location = new Point(num2, num + num3 * 30),
								FlatStyle = FlatStyle.Flat,
								BackColor = panelLight,
								ForeColor = Skin.Text
							};
							button.FlatAppearance.BorderSize = 0;
							button.Click += (object _, EventArgs _) =>
							{
								foreach (var item5 in itemChecks)
								{
									item5.cb.Checked = item5.line.Seat == seatNo;
								}
							};
							form.Controls.Add(button);
							num2 += 50;
						}
						num += 34 + num3 * 30;
					}
				}
				foreach (SoldLine item6 in openOrder.Items)
				{
					string text = ((store.Features.SeatOrdering && item6.Seat > 0) ? $"[S{item6.Seat}] " : "");
					CheckBox checkBox = new CheckBox();
					checkBox.Text = $"{text}{item6.Quantity}x {item6.Product} ({item6.UnitPrice * (decimal)item6.Quantity:C})";
					checkBox.AutoSize = true;
					checkBox.Location = new Point(20, num);
					checkBox.ForeColor = Skin.Text;
					CheckBox item = checkBox;
					itemChecks.Add((item, item6));
					num += 28;
				}
				num += 12;
				Button button2 = new Button
				{
					Text = Tr.T("Pay selected items"),
					Location = new Point(15, num),
					Size = new Size(170, 38),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.OK;
				};
				form.ClientSize = new Size(500, Math.Max(340, num + 66));
				form.Controls.AddRange(new Control[2] { label, button2 });
				foreach (var item7 in itemChecks)
				{
					CheckBox item2 = item7.cb;
					form.Controls.Add(item2);
				}
				form.AcceptButton = button2;
				if (form.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				List<SoldLine> list2 = (from x in itemChecks
					where x.cb.Checked
					select x.line).ToList();
				if (list2.Count == 0)
				{
					MessageBox.Show(Tr.T("Select at least one item to pay for."), Tr.T("Split bill"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return;
				}
				decimal num4 = list2.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity);
				decimal num5 = ((basketDiscountPercent > 0m) ? Math.Round(num4 * basketDiscountPercent / 100m, 2) : 0m);
				decimal num6 = num4 - num5;
				Form payForm = new Form
				{
					Text = Tr.T("Split payment"),
					Size = new Size(400, 268),
					StartPosition = FormStartPosition.CenterParent,
					BackColor = background,
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 10f),
					FormBorderStyle = FormBorderStyle.FixedDialog,
					MaximizeBox = false,
					MinimizeBox = false
				};
				try
				{
					Label label2 = new Label
					{
						Text = $"Total: {num4:C}",
						AutoSize = true,
						Font = new Font("Segoe UI Semibold", 16f),
						ForeColor = mint,
						Location = new Point(20, 20)
					};
					Label label3 = new Label
					{
						Text = ((num5 > 0m) ? $"{list2.Sum((SoldLine l) => l.Quantity)} item(s) • Discount (-{basketDiscountPercent:0.#}%): -{num5:C}" : $"{list2.Sum((SoldLine l) => l.Quantity)} item(s) on this payment"),
						AutoSize = true,
						ForeColor = Skin.TextDim,
						Location = new Point(22, 56)
					};
					Label label4 = new Label
					{
						Text = Tr.T("Payment type:"),
						AutoSize = true,
						Location = new Point(20, 100)
					};
					ComboBox comboBox = new ComboBox
					{
						FlatStyle = FlatStyle.Flat,
						Size = new Size(210, 30),
						DropDownStyle = ComboBoxStyle.DropDownList,
						BackColor = panelLight,
						ForeColor = Skin.Text,
						Location = new Point(150, 96)
					};
					comboBox.Items.AddRange(new object[4] { "Cash", "Card", "Transfer", "Mobile" });
					comboBox.SelectedIndex = 0;
					Button button3 = new Button
					{
						Text = $"Accept payment  {num6:C}",
						Location = new Point(20, 142),
						Size = new Size(345, 46),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat,
						Font = new Font("Segoe UI Semibold", 12f)
					};
					button3.FlatAppearance.BorderSize = 0;
					button3.Click += (object _, EventArgs _) =>
					{
						payForm.DialogResult = DialogResult.OK;
					};
					Button button4 = new Button
					{
						Text = Tr.T("Cancel"),
						Location = new Point(20, 198),
						Size = new Size(345, 34),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						FlatStyle = FlatStyle.Flat
					};
					button4.FlatAppearance.BorderSize = 0;
					button4.Click += (object _, EventArgs _) =>
					{
						payForm.DialogResult = DialogResult.Cancel;
					};
					payForm.Controls.AddRange(new Control[6] { label2, label3, label4, comboBox, button3, button4 });
					payForm.AcceptButton = button3;
					payForm.CancelButton = button4;
					if (payForm.ShowDialog() != DialogResult.OK)
					{
						return;
					}
					string text2 = comboBox.Text;
					int num7 = store.NextPaymentNumber();
					store.AddSale(new Sale(DateTime.Now, num6, selectedTable, currentOperator.Name, list2, num7, openOrder.BillNumber, 0m, text2, OrderType: openOrder.OrderType, CustomerName: openOrder.CustomerName, Discount: num5));
					if (store.Features.AuditLog)
					{
						store.LogAudit(currentOperator.Name, "Payment", $"Split {num6:C} ({text2}) {selectedTable}");
					}
					if (store.Features.StockManagement)
					{
						StockEngine.Apply(store, list2.Select(l => (l.Product, (decimal)l.Quantity)), currentOperator?.Name ?? "Cashier", num7.ToString(), reverse: false);
						Auto86Sync();
					}
					List<SoldLine> list4 = openOrder.Items.Except(list2).ToList();
					store.RemoveOpenOrder(selectedRoom, selectedTable);
					if (list4.Count > 0)
					{
						store.AddOpenOrder(new OpenOrder(selectedRoom, selectedTable, currentOperator.Name, openOrder.Created, list4, openOrder.Note, openOrder.OrderNumber, openOrder.BillNumber, openOrder.OrderType, openOrder.CustomerName, openOrder.SeatCount, openOrder.Ready));
					}
					PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Payment");
					if (printerDestination != null && !string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
					{
						try
						{
							if (isOrderPc)
							{
								byte[] data = BuildEscPosBytes(printerDestination, list2, selectedRoom, selectedTable, currentOperator.Name, 0, openOrder.BillNumber, num7, "", basketDiscountPercent, num5);
								TcpPrintClient.SendPrintJob(GetMainPcHost(), printerDestination.WindowsPrinter, data);
							}
							else if (printerDestination.CutAfterPrint)
							{
								try
								{
									RawPrinter.PrintTicket(printerDestination, selectedRoom, selectedTable, currentOperator.Name, list2, ResolvePrinterName(printerDestination), 0, openOrder.BillNumber, num7, "", basketDiscountPercent, num5);
								}
								catch (InvalidOperationException)
								{
									PrintWindowsTicket(printerDestination, list2, 0, openOrder.BillNumber, num7, "", basketDiscountPercent, num5);
								}
							}
							else
							{
								PrintWindowsTicket(printerDestination, list2, 0, openOrder.BillNumber, num7, "", basketDiscountPercent, num5);
							}
						}
						catch (Exception ex2)
						{
							MessageBox.Show(Tr.T("Could not print payment: ") + ex2.Message, Tr.T("Payment"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
						}
					}
					MessageBox.Show(string.Format("{0}\n{1:C}  •  {2}", Tr.T("Payment accepted"), num6, selectedTable), Tr.T("Split bill"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					basket.Clear();
					activeSeat = 1;
					hasOpenOrder = list4.Count > 0;
					if (hasOpenOrder)
					{
						foreach (SoldLine item3 in list4)
						{
							Product product = products.FirstOrDefault((Product pr) => pr.Name == item3.Product);
							if (product != null)
							{
								basket.Add((product, item3.Quantity, item3.Course, item3.Note, item3.Seat, item3.Modifiers));
							}
						}
					}
					UpdateOrderButtons();
					salesLabel.Text = TodaySalesAmount();
					RenderBasket();
					orderLabel.Text = OrderContextText();
					Room room = store.Rooms.FirstOrDefault((Room r) => r.Name == selectedRoom);
					if (room != null)
					{
						RenderTableMap(room);
					}
				}
				finally
				{
					if (payForm != null)
					{
						((IDisposable)payForm).Dispose();
					}
				}
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
		}

		private void TransferTable()
		{
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder == null)
			{
				return;
			}
			List<(string, string)> list = new List<(string, string)>();
			foreach (Room room in store.Rooms)
			{
				for (int i = 1; i <= room.TableCount; i++)
				{
					string text = TableName(room.Name, i);
					if (store.GetOpenOrder(room.Name, text) == null)
					{
						list.Add((room.Name, text));
					}
				}
			}
			Form form = new Form
			{
				Text = Tr.T("Transfer to..."),
				Size = new Size(350, 300),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				ListBox tableList = new ListBox
				{
					Location = new Point(15, 10),
					Size = new Size(305, 200),
					BackColor = panelLight,
					ForeColor = Skin.Text
				};
				foreach (var item in list)
				{
					tableList.Items.Add(item.Item1 + " → " + item.Item2);
				}
				if (tableList.Items.Count == 0)
				{
					tableList.Items.Add("No available tables");
				}
				Button okBtn = ActionButton(Tr.T("Transfer"), 15, 218, 140, 34, mint);
				okBtn.ForeColor = Skin.OnAccent;
				okBtn.Enabled = false;
				tableList.SelectedIndexChanged += (object _, EventArgs _) =>
				{
					okBtn.Enabled = tableList.SelectedIndex >= 0;
				};
				okBtn.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.OK;
				};
				form.Controls.AddRange(new Control[2] { tableList, okBtn });
				if (form.ShowDialog() == DialogResult.OK && tableList.SelectedIndex >= 0)
				{
					var (text2, text3) = list[tableList.SelectedIndex];
					store.RemoveOpenOrder(selectedRoom, selectedTable);
					PosStore posStore = store;
					OpenOrder openOrder2 = openOrder._003CClone_003E_0024();
					openOrder2.Room = text2;
					openOrder2.Table = text3;
					posStore.AddOpenOrder(openOrder2);
					if (store.Features.AuditLog)
					{
						store.LogAudit(currentOperator.Name, "Transfer", selectedRoom + "/" + selectedTable + " → " + text2 + "/" + text3);
					}
					MessageBox.Show(Tr.T("Order transferred to ") + text3 + " (" + text2 + ")", Tr.T("Transfer"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					basket.Clear();
					activeSeat = 1;
					hasOpenOrder = false;
					UpdateOrderButtons();
					RenderBasket();
					ShowRooms();
				}
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
		}

		private void MergeTables()
		{
			OpenOrder openOrder = store.GetOpenOrder(selectedRoom, selectedTable);
			if (openOrder == null)
			{
				return;
			}
			List<(string, string, int)> list = new List<(string, string, int)>();
			foreach (Room room2 in store.Rooms)
			{
				for (int i = 1; i <= room2.TableCount; i++)
				{
					string text = TableName(room2.Name, i);
					if (!(room2.Name == selectedRoom) || !(text == selectedTable))
					{
						OpenOrder openOrder2 = store.GetOpenOrder(room2.Name, text);
						if (openOrder2 != null)
						{
							list.Add((room2.Name, text, openOrder2.Items.Count));
						}
					}
				}
			}
			if (list.Count == 0)
			{
				MessageBox.Show(Tr.T("No other occupied tables to merge with."), Tr.T("Merge tables"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			Form form = new Form
			{
				Text = Tr.T("Merge into ") + selectedTable,
				Size = new Size(350, 300),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				ListBox tableList = new ListBox
				{
					Location = new Point(15, 10),
					Size = new Size(305, 200),
					BackColor = panelLight,
					ForeColor = Skin.Text
				};
				foreach (var item4 in list)
				{
					tableList.Items.Add($"{item4.Item1} → {item4.Item2} ({item4.Item3} items)");
				}
				Button okBtn = ActionButton(Tr.T("Merge"), 15, 218, 140, 34, mint);
				okBtn.ForeColor = Skin.OnAccent;
				okBtn.Enabled = false;
				tableList.SelectedIndexChanged += (object _, EventArgs _) =>
				{
					okBtn.Enabled = tableList.SelectedIndex >= 0;
				};
				okBtn.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.OK;
				};
				form.Controls.AddRange(new Control[2] { tableList, okBtn });
				if (form.ShowDialog() != DialogResult.OK || tableList.SelectedIndex < 0)
				{
					return;
				}
				(string, string, int) tuple = list[tableList.SelectedIndex];
				string item = tuple.Item1;
				string item2 = tuple.Item2;
				OpenOrder openOrder3 = store.GetOpenOrder(item, item2);
				if (openOrder3 == null)
				{
					return;
				}
				int seatOffset = 0;
				if (store.Features.SeatOrdering && openOrder3.Items.Any((SoldLine soldLine) => soldLine.Seat > 0))
				{
					seatOffset = Math.Max(openOrder.SeatCount, (openOrder.Items.Count > 0) ? openOrder.Items.Max((SoldLine soldLine) => soldLine.Seat) : 0);
				}
				List<SoldLine> list2 = openOrder3.Items.Select((SoldLine soldLine2) =>
				{
					SoldLine soldLine = soldLine2._003CClone_003E_0024();
					soldLine.Seat = ((soldLine2.Seat > 0) ? (soldLine2.Seat + seatOffset) : soldLine2.Seat);
					return soldLine;
				}).ToList();
				List<SoldLine> list3 = openOrder.Items.Concat(list2).ToList();
				OpenOrder openOrder4 = openOrder._003CClone_003E_0024();
				openOrder4.Items = list3;
				openOrder4.SeatCount = Math.Max(openOrder.SeatCount, (list3.Count > 0) ? list3.Max((SoldLine soldLine) => soldLine.Seat) : 0);
				openOrder4.Ready = false;
				OpenOrder order = openOrder4;
				store.RemoveOpenOrder(item, item2);
				store.RemoveOpenOrder(selectedRoom, selectedTable);
				store.AddOpenOrder(order);
				foreach (SoldLine item3 in list2)
				{
					Product product = products.FirstOrDefault((Product p) => p.Name == item3.Product);
					if (!(product == null))
					{
						int num = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) b) => b.Product == product && b.Note == item3.Note && b.Modifiers == item3.Modifiers && (!store.Features.SeatOrdering || b.Seat == item3.Seat));
						if (num >= 0)
						{
							basket[num] = (product, basket[num].Count + item3.Quantity, basket[num].Course, basket[num].Note, basket[num].Seat, JoinMods(basket[num].Modifiers, item3.Modifiers));
						}
						else
						{
							basket.Add((product, item3.Quantity, item3.Course, item3.Note, item3.Seat, item3.Modifiers));
						}
					}
				}
				hasOpenOrder = true;
				activeSeat = 1;
				UpdateOrderButtons();
				RenderBasket();
				orderLabel.Text = OrderContextText();
				if (store.Features.AuditLog)
				{
					store.LogAudit(currentOperator.Name, "Merge", item + "/" + item2 + " → " + selectedRoom + "/" + selectedTable);
				}
				MessageBox.Show(string.Format("{0} {1} {2} {3} ({4}) {5} {6}.\n{7} {8}", Tr.T("Merged"), openOrder3.Items.Count, Tr.T("items from"), item2, item, Tr.T("into"), selectedTable, item2, Tr.T("is now free.")), Tr.T("Merge tables"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				Room room = store.Rooms.FirstOrDefault((Room r) => r.Name == selectedRoom);
				if (room != null)
				{
					RenderTableMap(room);
				}
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
		}

		private void ClockInOut()
		{
			Form form = new Form
			{
				Text = Tr.T("Clock In / Out"),
				Size = new Size(320, 200),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				ShiftRecord active = store.Shifts.FirstOrDefault((ShiftRecord s) => s.Operator == currentOperator.Name && !s.ClockOut.HasValue);
				Label label;
				Button button;
				if (active != null)
				{
					label = new Label
					{
						Text = $"Clocked in at {active.ClockIn:HH:mm}",
						AutoSize = true,
						Location = new Point(20, 20),
						ForeColor = mint
					};
					button = new Button
					{
						Text = Tr.T("Clock Out"),
						Location = new Point(20, 60),
						Size = new Size(270, 40),
						BackColor = Skin.Danger,
						ForeColor = Skin.OnFill,
						FlatStyle = FlatStyle.Flat
					};
					button.Click += (object _, EventArgs _) =>
					{
						int index = store.Shifts.IndexOf(active);
						List<ShiftRecord> shifts = store.Shifts;
						ShiftRecord shiftRecord = active._003CClone_003E_0024();
						shiftRecord.ClockOut = DateTime.Now;
						shifts[index] = shiftRecord;
						store.SaveShifts(store.Shifts);
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Clock Out", active.ClockIn.ToString("HH:mm"));
						}
						form.DialogResult = DialogResult.OK;
					};
				}
				else
				{
					label = new Label
					{
						Text = Tr.T("Not currently clocked in"),
						AutoSize = true,
						Location = new Point(20, 20),
						ForeColor = Skin.Warning
					};
					button = new Button
					{
						Text = Tr.T("Clock In"),
						Location = new Point(20, 60),
						Size = new Size(270, 40),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat
					};
					button.Click += (object _, EventArgs _) =>
					{
						store.Shifts.Add(new ShiftRecord(currentOperator.Name, DateTime.Now));
						store.SaveShifts(store.Shifts);
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Clock In", DateTime.Now.ToString("HH:mm"));
						}
						form.DialogResult = DialogResult.OK;
					};
				}
				button.FlatAppearance.BorderSize = 0;
				form.Controls.AddRange(new Control[2] { label, button });
				form.ShowDialog();
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
		}

		private void ShowShiftReport()
		{
			List<ShiftRecord> list = store.Shifts.Where((ShiftRecord s) => s.Operator == currentOperator.Name && s.ClockOut.HasValue && s.ClockOut.Value.Date == DateTime.Today).ToList();
			using Form form = new Form
			{
				Text = Tr.T("Shift Report"),
				Size = new Size(500, 360),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			ListView listView = new ListView
			{
				Location = new Point(15, 10),
				Size = new Size(455, 250),
				BackColor = panelLight,
				ForeColor = Skin.Text,
				View = View.Details,
				FullRowSelect = true
			};
			listView.Columns.Add("Clock In", 100);
			listView.Columns.Add("Clock Out", 100);
			listView.Columns.Add("Duration", 100);
			listView.Columns.Add("Operator", 130);
			foreach (ShiftRecord item in list)
			{
				TimeSpan timeSpan = item.ClockOut.Value - item.ClockIn;
				listView.Items.Add(new ListViewItem(new string[4]
				{
					item.ClockIn.ToString("HH:mm"),
					item.ClockOut?.ToString("HH:mm") ?? "-",
					$"{timeSpan.Hours}h{timeSpan.Minutes}m",
					item.Operator
				}));
			}
			List<Sale> list2 = store.Sales.Where((Sale s) => s.Time.Date == DateTime.Today).ToList();
			decimal num = list2.Sum((Sale s) => s.Total);
