			{
				Text = $"Today: {list2.Count} sales  •  {num:C}\nShifts: {list.Count}",
				AutoSize = true,
				Location = new Point(15, 268),
				ForeColor = mint
			};
			form.Controls.AddRange(new Control[2] { listView, label });
			form.ShowDialog();
		}

		private void DispatchReport(string id)
		{
			if (id == null)
			{
				return;
			}
			switch (id.Length)
			{
			case 7:
				switch (id[0])
				{
				case 'P':
					if (id == "Payroll")
					{
						ShowPayrollExport();
					}
					break;
				case 'H':
					if (id == "Heatmap")
					{
						ShowOccupancyHeatmap();
					}
					break;
				case 'M':
					if (id == "MenuEng")
					{
						ShowMenuEngineering();
					}
					break;
				}
				break;
			case 10:
				switch (id[0])
				{
				case 'S':
					if (id == "ServerPerf")
					{
						ShowServerPerformance();
					}
					break;
				case 'A':
					if (id == "AcctExport")
					{
						ShowAccountingExport();
					}
					break;
				}
				break;
			case 6:
				switch (id[0])
				{
				case 'E':
					if (id == "EmpPct")
					{
						PromptEmployeeDiscountPct();
					}
					break;
				case 'B':
					if (id == "Backup")
					{
						ShowBackupDialog();
					}
					break;
				case 'A':
					if (id == "ApiCfg")
					{
						ShowApiConfigDialog();
					}
					break;
				case 'C':
				case 'D':
					break;
				}
				break;
			case 8:
				switch (id[0])
				{
				case 'L':
					if (id == "LiveDash")
					{
						ShowLiveDashboard();
					}
					break;
				case 'C':
					if (id == "CloseDay")
					{
						ShowCloseOfDayScreen();
					}
					break;
				case 'D':
					if (id == "DiscVoid")
					{
						ShowDiscountVoidReport();
					}
					break;
				case 'I':
					if (id == "Insights")
					{
						ShowAiInsights();
					}
					break;
				case 'B':
					if (id == "Branches")
					{
						ShowBranchesDialog();
					}
					break;
				case 'G':
					if (id == "GuestUrl")
					{
						ShowGuestUrlDialog();
					}
					break;
				case 'E':
				case 'F':
				case 'H':
				case 'J':
				case 'K':
					break;
				}
				break;
			case 13:
				if (id == "PrepAnalytics")
				{
					ShowPrepAnalytics();
				}
				break;
			case 9:
				if (id == "CloudSync")
				{
					ShowCloudSyncDialog();
				}
				break;
			case 11:
			case 12:
				break;
			}
		}

		private Form ReportShell(string title, int w, int h)
		{
			return new Form
			{
				Text = title,
				Size = new Size(w, h),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
		}

		private Button ReportButton(string text, Point loc, Size size, Color back, Color fore)
		{
			if (fore == Skin.Background)
			{
				fore = Skin.OnAccent;
			}
			Button button = new Button();
			button.Text = text;
			button.Location = loc;
			button.Size = size;
			button.BackColor = back;
			button.ForeColor = fore;
			button.FlatStyle = FlatStyle.Flat;
			button.Font = new Font("Segoe UI Semibold", 10f);
			button.Cursor = Cursors.Hand;
			button.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(button);
			return button;
		}

		private void PromptEmployeeDiscountPct()
