		private void ShowPayrollExport()
		{
			if (!store.Features.PayrollExport)
			{
				return;
			}
			Form f = ReportShell("Payroll export", 740, 530);
			try
			{
				DateTime from = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1);
				Label label = new Label
				{
					Text = $"Pay period: {from:MMMM yyyy} (1 → today)",
					AutoSize = true,
					Location = new Point(14, 12),
					ForeColor = mint,
					Font = new Font("Segoe UI Semibold", 12f)
				};
				ListView listView = new ListView
				{
					Location = new Point(14, 42),
					Size = new Size(696, 340),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true,
					GridLines = true
				};
				listView.Columns.AddRange(new ColumnHeader[6]
				{
					new ColumnHeader
					{
						Text = Tr.T("Operator"),
						Width = 170
					},
					new ColumnHeader
					{
						Text = Tr.T("Shifts"),
						Width = 70
					},
					new ColumnHeader
					{
						Text = Tr.T("Hours"),
						Width = 80
					},
					new ColumnHeader
					{
						Text = Tr.T("Wage/h"),
						Width = 90
					},
					new ColumnHeader
					{
						Text = Tr.T("Gross pay"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Clocked in"),
						Width = 90
					}
				});
				decimal grand = 0m;
				List<(string Name, int Shifts, decimal Hours, decimal Wage, decimal Pay)> rows = new List<(string, int, decimal, decimal, decimal)>();
				foreach (OperatorAccount op in store.Operators)
				{
					List<ShiftRecord> list = store.Shifts.Where((ShiftRecord s) => s.Operator == op.Name && s.ClockIn >= from).ToList();
					decimal num = (decimal)list.Sum((ShiftRecord s) => ((s.ClockOut ?? DateTime.Now) - s.ClockIn).TotalHours);
					decimal num2 = Math.Round(num * op.Wage, 2);
					grand += num2;
					int num3 = Enumerable.Count(list, (ShiftRecord s) => !s.ClockOut.HasValue);
					rows.Add((op.Name, list.Count, num, op.Wage, num2));
					listView.Items.Add(new ListViewItem(new string[6]
					{
						op.Name,
						list.Count.ToString(),
						num.ToString("0.0"),
						op.Wage.ToString("C"),
						num2.ToString("C"),
						num3.ToString()
					}));
				}
				Label label2 = new Label
				{
					Text = $"Total gross payroll: {grand:C}",
					AutoSize = true,
					Location = new Point(14, 394),
					ForeColor = Skin.Warning,
					Font = new Font("Segoe UI Semibold", 13f)
				};
				Button button = ReportButton("Export CSV", new Point(14, 434), new Size(170, 40), mint, background);
				button.Click += (object _, EventArgs _) =>
				{
					using SaveFileDialog saveFileDialog = new SaveFileDialog
					{
						Filter = "CSV files (*.csv)|*.csv|All files (*.*)|*.*",
						FileName = $"payroll-{DateTime.Now:yyyy-MM}.csv"
					};
					if (saveFileDialog.ShowDialog() == DialogResult.OK)
					{
						StringBuilder stringBuilder = new StringBuilder("Operator,Shifts,Hours,WagePerHour,GrossPay\n");
						foreach (var item2 in rows)
						{
							object[] array = new object[5] { item2.Name, item2.Shifts, null, null, null };
							decimal item = item2.Hours;
							array[2] = item.ToString("0.0", CultureInfo.InvariantCulture);
							item = item2.Wage;
							array[3] = item.ToString("0.00", CultureInfo.InvariantCulture);
							item = item2.Pay;
							array[4] = item.ToString("0.00", CultureInfo.InvariantCulture);
							stringBuilder.AppendLine(string.Format("{0},{1},{2},{3},{4}", array));
						}
						stringBuilder.AppendLine("TOTAL,,," + grand.ToString("0.00", CultureInfo.InvariantCulture));
						File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString());
						MessageBox.Show(Tr.T("Payroll CSV exported:\n") + saveFileDialog.FileName, Tr.T("Payroll export"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
				};
				Button button2 = ReportButton("Close", new Point(580, 434), new Size(130, 40), panelLight, Skin.Text);
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[5] { label, listView, label2, button, button2 });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

		private void ShowServerPerformance()
		{
			if (!store.Features.ServerPerformance)
			{
				return;
			}
			Form f = ReportShell("Server performance", 780, 530);
			try
			{
				List<Sale> list = store.Sales.Where((Sale s) => s.Time.Date == DateTime.Today && !s.IsRefund).ToList();
				Label label = new Label
				{
					Text = $"Today — {DateTime.Today:dd/MM/yyyy}",
					AutoSize = true,
					Location = new Point(14, 12),
					ForeColor = mint,
					Font = new Font("Segoe UI Semibold", 12f)
				};
				ListView listView = new ListView
				{
					Location = new Point(14, 42),
					Size = new Size(736, 350),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true,
					GridLines = true
				};
				listView.Columns.AddRange(new ColumnHeader[7]
				{
					new ColumnHeader
					{
						Text = Tr.T("Server"),
						Width = 160
					},
					new ColumnHeader
					{
						Text = Tr.T("Sales"),
						Width = 80
					},
					new ColumnHeader
					{
						Text = Tr.T("Gross"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Items"),
						Width = 80
					},
					new ColumnHeader
					{
						Text = Tr.T("Avg ticket"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Discounts"),
						Width = 90
					},
					new ColumnHeader
					{
						Text = Tr.T("Refunds"),
						Width = 90
					}
				});
				string text = "";
				decimal num = 0m;
				foreach (IGrouping<string, Sale> g in from s in list
					group s by s.Operator into source
					orderby source.Sum((Sale s) => s.Total) descending
					select source)
				{
					decimal num2 = g.Sum((Sale s) => s.Total);
					if (num2 > num)
					{
						num = num2;
						text = g.Key;
					}
					int num3 = g.Sum((Sale s) =>
					{
						List<SoldLine>? items = s.Items;
						return (items != null) ? items.Sum((SoldLine i) => i.Quantity) : 0;
					});
					decimal num4 = ((g.Count() > 0) ? (num2 / (decimal)g.Count()) : 0m);
					int num5 = g.Count((Sale s) => s.Discount > 0m);
					int num6 = Enumerable.Count(store.Sales, (Sale s) => s.Time.Date == DateTime.Today && s.IsRefund && s.Operator == g.Key);
					listView.Items.Add(new ListViewItem(new string[7]
					{
						g.Key,
						g.Count().ToString(),
						num2.ToString("C"),
						num3.ToString(),
						num4.ToString("C"),
						num5.ToString(),
						num6.ToString()
					}));
				}
				Label label2 = new Label();
				label2.Text = ((list.Count == 0) ? "No sales yet today." : $"Top server: {text} ({num:C})   •   {list.Count} sales   •   {list.Sum((Sale s) => s.Total):C} gross");
				label2.AutoSize = true;
				label2.Location = new Point(14, 404);
				label2.ForeColor = Skin.Warning;
				label2.Font = new Font("Segoe UI Semibold", 11f);
				Label label3 = label2;
				Button button = ReportButton("Close", new Point(620, 452), new Size(130, 40), panelLight, Skin.Text);
				button.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[4] { label, listView, label3, button });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

		private void ShowLiveDashboard()
		{
			if (!store.Features.LiveDashboard)
			{
				return;
			}
			Form f = ReportShell("Live dashboard", 1000, 640);
			try
			{
				List<Sale> list = store.Sales.Where((Sale s) => s.Time.Date == DateTime.Today).ToList();
				decimal num = list.Where((Sale s) => !s.IsRefund).Sum((Sale s) => s.Total);
				int num2 = Enumerable.Count(list, (Sale s) => !s.IsRefund);
				Label label = new Label
				{
					Text = $"Sales\n{num:C}",
					AutoSize = true,
					Location = new Point(20, 14),
					ForeColor = mint,
					Font = new Font("Segoe UI Semibold", 14f)
				};
				Label label2 = new Label
				{
					Text = $"Transactions\n{num2}",
					AutoSize = true,
					Location = new Point(200, 14),
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI Semibold", 14f)
				};
				Label label3 = new Label
				{
					Text = "Avg ticket\n" + ((num2 > 0) ? (num / (decimal)num2).ToString("C") : 0m.ToString("C")),
					AutoSize = true,
					Location = new Point(380, 14),
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI Semibold", 14f)
				};
				Label label4 = new Label
				{
					Text = $"Tips\n{list.Sum((Sale s) => s.Tip):C}",
					AutoSize = true,
					Location = new Point(560, 14),
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI Semibold", 14f)
				};
				Label label5 = new Label
				{
					Text = $"Open tables\n{store.OpenOrders.Count}",
					AutoSize = true,
					Location = new Point(730, 14),
					ForeColor = Skin.Warning,
					Font = new Font("Segoe UI Semibold", 14f)
				};
				Panel panel = new Panel
				{
					Location = new Point(20, 86),
					Size = new Size(720, 360),
					BackColor = panelLight
				};
				List<Sale> gToday = list;
				panel.Paint += (object _, PaintEventArgs e) =>
				{
					List<(int, decimal)> list2 = (from num7 in Enumerable.Range(6, 18)
						select (Hour: num7, Value: gToday.Where((Sale s) => s.Time.Hour == num7).Sum((Sale s) => s.Total))).ToList();
					decimal num4 = Math.Max(1m, list2.Max(((int Hour, decimal Value) x) => x.Value));
					int num5 = 14;
					foreach (var item2 in list2)
					{
						int num6 = (int)(280.0 * (double)item2.Item2 / (double)num4);
						if (item2.Item2 > 0m)
						{
							e.Graphics.FillRectangle(new SolidBrush(Skin.Success), new Rectangle(num5, 300 - num6, 34, num6));
						}
						if (item2.Item2 > 0m)
						{
							Graphics graphics = e.Graphics;
							decimal item = item2.Item2;
							graphics.DrawString(item.ToString("0"), Font, Brushes.White, num5, Math.Max(2, 300 - num6 - 16));
						}
						e.Graphics.DrawString($"{item2.Item1}h", Font, Brushes.LightGray, num5, 306f);
						num5 += 39;
					}
					e.Graphics.DrawString("Hourly sales — today", Font, Brushes.Gainsboro, 14f, 6f);
				};
				ListView listView = new ListView
				{
					Location = new Point(756, 86),
					Size = new Size(210, 360),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true
				};
				listView.Columns.Add("Hour", 70);
				listView.Columns.Add("Sales", 120);
				foreach (int h in Enumerable.Range(6, 18))
				{
					decimal num3 = list.Where((Sale s) => s.Time.Hour == h).Sum((Sale s) => s.Total);
					if (num3 > 0m)
					{
						listView.Items.Add(new ListViewItem(new string[2]
						{
							$"{h}h",
							num3.ToString("C")
						}));
					}
				}
				Button button = ReportButton("Refresh", new Point(20, 462), new Size(140, 40), mint, background);
				button.Click += (object _, EventArgs _) =>
				{
					f.Dispose();
					ShowLiveDashboard();
				};
				Button button2 = ReportButton("Close", new Point(172, 462), new Size(130, 40), panelLight, Skin.Text);
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[9] { label, label2, label3, label4, label5, panel, listView, button, button2 });
