		private void ShowMenuEngineering()
		{
			if (!store.Features.MenuEngineering)
			{
				return;
			}
			Form f = ReportShell("Menu engineering matrix", 860, 560);
			try
			{
				List<Sale> source = store.Sales.Where((Sale s) => !s.IsRefund).ToList();
				Label label = new Label
				{
					Text = Tr.T("Popularity vs contribution — Stars / Plowhorses / Puzzles / Dogs"),
					AutoSize = true,
					Location = new Point(14, 12),
					ForeColor = mint,
					Font = new Font("Segoe UI Semibold", 12f)
				};
				ListView listView = new ListView
				{
					Location = new Point(14, 42),
					Size = new Size(640, 430),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true,
					GridLines = true
				};
				listView.Columns.AddRange(new ColumnHeader[5]
				{
					new ColumnHeader
					{
						Text = Tr.T("Product"),
						Width = 230
					},
					new ColumnHeader
					{
						Text = Tr.T("Qty"),
						Width = 60
					},
					new ColumnHeader
					{
						Text = Tr.T("Revenue"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Share %"),
						Width = 80
					},
					new ColumnHeader
					{
						Text = Tr.T("Class"),
						Width = 140
					}
				});
				var items = (from i in source.SelectMany((Sale s) => s.Items ?? new List<SoldLine>())
					group i by i.Product into g
					select new
					{
						Product = g.Key,
						Qty = g.Sum((SoldLine i) => i.Quantity),
						Rev = g.Sum((SoldLine i) => i.UnitPrice * (decimal)i.Quantity - i.Discount)
					}).ToList();
				if (items.Count == 0)
				{
					listView.Items.Add(new ListViewItem(new string[5] { "No item sales yet", "0", "0", "0", "" }));
				}
				else
				{
					double num = items.Average(i => (double)i.Qty);
					double num2 = (double)items.Average(i => i.Rev);
					decimal num3 = items.Sum(i => i.Rev);
					foreach (var item in items.OrderByDescending(i => i.Rev))
					{
						string text;
						if ((double)item.Qty >= num && (double)item.Rev >= num2)
						{
							text = "Star ⭐";
						}
						else if ((double)item.Qty >= num)
						{
							text = "Plowhorse";
						}
						else
						{
							text = (((double)item.Rev >= num2) ? "Puzzle" : "Dog");
						}
						double num4 = ((num3 > 0m) ? ((double)item.Rev / (double)num3 * 100.0) : 0.0);
						ListViewItem listViewItem = new ListViewItem(new string[5]
						{
							item.Product,
							item.Qty.ToString(),
							item.Rev.ToString("C"),
							num4.ToString("0.0"),
							text
						});
						if (text.StartsWith("Star"))
						{
							listViewItem.ForeColor = Skin.SuccessText;
						}
						else if (text == "Dog")
						{
							listViewItem.ForeColor = Skin.DangerText;
						}
						listView.Items.Add(listViewItem);
					}
				}
				Label label2 = new Label
				{
					Text = ((items.Count == 0) ? "" : $"⭐ Stars: {Enumerable.Count(items, i => (double)i.Qty >= items.Average(x => (double)x.Qty) && (double)i.Rev >= items.Average(x => (double)x.Rev))}   •   items: {items.Count}   •   revenue: {items.Sum(i => i.Rev):C}"),
					AutoSize = true,
					Location = new Point(14, 482),
					ForeColor = Skin.Warning
				};
				Button button = ReportButton("Close", new Point(716, 486), new Size(130, 40), panelLight, Skin.Text);
				button.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[4] { label, listView, label2, button });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

