		private byte[]? BuildDatabaseZip()
		{
			string[] files = Directory.GetFiles(store.DataFolder, "*.json");
			if (files.Length == 0)
			{
				return null;
			}
			using MemoryStream memoryStream = new MemoryStream();
			using (ZipArchive destination = new ZipArchive(memoryStream, ZipArchiveMode.Create, leaveOpen: true))
			{
				string[] array = files;
				foreach (string text in array)
				{
					destination.CreateEntryFromFile(text, Path.GetFileName(text), CompressionLevel.Optimal);
				}
			}
			return memoryStream.ToArray();
		}

		private bool RunBackup(bool silent)
		{
			try
			{
				string text = store.Features.BackupPath.Trim();
				if (text.Length == 0)
				{
					if (!silent)
					{
						MessageBox.Show(Tr.T("Set a backup folder first."), Tr.T("Cloud backup"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
					return false;
				}
				Directory.CreateDirectory(text);
				byte[] array = BuildDatabaseZip();
				if (array == null)
				{
					if (!silent)
					{
						MessageBox.Show(Tr.T("No database files found to back up."), Tr.T("Cloud backup"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
					return false;
				}
				string text2 = Path.Combine(text, $"vectron-backup-{DateTime.Now:yyyyMMdd-HHmmss}.zip");
				if (File.Exists(text2))
				{
					File.Delete(text2);
				}
				File.WriteAllBytes(text2, array);
				if (!silent)
				{
					MessageBox.Show(string.Format("{0}{1}\n\n{2} KB zipped.", Tr.T("Backup created:\n"), text2, array.Length / 1024), Tr.T("Cloud backup"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				}
				return true;
			}
			catch (Exception ex)
			{
				if (!silent)
				{
					MessageBox.Show(Tr.T("Backup failed:\n") + ex.Message, Tr.T("Cloud backup"), MessageBoxButtons.OK, MessageBoxIcon.Hand);
				}
				return false;
			}
		}

		private void StartKioskAutoVoidScheduler()
		{
			System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer { Interval = 30000 };
			timer.Tick += (object _, EventArgs _) =>
			{
				try
				{
					store.CleanExpiredKioskOrders();
				}
				catch
				{
				}
			};
			timer.Start();
		}

		private void StartBackupScheduler()
		{
			Check();
			System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer();
			timer.Interval = 1800000;
			timer.Tick += (object _, EventArgs _) =>
			{
				Check();
			};
			timer.Start();
			void Check()
			{
				try
				{
					if (store.Features.CloudBackup && store.Features.BackupDaily && store.Features.BackupPath.Trim().Length != 0 && !(lastDailyBackup.Date == DateTime.Today) && RunBackup(silent: true))
					{
						lastDailyBackup = DateTime.Today;
					}
				}
				catch
				{
				}
			}
		}

		private static string NormalizeSyncUrl(string url)
		{
			url = url.Trim().TrimEnd('/');
			if (url.Length > 0 && !url.StartsWith("http://", StringComparison.OrdinalIgnoreCase) && !url.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
			{
				url = "http://" + url;
			}
			return url;
		}

		private void StartCloudSyncScheduler()
		{
			System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer();
			timer.Interval = 60000;
			timer.Tick += (object _, EventArgs _) =>
			{
				try
				{
					if (store.Features.CloudSync)
					{
						int num = Math.Max(1, Math.Min(1440, store.Features.CloudSyncMinutes));
						if (!((DateTime.Now - lastCloudSync).TotalMinutes < (double)num))
						{
							RunCloudSync(showResult: false);
						}
					}
				}
				catch
				{
				}
			};
			timer.Start();
		}

		private void RunCloudSync(bool showResult)
		{
			if (syncRunning || IsDisposed || !IsHandleCreated)
			{
				return;
			}
			string url = NormalizeSyncUrl(store.Features.CloudSyncUrl);
			if (url.Length == 0)
			{
				if (showResult)
				{
					MessageBox.Show(Tr.T("Set the cloud sync server URL first\n(Settings > Network > Cloud sync settings)."), Tr.T("Cloud sync"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				}
				return;
			}
			if (string.IsNullOrEmpty(store.Features.CloudSyncDevice))
			{
				store.Features.CloudSyncDevice = Environment.MachineName;
				store.SaveFeatures(store.Features);
			}
			string key = (string.IsNullOrEmpty(store.Features.CloudSyncKey) ? store.Features.ApiKey : store.Features.CloudSyncKey);
			string device = store.Features.CloudSyncDevice;
			string since = store.Features.CloudSyncLast;
			bool doPull = store.Features.CloudSyncPull;
			List<Sale> queued = store.SyncQueue.ToList();
			syncRunning = true;
			lastCloudSync = DateTime.Now;
			Task.Run(async () =>
			{
				string status = "";
				int added = 0;
				bool pushedOk = true;
				string serverTime = "";
				List<Sale> pulled = new List<Sale>();
				try
				{
					using HttpClient hc = new HttpClient
					{
						Timeout = TimeSpan.FromSeconds(10.0)
					};
					if (queued.Count > 0)
					{
						string content = JsonSerializer.Serialize(new
						{
							key = key,
							device = device,
							sales = queued
						});
						HttpResponseMessage resp = await hc.PostAsync(url + "/sync/sales", new StringContent(content, Encoding.UTF8, "application/json"));
						using JsonDocument jsonDocument = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
						JsonElement rootElement = jsonDocument.RootElement;
						if (rootElement.TryGetProperty("ok", out var value) && value.ValueKind == JsonValueKind.True)
						{
							int count = queued.Count;
							status = $"Pushed {count} sale(s).";
						}
						else
						{
							pushedOk = false;
							status = "Push failed: " + (rootElement.TryGetProperty("error", out var value2) ? value2.GetString() : $"HTTP {(int)resp.StatusCode}");
						}
					}
					else
					{
						status = "Nothing to push.";
					}
					if (pushedOk & doPull)
					{
						HttpResponseMessage resp = await hc.GetAsync(url + "/sync/sales?since=" + Uri.EscapeDataString(since) + "&device=" + Uri.EscapeDataString(device) + "&key=" + Uri.EscapeDataString(key));
						using JsonDocument jsonDocument2 = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
						JsonElement rootElement2 = jsonDocument2.RootElement;
						if (rootElement2.TryGetProperty("ok", out var value3) && value3.ValueKind == JsonValueKind.True)
						{
							if (rootElement2.TryGetProperty("server_time", out var value4))
							{
								serverTime = value4.GetString() ?? "";
							}
							if (rootElement2.TryGetProperty("sales", out var value5) && value5.ValueKind == JsonValueKind.Array)
							{
								foreach (JsonElement item in value5.EnumerateArray())
								{
									try
									{
										Sale sale = JsonSerializer.Deserialize<Sale>(item.GetRawText());
										if (!(sale == null) && !(sale.Device == device))
										{
											pulled.Add(sale);
										}
									}
									catch
									{
									}
								}
							}
							status += $" Fetched {pulled.Count} remote sale(s).";
						}
						else
						{
							status = status + " Pull failed: " + (rootElement2.TryGetProperty("error", out var value6) ? value6.GetString() : $"HTTP {(int)resp.StatusCode}");
						}
					}
				}
				catch (Exception ex)
				{
					status = "Sync error: " + ex.Message;
				}
				try
				{
					BeginInvoke((Action)(() =>
					{
						try
						{
							foreach (Sale item2 in pulled)
							{
								if (!store.HasSale(item2))
								{
									store.Sales.Add(item2);
									added++;
								}
							}
							if (added > 0)
							{
								store.Sales.Sort((Sale a, Sale b) => a.Time.CompareTo(b.Time));
								store.SaveSales();
							}
							if (pushedOk && queued.Count > 0)
							{
								HashSet<Sale> hashSet = new HashSet<Sale>(queued);
								store.SyncQueue.RemoveAll(hashSet.Contains);
								store.SaveSyncQueue();
							}
							if (!string.IsNullOrEmpty(serverTime) && serverTime != store.Features.CloudSyncLast)
							{
								store.Features.CloudSyncLast = serverTime;
								store.SaveFeatures(store.Features);
							}
							if (added > 0)
							{
								status += $" Added {added} new sale(s) locally.";
							}
						}
						finally
						{
							syncRunning = false;
						}
						if (showResult)
						{
							MessageBox.Show(status, Tr.T("Cloud sync"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
						}
					}));
				}
				catch
				{
					syncRunning = false;
				}
			});
		}

		private void UploadBackupToHome(bool showResult)
		{
			if (uploadRunning || IsDisposed || !IsHandleCreated)
			{
				return;
			}
			string url = NormalizeSyncUrl(store.Features.CloudSyncUrl);
			if (url.Length == 0)
			{
				if (showResult)
				{
					MessageBox.Show(Tr.T("Set the cloud sync server URL first\n(Settings > Network > Cloud sync settings)."), Tr.T("Database backup"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				}
				return;
			}
			if (string.IsNullOrEmpty(store.Features.CloudSyncDevice))
			{
				store.Features.CloudSyncDevice = Environment.MachineName;
				store.SaveFeatures(store.Features);
			}
			string key = (string.IsNullOrEmpty(store.Features.CloudSyncKey) ? store.Features.ApiKey : store.Features.CloudSyncKey);
			string device = store.Features.CloudSyncDevice;
			uploadRunning = true;
			Task.Run(async () =>
			{
				bool ok = false;
				string status;
				try
				{
					byte[] zip = BuildDatabaseZip();
					if (zip == null)
					{
						status = "No database files found to back up.";
					}
					else
					{
						using HttpClient hc = new HttpClient
						{
							Timeout = TimeSpan.FromSeconds(180.0)
						};
						string content = JsonSerializer.Serialize(new
						{
							key = key,
							store = device,
							data = Convert.ToBase64String(zip)
						});
						HttpResponseMessage resp = await hc.PostAsync(url + "/sync/backup", new StringContent(content, Encoding.UTF8, "application/json"));
						using JsonDocument jsonDocument = JsonDocument.Parse(await resp.Content.ReadAsStringAsync());
						JsonElement rootElement = jsonDocument.RootElement;
						if (rootElement.TryGetProperty("ok", out var value) && value.ValueKind == JsonValueKind.True)
						{
							ok = true;
							status = $"Database backup uploaded to home ({zip.Length / 1024} KB).";
						}
						else
						{
							status = "Backup upload failed: " + (rootElement.TryGetProperty("error", out var value2) ? value2.GetString() : $"HTTP {(int)resp.StatusCode}");
						}
					}
				}
				catch (Exception ex)
				{
					status = "Backup upload failed: " + ex.Message;
				}
				try
				{
					BeginInvoke((Action)(() =>
					{
						try
						{
							if (ok)
							{
								store.Features.CloudSyncLastBackup = DateTime.Now.ToString("o");
								store.SaveFeatures(store.Features);
							}
						}
						finally
						{
							uploadRunning = false;
						}
						if (showResult)
						{
							MessageBox.Show(status, Tr.T("Database backup"), MessageBoxButtons.OK, ok ? MessageBoxIcon.Asterisk : MessageBoxIcon.Exclamation);
						}
					}));
				}
				catch
				{
					uploadRunning = false;
				}
			});
		}

		private void RunManualPull()
		{
			if (syncRunning || uploadRunning || IsDisposed || !IsHandleCreated)
			{
				MessageBox.Show(Tr.T("Another sync operation is already running."), Tr.T("Cloud sync"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string url = NormalizeSyncUrl(store.Features.CloudSyncUrl);
			if (url.Length == 0)
			{
				MessageBox.Show(Tr.T("Set the cloud sync server URL first\n(Settings > Network > Cloud sync settings)."), Tr.T("Cloud sync"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			if (string.IsNullOrEmpty(store.Features.CloudSyncDevice))
			{
				store.Features.CloudSyncDevice = Environment.MachineName;
				store.SaveFeatures(store.Features);
			}
			string key = (string.IsNullOrEmpty(store.Features.CloudSyncKey) ? store.Features.ApiKey : store.Features.CloudSyncKey);
			string device = store.Features.CloudSyncDevice;
			syncRunning = true;
			Task.Run(async () =>
			{
				List<Sale> pulled = null;
				string error = "";
				try
				{
					using HttpClient hc = new HttpClient
					{
						Timeout = TimeSpan.FromSeconds(120.0)
					};
					HttpResponseMessage httpResponseMessage = await hc.GetAsync(url + "/sync/sales?since=&device=" + Uri.EscapeDataString(device) + "&key=" + Uri.EscapeDataString(key) + "&scope=mine");
					if (!httpResponseMessage.IsSuccessStatusCode)
					{
						throw new Exception($"server returned HTTP {(int)httpResponseMessage.StatusCode}");
					}
					string text = await httpResponseMessage.Content.ReadAsStringAsync();
					if (text.Length == 0)
					{
						throw new Exception("empty response from server");
					}
					pulled = new List<Sale>();
					using JsonDocument jsonDocument = JsonDocument.Parse(text);
					JsonElement rootElement = jsonDocument.RootElement;
					JsonElement value2;
					if (rootElement.TryGetProperty("error", out var value))
					{
						error = value.GetString() ?? "unknown error";
						pulled = null;
					}
					else if (rootElement.TryGetProperty("sales", out value2) && value2.ValueKind == JsonValueKind.Array)
					{
						foreach (JsonElement item in value2.EnumerateArray())
						{
							try
							{
								Sale sale = JsonSerializer.Deserialize<Sale>(item.GetRawText());
								if (!(sale == null) && !(sale.Device != device))
								{
									pulled.Add(sale);
								}
							}
							catch
							{
							}
						}
					}
				}
				catch (Exception ex)
				{
					error = ex.Message;
					pulled = null;
				}
				try
				{
					BeginInvoke((Action)(() =>
					{
						int num = 0;
						try
						{
							if (pulled != null)
							{
								foreach (Sale item2 in pulled)
								{
									if (!store.HasSale(item2))
									{
										store.Sales.Add(item2);
										num++;
									}
								}
								if (num > 0)
								{
									store.Sales.Sort((Sale a, Sale b) => a.Time.CompareTo(b.Time));
									store.SaveSales();
								}
							}
						}
						finally
						{
							syncRunning = false;
						}
						if (pulled != null)
						{
							MessageBox.Show(string.Format("{0}{1} sale(s) from home.\n{2} new sale(s) added to this POS.", Tr.T("Pulled "), pulled.Count, num), Tr.T("Pull sales history"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
						}
						else
						{
							MessageBox.Show(Tr.T("Pull failed: ") + error, Tr.T("Pull sales history"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
						}
					}));
				}
				catch
				{
					syncRunning = false;
				}
			});
		}

		private void RestoreFromHome()
		{
			if (syncRunning || uploadRunning || restoreRunning)
			{
				MessageBox.Show(Tr.T("Another sync operation is already running."), Tr.T("Restore"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			string url = NormalizeSyncUrl(store.Features.CloudSyncUrl);
			if (url.Length == 0)
			{
				MessageBox.Show(Tr.T("Set the cloud sync server URL first."), Tr.T("Restore"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			if (string.IsNullOrEmpty(store.Features.CloudSyncDevice))
			{
				store.Features.CloudSyncDevice = Environment.MachineName;
				store.SaveFeatures(store.Features);
			}
			string key = (string.IsNullOrEmpty(store.Features.CloudSyncKey) ? store.Features.ApiKey : store.Features.CloudSyncKey);
			string device = store.Features.CloudSyncDevice;
			if (MessageBox.Show("Restore this POS from the backup stored at home?\n\nStore: " + device + "\n\nThis REPLACES this computer's entire database\n(products, settings, sales, shifts) with the copy uploaded from home.\n\nRun it on the MAIN PC, with the order PCs closed.\n\nContinue?", Tr.T("Restore from home"), MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) != DialogResult.Yes)
			{
				return;
			}
			restoreRunning = true;
			Task.Run(async () =>
			{
				string error = null;
				try
				{
					using HttpClient hc = new HttpClient
					{
						Timeout = TimeSpan.FromSeconds(180.0)
					};
					HttpResponseMessage httpResponseMessage = await hc.GetAsync(url + "/sync/backup?store=" + Uri.EscapeDataString(device) + "&key=" + Uri.EscapeDataString(key));
					if (!httpResponseMessage.IsSuccessStatusCode)
					{
						throw new Exception($"server returned HTTP {(int)httpResponseMessage.StatusCode}");
					}
					string text = await httpResponseMessage.Content.ReadAsStringAsync();
					if (text.Length == 0)
					{
						throw new Exception("empty response from server");
					}
					using JsonDocument jsonDocument = JsonDocument.Parse(text);
					JsonElement rootElement = jsonDocument.RootElement;
					JsonElement value2;
					if (!rootElement.TryGetProperty("ok", out var value) || value.ValueKind != JsonValueKind.True)
					{
						throw new Exception(rootElement.TryGetProperty("error", out value2) ? value2.GetString() : "no backup available");
					}
					byte[] bytes = Convert.FromBase64String(rootElement.GetProperty("data").GetString() ?? "");
					string text2 = Path.Combine(Path.GetTempPath(), $"vectron-restore-{Guid.NewGuid():N}.zip");
					File.WriteAllBytes(text2, bytes);
					PosZip.ExtractOverwrite(text2, store.DataFolder);
					try
					{
						File.Delete(text2);
					}
					catch
					{
					}
				}
				catch (Exception ex)
				{
					error = ex.Message;
				}
				try
				{
					BeginInvoke((Action)(() =>
					{
						restoreRunning = false;
						if (error != null)
						{
							MessageBox.Show(Tr.T("Restore failed:\n") + error, Tr.T("Restore from home"), MessageBoxButtons.OK, MessageBoxIcon.Hand);
						}
						else
						{
							MessageBox.Show(Tr.T("Backup restored.\nThe application will now restart to load the restored data."), Tr.T("Restore from home"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
							Program.SafeRestart();
						}
					}));
				}
				catch
				{
					restoreRunning = false;
				}
			});
		}

