						Program.SafeRestart();
					}
					catch (Exception ex)
					{
						MessageBox.Show(Tr.T("Restore failed:\n") + ex.Message, Tr.T("Restore"), MessageBoxButtons.OK, MessageBoxIcon.Hand);
					}
				};
				Label label3 = new Label
				{
					Text = "",
					AutoSize = true,
					Location = new Point(20, 236),
					ForeColor = Skin.TextDim,
					Font = new Font("Segoe UI", 9f)
				};
				try
				{
					DateTime dateTime = (Directory.Exists(store.Features.BackupPath) ? (from t in Directory.GetFiles(store.Features.BackupPath, "vectron-backup-*.zip").Select(File.GetLastWriteTime)
						orderby t descending
						select t).FirstOrDefault() : default(DateTime));
					label3.Text = ((dateTime == default(DateTime)) ? "No previous backup found in this folder." : $"Last backup in this folder: {dateTime:dd MMM yyyy HH:mm}");
				}
				catch
				{
					label3.Text = "";
