					}
					store.SaveFeatures(store.Features);
					MessageBox.Show(Tr.T("Branches saved.\n") + Tr.T("Current branch:") + " " + ((store.Features.CurrentBranch.Length == 0) ? Tr.T("(none)") : store.Features.CurrentBranch), Tr.T("Branches"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
