		private string BranchSuffix()
		{
			string text = (store.Features.MultiBranch ? store.Features.CurrentBranch.Trim() : "");
			if (text.Length <= 0)
			{
				return "";
			}
			return "  •  " + text;
		}

		private string EffectiveGuestUrl()
		{
			string text = store.Features.GuestOrderUrl?.Trim() ?? "";
			if (text.Length <= 0)
			{
				return "http://" + TcpPrintServer.LocalIp + ":8080";
			}
			return text.TrimEnd('/');
		}

