		private void ShowPrepAnalytics()
		{
			if (!store.Features.KdsLateAlarm)
			{
				return;
			}
			Form f = ReportShell("KDS prep-time analytics", 640, 560);
			try
			{
				int target = store.Features.KdsPrepMinutes;
				List<PosStore.PrepRecord> prepTimes = store.PrepTimes;
				string text;
				if (prepTimes.Count == 0)
				{
					text = "No completed orders yet — press ✓ READY on the KDS to record prep times.";
				}
				else
				{
					double num = prepTimes.Average((PosStore.PrepRecord r) => r.Minutes);
					double num2 = (double)Enumerable.Count(prepTimes, (PosStore.PrepRecord r) => r.Minutes <= target) * 100.0 / (double)prepTimes.Count;
					text = $"Orders: {prepTimes.Count}   •   Avg prep: {num:0.0} min   •   Fastest: {prepTimes.Min((PosStore.PrepRecord r) => r.Minutes)} min   •   Slowest: {prepTimes.Max((PosStore.PrepRecord r) => r.Minutes)} min\nOn time (≤ {target} min target): {num2:0.0}%   •   Last: {prepTimes.Max((PosStore.PrepRecord r) => r.Time):dd MMM HH:mm}";
				}
				Label label = new Label
				{
					Text = text,
					Location = new Point(14, 12),
					Size = new Size(430, 64),
					ForeColor = Skin.Warning,
					Font = new Font("Segoe UI Semibold", 11f)
				};
				Label label2 = new Label
				{
					Text = Tr.T("Target prep (min):"),
					AutoSize = true,
					Location = new Point(456, 14),
					ForeColor = Skin.Text
				};
				NumericUpDown targetNum = new NumericUpDown
				{
					Minimum = 1m,
					Maximum = 180m,
					Value = Math.Max(1, Math.Min(180, store.Features.KdsPrepMinutes)),
					Location = new Point(456, 38),
					Size = new Size(70, 30),
					BackColor = panelLight,
					ForeColor = Skin.Text
				};
				Button button = ReportButton("Save", new Point(534, 36), new Size(84, 34), mint, background);
				button.Click += (object _, EventArgs _) =>
				{
					store.Features.KdsPrepMinutes = (int)targetNum.Value;
					store.SaveFeatures(store.Features);
					MessageBox.Show(string.Format("{0}{1} minutes.", Tr.T("Target prep time: "), store.Features.KdsPrepMinutes), Tr.T("KDS settings"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				};
				ListView listView = new ListView
				{
					Location = new Point(14, 88),
					Size = new Size(610, 400),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true,
					GridLines = true
				};
				listView.Columns.AddRange(new ColumnHeader[4]
				{
					new ColumnHeader
					{
						Text = Tr.T("Completed"),
						Width = 190
					},
					new ColumnHeader
					{
						Text = Tr.T("Prep minutes"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Status"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Branch"),
						Width = 140
					}
				});
				foreach (PosStore.PrepRecord item in prepTimes.AsEnumerable().Reverse().Take(100))
				{
					bool flag = item.Minutes > target;
					ListViewItem listViewItem = new ListViewItem(new string[4]
					{
						item.Time.ToString("yyyy-MM-dd HH:mm:ss"),
						item.Minutes.ToString(),
						flag ? "LATE" : "on time",
						store.Features.CurrentBranch
					});
					if (flag)
					{
						listViewItem.ForeColor = Skin.DangerText;
					}
					else
					{
						listViewItem.ForeColor = Skin.SuccessText;
					}
					listView.Items.Add(listViewItem);
				}
				Button button2 = ReportButton("Close", new Point(496, 502), new Size(128, 40), panelLight, Skin.Text);
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[6] { label, label2, targetNum, button, listView, button2 });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

		private void ShowAiInsights()
		{
			if (!store.Features.AiInsights)
			{
				return;
			}
			Form f = ReportShell("AI insights", 760, 560);
			try
			{
				DateTime from = DateTime.Today.AddDays(-6.0);
				List<Sale> list = store.Sales.Where((Sale s) => s.Time.Date >= from && !s.IsRefund).ToList();
				List<string> list2 = new List<string>();
				if (list.Count == 0)
				{
					list2.Add("No sales data yet — insights appear once orders come in.");
				}
				else
				{
					decimal num = list.Sum((Sale s) => s.Total);
					list2.Add($"PERFORMANCE — {list.Count} sales, {num:C} over the last 7 days, avg ticket {num / (decimal)list.Count:C}.");
					IGrouping<int, Sale> grouping = (from s in list
						group s by s.Time.Hour into g
						orderby g.Sum((Sale s) => s.Total) descending
						select g).First();
					list2.Add($"PEAK HOUR — {grouping.Key}:00 generated {grouping.Sum((Sale s) => s.Total):C} ({grouping.Count()} sales). Consider extra staff around this hour.");
					IEnumerable<IGrouping<string, SoldLine>> source = from i in list.SelectMany((Sale s) => s.Items ?? new List<SoldLine>())
						group i by i.Product;
					if (source.Any())
					{
						IGrouping<string, SoldLine> grouping2 = source.OrderByDescending((IGrouping<string, SoldLine> g) => g.Sum((SoldLine i) => i.Quantity)).First();
						list2.Add($"BEST SELLER — {grouping2.Key}: {grouping2.Sum((SoldLine i) => i.Quantity)} sold, {grouping2.Sum((SoldLine i) => i.UnitPrice * (decimal)i.Quantity - i.Discount):C} revenue.");
						IGrouping<string, SoldLine> grouping3 = source.OrderBy((IGrouping<string, SoldLine> g) => g.Sum((SoldLine i) => i.Quantity)).First();
						if (grouping3.Key != grouping2.Key)
						{
							list2.Add($"SLOW MOVER — {grouping3.Key}: only {grouping3.Sum((SoldLine i) => i.Quantity)} sold. Consider a promo or removing it.");
						}
					}
					decimal num2 = list.Where((Sale s) => s.PaymentType.StartsWith("Cash")).Sum((Sale s) => s.Total);
					decimal num3 = list.Where((Sale s) => s.PaymentType.StartsWith("Card")).Sum((Sale s) => s.Total);
					if (num > 0m)
					{
						list2.Add(string.Format("PAYMENT MIX — cash {0:P0}, card {1:P0}. {2}", num2 / num, num3 / num, (num2 > num3) ? "Card adoption is low — offer contactless." : "Card-first is healthy for queue speed."));
					}
					List<Sale> list3 = list.Where((Sale s) => s.Discount > 0m).ToList();
					if (list.Count > 0)
					{
						list2.Add($"DISCOUNT RATE — {list3.Count}/{list.Count} sales discounted ({list3.Sum((Sale s) => s.Discount):C} given). Watch margin if this grows.");
					}
					int num4 = Enumerable.Count(store.Sales, (Sale s) => s.Time.Date >= from && s.IsRefund);
					list2.Add($"REFUNDS — {num4} in 7 days." + (((double)num4 > (double)list.Count / 10.0) ? " High vs sales volume — review staff training." : " Within a healthy range."));
					IGrouping<int, Sale> grouping4 = (from g in list.GroupBy((Sale s) =>
						{
							int hour = s.Time.Hour;
							if (hour < 17)
							{
								if (hour < 11)
								{
									return 0;
								}
								if (hour < 14)
								{
									return 1;
								}
								return 2;
							}
							return (hour < 21) ? 3 : 4;
						})
						orderby g.Sum((Sale s) => s.Total) descending
						select g).First();
					list2.Add(string.Format("BUSIEST DAYPART — {0} ({1:C}). Staff and prep accordingly.", grouping4.Key switch
					{
						0 => (object)"morning", 
						1 => "lunch", 
						2 => "afternoon", 
						3 => "dinner", 
						_ => "night", 
					}, grouping4.Sum((Sale s) => s.Total)));
					IGrouping<string, Sale> grouping5 = (from s in list
						group s by s.Operator into g
						orderby g.Sum((Sale s) => s.Total) descending
						select g).First();
					list2.Add($"TOP SERVER — {grouping5.Key} with {grouping5.Sum((Sale s) => s.Total):C} across {grouping5.Count()} sales.");
					if (store.Operators.Any((OperatorAccount o) => o.Wage > 0m))
					{
						double num5 = store.Shifts.Where((ShiftRecord sh) => sh.ClockIn >= from).Sum((ShiftRecord sh) => ((sh.ClockOut ?? DateTime.Now) - sh.ClockIn).TotalHours);
						list2.Add($"LABOUR — {(decimal)num5:0.0} clocked hours in the period (wages not included in sales).");
					}
				}
				TextBox textBox = new TextBox
				{
					Multiline = true,
					ReadOnly = true,
					ScrollBars = ScrollBars.Vertical,
					Location = new Point(14, 44),
					Size = new Size(716, 420),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 10f),
					BorderStyle = BorderStyle.FixedSingle,
					Text = string.Join("\r\n\r\n", list2.Select((string l) => "• " + l))
				};
				Label label = new Label
				{
					Text = Tr.T("Auto analysis of your sales"),
					AutoSize = true,
					Location = new Point(14, 14),
					ForeColor = mint,
					Font = new Font("Segoe UI Semibold", 12f)
				};
				Button button = ReportButton("Close", new Point(600, 478), new Size(130, 40), panelLight, Skin.Text);
				button.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[3] { label, textBox, button });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

		private void ShowCashDrawer()
		{
			if (!store.Features.CashDrawer)
			{
				return;
			}
			if (!HasPermission("Cash drawer"))
			{
				MessageBox.Show(Tr.T("You do not have the \"Cash drawer\" permission.\nAsk your manager to assign it in Settings → Operators."), Tr.T("Cash drawer"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			Form form = new Form
			{
				Text = Tr.T("Cash drawer & cash-up"),
				Size = new Size(560, 600),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Rebuild();
				form.ShowDialog();
			}
			finally
			{
				if (form != null)
				{
					((IDisposable)form).Dispose();
				}
			}
			static Button FlatBtn(string text, int x, int y, int w, int h, Color back)
			{
				Button button = new Button();
				button.Text = text;
				button.Location = new Point(x, y);
				button.Size = new Size(w, h);
				button.BackColor = back;
				button.ForeColor = Skin.Text;
				button.FlatStyle = FlatStyle.Flat;
				button.Font = new Font("Segoe UI Semibold", 9.5f);
				button.FlatAppearance.BorderSize = 0;
				return button;
			}
			void Rebuild()
			{
				form.Controls.Clear();
				List<CashMovement> source = store.CashMovements.Where((CashMovement m) => m.Time.Date == DateTime.Today).ToList();
				decimal num = store.Sales.Where((Sale s) => s.Time.Date == DateTime.Today).Sum((Func<Sale, decimal>)CashPortion);
				decimal num2 = source.Where((CashMovement m) => m.Kind == "Float").Sum((CashMovement m) => m.Amount);
				decimal num3 = source.Where((CashMovement m) => m.Kind == "Paid in").Sum((CashMovement m) => m.Amount);
				decimal num4 = source.Where((CashMovement m) => m.Kind == "Paid out").Sum((CashMovement m) => m.Amount);
				decimal expected = num + num2 + num3 - num4;
				Label label = new Label
				{
					Location = new Point(20, 15),
					Size = new Size(520, 92),
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 10.5f),
					Text = $"Net cash sales (incl. refunds): {num:C}\nFloat: {num2:C}     Paid in: {num3:C}     Paid out: {num4:C}\nExpected in drawer:  {expected:C}"
				};
				ListView listView = new ListView
				{
					Location = new Point(20, 115),
					Size = new Size(520, 240),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true
				};
				listView.Columns.Add("Time", 70);
				listView.Columns.Add("Kind", 90);
				listView.Columns.Add("Reason", 240);
				listView.Columns.Add("Amount", 100);
				foreach (CashMovement item in source.OrderByDescending((CashMovement m) => m.Time))
				{
					listView.Items.Add(new ListViewItem(new string[4]
					{
						item.Time.ToString("HH:mm"),
						item.Kind,
						item.Reason,
						item.Amount.ToString("C")
					}));
				}
				if (listView.Items.Count > 0)
				{
					listView.AutoResizeColumns(ColumnHeaderAutoResizeStyle.HeaderSize);
				}
				Button button = FlatBtn("Open float", 20, 365, 168, 36, Skin.Info);
				Button button2 = FlatBtn("Paid in", 196, 365, 168, 36, Skin.Success);
				Button button3 = FlatBtn("Paid out", 372, 365, 168, 36, Skin.Danger);
				button.Click += (object _, EventArgs _) =>
				{
					decimal? num5 = PromptAmount("Open float", "Starting cash placed in the drawer:");
					if (num5.HasValue)
					{
						AddCashMovement(num5.Value, "Float", "Drawer opened");
						Rebuild();
					}
				};
				button2.Click += (object _, EventArgs _) =>
				{
					decimal? num5 = PromptAmount("Paid in", "Cash taken out of the drawer (e.g. petty cash deposit):");
					if (num5.HasValue)
					{
						AddCashMovement(num5.Value, "Paid in", "Cash added to drawer");
						Rebuild();
					}
				};
				button3.Click += (object _, EventArgs _) =>
				{
					decimal? num5 = PromptAmount("Paid out", "Cash taken out of the drawer (e.g. supplier payment):");
					if (num5.HasValue)
					{
						AddCashMovement(-num5.Value, "Paid out", "Cash removed from drawer");
						Rebuild();
					}
				};
				Button button4 = FlatBtn("Count cash & record cash-up", 20, 410, 520, 40, mint);
				button4.ForeColor = Skin.OnAccent;
				button4.Click += (object _, EventArgs _) =>
				{
					decimal? num5 = PromptAmount("Cash-up", $"Enter the counted cash in the drawer.\nExpected: {expected:C}");
					if (num5.HasValue)
					{
						decimal num6 = num5.Value - expected;
						store.CashMovements.Add(new CashMovement(DateTime.Now, num5.Value, "Cash-up", $"Expected {expected:C} — variance {num6:C}", currentOperator.Name));
						store.SaveCashMovements(store.CashMovements);
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Cash-up", $"Counted {num5.Value:C}, expected {expected:C}, variance {num6:C}");
						}
						MessageBox.Show(string.Format("{0}{1:C}\n{2} {3:C}\n{4} {5:C}", Tr.T("Counted: "), num5.Value, Tr.T("Expected:"), expected, (num6 >= 0m) ? Tr.T("Over:") : Tr.T("Short:"), Math.Abs(num6)), "Cash-up result", MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
						Rebuild();
					}
				};
				Button button5 = FlatBtn("Test drawer open", 20, 458, 168, 36, panelLight);
				button5.Click += (object _, EventArgs _) =>
				{
					TryOpenDrawerKick();
				};
				Button button6 = FlatBtn("No sale (open & log)", 196, 458, 168, 36, Skin.WarningDeep);
				button6.Click += (object _, EventArgs _) =>
				{
					string text = PromptText("No sale", "Reason (optional, e.g. 'cashier change'):");
					if (text != null)
					{
						TryOpenDrawerKick();
						AddCashMovement(0m, "No sale", string.IsNullOrWhiteSpace(text) ? "Drawer opened without a sale" : text);
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "No sale", string.IsNullOrWhiteSpace(text) ? "drawer opened" : text);
						}
						Rebuild();
					}
				};
				Button button7 = FlatBtn("Close", 372, 458, 168, 36, panelLight);
				button7.Click += (object _, EventArgs _) =>
				{
					form.DialogResult = DialogResult.OK;
				};
				form.Controls.AddRange(new Control[9] { label, listView, button, button2, button3, button4, button5, button6, button7 });
			}
		}

		private static decimal CashPortion(Sale s)
		{
			if (s.CashAmount >= 0m)
			{
				return s.CashAmount;
			}
			if (!((s.PaymentType ?? "Cash") == "Cash"))
			{
				return 0m;
			}
			return s.Total;
		}

		private void AddCashMovement(decimal amount, string kind, string reason)
		{
			store.CashMovements.Add(new CashMovement(DateTime.Now, amount, kind, reason, currentOperator.Name));
			store.SaveCashMovements(store.CashMovements);
			if (store.Features.AuditLog)
			{
				store.LogAudit(currentOperator.Name, kind, $"{amount:C} — {reason}");
			}
		}

		private decimal? PromptAmount(string title, string caption)
		{
			Form f = new Form
			{
				Text = title,
				Size = new Size(380, 210),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Label label = new Label
				{
					Text = caption,
					Location = new Point(20, 15),
					Size = new Size(335, 48)
				};
				NumericUpDown numericUpDown = new NumericUpDown
				{
					Minimum = 0m,
					Maximum = 1000000m,
					DecimalPlaces = 2,
					Location = new Point(20, 70),
					Size = new Size(200, 30),
					BackColor = panelLight,
					ForeColor = Skin.Text
				};
				Button button = new Button
				{
					Text = Tr.T("OK"),
					Location = new Point(20, 115),
					Size = new Size(110, 36),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				Button button2 = new Button
				{
					Text = Tr.T("Cancel"),
					Location = new Point(140, 115),
					Size = new Size(110, 36),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				button2.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.Cancel;
				};
				f.Controls.AddRange(new Control[4] { label, numericUpDown, button, button2 });
				f.AcceptButton = button;
				f.CancelButton = button2;
				return (f.ShowDialog() == DialogResult.OK) ? new decimal?(numericUpDown.Value) : ((decimal?)null);
