				};
				button.FlatAppearance.BorderSize = 0;
				lv = new ListView
				{
					Location = new Point(14, 48),
					Size = new Size(738, 380),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true,
