					GridLines = true
				};
				lv.Columns.AddRange(new ColumnHeader[7]
				{
					new ColumnHeader
					{
						Text = Tr.T("Time"),
						Width = 130
					},
					new ColumnHeader
					{
						Text = Tr.T("Pay #"),
						Width = 60
					},
					new ColumnHeader
					{
						Text = Tr.T("Bill #"),
						Width = 60
					},
					new ColumnHeader
					{
						Text = Tr.T("Table"),
						Width = 120
					},
					new ColumnHeader
					{
						Text = Tr.T("Customer"),
						Width = 130
					},
					new ColumnHeader
					{
						Text = Tr.T("Type"),
						Width = 170
					},
					new ColumnHeader
					{
						Text = Tr.T("Total"),
						Width = 90
					}
				});
				button.Click += (object _, EventArgs _) =>
				{
					RefreshList();
				};
				search.KeyDown += (object _, KeyEventArgs e) =>
				{
					if (e.KeyCode == Keys.Return)
					{
						RefreshList();
						e.SuppressKeyPress = true;
					}
				};
				date.ValueChanged += (object _, EventArgs _) =>
				{
					RefreshList();
				};
				RefreshList();
				Button button2 = new Button
				{
					Text = Tr.T("Reprint"),
					Location = new Point(14, 442),
					Size = new Size(150, 40),
					BackColor = Skin.Teal,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				Button button3 = new Button
				{
					Text = Tr.T("Reopen check"),
					Location = new Point(176, 442),
					Size = new Size(170, 40),
					BackColor = Skin.InfoAlt,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				Button button4 = new Button
				{
					Text = Tr.T("Close"),
					Location = new Point(602, 442),
					Size = new Size(150, 40),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				button2.FlatAppearance.BorderSize = 0;
				button3.FlatAppearance.BorderSize = 0;
				button4.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count == 0)
					{
						MessageBox.Show(Tr.T("Select a receipt first."), Tr.T("Reprint"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else if (lv.SelectedItems[0].Tag is Sale sale)
					{
						PrintPaymentReceipt(sale, sale.Items ?? new List<SoldLine>(), 0m, "", sale.Table ?? "");
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Receipt reprint", $"payment #{sale.PaymentNumber} {sale.Total:C}");
						}
					}
				};
				button3.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count == 0)
					{
						MessageBox.Show(Tr.T("Select a receipt first."), Tr.T("Reopen"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else if (lv.SelectedItems[0].Tag is Sale sale)
					{
						List<SoldLine> list = sale.Items ?? new List<SoldLine>();
						if (list.Count == 0)
						{
							MessageBox.Show(Tr.T("This sale has no line items to reopen."), Tr.T("Reopen"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
						}
						else if (basket.Count <= 0 || MessageBox.Show(string.Format("{0} ({1} {2}", Tr.T("Replace the current basket"), basket.Count, Tr.T("line(s)) with this check?")), Tr.T("Reopen"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
						{
							if (hasOpenOrder)
							{
								MessageBox.Show(Tr.T("Finish or park the open order on this table before reopening a closed check."), Tr.T("Reopen"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							}
							else
							{
								basket.Clear();
								foreach (SoldLine item in list)
								{
									Product product = products.FirstOrDefault((Product p) => p.Name == item.Product);
									if (!(product == null))
									{
										int num = basket.FindIndex(((Product Product, int Count, int Course, string Note, int Seat, string Modifiers) b) => b.Product == product && b.Note == item.Note && b.Modifiers == item.Modifiers);
										if (num >= 0)
										{
											basket[num] = (product, basket[num].Count + item.Quantity, basket[num].Course, basket[num].Note, item.Seat, JoinMods(basket[num].Modifiers, item.Modifiers));
										}
										else
										{
											basket.Add((product, item.Quantity, item.Course, item.Note, item.Seat, item.Modifiers));
										}
									}
								}
								hasOpenOrder = false;
								RenderBasket();
								UpdateOrderButtons();
								orderLabel.Text = OrderContextText();
								if (store.Features.AuditLog)
								{
									store.LogAudit(currentOperator.Name, "Check reopened", $"payment #{sale.PaymentNumber} into basket");
								}
								f.DialogResult = DialogResult.OK;
							}
						}
					}
				};
				button4.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.Cancel;
				};
				f.Controls.AddRange(new Control[7] { date, search, button, lv, button2, button3, button4 });
				f.AcceptButton = button;
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
			void RefreshList()
			{
				lv.Items.Clear();
				string q = search.Text.Trim();
				foreach (Sale item2 in from s in store.Sales
					where s.Time.Date == date.Value.Date
					where q.Length == 0 || s.PaymentNumber.ToString().AsSpan().Contains(q.AsSpan(), StringComparison.OrdinalIgnoreCase) || s.BillNumber.ToString().AsSpan().Contains(q.AsSpan(), StringComparison.OrdinalIgnoreCase) || (s.Table ?? "").AsSpan().Contains(q.AsSpan(), StringComparison.OrdinalIgnoreCase) || (s.CustomerName ?? "").AsSpan().Contains(q.AsSpan(), StringComparison.OrdinalIgnoreCase) || (s.PaymentType ?? "").AsSpan().Contains(q.AsSpan(), StringComparison.OrdinalIgnoreCase)
					orderby s.Time descending
					select s)
				{
					lv.Items.Add(new ListViewItem(new string[7]
					{
						item2.Time.ToString("HH:mm:ss"),
						item2.PaymentNumber.ToString(),
						item2.BillNumber.ToString(),
						item2.Table ?? "",
						item2.CustomerName ?? "",
						item2.PaymentType ?? "",
						item2.Total.ToString("C")
					})
					{
						Tag = item2
					});
				}
				if (lv.Items.Count == 0 && preselect.HasValue)
				{
					DateTime p = preselect.GetValueOrDefault();
					if (p.Date == date.Value.Date && store.Sales.LastOrDefault((Sale s) => s.Time.Date == p.Date) != null && lv.Items.Count == 0)
					{
						foreach (Sale item3 in (from s in store.Sales
							where s.Time.Date == p.Date
							orderby s.Time descending
							select s).Take(1))
						{
							lv.Items.Add(new ListViewItem(new string[7]
							{
								item3.Time.ToString("HH:mm:ss"),
								item3.PaymentNumber.ToString(),
								item3.BillNumber.ToString(),
								item3.Table ?? "",
								item3.CustomerName ?? "",
								item3.PaymentType ?? "",
								item3.Total.ToString("C")
							})
							{
								Tag = item3
							});
						}
					}
				}
			}
		}

