					{
						Text = Tr.T("Paid"),
						Width = 90
					},
					new ColumnHeader
					{
						Text = Tr.T("Due"),
						Width = 90
					},
					new ColumnHeader
					{
						Text = Tr.T("Status"),
						Width = 90
					}
				});
				RefreshList();
				Button button = new Button
				{
					Text = Tr.T("Collect balance"),
					Location = new Point(14, 384),
					Size = new Size(170, 40),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				Button button2 = new Button
				{
					Text = Tr.T("Cancel order"),
					Location = new Point(196, 384),
					Size = new Size(150, 40),
					BackColor = Skin.Danger,
					ForeColor = Skin.OnFill,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				Button button3 = new Button
				{
					Text = Tr.T("Close"),
					Location = new Point(596, 384),
					Size = new Size(134, 40),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				button.FlatAppearance.BorderSize = 0;
				button2.FlatAppearance.BorderSize = 0;
				button3.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count != 0)
					{
						object tag = lv.SelectedItems[0].Tag;
						SpecialOrder o = tag as SpecialOrder;
						if ((object)o != null)
						{
							if (o.Status != "Open")
							{
								MessageBox.Show(Tr.T("This order is ") + o.Status + ".", Tr.T("Collect"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							}
							else
							{
								decimal num = o.Total - o.Paid;
								if (!(num <= 0m))
								{
									Form pf = new Form
									{
										Text = Tr.T("Collect balance"),
										Size = new Size(400, 250),
										StartPosition = FormStartPosition.CenterParent,
										BackColor = background,
										ForeColor = Skin.Text,
										Font = new Font("Segoe UI", 10f),
										FormBorderStyle = FormBorderStyle.FixedDialog,
										MaximizeBox = false,
										MinimizeBox = false
									};
									try
									{
										Label label = new Label
										{
											Text = $"Order #{o.Id} — balance due: {num:C}",
											AutoSize = true,
											Location = new Point(20, 16)
										};
										NumericUpDown numericUpDown = new NumericUpDown
										{
											Minimum = 0.01m,
											Maximum = 1000000m,
											DecimalPlaces = 2,
											Value = Math.Min(1000000m, num),
											Location = new Point(20, 50),
											Size = new Size(170, 30),
											BackColor = panelLight,
											ForeColor = Skin.Text
										};
										Label label2 = new Label
										{
											Text = Tr.T("Paid by:"),
											AutoSize = true,
											Location = new Point(20, 94)
										};
										ComboBox comboBox = new ComboBox
										{
											FlatStyle = FlatStyle.Flat,
											Location = new Point(20, 118),
											Size = new Size(170, 30),
											DropDownStyle = ComboBoxStyle.DropDownList,
											BackColor = panelLight,
											ForeColor = Skin.Text
										};
										comboBox.Items.AddRange(new object[4] { "Cash", "Card", "Transfer", "Mobile" });
										comboBox.SelectedIndex = 0;
										Button button4 = new Button
										{
											Text = Tr.T("Collect"),
											Location = new Point(20, 162),
											Size = new Size(130, 38),
											BackColor = mint,
											ForeColor = Skin.OnAccent,
											FlatStyle = FlatStyle.Flat
										};
										Button button5 = new Button
										{
											Text = Tr.T("Cancel"),
											Location = new Point(162, 162),
											Size = new Size(110, 38),
											BackColor = panelLight,
											ForeColor = Skin.Text,
											FlatStyle = FlatStyle.Flat
										};
										button4.FlatAppearance.BorderSize = 0;
										button5.FlatAppearance.BorderSize = 0;
										button4.Click += (object obj, EventArgs e) =>
										{
											pf.DialogResult = DialogResult.OK;
										};
										button5.Click += (object obj, EventArgs e) =>
										{
											pf.DialogResult = DialogResult.Cancel;
										};
										pf.Controls.AddRange(new Control[6] { label, numericUpDown, label2, comboBox, button4, button5 });
										pf.AcceptButton = button4;
										if (pf.ShowDialog() == DialogResult.OK)
										{
											int num2 = store.SpecialOrders.FindIndex((SpecialOrder x) => x.Id == o.Id);
											if (num2 >= 0)
											{
												decimal value = numericUpDown.Value;
												List<SpecialOrder> specialOrders = store.SpecialOrders;
												SpecialOrder specialOrder = store.SpecialOrders[num2]._003CClone_003E_0024();
												specialOrder.Paid = store.SpecialOrders[num2].Paid + value;
												specialOrder.Status = ((store.SpecialOrders[num2].Total - store.SpecialOrders[num2].Paid - value <= 0.005m) ? "Delivered" : "Open");
												specialOrders[num2] = specialOrder;
												Save();
												store.AddSale(new Sale(DateTime.Now, value, o.Table, currentOperator.Name, new List<SoldLine>(), store.NextPaymentNumber(), o.PaymentNum, 0m, $"{comboBox.Text} (special #{o.Id})", o.Customer, "Special", 0m, IsRefund: false, 0, "", (comboBox.Text == "Cash") ? value : 0m));
												if (store.Features.AuditLog)
												{
													store.LogAudit(currentOperator.Name, "Special order balance", $"#{o.Id} +{value:C} via {comboBox.Text} → {store.SpecialOrders[num2].Status}");
												}
												RefreshList();
											}
										}
										return;
									}
									finally
									{
										if (pf != null)
										{
											((IDisposable)pf).Dispose();
										}
									}
								}
							}
							return;
						}
					}
					MessageBox.Show(Tr.T("Select a special order first."), Tr.T("Collect"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				};
				button2.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count != 0)
					{
						object tag = lv.SelectedItems[0].Tag;
						SpecialOrder o = tag as SpecialOrder;
						if ((object)o != null)
						{
							if (o.Status != "Open")
							{
								MessageBox.Show(Tr.T("This order is") + " " + o.Status + ".", Tr.T("Cancel"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							}
							else if (MessageBox.Show(string.Format("{0}{1}?\n{2} {3:C} {4}", Tr.T("Cancel special order #"), o.Id, Tr.T("Deposit of"), o.Paid, Tr.T("is kept (refund separately if needed).")), Tr.T("Cancel order"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
							{
								int num = store.SpecialOrders.FindIndex((SpecialOrder x) => x.Id == o.Id);
								if (num >= 0)
								{
									List<SpecialOrder> specialOrders = store.SpecialOrders;
									SpecialOrder specialOrder = store.SpecialOrders[num]._003CClone_003E_0024();
									specialOrder.Status = "Cancelled";
									specialOrders[num] = specialOrder;
								}
								Save();
								if (store.Features.AuditLog)
								{
									store.LogAudit(currentOperator.Name, "Special order cancelled", $"#{o.Id}");
								}
								RefreshList();
							}
							return;
						}
					}
					MessageBox.Show(Tr.T("Select a special order first."), Tr.T("Cancel"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				};
				button3.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[4] { lv, button, button2, button3 });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
			void RefreshList()
			{
				lv.Items.Clear();
				foreach (SpecialOrder item in store.SpecialOrders.OrderByDescending((SpecialOrder o) => o.Time))
				{
					ListViewItem listViewItem = new ListViewItem(new string[8]
					{
						item.Id.ToString(),
						item.Time.ToString("dd/MM HH:mm"),
						item.Customer,
						item.Table,
						item.Total.ToString("C"),
						item.Paid.ToString("C"),
						(item.Total - item.Paid).ToString("C"),
						item.Status
					})
					{
						Tag = item
					};
					if (item.Status == "Delivered")
					{
						listViewItem.ForeColor = Skin.SuccessText;
					}
					else if (item.Status == "Cancelled")
					{
						listViewItem.ForeColor = Skin.TextFaded;
					}
					lv.Items.Add(listViewItem);
				}
			}
			void Save()
			{
				store.SaveSpecialOrders(store.SpecialOrders);
			}
		}

