			};
			ListView lv;
			try
			{
				Label label = new Label
				{
					Text = (store.FeeSettings.TerminalOffline ? "Terminal mode: OFFLINE — card payments are being queued." : "Terminal mode: ONLINE."),
					AutoSize = true,
					Location = new Point(14, 14),
					ForeColor = (store.FeeSettings.TerminalOffline ? Skin.Warning : Skin.SuccessText)
				};
				lv = new ListView
				{
					Location = new Point(14, 44),
					Size = new Size(636, 300),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					View = View.Details,
					FullRowSelect = true,
					MultiSelect = false,
					GridLines = true
				};
				lv.Columns.AddRange(new ColumnHeader[6]
				{
					new ColumnHeader
					{
						Text = Tr.T("Time"),
						Width = 130
					},
					new ColumnHeader
					{
						Text = Tr.T("Pay #"),
						Width = 60
					},
					new ColumnHeader
					{
						Text = Tr.T("Table"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Operator"),
						Width = 110
					},
					new ColumnHeader
					{
						Text = Tr.T("Amount"),
						Width = 100
					},
					new ColumnHeader
					{
						Text = Tr.T("Status"),
						Width = 90
					}
				});
				RefreshList();
				Button button = new Button
				{
					Text = Tr.T("Terminal back online — settle all"),
					Location = new Point(14, 356),
					Size = new Size(250, 40),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				Button button2 = new Button
				{
					Text = Tr.T("Close"),
					Location = new Point(516, 356),
					Size = new Size(134, 40),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", 10f)
				};
				button.FlatAppearance.BorderSize = 0;
				button2.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					List<OfflinePayment> list = store.OfflinePayments.Where((OfflinePayment offlinePayment2) => offlinePayment2.Status == "Pending").ToList();
					if (list.Count == 0)
					{
						MessageBox.Show(Tr.T("No pending offline payments."), Tr.T("Offline queue"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else
					{
						foreach (OfflinePayment p in list)
						{
							int num = store.OfflinePayments.FindIndex((OfflinePayment x) => x.PaymentNumber == p.PaymentNumber && x.Time == p.Time);
							if (num >= 0)
							{
								List<OfflinePayment> offlinePayments = store.OfflinePayments;
								OfflinePayment offlinePayment = store.OfflinePayments[num]._003CClone_003E_0024();
								offlinePayment.Status = "Cleared";
								offlinePayments[num] = offlinePayment;
							}
						}
						store.SaveOfflinePayments(store.OfflinePayments);
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Offline payments settled", $"{list.Count} payment(s), {list.Sum((OfflinePayment offlinePayment2) => offlinePayment2.Amount):C}");
						}
						MessageBox.Show(string.Format("{0} {1} ({2:C}).\n{3:C} {4}", list.Count, Tr.T("offline payment(s) settled"), list.Sum((OfflinePayment offlinePayment2) => offlinePayment2.Amount), list.Sum((OfflinePayment offlinePayment2) => offlinePayment2.Amount), Tr.T("should be on the card terminal batch.")), Tr.T("Offline queue"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
						RefreshList();
					}
				};
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[4] { label, lv, button, button2 });
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
			void RefreshList()
			{
				lv.Items.Clear();
				foreach (OfflinePayment item in store.OfflinePayments.OrderByDescending((OfflinePayment p) => p.Time))
				{
					ListViewItem listViewItem = new ListViewItem(new string[6]
					{
						item.Time.ToString("dd/MM HH:mm"),
						item.PaymentNumber.ToString(),
						item.Table,
						item.Operator,
						item.Amount.ToString("C"),
						item.Status
					})
					{
						Tag = item
					};
					if (item.Status == "Pending")
					{
						listViewItem.ForeColor = Skin.Warning;
					}
					lv.Items.Add(listViewItem);
				}
			}
		}

