					else
					{
						int num2 = ((store.VtInvoices.Count <= 0) ? 1 : (store.VtInvoices.Max((VtInvoice v) => v.Id) + 1));
						store.VtInvoices.Add(new VtInvoice(num2, DateTime.Now, nameBox.Text.Trim(), phoneBox.Text.Trim(), amt.Value, noteBox.Text.Trim(), "Pending"));
