				{
					array[num].FlatAppearance.BorderSize = 0;
				}
				button2.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count == 0 || !(lv.SelectedItems[0].Tag is VtInvoice vtInvoice))
					{
						MessageBox.Show(Tr.T("Select an invoice first."), Tr.T("Virtual terminal"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
						return;
					}
					string fileName = LinkFor(vtInvoice.Id);
					try
					{
						Clipboard.SetText(fileName);
					}
					catch
					{
					}
					try
					{
						Process.Start(new ProcessStartInfo(fileName)
						{
							UseShellExecute = true
						});
					}
					catch
					{
					}
				};
				button3.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count == 0 || !(lv.SelectedItems[0].Tag is VtInvoice vtInvoice))
					{
						MessageBox.Show(Tr.T("Select an invoice first."), Tr.T("Virtual terminal"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else if (vtInvoice.Status == "Paid")
					{
						MessageBox.Show(Tr.T("Already paid."), Tr.T("Virtual terminal"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else
					{
						MarkPaid(vtInvoice);
					}
				};
				button4.Click += (object _, EventArgs _) =>
				{
					if (lv.SelectedItems.Count != 0)
					{
						object tag = lv.SelectedItems[0].Tag;
						VtInvoice inv = tag as VtInvoice;
						if ((object)inv != null)
						{
							if (inv.Status == "Paid")
							{
								MessageBox.Show(Tr.T("Paid invoices cannot be deleted."), Tr.T("Virtual terminal"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							}
							else if (MessageBox.Show(string.Format("{0}{1} ({2:C})?", Tr.T("Delete pending invoice #"), inv.Id, inv.Amount), Tr.T("Virtual terminal"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
							{
								store.VtInvoices.RemoveAll((VtInvoice v) => v.Id == inv.Id);
								store.SaveVtInvoices(store.VtInvoices);
								RefreshList();
							}
							return;
						}
					}
					MessageBox.Show(Tr.T("Select an invoice first."), Tr.T("Virtual terminal"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				};
				button5.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				f.Controls.AddRange(new Control[13]
				{
					label, amt, label2, nameBox, label3, phoneBox, noteBox, button, lv, button2,
					button3, button4, button5
				});
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
			static string LinkFor(int id)
			{
				return $"http://{TcpPrintServer.LocalIp}:8080/vt/{id}";
			}
			void MarkPaid(VtInvoice inv)
			{
				if (!(inv.Status == "Paid"))
				{
					int num2 = store.VtInvoices.FindIndex((VtInvoice v) => v.Id == inv.Id);
					if (num2 >= 0)
					{
						List<VtInvoice> vtInvoices = store.VtInvoices;
						VtInvoice vtInvoice = store.VtInvoices[num2]._003CClone_003E_0024();
						vtInvoice.Status = "Paid";
						vtInvoices[num2] = vtInvoice;
					}
					store.SaveVtInvoices(store.VtInvoices);
					store.AddSale(new Sale(DateTime.Now, inv.Amount, "VT", currentOperator.Name, new List<SoldLine>(), store.NextPaymentNumber(), 0, 0m, $"VT #{inv.Id} {inv.Name}", inv.Name, "Phone order"));
					if (store.Features.AuditLog)
					{
						store.LogAudit(currentOperator.Name, "VT paid", $"#{inv.Id} {inv.Amount:C} {inv.Name}");
					}
					RefreshList();
				}
			}
			void RefreshList()
			{
				lv.Items.Clear();
				foreach (VtInvoice item in store.VtInvoices.OrderByDescending((VtInvoice v) => v.Time))
				{
					ListViewItem listViewItem = new ListViewItem(new string[7]
					{
						item.Id.ToString(),
						item.Time.ToString("dd/MM HH:mm"),
						item.Name,
						item.Phone,
						item.Amount.ToString("C"),
						item.Status,
						item.Note
					})
					{
						Tag = item
					};
					if (item.Status == "Paid")
					{
						listViewItem.ForeColor = Skin.SuccessText;
					}
					lv.Items.Add(listViewItem);
				}
			}
		}

		private void TryOpenDrawerKick()
		{
			byte[] array = new byte[7] { 27, 64, 27, 112, 0, 25, 250 };
			foreach (PrinterDestination printerDestination in store.PrinterDestinations)
			{
				if (string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
				{
					continue;
				}
				string text = ResolvePrinterName(printerDestination);
				if (string.IsNullOrWhiteSpace(text))
				{
					continue;
				}
				try
				{
					if (!RawPrinter.OpenPrinterLocal(text, out var printer, (IntPtr)0))
					{
						continue;
					}
					try
					{
						RawPrinter.DocumentInfo documentInfo = new RawPrinter.DocumentInfo
						{
							DocumentName = "Drawer open",
							OutputFile = null,
							DataType = null
						};
						RawPrinter.StartDocPrinter(printer, 1, documentInfo);
						RawPrinter.StartPagePrinter(printer);
						RawPrinter.WritePrinter(printer, array, array.Length, out var _);
						RawPrinter.EndPagePrinter(printer);
						RawPrinter.EndDocPrinter(printer);
						break;
					}
					finally
					{
						RawPrinter.ClosePrinter(printer);
					}
				}
				catch
				{
				}
			}
		}

		private string NewGiftCardCode()
		{
			string code;
			do
			{
				code = "GC-" + SafeRandom.Next(100000, 999999);
			}
			while (store.GiftCards.Any((GiftCard c) => c.Code == code));
			return code;
		}

		private string? PromptText(string title, string caption, string prefill = "")
		{
			Form f = new Form
			{
				Text = title,
				Size = new Size(380, 200),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = background,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				Label label = new Label
				{
					Text = caption,
					Location = new Point(20, 15),
					Size = new Size(335, 40)
				};
				TextBox textBox = new TextBox
				{
					Location = new Point(20, 60),
					Size = new Size(335, 30),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					Text = prefill
				};
				Button button = new Button
				{
					Text = Tr.T("OK"),
					Location = new Point(20, 105),
					Size = new Size(110, 36),
					BackColor = mint,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				Button button2 = new Button
				{
					Text = Tr.T("Cancel"),
					Location = new Point(140, 105),
					Size = new Size(110, 36),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				button2.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.OK;
				};
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.Cancel;
				};
				f.Controls.AddRange(new Control[4] { label, textBox, button, button2 });
				f.AcceptButton = button;
				f.CancelButton = button2;
				return (f.ShowDialog() == DialogResult.OK) ? textBox.Text.Trim() : null;
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
		}

