						Location = new Point(20, 216),
						Size = new Size(120, 38),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat
					};
					Button button5 = new Button
					{
						Text = Tr.T("Cancel"),
						Location = new Point(150, 216),
						Size = new Size(120, 38),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						FlatStyle = FlatStyle.Flat
					};
