					GiftCard giftCard = store.GiftCards.FirstOrDefault((GiftCard c) => string.Equals(c.Code, code, StringComparison.OrdinalIgnoreCase));
					if (giftCard == null)
					{
						MessageBox.Show(Tr.T("Gift card") + " \"" + code + "\" " + Tr.T("was not found."), Tr.T("Gift cards"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
					else
					{
						MessageBox.Show(string.Format("{0} {1}\n{2} {3:C}\n{4} {5:C}\n{6} {7:dd/MM/yyyy}", Tr.T("Code:"), giftCard.Code, Tr.T("Balance:"), giftCard.Balance, Tr.T("Originally sold for:"), giftCard.Sold, Tr.T("Created:"), giftCard.Created), Tr.T("Gift card balance"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
				}
			};
			button3.Click += (object _, EventArgs _) =>
			{
				string code = PromptText("Add funds", "Enter the gift card code:");
				if (!string.IsNullOrWhiteSpace(code))
				{
					int num = store.GiftCards.FindIndex((GiftCard c) => string.Equals(c.Code, code, StringComparison.OrdinalIgnoreCase));
					if (num < 0)
					{
						MessageBox.Show(Tr.T("Gift card") + " \"" + code + "\" " + Tr.T("was not found."), Tr.T("Gift cards"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
					else
					{
						decimal? num2 = PromptAmount("Add funds", $"Current balance: {store.GiftCards[num].Balance:C}\nAmount to add:");
						if (num2.HasValue)
						{
							List<GiftCard> giftCards = store.GiftCards;
							GiftCard giftCard = store.GiftCards[num]._003CClone_003E_0024();
							giftCard.Balance = store.GiftCards[num].Balance + num2.Value;
							giftCards[num] = giftCard;
							store.SaveGiftCards(store.GiftCards);
							if (store.Features.AuditLog)
							{
								store.LogAudit(currentOperator.Name, "Gift card top-up", $"{store.GiftCards[num].Code} +{num2.Value:C} → {store.GiftCards[num].Balance:C}");
							}
							Rebuild();
						}
					}
				}
			};
