			static Button B(string text, Color back)
			{
				Button button4 = new Button();
				button4.Text = text;
				button4.Size = new Size(170, 36);
				button4.BackColor = back;
				button4.ForeColor = Skin.Text;
				button4.FlatStyle = FlatStyle.Flat;
				button4.Margin = new Padding(0, 0, 8, 0);
				button4.Font = new Font("Segoe UI Semibold", 9.5f);
				button4.FlatAppearance.BorderSize = 0;
				return button4;
			}
			void Rebuild()
			{
				lv.Items.Clear();
				foreach (GiftCard item in store.GiftCards.OrderByDescending((GiftCard c) => c.Created))
				{
					ListViewItem listViewItem = new ListViewItem(new string[4]
					{
						item.Code,
						item.Balance.ToString("C"),
						item.Sold.ToString("C"),
						item.Created.ToString("dd/MM/yyyy HH:mm")
					});
					if (item.Balance <= 0m)
					{
						listViewItem.ForeColor = Skin.TextFaded;
					}
					else if (item.Balance <= 5m)
					{
						listViewItem.ForeColor = Skin.Warning;
					}
					lv.Items.Add(listViewItem);
				}
			}
		}

