				void FillTables()
				{
					tableC.Items.Clear();
					Room room = store.Rooms.FirstOrDefault((Room r) => r.Name == roomC.Text);
					if (!(room == null))
					{
						for (int num = 0; num < room.TableCount; num++)
						{
							tableC.Items.Add(TableName(room.Name, num));
						}
						if (tableC.Items.Count > 0)
						{
							tableC.SelectedIndex = 0;
						}
					}
				}
