			void Rebuild()
			{
				lv.Items.Clear();
				foreach (Reservation item in from r in store.Reservations
					where r.When.Date >= DateTime.Today && r.Status != "Cancelled"
					orderby r.When
					select r)
				{
					ListViewItem listViewItem = new ListViewItem(new string[7]
					{
						item.Name,
						item.Phone,
						item.PartySize.ToString(),
						item.When.ToString("dd/MM HH:mm"),
						item.Room,
						item.Table,
						item.Status
					});
					if (item.Status == "Seated")
					{
						listViewItem.ForeColor = mint;
					}
					else if (item.Status == "No-show")
					{
						listViewItem.ForeColor = Skin.DangerText;
					}
					else if (item.Status == "Done")
					{
						listViewItem.ForeColor = Skin.TextFaded;
					}
					lv.Items.Add(listViewItem);
				}
			}
			void SetStatus(string status)
			{
				if (lv.SelectedItems.Count == 0)
				{
					MessageBox.Show(Tr.T("Select a reservation first."), Tr.T("Reservations"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				}
				else
				{
					string name = lv.SelectedItems[0].Text;
					string whenTxt = lv.SelectedItems[0].SubItems[3].Text;
					int num = store.Reservations.FindIndex((Reservation r) => r.Name == name && r.When.ToString("dd/MM HH:mm") == whenTxt);
					if (num >= 0)
					{
						List<Reservation> reservations = store.Reservations;
						Reservation reservation = store.Reservations[num]._003CClone_003E_0024();
						reservation.Status = status;
						reservations[num] = reservation;
						store.SaveReservations(store.Reservations);
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Reservation", store.Reservations[num].Name + " → " + status);
						}
						Rebuild();
					}
				}
			}
		}

		private static DateTime WeekStart(DateTime any)
		{
			int num = (int)(any.DayOfWeek + 6) % 7;
			return any.Date.AddDays(-num);
		}

