			tipsGrid.Columns.Add("Amount", 120);
			button5.Click += (object _, EventArgs _) =>
			{
				DateTime day = dateP2.Value.Date;
				List<Sale> source = store.Sales.Where((Sale s) => s.Time.Date == day && s.Tip > 0m && !s.IsRefund).ToList();
				decimal num = source.Sum((Sale s) => s.Tip);
				if (num <= 0m)
				{
					MessageBox.Show(string.Format("{0}{1:dd/MM/yyyy}.", Tr.T("No tips recorded on "), day), Tr.T("Tip pool"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				}
				else
				{
					Dictionary<string, decimal> bySales = (from s in source
						group s by s.Operator).ToDictionary((IGrouping<string, Sale> g) => g.Key, (IGrouping<string, Sale> g) => g.Sum((Sale s) => s.Tip));
					Dictionary<string, decimal> byHours = new Dictionary<string, decimal>();
					foreach (ScheduleEntry item in store.Schedule.Where((ScheduleEntry e) => e.Date == day))
					{
						TimeSpan timeSpan = item.End - item.Start;
						if (timeSpan < TimeSpan.Zero)
						{
							timeSpan += TimeSpan.FromDays(1.0);
						}
						byHours[item.Operator] = byHours.GetValueOrDefault(item.Operator, 0m) + (decimal)timeSpan.TotalHours;
					}
					List<string> list = (from o in store.Operators
						where bySales.ContainsKey(o.Name) || byHours.ContainsKey(o.Name) || store.Schedule.Any((ScheduleEntry s) => s.Date == day && s.Operator == o.Name)
						select o.Name).Distinct().ToList();
					if (list.Count == 0)
					{
						MessageBox.Show(Tr.T("No participants for that day."), Tr.T("Tip pool"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					}
					else
					{
						tipsGrid.Items.Clear();
						foreach (string item2 in list)
						{
							int selectedIndex = ruleC.SelectedIndex;
							decimal num2 = ((selectedIndex == 1 && byHours.Sum((KeyValuePair<string, decimal> kv) => kv.Value) > 0m) ? (byHours.GetValueOrDefault(item2, 0m) / byHours.Sum((KeyValuePair<string, decimal> kv) => kv.Value)) : ((selectedIndex != 2 || !(bySales.Values.Sum() > 0m)) ? (1m / (decimal)list.Count) : (bySales.GetValueOrDefault(item2, 0m) / bySales.Values.Sum())));
							decimal num3 = Math.Round(num * num2, 2);
							ListViewItem value = new ListViewItem(new string[3]
							{
								item2,
								$"{num2:P0}",
								num3.ToString("C")
							});
							tipsGrid.Items.Add(value);
						}
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Tip pool", $"{day:dd/MM} {num:C} ({ruleC.Text})");
						}
					}
				}
			};
