			static Button HBtn(string text2, int x, Color back)
			{
				Button button6 = new Button();
				button6.Text = text2;
				button6.Location = new Point(x, 6);
				button6.Size = new Size(90, 32);
				button6.BackColor = back;
				button6.ForeColor = Skin.Text;
				button6.FlatStyle = FlatStyle.Flat;
				button6.Font = new Font("Segoe UI Semibold", 9f);
				button6.FlatAppearance.BorderSize = 0;
				return button6;
			}
			void RebuildSchedule()
			{
				weekLabel.Text = $"{weekStart:dd/MM} — {weekStart.AddDays(6.0):dd/MM/yyyy}";
				grid.Items.Clear();
				List<ScheduleEntry> source = store.Schedule.Where((ScheduleEntry e) => e.Date >= weekStart && e.Date < weekStart.AddDays(7.0)).ToList();
				foreach (OperatorAccount op in store.Operators)
				{
					List<ScheduleEntry> list = source.Where((ScheduleEntry e) => e.Operator == op.Name).ToList();
					if (list.Count != 0)
					{
						ListViewItem listViewItem = new ListViewItem(new string[1] { op.Name });
						decimal num = 0m;
						for (int num2 = 0; num2 < 7; num2++)
						{
							DateTime day = weekStart.AddDays(num2);
							IEnumerable<string> values = from e in list
								where e.Date == day
								orderby e.Start
								select $"{e.Start:hh\\:mm}–{e.End:hh\\:mm}";
							string text2 = string.Join(", ", values);
							listViewItem.SubItems.Add(text2);
							foreach (ScheduleEntry item3 in list.Where((ScheduleEntry e) => e.Date == day))
							{
								TimeSpan timeSpan = item3.End - item3.Start;
								if (timeSpan < TimeSpan.Zero)
								{
									timeSpan += TimeSpan.FromDays(1.0);
								}
								num += (decimal)timeSpan.TotalHours;
							}
						}
						listViewItem.SubItems.Add(num.ToString("0.#"));
						grid.Items.Add(listViewItem);
					}
				}
				decimal num3 = source.Sum((ScheduleEntry e) =>
				{
					TimeSpan timeSpan2 = e.End - e.Start;
					if (timeSpan2 < TimeSpan.Zero)
					{
						timeSpan2 += TimeSpan.FromDays(1.0);
					}
					return (decimal)timeSpan2.TotalHours;
				});
				decimal num4 = source.Sum((ScheduleEntry e) =>
				{
					TimeSpan timeSpan2 = e.End - e.Start;
					if (timeSpan2 < TimeSpan.Zero)
					{
						timeSpan2 += TimeSpan.FromDays(1.0);
					}
					decimal num5 = store.Operators.FirstOrDefault((OperatorAccount o) => o.Name == e.Operator)?.Wage ?? 0m;
					return (decimal)timeSpan2.TotalHours * num5;
				});
				summaryLabel.Text = $"{num3:0.#} h scheduled  •  labor {num4:C}";
			}
		}

		private decimal ProductFoodCost(string productName)
		{
			if (!store.Recipes.TryGetValue(productName, out List<RecipeItem> value))
			{
				return 0m;
			}
			decimal result = 0m;
			foreach (RecipeItem ri in value)
			{
				Ingredient ingredient = store.Ingredients.FirstOrDefault((Ingredient i) => i.Name == ri.Ingredient);
				if (ingredient != null)
				{
					result += ri.Quantity * ingredient.Cost;
				}
			}
			return result;
		}

