							else
							{
								int selectedIndex = ingrC.SelectedIndex;
								if (selectedIndex >= 0)
								{
									Ingredient ingredient = store.Ingredients[selectedIndex];
									if (text3 == "Main")
									{
										if (qty.Value > ingredient.Stock)
