											MessageBox.Show(string.Format("{0}{1:0.##} {2} in main stock.", Tr.T("Only "), ingredient.Stock, ingredient.Unit), Tr.T("Transfer"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
