										AddLoc(text3, ingredient.Name, -qty.Value);
										List<Ingredient> ingredients2 = store.Ingredients;
										Ingredient ingredient3 = ingredient._003CClone_003E_0024();
										ingredient3.Stock = ingredient.Stock + qty.Value;
										ingredients2[selectedIndex] = ingredient3;
										store.SaveIngredients(store.Ingredients);
