					.Max();
				list2.Add((p.Name, source.Sum((SoldLine l) => l.Quantity), source.Sum((SoldLine l) => (decimal)l.Quantity * l.UnitPrice), item));
			}
			foreach (var item11 in list2.OrderByDescending(((string Name, int Qty, decimal Rev, DateTime? Last) s) => s.Qty))
			{
				string item2 = item11.Item1;
