				string text;
				if (item3 != 0)
				{
					if (item3 <= 5)
					{
						text = "Slow";
					}
					else
					{
						text = ((item3 >= 21) ? "Hot" : "OK");
					}
				}
				else
				{
					text = "DEAD";
				}
				string text2 = text switch
				{
					"DEAD" => "No sales in 30 days — consider delisting or promotion", 
					"Slow" => "Low turnover — keep stock minimal", 
					"Hot" => $"Top mover ({(decimal)item3 / 30m:0.0}/day) — keep 7 days of stock ready", 
					_ => "", 
				};
				ListViewItem listViewItem = new ListViewItem(new string[6]
				{
					item2,
