			void AddLoc(string loc, string ing, decimal amount)
			{
				if (!store.LocationStock.ContainsKey(loc))
				{
					store.LocationStock[loc] = new Dictionary<string, decimal>();
				}
				store.LocationStock[loc].TryGetValue(ing, out var value2);
				store.LocationStock[loc][ing] = value2 + amount;
			}
			static Button B(string text3, Color back)
			{
				Button button14 = new Button();
				button14.Text = text3;
				button14.Size = new Size(140, 36);
