				button14.ForeColor = Skin.Text;
				button14.FlatStyle = FlatStyle.Flat;
				button14.Margin = new Padding(0, 0, 8, 0);
				button14.Font = new Font("Segoe UI Semibold", 9.5f);
				button14.FlatAppearance.BorderSize = 0;
				return button14;
			}
			decimal GetLoc(string loc, string ing)
			{
				if (!store.LocationStock.TryGetValue(loc, out Dictionary<string, decimal> value2) || !value2.TryGetValue(ing, out var value3))
				{
					return 0m;
				}
				return value3;
			}
			string[] Locations()
			{
				string text3 = "Main";
				List<string> locations = store.Locations;
				int num = 0;
				string[] array = new string[1 + locations.Count];
				array[num] = text3;
				num++;
				foreach (string item12 in locations)
				{
					array[num] = item12;
					num++;
				}
				return array;
			}
			void RebuildPo()
			{
				poList.Items.Clear();
				foreach (PurchaseOrder item13 in store.PurchaseOrders.OrderByDescending((PurchaseOrder purchaseOrder) => purchaseOrder.Id))
				{
					ListViewItem listViewItem2 = new ListViewItem(new string[6]
					{
						item13.Id.ToString(),
						item13.Supplier,
						item13.Created.ToString("dd/MM/yyyy"),
						item13.Status,
						item13.Lines.Sum((POLine l) => l.Qty * l.Cost).ToString("C"),
						item13.Lines.Count.ToString()
					});
					if (item13.Status == "Received")
					{
						listViewItem2.ForeColor = Skin.SuccessText;
					}
					else if (item13.Status == "Cancelled")
					{
						listViewItem2.ForeColor = Skin.TextFaded;
					}
					poList.Items.Add(listViewItem2);
				}
			}
			void RebuildProfit()
			{
				profitGrid.Items.Clear();
				DateTime from = periodC.SelectedIndex switch
				{
					0 => DateTime.Today, 
					1 => DateTime.Today.AddDays(-6.0), 
					2 => DateTime.Today.AddDays(-29.0), 
					_ => DateTime.MinValue, 
				};
				List<SoldLine> source2 = store.Sales.Where((Sale s) => !s.IsRefund && s.Time >= from).ToList().SelectMany((Sale s) => s.Items ?? new List<SoldLine>())
					.ToList();
				decimal num = 0m;
				decimal num2 = 0m;
				foreach (IGrouping<string, SoldLine> item14 in from l in source2
					group l by l.Product into g
					orderby g.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity) descending
					select g)
				{
					decimal num3 = item14.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity);
					decimal num4 = ProductFoodCost(item14.Key) * (decimal)item14.Sum((SoldLine l) => l.Quantity);
					num += num3;
					num2 += num4;
					decimal num5 = ((num3 > 0m) ? (num4 / num3) : 0m);
					ListViewItem listViewItem2 = new ListViewItem(new string[6]
					{
						item14.Key,
						item14.Sum((SoldLine l) => l.Quantity).ToString(),
						num3.ToString("C"),
						num4.ToString("C"),
						(num3 - num4).ToString("C"),
						$"{num5:P0}"
					});
					if (num5 > 0.40m)
					{
						listViewItem2.ForeColor = Skin.Warning;
					}
					profitGrid.Items.Add(listViewItem2);
				}
				profitSummary.Text = ((num > 0m) ? $"Revenue {num:C}  •  food cost {num2:C} ({num2 / num:P0})  •  margin {num - num2:C}" : "No sales in period");
			}
			void RebuildSt()
			{
				stList.Items.Clear();
				foreach (StockTake item15 in store.StockTakes.OrderByDescending((StockTake s) => s.Id))
				{
					decimal num = item15.Lines.Sum((StockTakeLine l) => l.CountedQty - l.SystemQty);
					ListViewItem listViewItem2 = new ListViewItem(new string[6]
					{
						item15.Id.ToString(),
						item15.When.ToString("dd/MM/yyyy HH:mm"),
						item15.By,
						item15.Note,
						item15.Lines.Count.ToString(),
						num.ToString("+0.##;-0.##;0")
					});
					if (num != 0m)
					{
						listViewItem2.ForeColor = Skin.Warning;
					}
					stList.Items.Add(listViewItem2);
				}
			}
			void RebuildSup()
			{
				supGrid.Items.Clear();
				foreach (Supplier supplier4 in store.Suppliers)
				{
					supGrid.Items.Add(new ListViewItem(new string[3] { supplier4.Name, supplier4.Phone, supplier4.Email }));
				}
			}
			void RebuildTr()
			{
				trList.Items.Clear();
				foreach (StockTransfer item16 in store.StockTransfers.OrderByDescending((StockTransfer t) => t.Id))
				{
					trList.Items.Add(new ListViewItem(new string[7]
					{
						item16.Id.ToString(),
						item16.When.ToString("dd/MM/yyyy HH:mm"),
						item16.From,
						item16.To,
						item16.Ingredient,
						item16.Qty.ToString("0.##"),
						item16.By
					}));
				}
			}
			void RebuildWaste()
			{
				wasteList.Items.Clear();
				foreach (WasteEntry item17 in store.WasteLog.OrderByDescending((WasteEntry w) => w.When))
				{
					wasteList.Items.Add(new ListViewItem(new string[5]
					{
						item17.When.ToString("dd/MM/yyyy HH:mm"),
						item17.Ingredient,
						item17.Qty.ToString("0.##"),
						item17.Reason,
						item17.By
					}));
				}
			}
			PurchaseOrder? SelectedPo()
			{
				if (poList.SelectedItems.Count == 0)
				{
					MessageBox.Show(Tr.T("Select a purchase order first."), Tr.T("Purchases"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
					return null;
				}
				int id = int.Parse(poList.SelectedItems[0].Text);
				return store.PurchaseOrders.FirstOrDefault((PurchaseOrder purchaseOrder) => purchaseOrder.Id == id);
			}
		}

