					store.SaveEmailSettings(new EmailSettings(host.Text.Trim(), (int)port.Value, user.Text.Trim(), pass.Text, from.Text.Trim(), tls.Checked));
					if (store.Features.AuditLog)
					{
						store.LogAudit(currentOperator.Name, "Email settings", $"{host.Text.Trim()}:{port.Value} from {from.Text.Trim()}");
					}
					f.DialogResult = DialogResult.OK;
				};
				button2.Click += (object _, EventArgs _) =>
				{
					f.DialogResult = DialogResult.Cancel;
				};
				f.Controls.AddRange(new Control[3] { label, button, button2 });
				f.AcceptButton = button;
				f.ShowDialog();
			}
			finally
			{
				if (f != null)
				{
					((IDisposable)f).Dispose();
				}
			}
			void Row(string t, Control c, int y)
			{
				f.Controls.Add(new Label
				{
					Text = t,
					AutoSize = true,
					Location = new Point(20, y + 4)
				});
				c.Location = new Point(150, y);
				f.Controls.Add(c);
			}
		}

		private bool SendMailWithAttachment(string to, string subject, string body, string attachmentPath)
		{
			EmailSettings emailSettings = store.EmailSettings;
			if (emailSettings.Host.Length == 0)
			{
				return false;
			}
			try
			{
				using MailMessage mailMessage = new MailMessage(emailSettings.From, to, subject, body);
				if (File.Exists(attachmentPath))
				{
					mailMessage.Attachments.Add(new Attachment(attachmentPath));
				}
				using SmtpClient smtpClient = new SmtpClient(emailSettings.Host, emailSettings.Port)
				{
					EnableSsl = emailSettings.Tls
				};
				if (emailSettings.User.Length > 0)
				{
					smtpClient.Credentials = new NetworkCredential(emailSettings.User, emailSettings.Password);
				}
				smtpClient.Send(mailMessage);
				return true;
			}
			catch (Exception ex)
			{
				if (store.Features.AuditLog)
				{
					store.LogAudit("System", "Email failed", ex.Message);
				}
				return false;
			}
		}

		private void TrySendEmailReceipt(string customerName, string paymentType, List<SoldLine> lines, decimal finalTotal, decimal discount, decimal tip, int paymentNum, string orderType, decimal serviceFee = 0m, decimal cashDisc = 0m, decimal surcharge = 0m)
		{
			if (!store.Features.EmailReceipts)
			{
				return;
			}
			EmailSettings es = store.EmailSettings;
			if (string.IsNullOrWhiteSpace(es.Host) || string.IsNullOrWhiteSpace(es.From) || string.IsNullOrWhiteSpace(customerName))
			{
				return;
			}
			Customer customer = store.Customers.FirstOrDefault((Customer c) => c.Name == customerName);
			if (customer == null || string.IsNullOrWhiteSpace(customer.Email))
			{
				return;
			}
			string text = ((serviceFee > 0m || cashDisc > 0m || surcharge > 0m) ? ("Fees: " + string.Join("  ", new string[3]
			{
				(serviceFee > 0m) ? $"service +{serviceFee:C}" : "",
				(cashDisc > 0m) ? $"cash discount -{cashDisc:C}" : "",
				(surcharge > 0m) ? $"card surcharge +{surcharge:C}" : ""
			}.Where((string s) => s.Length > 0)) + Environment.NewLine) : "");
			string body = new StringBuilder().AppendLine("Thank you for your visit!").AppendLine($"Date: {DateTime.Now:dd/MM/yyyy HH:mm}").AppendLine("Operator: " + currentOperator.Name + "   Table: " + selectedTable + "   " + orderType)
				.AppendLine($"Payment #{paymentNum}   {paymentType}")
				.AppendLine("---")
				.ToString() + string.Join(Environment.NewLine, lines.Select((SoldLine l) => $"{l.Quantity} x {l.Product}  {l.UnitPrice * (decimal)l.Quantity:C}")) + Environment.NewLine + $"Discount: -{discount:C}   Tip: {tip:C}" + Environment.NewLine + text + $"TOTAL: {finalTotal:C}";
			string to = customer.Email;
			string fromAddr = es.From;
			Task.Run(() =>
			{
				try
				{
					using SmtpClient smtpClient = new SmtpClient(es.Host, es.Port)
					{
						EnableSsl = es.Tls
					};
					if (!string.IsNullOrWhiteSpace(es.User))
					{
						smtpClient.Credentials = new NetworkCredential(es.User, es.Password);
					}
					using MailMessage message = new MailMessage(fromAddr, to, $"Receipt — {DateTime.Now:dd/MM/yyyy HH:mm}", body);
					smtpClient.Send(message);
					if (store.Features.AuditLog)
					{
						store.LogAudit(currentOperator.Name, "Email receipt", "sent to " + to);
					}
				}
				catch (Exception ex)
				{
					try
					{
						if (store.Features.AuditLog)
						{
							store.LogAudit(currentOperator.Name, "Email receipt failed", ex.Message);
						}
					}
					catch
					{
					}
				}
			});
		}

		private void StartQrServer()
		{
			if (isOrderPc)
			{
				return;
			}
			if (qrServer != null)
			{
				UpdateQrBanner();
				return;
			}
			qrServer = new QrOrderServer(8080, HandleQrRequest);
			try
			{
				qrServer.Start();
			}
			catch (Exception)
			{
				try
				{
					Thread.Sleep(300);
					qrServer = new QrOrderServer(8080, HandleQrRequest);
					qrServer.Start();
				}
				catch
				{
					qrServer = null;
				}
			}
			UpdateQrBanner();
		}

		public void StopQrServer()
		{
			try
			{
				qrServer?.Stop();
			}
			catch { }
			qrServer = null;
			try
			{
				UpdateQrBanner();
			}
			catch { }
		}

		private string? HandleQrRequest(string method, string path, string body)
		{
			if (IsDisposed || !IsHandleCreated)
			{
				return null;
			}
			if (path.StartsWith("/api/tablet/", StringComparison.Ordinal))
			{
				try
				{
					string query = "";
					int num = path.IndexOf('?');
					if (num >= 0)
					{
						query = path.Substring(num + 1);
						path = path.Substring(0, num);
					}
					return RouteTablet(method, path, query, body);
				}
				catch
				{
					return null;
				}
			}
			if (path.StartsWith("/api/kiosk/", StringComparison.Ordinal))
			{
				try
				{
					string query = "";
					int num = path.IndexOf('?');
					if (num >= 0)
					{
						query = path.Substring(num + 1);
						path = path.Substring(0, num);
					}
					return RouteKiosk(method, path, query, body);
				}
				catch
				{
					return null;
				}
			}
			string result = null;
			ManualResetEventSlim done = new ManualResetEventSlim(initialState: false);
			try
			{
				try
				{
					BeginInvoke((Action)(() =>
					{
						try
						{
							result = RouteQr(method, path, body);
						}
						finally
						{
							done.Set();
						}
					}));
				}
				catch
				{
					return null;
				}
				return done.Wait(8000) ? result : null;
			}
			finally
			{
				if (done != null)
				{
					((IDisposable)done).Dispose();
				}
			}
		}

		private string RouteQr(string method, string path, string body)
		{
			string query = "";
			int num = path.IndexOf('?');
			if (num >= 0)
			{
				query = path.Substring(num + 1);
				path = path.Substring(0, num);
			}
			if (method == "GET" && (path == "/" || path == "/index.html"))
			{
				return HtmlResponse(BuildOrderPage(query));
			}
			if (method == "GET" && path == "/api/menu")
			{
				return JsonResponse((from p in store.Products
					where !Is86(store, p.Name)
					group p by p.Category into g
					select new
					{
						category = g.Key,
						products = g.Select((Product p) => new
						{
							name = p.Name,
							price = p.Price
						}).ToList()
					}).ToList());
			}
			if (method == "GET")
			{
				switch (path)
				{
				case "/api/stock":
					if (!store.Features.ApiEnabled)
					{
						return JsonResponse(new { ok = false, error = "API is disabled (Settings > Network)." });
					}
					return JsonResponse(new
					{
						ok = true,
						ingredients = store.Ingredients.Select(i => new { name = i.Name, unit = i.Unit, stock = i.Stock, min = i.MinStock, cost = i.Cost, supplier = i.Supplier, location = i.Location }),
						products = store.ProductStocks.Select(p => new { product = p.Product, stock = p.Stock, min = p.MinStock, unit = p.Unit, tracked = p.Tracked, cost = p.Cost }),
						low = StockEngine.Low(store).Select(a => new { product = a.ProductName, ingredient = a.Ingredient, remaining = a.Remaining, min = a.MinStock }),
						updated = DateTime.Now.ToString("s")
					});
				case "/api/sales":
				case "/api/products":
				case "/api/orders":
					if (!store.Features.ApiEnabled)
					{
						return JsonResponse(new
						{
							ok = false,
							error = "API is disabled (Settings > Network)."
						});
					}
					if (!string.IsNullOrEmpty(store.Features.ApiKey) && QV(query, "key") != store.Features.ApiKey)
					{
						return JsonResponse(new
						{
							ok = false,
							error = "Missing or invalid ?key=."
						});
					}
					if (path == "/api/sales")
					{
						int count = (int.TryParse(QV(query, "limit"), out var result) ? Math.Max(1, Math.Min(500, result)) : 50);
						return JsonResponse(new
						{
							ok = true,
							sales = (from s in store.Sales.OrderByDescending((Sale s) => s.Time).Take(count)
								select new
								{
									payment = s.PaymentNumber,
									time = s.Time.ToString("yyyy-MM-ddTHH:mm:ss"),
									total = s.Total,
									payment_type = s.PaymentType,
									@operator = s.Operator,
									branch = s.Branch,
									table = s.Table,
									order_type = s.OrderType,
									discount = s.Discount,
									tip = s.Tip,
									refund = s.IsRefund
								}).ToList()
						});
					}
					if (path == "/api/products")
					{
						return JsonResponse(new
						{
							ok = true,
							products = (from p in store.Products
								where !Is86(store, p.Name)
								select new
								{
									name = p.Name,
									category = p.Category,
									price = p.Price,
									family = p.Family,
									barcode = p.Barcode,
									weighted = p.Weighted
								}).ToList()
						});
					}
					return JsonResponse(new
					{
						ok = true,
						orders = store.OpenOrders.Select((OpenOrder o) => new
						{
							room = o.Room,
							table = o.Table,
							order = o.OrderNumber,
							created = o.Created.ToString("yyyy-MM-ddTHH:mm:ss"),
							ready = o.Ready,
							source = o.Source,
							items = o.Items.Select((SoldLine i) => new
							{
								product = i.Product,
								qty = i.Quantity,
								price = i.UnitPrice,
								note = i.Note
							}).ToList()
						}).ToList()
					});
				}
			}
			if (path == "/sync/sales")
			{
				if (!store.Features.CloudSync && !store.Features.ApiEnabled)
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Cloud sync is disabled (Settings > Network)."
					});
				}
				string text = ((!string.IsNullOrEmpty(store.Features.CloudSyncKey)) ? store.Features.CloudSyncKey : store.Features.ApiKey);
				if (method == "GET")
				{
					if (!string.IsNullOrEmpty(text) && QVs(query, "key") != text)
					{
						return JsonResponse(new
						{
							ok = false,
							error = "Missing or invalid ?key=."
						});
					}
					string requester = QVs(query, "device");
					DateTime.TryParse(QVs(query, "since"), null, DateTimeStyles.RoundtripKind, out var since);
					string text2 = QVs(query, "scope");
					IEnumerable<Sale> source = store.Sales.Where((Sale s) => s.Time > since).AsEnumerable();
					if (text2 == "mine")
					{
						if (string.IsNullOrEmpty(requester))
						{
							return JsonResponse(new
							{
								ok = false,
								error = "Missing ?device= when using scope=mine."
							});
						}
						source = source.Where((Sale s) => s.Device == requester);
						return JsonResponse(new
						{
							ok = true,
							server_time = DateTime.Now.ToString("o"),
							sales = source.OrderBy((Sale s) => s.Time).Take(10000).ToList()
						});
					}
					if (!string.IsNullOrEmpty(requester))
					{
						source = source.Where((Sale s) => s.Device != requester);
					}
					List<Sale> sales = source.OrderBy((Sale s) => s.Time).Take(500).ToList();
					return JsonResponse(new
					{
						ok = true,
						server_time = DateTime.Now.ToString("o"),
						sales = sales
					});
				}
				if (method == "POST")
				{
					try
					{
						using JsonDocument jsonDocument = JsonDocument.Parse(body);
						JsonElement rootElement = jsonDocument.RootElement;
						string text3 = (rootElement.TryGetProperty("key", out var value) ? (value.GetString() ?? "") : "");
						if (!string.IsNullOrEmpty(text) && text3 != text)
						{
							return JsonResponse(new
							{
								ok = false,
								error = "Missing or invalid key."
							});
						}
						string text4 = (rootElement.TryGetProperty("device", out var value2) ? (value2.GetString() ?? "") : "");
						int num2 = 0;
						if (rootElement.TryGetProperty("sales", out var value3) && value3.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item in value3.EnumerateArray())
							{
								try
								{
									Sale sale = JsonSerializer.Deserialize<Sale>(item.GetRawText());
									if (!(sale == null) && !store.HasSale(sale))
									{
										if (string.IsNullOrEmpty(sale.Device) && !string.IsNullOrEmpty(text4))
										{
											Sale sale2 = sale._003CClone_003E_0024();
											sale2.Device = text4;
											sale = sale2;
										}
										store.Sales.Add(sale);
										num2++;
									}
								}
								catch
								{
								}
							}
							if (num2 > 0)
							{
								store.Sales.Sort((Sale a, Sale b) => a.Time.CompareTo(b.Time));
								store.SaveSales();
							}
						}
						return JsonResponse(new
						{
							ok = true,
							added = num2
						});
					}
					catch (Exception ex)
					{
						return JsonResponse(new
						{
							ok = false,
							error = ex.Message
						});
					}
				}
				return JsonResponse(new
				{
					ok = false,
					error = "Use GET or POST /sync/sales."
				});
			}
			if (path == "/sync/backup")
			{
				if (!store.Features.CloudSync && !store.Features.ApiEnabled)
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Cloud sync is disabled (Settings > Network)."
					});
				}
				string text5 = ((!string.IsNullOrEmpty(store.Features.CloudSyncKey)) ? store.Features.CloudSyncKey : store.Features.ApiKey);
				if (method == "GET")
				{
					if (!string.IsNullOrEmpty(text5) && QVb(query, "key") != text5)
					{
						return JsonResponse(new
						{
							ok = false,
							error = "Missing or invalid ?key=."
						});
					}
					string text6 = QVb(query, "store");
					if (!ValidStore(text6))
					{
						return JsonResponse(new
						{
							ok = false,
							error = "Invalid store id."
						});
					}
					string path2 = Path.Combine(store.DataFolder, "stores", text6);
					string text7 = (Directory.Exists(path2) ? (from f in Directory.GetFiles(path2, "backup-*.zip")
						orderby f descending
						select f).FirstOrDefault() : null);
					if (text7 == null)
					{
						return JsonResponse(new
						{
							ok = false,
							error = "No backup found for store " + text6 + "."
						});
					}
					byte[] inArray = File.ReadAllBytes(text7);
					return JsonResponse(new
					{
						ok = true,
						store = text6,
						file = Path.GetFileName(text7),
						data = Convert.ToBase64String(inArray)
					});
				}
				if (method == "POST")
				{
					try
					{
						using JsonDocument jsonDocument2 = JsonDocument.Parse(body);
						JsonElement rootElement2 = jsonDocument2.RootElement;
						string text8 = (rootElement2.TryGetProperty("key", out var value4) ? (value4.GetString() ?? "") : "");
						if (!string.IsNullOrEmpty(text5) && text8 != text5)
						{
							return JsonResponse(new
							{
								ok = false,
								error = "Missing or invalid key."
							});
						}
						string text9 = (rootElement2.TryGetProperty("store", out var value5) ? (value5.GetString() ?? "") : "");
						if (!ValidStore(text9))
						{
							return JsonResponse(new
							{
								ok = false,
								error = "Invalid store id (letters, digits, - and _ only)."
							});
						}
						string text10 = (rootElement2.TryGetProperty("data", out var value6) ? (value6.GetString() ?? "") : "");
						if (text10.Length == 0)
						{
							return JsonResponse(new
							{
								ok = false,
								error = "No backup data."
							});
						}
						byte[] array = Convert.FromBase64String(text10);
						string text11 = Path.Combine(store.DataFolder, "stores", text9);
						Directory.CreateDirectory(text11);
						string text12 = $"backup-{DateTime.Now:yyyyMMdd-HHmmss}.zip";
						File.WriteAllBytes(Path.Combine(text11, text12), array);
						List<string> list = (from f in Directory.GetFiles(text11, "backup-*.zip")
							orderby f
							select f).ToList();
						for (int num3 = 0; num3 < list.Count - 14; num3++)
						{
							try
							{
								File.Delete(list[num3]);
							}
							catch
							{
							}
						}
						return JsonResponse(new
						{
							ok = true,
							file = text12,
							size = array.Length
						});
					}
					catch (Exception ex2)
					{
						return JsonResponse(new
						{
							ok = false,
							error = ex2.Message
						});
					}
				}
				return JsonResponse(new
				{
					ok = false,
					error = "Use GET or POST /sync/backup."
				});
			}
			if (path.StartsWith("/api/tablet/", StringComparison.Ordinal))
			{
				return RouteTablet(method, path, query, body);
			}
			if (method == "POST" && path == "/api/order")
			{
				return HandleQrOrder(body);
			}
			if (method == "GET" && path == "/api/call")
			{
				string text13 = QV2("room");
				string text14 = QV2("table");
				if (text13.Length == 0 || text14.Length == 0)
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Missing table."
					});
				}
				store.RaiseGuestAlert(text13, text14, "waiter");
				if (store.Features.AuditLog)
				{
					store.LogAudit("Guest", "Call waiter", text13 + "/" + text14);
				}
				return JsonResponse(new
				{
					ok = true
				});
			}
			if (method == "GET" && path == "/api/status")
			{
				string room = QV3("room");
				string table = QV3("table");
				OpenOrder openOrder = store.GetOpenOrder(room, table);
				string text15;
				if (openOrder == null)
				{
					text15 = "none";
				}
				else
				{
					text15 = (openOrder.Ready ? "ready" : "preparing");
				}
				return JsonResponse(new
				{
					ok = true,
					state = text15,
					order = (openOrder?.OrderNumber ?? 0),
					total = (((object)openOrder != null) ? openOrder.Items.Sum((SoldLine i) => i.UnitPrice * (decimal)i.Quantity) : 0m),
					items = (((object)openOrder != null) ? openOrder.Items.Sum((SoldLine i) => i.Quantity) : 0)
				});
			}
			if (method == "GET" && path == "/status")
			{
				return HtmlResponse(BuildStatusPage(query));
			}
			if (method == "GET" && path.StartsWith("/vt/") && !path.EndsWith("/pay"))
			{
				return HtmlResponse(BuildVtPage(path.Substring(4)));
			}
			if (method == "POST" && path.StartsWith("/vt/") && path.EndsWith("/pay"))
			{
				string text16 = path;
				if (!int.TryParse(text16.Substring(4, text16.Length - 4 - 4).TrimEnd('/'), out var vtId))
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Bad invoice id."
					});
				}
				int num4 = store.VtInvoices.FindIndex((VtInvoice v) => v.Id == vtId && v.Status == "Pending");
				if (num4 < 0)
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Invoice not found or already paid."
					});
				}
				VtInvoice vtInvoice = store.VtInvoices[num4];
				List<VtInvoice> vtInvoices = store.VtInvoices;
				VtInvoice vtInvoice2 = vtInvoice._003CClone_003E_0024();
				vtInvoice2.Status = "Paid";
				vtInvoices[num4] = vtInvoice2;
				store.SaveVtInvoices(store.VtInvoices);
				store.AddSale(new Sale(DateTime.Now, vtInvoice.Amount, "VT", "Web", new List<SoldLine>(), store.NextPaymentNumber(), 0, 0m, $"VT #{vtInvoice.Id} {vtInvoice.Name}", vtInvoice.Name, "Phone order"));
				if (store.Features.AuditLog)
				{
					store.LogAudit("Web", "VT paid", $"#{vtInvoice.Id} {vtInvoice.Amount:C} {vtInvoice.Name}");
				}
				return JsonResponse(new
				{
					ok = true,
					amount = vtInvoice.Amount
				});
			}
			return "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
			static string QV(string q, string k)
			{
				string[] array2 = q.Split(new char[1] { '&' }, StringSplitOptions.RemoveEmptyEntries);
				for (int i = 0; i < array2.Length; i++)
				{
					string[] array3 = array2[i].Split(new char[1] { '=' }, 2);
					if (array3.Length == 2 && array3[0] == k)
					{
						return Uri.UnescapeDataString(array3[1].Replace('+', ' '));
					}
