			{
				if (s.Length < 1 || s.Length > 64)
				{
					return false;
				}
				foreach (char c in s)
				{
					if (!char.IsLetterOrDigit(c) && c != '-' && c != '_')
					{
						return false;
					}
				}
				return true;
