		private string HandleQrOrder(string body)
		{
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(body);
				JsonElement rootElement = jsonDocument.RootElement;
				string text = (rootElement.TryGetProperty("room", out var value) ? (value.GetString() ?? "") : "");
				string text2 = (rootElement.TryGetProperty("table", out var value2) ? (value2.GetString() ?? "") : "");
				if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(text2))
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Choose a room and table."
					});
				}
				List<SoldLine> list = new List<SoldLine>();
				if (rootElement.TryGetProperty("items", out var value3))
				{
					foreach (JsonElement item in value3.EnumerateArray())
					{
						string name = item.GetProperty("name").GetString() ?? "";
						int num = ((item.TryGetProperty("qty", out var value4) && value4.TryGetInt32(out var value5)) ? value5 : 0);
						if (name.Length != 0 && num > 0)
						{
							Product product = store.Products.FirstOrDefault((Product p) => p.Name == name);
							if (!(product == null))
							{
								list.Add(new SoldLine(product.Name, product.Family, num, product.Price, product.Category, ResolvePrinter(product)));
							}
						}
					}
				}
				if (list.Count == 0)
				{
					return JsonResponse(new
					{
						ok = false,
						error = "No valid items in the order."
					});
				}
				OpenOrder openOrder = store.GetOpenOrder(text, text2);
				int num2;
				if (openOrder != null)
				{
					num2 = openOrder.OrderNumber;
					List<SoldLine> items = openOrder.Items.Concat(list).ToList();
					store.RemoveOpenOrder(text, text2);
					PosStore posStore = store;
					OpenOrder openOrder2 = openOrder._003CClone_003E_0024();
					openOrder2.Items = items;
					openOrder2.Source = ((openOrder.Source == "") ? "QR" : openOrder.Source);
					posStore.AddOpenOrder(openOrder2);
				}
				else
				{
					num2 = store.NextOrderNumber();
					store.AddOpenOrder(new OpenOrder(text, text2, "QR", DateTime.Now, list, "", num2, num2, "Dine-in", "", 0, Ready: false, 0, "QR"));
				}
				PrintTickets(list, num2, 0, "Dine-in", text, text2);
				if (store.Features.AuditLog)
				{
					store.LogAudit("QR", "Order received", $"{text}/{text2} — {list.Sum((SoldLine l) => l.Quantity)} items, order #{num2}");
				}
				UpdateQrBanner();
				return JsonResponse(new
				{
					ok = true,
					order = num2,
					table = text2,
					room = text,
					total = list.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity)
				});
			}
			catch (Exception ex)
			{
				return JsonResponse(new
				{
					ok = false,
					error = ex.Message
				});
			}
		}

		private static string TabletQ(string query, string key)
		{
			string[] array = query.Split(new char[1] { '&' }, StringSplitOptions.RemoveEmptyEntries);
			for (int i = 0; i < array.Length; i++)
			{
				string[] array2 = array[i].Split(new char[1] { '=' }, 2);
				if (array2.Length == 2 && array2[0] == key)
				{
					return Uri.UnescapeDataString(array2[1].Replace('+', ' '));
				}
			}
			return "";
		}

		private string RouteKiosk(string method, string path, string query, string body)
		{
			if (!store.Features.ApiEnabled && !store.Features.KioskMode)
			{
				return JsonResponse(new { ok = false, error = "Kiosk mode or API is disabled in Settings." });
			}
			if (!string.IsNullOrWhiteSpace(store.Features.ApiKey) && TabletQ(query, "key") != store.Features.ApiKey)
			{
				return JsonResponse(new { ok = false, error = "Invalid API key." });
			}
			store.CleanExpiredKioskOrders();
			JsonDocument? jsonDocument = null;
			try
			{
				if (method == "POST" && !string.IsNullOrWhiteSpace(body))
				{
					try { jsonDocument = JsonDocument.Parse(body); }
					catch (Exception ex) { return JsonResponse(new { ok = false, error = "Invalid JSON: " + ex.Message }); }
				}
				return path switch
				{
					"/api/kiosk/bootstrap" => KioskBootstrap(),
					"/api/kiosk/menu" => KioskMenu(),
					"/api/kiosk/image" => TabletImage(query),
					"/api/kiosk/order" => KioskPostOrder(jsonDocument),
					"/api/kiosk/orders/pending" => KioskGetPending(),
					"/api/kiosk/orders/confirm" => KioskConfirm(method, jsonDocument),
					"/api/kiosk/orders/reject" => KioskReject(method, jsonDocument),
					_ => JsonResponse(new { ok = false, error = "Unknown kiosk endpoint." })
				};
			}
			finally
			{
				jsonDocument?.Dispose();
			}
		}

		private string KioskBootstrap()
		{
			store.CleanExpiredKioskOrders();
			PrinterDestination? printDest = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Payment");
			return JsonResponse(new
			{
				ok = true,
				restaurant_name = (printDest?.Header ?? "VECTRON RESTAURANT"),
				currency = store.RegisterSettings.Currency,
				tva_rate = store.RegisterSettings.TvaRate,
				confirmation_required = store.Features.KioskRequireConfirmation,
				auto_void_minutes = ((store.Features.KioskAutoVoidMinutes > 0) ? store.Features.KioskAutoVoidMinutes : 10),
				printer_name = store.Features.KioskPrinterName,
				print_customer_slip = store.Features.KioskPrintCustomerSlip,
				server_time = DateTime.Now.ToString("o")
			});
		}

