				tva_rate = store.RegisterSettings.TvaRate,
				prices_include_tva = store.RegisterSettings.PricesIncludeTva,
				course_management = store.Features.CourseManagement,
				seat_ordering = store.Features.SeatOrdering,
				item_notes = store.Features.ItemNotes,
				modifiers_enabled = store.Features.Modifiers,
				pin_login = store.Features.PinLogin,
				product_variants = store.Features.ProductVariants,
				weighted_items = store.Features.WeightedItems,
				happy_hour = (store.Features.HappyHour && store.HappyHourRules.Count > 0),
				course_names = store.CourseNames,
				operators = store.Operators.Select((OperatorAccount o) => new
				{
					name = o.Name,
