		private string TabletLogin(string method, JsonDocument? doc)
		{
			if (method != "POST" || doc == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Use POST /api/tablet/login with {name, pin}."
				});
			}
			JsonElement rootElement = doc.RootElement;
			string name = (rootElement.TryGetProperty("name", out var value) ? (value.GetString() ?? "") : "");
			string text = (rootElement.TryGetProperty("pin", out var value2) ? (value2.GetString() ?? "") : "");
			OperatorAccount operatorAccount = store.Operators.FirstOrDefault((OperatorAccount o) => string.Equals(o.Name, name, StringComparison.OrdinalIgnoreCase));
			if (operatorAccount == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Unknown operator."
				});
			}
			if (!string.IsNullOrWhiteSpace(operatorAccount.Password) && operatorAccount.Password != text)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Incorrect PIN."
				});
			}
			if (store.Features.AuditLog)
			{
				store.LogAudit(operatorAccount.Name, "Tablet login", "waiter terminal");
			}
			return JsonResponse(new
			{
				ok = true,
				@operator = operatorAccount.Name,
				permissions = operatorAccount.Permissions
			});
		}

		private string TabletMenu()
