		private string TabletImage(string query)
		{
			string fileName = Path.GetFileName(TabletQ(query, "name"));
			if (fileName.Length == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Missing image name."
				});
			}
			string? text = CatalogImageStore.Resolve(fileName);
			if (text == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Unknown image."
				});
			}
			byte[] array = CatalogImageStore.Thumbnail(text);
			if (array == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Unreadable image."
				});
			}
			return JsonResponse(new
			{
				ok = true,
				name = fileName,
				mime = "image/jpeg",
				data = Convert.ToBase64String(array)
			});
		}

		private string TabletMap()
		{
			var rooms = store.Rooms.Select((Room r) => new
			{
				name = r.Name,
				tables = Enumerable.Range(1, Math.Max(1, r.TableCount)).Select((int i) =>
				{
					string text = TableName(r.Name, i);
					OpenOrder oo = store.GetOpenOrder(r.Name, text);
					object order = ((oo == null) ? null : new
					{
						number = oo.OrderNumber,
						@operator = oo.Operator,
						created = oo.Created.ToString("yyyy-MM-ddTHH:mm:ss"),
						items = oo.Items.Sum((SoldLine l) => l.Quantity),
						total = oo.Items.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity),
						ready = oo.Ready,
						fired_course = oo.FiredCourse,
						pending_course = oo.Items.Any((SoldLine l) => l.Course > oo.FiredCourse),
						source = oo.Source,
						order_type = oo.OrderType
					});
					return new
					{
						name = text,
						taken = (oo != null),
						order = order
					};
				}).ToList()
			}).ToList();
			return JsonResponse(new
			{
				ok = true,
				server_time = DateTime.Now.ToString("o"),
				rooms = rooms
			});
		}

		private string TabletGetOrder(string query)
		{
