		private string TabletPostOrder(JsonDocument? doc)
		{
			if (doc == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Missing JSON body."
				});
			}
			JsonElement rootElement = doc.RootElement;
			string text = (rootElement.TryGetProperty("pending_id", out var value) ? (value.GetString() ?? "") : "");
			if (text.Length > 0)
			{
				lock (tabletOrderDedupeLock)
				{
					if (tabletOrderDedupe.TryGetValue(text, out (string, DateTime) value2) && DateTime.UtcNow - value2.Item2 < TimeSpan.FromHours(24.0))
					{
						return value2.Item1;
					}
				}
			}
			string text2 = (rootElement.TryGetProperty("room", out var value3) ? (value3.GetString() ?? "") : "");
			string text3 = (rootElement.TryGetProperty("table", out var value4) ? (value4.GetString() ?? "") : "");
			string opName = (rootElement.TryGetProperty("operator", out var value5) ? (value5.GetString() ?? "") : "");
			string text4 = (rootElement.TryGetProperty("order_type", out var value6) ? value6.GetString() : null);
			string orderType = (string.IsNullOrWhiteSpace(text4) ? "Dine-in" : text4);
			string text5 = (rootElement.TryGetProperty("delivery_address", out var value7) ? (value7.GetString() ?? "") : "");
			string note = (rootElement.TryGetProperty("note", out var value8) ? (value8.GetString() ?? "") : "");
			if (string.IsNullOrWhiteSpace(text2) || string.IsNullOrWhiteSpace(text3))
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Choose a room and table."
				});
			}
			OperatorAccount operatorAccount = store.Operators.FirstOrDefault((OperatorAccount x) => string.Equals(x.Name, opName, StringComparison.OrdinalIgnoreCase));
			if (operatorAccount == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Unknown operator. Log in on the tablet first."
				});
			}
			bool courseManagement = store.Features.CourseManagement;
			List<SoldLine> list = new List<SoldLine>();
			List<string> list2 = new List<string>();
			if (rootElement.TryGetProperty("items", out var value9) && value9.ValueKind == JsonValueKind.Array)
			{
				foreach (JsonElement item2 in value9.EnumerateArray())
				{
					try
					{
						string name = (item2.TryGetProperty("name", out var value10) ? (value10.GetString() ?? "") : "");
						int num = ((item2.TryGetProperty("qty", out var value11) && value11.TryGetInt32(out var value12)) ? value12 : 0);
						if (name.Length == 0 || num <= 0)
						{
							list2.Add("Skipped an item with missing name/qty.");
							continue;
						}
						Product product = store.Products.FirstOrDefault((Product x) => x.Name == name);
						if (product == null)
						{
							list2.Add("Unknown product: " + name);
							continue;
						}
						if (Is86(store, product.Name))
						{
							list2.Add(name + " is out of stock (86'd).");
							continue;
						}
						if (!store.Features.ProductVariants || !item2.TryGetProperty("variant", out var value13) || string.IsNullOrWhiteSpace(value13.GetString()))
						{
							goto IL_04c4;
						}
						string vname = value13.GetString();
						ProductVariant productVariant = store.ProductVariants.FirstOrDefault((ProductVariant v) => v.Product == product.Name && v.Name == vname);
						if (productVariant == null)
						{
							list2.Add("Unknown variant: " + name + " (" + vname + ")");
							continue;
						}
						Product product2 = product._003CClone_003E_0024();
						product2.Name = product.Name + " (" + productVariant.Name + ")";
						product2.Price = productVariant.Price;
						product2.Barcode = ((productVariant.Barcode.Length > 0) ? productVariant.Barcode : product.Barcode);
						product = product2;
						goto IL_04c4;
						IL_04c4:
						decimal num2 = product.Price;
						if (store.Features.HappyHour && store.HappyHourRules.Count > 0)
						{
							DateTime now = DateTime.Now;
							string item = now.DayOfWeek.ToString();
							foreach (HappyHourRule happyHourRule in store.HappyHourRules)
							{
								if (happyHourRule.Days.Contains(item) && now.TimeOfDay >= happyHourRule.Start && now.TimeOfDay <= happyHourRule.End)
								{
									num2 = product.Price * (1m - happyHourRule.DiscountPercent / 100m);
									break;
								}
							}
						}
						List<string> list3 = new List<string>();
						if (store.Features.Modifiers && item2.TryGetProperty("modifiers", out var value14) && value14.ValueKind == JsonValueKind.Array)
						{
							foreach (JsonElement item3 in value14.EnumerateArray())
							{
								string mname = ((item3.ValueKind == JsonValueKind.String) ? (item3.GetString() ?? "") : "");
								if (mname.Length != 0)
								{
									ModifierOption modifierOption = store.ModifierGroups.SelectMany((ModifierGroup g) => g.Options).FirstOrDefault((ModifierOption x) => x.Name == mname);
									if (modifierOption == null)
									{
										list2.Add("Unknown modifier: " + mname);
										continue;
									}
									num2 += modifierOption.Price;
									list3.Add(mname);
								}
							}
						}
						string text6 = (item2.TryGetProperty("note", out var value15) ? (value15.GetString() ?? "") : "");
						if (store.Features.WeightedItems && product.Weighted && item2.TryGetProperty("weight", out var value16) && value16.TryGetDecimal(out var value17) && value17 > 0m)
						{
							num2 = Math.Round(num2 * value17, 2);
							text6 = (string.IsNullOrWhiteSpace(text6) ? $"{value17:0.###} kg @ {product.Price:C}/kg" : $"{text6} · {value17:0.###} kg");
						}
						int course = (courseManagement ? ((!item2.TryGetProperty("course", out var value18) || !value18.TryGetInt32(out var value19) || value19 <= 0) ? 1 : value19) : 0);
						int num3 = ((store.Features.SeatOrdering && item2.TryGetProperty("seat", out var value20) && value20.TryGetInt32(out var value21) && value21 > 0) ? value21 : 0);
						string name2 = product.Name;
						string family = product.Family;
						decimal unitPrice = num2;
						string text7 = product.Category;
						string printerDestination = ResolvePrinter(product);
						string note2 = text6;
						string modifiers = string.Join(", ", list3);
						int seat = num3;
						list.Add(new SoldLine(name2, family, num, unitPrice, text7, printerDestination, note2, modifiers, 0m, "", course, seat));
					}
					catch (Exception ex)
					{
						list2.Add("Bad item: " + ex.Message);
					}
				}
			}
			List<string> list4 = list2.Where((string i) => i.StartsWith("Unknown ", StringComparison.Ordinal)).ToList();
			if (list4.Count > 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = string.Join("; ", list4)
				});
			}
			if (list.Count == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = ((list2.Count > 0) ? string.Join("; ", list2) : "No valid items in the order.")
				});
			}
			OpenOrder openOrder = store.GetOpenOrder(text2, text3);
			int num4;
			if (openOrder != null)
			{
				num4 = openOrder.OrderNumber;
				List<SoldLine> list5 = openOrder.Items.Concat(list).ToList();
				store.RemoveOpenOrder(text2, text3);
				PosStore posStore = store;
				OpenOrder openOrder2 = openOrder._003CClone_003E_0024();
				openOrder2.Items = list5;
				openOrder2.Operator = operatorAccount.Name;
				openOrder2.SeatCount = Math.Max(openOrder.SeatCount, list5.Max((SoldLine l) => l.Seat));
				openOrder2.OrderType = (string.IsNullOrWhiteSpace(text4) ? openOrder.OrderType : text4);
				openOrder2.DeliveryAddress = ((!string.IsNullOrWhiteSpace(text5)) ? text5 : openOrder.DeliveryAddress);
				openOrder2.Source = ((openOrder.Source == "") ? "Tablet" : openOrder.Source);
				posStore.AddOpenOrder(openOrder2);
			}
			else
			{
				num4 = store.NextOrderNumber();
				store.AddOpenOrder(new OpenOrder(text2, text3, operatorAccount.Name, DateTime.Now, list, note, num4, num4, orderType, "", list.Max((SoldLine l) => l.Seat), Ready: false, 0, "Tablet", text5));
			}
			OpenOrder openOrder3 = store.GetOpenOrder(text2, text3);
			List<string> list6 = new List<string>();
			if (openOrder3 != null)
			{
				TabletFireNewLines(openOrder3, list, operatorAccount.Name, list6);
			}
			OpenOrder openOrder4 = store.GetOpenOrder(text2, text3);
			if (store.Features.AuditLog)
			{
				store.LogAudit(operatorAccount.Name, "Tablet order", $"{text2}/{text3} — {list.Sum((SoldLine l) => l.Quantity)} items, order #{num4}");
			}
			UpdateQrBanner();
			string text8 = JsonResponse(new
			{
				ok = true,
				order = num4,
				room = text2,
				table = text3,
				merged = (openOrder != null),
				lines = list.Count,
				fired_course = (openOrder4?.FiredCourse ?? 0),
				total = list.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity),
				order_total = (((object)openOrder4 != null) ? openOrder4.Items.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity) : 0m),
				issues = list2,
				print_warnings = list6
			});
			if (text.Length > 0)
			{
				lock (tabletOrderDedupeLock)
				{
					tabletOrderDedupe[text] = (text8, DateTime.UtcNow);
					if (tabletOrderDedupe.Count > 500)
					{
						foreach (string item4 in (from kv in tabletOrderDedupe
							where DateTime.UtcNow - kv.Value.At > TimeSpan.FromHours(24.0)
							select kv.Key).ToList())
						{
							tabletOrderDedupe.Remove(item4);
						}
					}
				}
			}
			return text8;
		}

		private void TabletFireNewLines(OpenOrder storedOrder, List<SoldLine> newLines, string operatorName, List<string> printWarnings)
		{
			if (!store.Features.CourseManagement)
			{
				PrintTickets(newLines, storedOrder.OrderNumber, 0, storedOrder.OrderType, storedOrder.Room, storedOrder.Table, operatorName, showWarnings: false, printWarnings);
			}
			else if (storedOrder.FiredCourse == 0)
			{
				if (!store.Features.HoldFire)
				{
					List<SoldLine> list = storedOrder.Items.Where((SoldLine l) => l.Course <= 1).ToList();
					if (list.Count != 0)
					{
						PrintTickets(list, storedOrder.OrderNumber, 0, storedOrder.OrderType, storedOrder.Room, storedOrder.Table, operatorName, showWarnings: false, printWarnings);
						SetFiredCourse(storedOrder, 1);
					}
				}
			}
			else
			{
				List<SoldLine> list2 = newLines.Where((SoldLine l) => l.Course == 0 || l.Course <= storedOrder.FiredCourse).ToList();
				if (list2.Count != 0)
				{
					PrintTickets(list2, storedOrder.OrderNumber, 0, storedOrder.OrderType, storedOrder.Room, storedOrder.Table, operatorName, showWarnings: false, printWarnings);
				}
			}
		}

		private string TabletFire(string method, JsonDocument? doc)
		{
			if (method != "POST" || doc == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Use POST /api/tablet/fire with {room, table, operator}."
				});
			}
			JsonElement rootElement = doc.RootElement;
			string text = (rootElement.TryGetProperty("room", out var value) ? (value.GetString() ?? "") : "");
			string text2 = (rootElement.TryGetProperty("table", out var value2) ? (value2.GetString() ?? "") : "");
			string text3 = (rootElement.TryGetProperty("operator", out var value3) ? (value3.GetString() ?? "") : "");
			if (text.Length == 0 || text2.Length == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Missing room or table."
				});
			}
			OpenOrder order = store.GetOpenOrder(text, text2);
			if (order == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "No open order for this table."
				});
			}
			int next = (from l in order.Items
				where l.Course > order.FiredCourse
				select l.Course).DefaultIfEmpty(0).Min();
			if (next <= 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "No pending course to fire."
				});
			}
			List<SoldLine> list = order.Items.Where((SoldLine l) => l.Course == next).ToList();
			if (list.Count == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "No lines for the next course."
				});
			}
			List<string> list2 = new List<string>();
			string text4 = ((text3.Length > 0) ? text3 : order.Operator);
			PrintTickets(list, order.OrderNumber, 0, order.OrderType, text, text2, text4, showWarnings: false, list2);
			SetFiredCourse(order, next);
			if (store.Features.AuditLog)
			{
				store.LogAudit(text4, "Tablet fire", $"{text}/{text2} — course {next}, {list.Count} lines");
			}
			UpdateQrBanner();
			return JsonResponse(new
			{
				ok = true,
				course = next,
				lines = list.Count,
				print_warnings = list2
			});
		}

		private string TabletBill(string method, JsonDocument? doc)
		{
			if (method != "POST" || doc == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Use POST /api/tablet/bill with {room, table}."
				});
			}
			JsonElement rootElement = doc.RootElement;
			string text = (rootElement.TryGetProperty("room", out var value) ? (value.GetString() ?? "") : "");
			string text2 = (rootElement.TryGetProperty("table", out var value2) ? (value2.GetString() ?? "") : "");
			string text3 = (rootElement.TryGetProperty("operator", out var value3) ? (value3.GetString() ?? "") : "");
			if (text.Length == 0 || text2.Length == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Missing room or table."
				});
			}
			OpenOrder openOrder = store.GetOpenOrder(text, text2);
			if (openOrder == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "No open order for this table."
				});
			}
			decimal discountAmount = ((rootElement.TryGetProperty("discount", out var value4) && value4.TryGetDecimal(out var value5)) ? value5 : 0m);
			List<SoldLine> list = openOrder.Items.Select((SoldLine i) => new SoldLine(i.Product, i.Family, i.Quantity, i.UnitPrice, i.Category, i.PrinterDestination, "", "", 0m, "", 0, i.Seat)).ToList();
			PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination pd) => pd.Name == "Bill");
			if (printerDestination == null || string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
			{
				return JsonResponse(new
				{
					ok = false,
					error = "No Bill printer configured (Settings > Printer routing)."
				});
			}
			try
			{
				if (printerDestination.CutAfterPrint)
				{
					try
					{
						RawPrinter.PrintTicket(printerDestination, text, text2, openOrder.Operator, list, ResolvePrinterName(printerDestination), openOrder.OrderNumber, openOrder.BillNumber, 0, "", 0m, discountAmount);
					}
					catch (InvalidOperationException)
					{
						PrintWindowsTicket(printerDestination, list, openOrder.OrderNumber, openOrder.BillNumber, 0, "", 0m, discountAmount, text, text2);
					}
				}
				else
				{
					PrintWindowsTicket(printerDestination, list, openOrder.OrderNumber, openOrder.BillNumber, 0, "", 0m, discountAmount, text, text2);
				}
			}
			catch (Exception ex2)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Could not print bill: " + ex2.Message
				});
			}
			if (store.Features.AuditLog)
			{
				store.LogAudit((text3.Length > 0) ? text3 : openOrder.Operator, "Tablet bill", $"{text}/{text2} — bill #{openOrder.BillNumber}");
			}
			UpdateQrBanner();
			return JsonResponse(new
			{
				ok = true,
				bill = openOrder.BillNumber
			});
		}

		private string TabletAlerts(string query)
		{
			DateTime since = DateTime.MinValue;
			string text = TabletQ(query, "since");
			if (text.Length > 0 && DateTimeOffset.TryParse(text, null, DateTimeStyles.RoundtripKind, out var result))
			{
				since = result.LocalDateTime;
			}
			var alerts = (from a in store.GuestAlerts
				where a.Time > since
				orderby a.Time
				select new
				{
					id = a.Id,
					room = a.Room,
					table = a.Table,
					kind = a.Kind,
					time = a.Time.ToString("o")
				}).ToList();
			var ready = (from o in store.OpenOrders
				where o.Ready && !o.Delivered
				select new
				{
					room = o.Room,
					table = o.Table,
					order = o.OrderNumber,
					total = o.Items.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity)
				}).ToList();
			store.CleanExpiredKioskOrders();
			var pendingKiosk = store.PendingKioskOrders.Where((PendingKioskOrder o) => o.Status == "Pending").Select((PendingKioskOrder o) => new
			{
				order = o.OrderNumber,
				time = o.Created.ToString("o"),
				order_type = o.OrderType,
				total = o.Total,
				items_count = o.Items.Sum((SoldLine i) => i.Quantity)
			}).ToList();
			return JsonResponse(new
			{
				ok = true,
				server_time = DateTime.Now.ToString("o"),
				alerts = alerts,
				ready = ready,
				pending_kiosk = pendingKiosk
			});
		}

		private string TabletOrderDeliver(string method, JsonDocument? doc)
		{
			if (method != "POST" || doc == null)
			{
				return JsonResponse(new { ok = false, error = "POST JSON { room, table, order } expected." });
			}
			JsonElement root = doc.RootElement;
			string room = root.TryGetProperty("room", out var r) ? (r.GetString() ?? "") : "";
			string table = root.TryGetProperty("table", out var t) ? (t.GetString() ?? "") : "";
			int orderNum = root.TryGetProperty("order", out var o) ? o.GetInt32() : 0;

			store.MarkOrderDelivered(room, table, orderNum);
			return JsonResponse(new { ok = true, message = "Order delivered" });
		}

		private string TabletAlertDismiss(string method, JsonDocument? doc)
		{
			if (method != "POST" || doc == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Use POST /api/tablet/alerts/dismiss."
				});
			}
			JsonElement rootElement = doc.RootElement;
			string text = (rootElement.TryGetProperty("id", out var value) ? (value.GetString() ?? "") : "");
			if (text.Length > 0)
			{
				store.DismissGuestAlert(text);
				return JsonResponse(new
				{
					ok = true
				});
			}
			string room = (rootElement.TryGetProperty("room", out var value2) ? (value2.GetString() ?? "") : "");
			string table = (rootElement.TryGetProperty("table", out var value3) ? (value3.GetString() ?? "") : "");
			string text2 = (rootElement.TryGetProperty("kind", out var value4) ? (value4.GetString() ?? "") : "");
			if (room.Length == 0 || table.Length == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Provide alert id, or room + table (+ kind)."
				});
			}
			if (text2.Length > 0)
			{
				store.DismissGuestAlerts(room, table, text2);
			}
			else
			{
				store.GuestAlerts.RemoveAll((GuestAlertItem a) => a.Room == room && a.Table == table);
			}
			return JsonResponse(new
			{
				ok = true
			});
		}

		private List<string> TabletPrintCancel(SoldLine line, string room, string table, string opName)
		{
			List<string> list = new List<string>();
			if (string.IsNullOrWhiteSpace(line.PrinterDestination))
			{
				return list;
			}
			PrinterDestination printerDestination = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == line.PrinterDestination);
			if (printerDestination == null || string.IsNullOrWhiteSpace(printerDestination.WindowsPrinter))
			{
				return list;
			}
			PrinterDestination printerDestination2 = store.PrinterDestinations.FirstOrDefault((PrinterDestination d) => d.Name == "Cancel");
			PrinterDestination printerDestination3 = ((printerDestination2 != null) ? new PrinterDestination(printerDestination2.Name, printerDestination.WindowsPrinter, printerDestination2.Header, printerDestination2.Footer, printerDestination2.CutAfterPrint, printerDestination2.Layout, printerDestination2.LogoPath) : printerDestination);
			SoldLine item = new SoldLine("CANCEL: " + line.Product, line.Family, -line.Quantity, line.UnitPrice, line.Category, line.PrinterDestination);
			try
			{
				if (printerDestination3.CutAfterPrint)
				{
					try
					{
						RawPrinter.PrintTicket(printerDestination3, room, table, opName, new List<SoldLine>(1) { item }, ResolvePrinterName(printerDestination3));
						return list;
					}
					catch (InvalidOperationException)
					{
					}
				}
				PrintWindowsTicket(printerDestination3, new List<SoldLine>(1) { item }, 0, 0, 0, "", 0m, 0m, room, table);
			}
			catch (Exception ex2)
			{
				list.Add("Cancel ticket not printed: " + ex2.Message);
			}
			return list;
		}

		private string TabletLineEdit(string method, JsonDocument? doc)
		{
			if (method != "POST" || doc == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Use POST /api/tablet/line-edit with {room, table, index, operator, remove} or {room, table, index, operator, qty}."
				});
			}
			JsonElement rootElement = doc.RootElement;
			string text = (rootElement.TryGetProperty("room", out var value) ? (value.GetString() ?? "") : "");
			string text2 = (rootElement.TryGetProperty("table", out var value2) ? (value2.GetString() ?? "") : "");
			string text3 = (rootElement.TryGetProperty("operator", out var value3) ? (value3.GetString() ?? "") : "");
			if (text.Length == 0 || text2.Length == 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Missing room or table."
				});
			}
			if (!rootElement.TryGetProperty("index", out var value4) || !value4.TryGetInt32(out var value5) || value5 < 0)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Missing line index."
				});
			}
			OpenOrder openOrder = store.GetOpenOrder(text, text2);
			if (openOrder == null)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "No open order for this table."
				});
			}
			if (value5 >= openOrder.Items.Count)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Line not found. Refresh the order."
				});
			}
			SoldLine soldLine = openOrder.Items[value5];
			string text4 = (rootElement.TryGetProperty("product", out var value6) ? (value6.GetString() ?? "") : "");
			if (text4.Length > 0 && text4 != soldLine.Product)
			{
				return JsonResponse(new
				{
					ok = false,
					error = "Order changed on another device. Refresh and try again."
				});
			}
			bool flag = rootElement.TryGetProperty("remove", out var value7) && value7.ValueKind == JsonValueKind.True;
			int num = 0;
			if (!flag)
			{
				if (!rootElement.TryGetProperty("qty", out var value8) || !value8.TryGetInt32(out var value9) || value9 < 1)
				{
					return JsonResponse(new
					{
						ok = false,
						error = "Quantity must be 1 or more, or set remove=true."
					});
				}
				num = value9;
				if (num == soldLine.Quantity)
				{
					return JsonResponse(new
					{
						ok = true,
						unchanged = true,
						order = openOrder.OrderNumber,
						remaining = openOrder.Items.Count,
						order_total = openOrder.Items.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity)
					});
				}
			}
			string text5 = ((text3.Length > 0) ? text3 : openOrder.Operator);
			List<string> list = new List<string>();
			bool flag2 = soldLine.Course <= openOrder.FiredCourse;
			List<SoldLine> list2 = new List<SoldLine>(openOrder.Items);
			if (flag)
			{
				if (flag2)
				{
					list.AddRange(TabletPrintCancel(soldLine, text, text2, text5));
				}
				list2.RemoveAt(value5);
			}
			else
			{
				if (flag2)
				{
					if (num > soldLine.Quantity)
					{
						List<string> list3 = new List<string>();
						List<SoldLine> list4 = new List<SoldLine>(1);
						SoldLine soldLine2 = soldLine._003CClone_003E_0024();
						soldLine2.Quantity = num - soldLine.Quantity;
						list4.Add(soldLine2);
						PrintTickets(list4, openOrder.OrderNumber, 0, openOrder.OrderType, text, text2, text5, showWarnings: false, list3);
						list.AddRange(list3);
					}
					else
					{
						SoldLine soldLine3 = soldLine._003CClone_003E_0024();
						soldLine3.Quantity = soldLine.Quantity - num;
						list.AddRange(TabletPrintCancel(soldLine3, text, text2, text5));
					}
				}
				int index = value5;
				SoldLine soldLine4 = soldLine._003CClone_003E_0024();
				soldLine4.Quantity = num;
				list2[index] = soldLine4;
			}
			store.RemoveOpenOrder(text, text2);
			if (list2.Count > 0)
			{
				PosStore posStore = store;
				OpenOrder openOrder2 = openOrder._003CClone_003E_0024();
				openOrder2.Items = list2;
				posStore.AddOpenOrder(openOrder2);
			}
			if (store.Features.AuditLog)
			{
				store.LogAudit(text5, "Tablet line edit", string.Format("{0}/{1} — {2}, order #{3}", text, text2, flag ? ("removed " + soldLine.Product) : $"{soldLine.Product} qty {soldLine.Quantity} -> {num}", openOrder.OrderNumber));
			}
			UpdateQrBanner();
			return JsonResponse(new
			{
				ok = true,
				order = openOrder.OrderNumber,
				removed = flag,
				qty = ((!flag) ? num : 0),
				remaining = list2.Count,
				order_gone = (list2.Count == 0),
				order_total = list2.Sum((SoldLine l) => l.UnitPrice * (decimal)l.Quantity),
				print_warnings = list
			});
		}

		private static string HtmlResponse(string html)
		{
			int byteCount = Encoding.UTF8.GetByteCount(html);
			return $"HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {byteCount}\r\nConnection: close\r\n\r\n{html}";
		}

		private static string JsonResponse(object payload)
		{
			string text = JsonSerializer.Serialize(payload);
			int byteCount = Encoding.UTF8.GetByteCount(text);
			return $"HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: {byteCount}\r\nConnection: close\r\n\r\n{text}";
		}

		private string BuildOrderPage(string query)
		{
			string text = JsonSerializer.Serialize((from p in store.Products
				where !Is86(store, p.Name)
				group p by p.Category into g
				select new
				{
					category = g.Key,
					products = g.Select((Product p) => new
					{
						name = p.Name,
						price = p.Price
					}).ToList()
				}).ToList());
			string text2 = JsonSerializer.Serialize(store.Rooms.Select((Room r) => new
			{
				name = r.Name,
				tables = (from i in Enumerable.Range(1, r.TableCount)
					select TableName(r.Name, i)).ToList()
			}).ToList());
			string text3 = "Vectron POS";
			string text4 = JsonSerializer.Serialize(store.RegisterSettings.Currency);
			string text5 = JsonSerializer.Serialize(QueryVal("room"));
			string text6 = JsonSerializer.Serialize(QueryVal("table"));
			return "<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n<title>" + text3 + " — Order</title>\r\n<style>\r\n  body{margin:0;font-family:system-ui,sans-serif;background:#141a24;color:#eef2f8}\r\n  header{padding:16px;background:#1c2536;position:sticky;top:0;z-index:5}\r\n  h1{margin:0 0 10px;font-size:20px;color:#47d6ae}\r\n  select{padding:9px;border-radius:8px;border:1px solid #33405a;background:#222c40;color:#eef2f8;font-size:15px;width:48%;box-sizing:border-box}\r\n  .hbtns{display:flex;gap:8px;margin-top:10px}\r\n  .hbtns button,.hbtns a{padding:9px 12px;border:none;border-radius:8px;background:#2f3d57;color:#eef2f8;font-size:14px;text-decoration:none;text-align:center;cursor:pointer}\r\n  .hbtns a{background:#3a4a68}\r\n  #callok{display:none;color:#47d6ae;font-size:13px;margin-top:8px}\r\n  section{padding:10px 14px}\r\n  h2{font-size:14px;color:#8fa3c0;text-transform:uppercase;letter-spacing:.5px;margin:14px 0 6px}\r\n  .row{display:flex;align-items:center;justify-content:space-between;background:#1c2536;border-radius:10px;padding:10px 12px;margin:7px 0}\r\n  .row .nm{font-size:15px}\r\n  .row .pr{color:#47d6ae;font-weight:600}\r\n  .qty{display:flex;align-items:center;gap:8px}\r\n  .qty button{width:32px;height:32px;border:none;border-radius:8px;background:#2f3d57;color:#fff;font-size:17px}\r\n  .qty span{min-width:20px;text-align:center;font-weight:600}\r\n  footer{position:fixed;bottom:0;left:0;right:0;background:#1c2536;padding:12px 14px;display:flex;gap:10px;align-items:center}\r\n  #send{flex:1;padding:13px;border:none;border-radius:10px;background:#47d6ae;color:#10231d;font-size:16px;font-weight:700}\r\n  #total{color:#8fa3c0;font-size:15px;min-width:90px}\r\n  #done{display:none;margin:16px;padding:16px;border-radius:12px;background:#17352b;color:#7ef0c7;font-size:16px;text-align:center}\r\n</style>\r\n</head>\r\n<body>\r\n<header>\r\n  <h1>" + text3 + "</h1>\r\n  <select id=\"room\"></select>\r\n  <select id=\"table\"></select>\r\n  <div class=\"hbtns\">\r\n    <button id=\"callWaiter\">\ud83d\udece Call waiter</button>\r\n    <a id=\"trackLink\" href=\"#\" target=\"_blank\">Track my order</a>\r\n  </div>\r\n  <div id=\"callok\">The waiter is on the way.</div>\r\n</header>\r\n<div id=\"done\"></div>\r\n<div id=\"menu\"></div>\r\n<footer><div id=\"total\">0.00</div><button id=\"send\">Send order to kitchen</button></footer>\r\n<script>\r\nconst MENU = " + text + ";\r\nconst ROOMS = " + text2 + ";\r\nconst CUR = " + text4 + ";\r\nconst DEF_ROOM = " + text5 + ";\r\nconst DEF_TABLE = " + text6 + ";\r\nconst cart = {};\r\nconst roomSel = document.getElementById('room');\r\nconst tableSel = document.getElementById('table');\r\nfunction fillRooms(){\r\n  roomSel.innerHTML = ROOMS.map(r => `<option value=\"${r.name}\">${r.name}</option>`).join('');\r\n  if (DEF_ROOM && ROOMS.some(r => r.name === DEF_ROOM)) roomSel.value = DEF_ROOM;\r\n  fillTables();\r\n}\r\nfunction fillTables(){\r\n  const room = ROOMS.find(r => r.name === roomSel.value) || ROOMS[0];\r\n  const tables = room ? room.tables : [];\r\n  tableSel.innerHTML = tables.map(t => `<option value=\"${t}\">${t}</option>`).join('');\r\n  if (DEF_TABLE && tables.includes(DEF_TABLE)) tableSel.value = DEF_TABLE;\r\n  updateTrack();\r\n}\r\nroomSel.onchange = () => { fillTables(); updateTrack(); };\r\ntableSel.onchange = updateTrack;\r\nfunction updateTrack(){\r\n  const link = document.getElementById('trackLink');\r\n  link.href = `/status?room=${encodeURIComponent(roomSel.value)}&table=${encodeURIComponent(tableSel.value)}`;\r\n}\r\ndocument.getElementById('callWaiter').onclick = async () => {\r\n  await fetch(`/api/call?room=${encodeURIComponent(roomSel.value)}&table=${encodeURIComponent(tableSel.value)}`);\r\n  document.getElementById('callok').style.display = 'block';\r\n  document.getElementById('callWaiter').disabled = true;\r\n};\r\nfunction render(){\r\n  const host = document.getElementById('menu');\r\n  host.innerHTML = MENU.map(cat => `<section><h2>${cat.category}</h2>` +\r\n    cat.products.map(p => {\r\n      const c = cart[p.name] || 0;\r\n      const enc = encodeURIComponent(p.name);\r\n      return `<div class=\"row\"><div><div class=\"nm\">${p.name}</div><div class=\"pr\">${p.price.toFixed(2)} ${CUR}</div></div>\r\n      <div class=\"qty\"><button onclick=\"step('${enc}',-1)\">−</button><span id=\"q_${enc}\">${c}</span><button onclick=\"step('${enc}',1)\">+</button></div></div>`;\r\n    }).join('') + `</section>`).join('');\r\n  updateTotal();\r\n}\r\nfunction step(enc, d){\r\n  const name = decodeURIComponent(enc);\r\n  cart[name] = Math.max(0, (cart[name] || 0) + d);\r\n  if (cart[name] === 0) delete cart[name];\r\n  document.getElementById('q_' + enc).textContent = cart[name] || 0;\r\n  updateTotal();\r\n}\r\nfunction updateTotal(){\r\n  let sum = 0;\r\n  for (const cat of MENU) for (const p of cat.products) sum += (cart[p.name] || 0) * p.price;\r\n  document.getElementById('total').textContent = sum.toFixed(2);\r\n}\r\ndocument.getElementById('send').onclick = async () => {\r\n  const items = Object.entries(cart).map(([name, qty]) => ({ name, qty }));\r\n  if (!items.length) { alert('Add items first.'); return; }\r\n  const res = await fetch('/api/order', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ room: roomSel.value, table: tableSel.value, items }) });\r\n  const data = await res.json();\r\n  if (data.ok) {\r\n    for (const k in cart) delete cart[k];\r\n    render();\r\n    const done = document.getElementById('done');\r\n    done.style.display = 'block';\r\n    done.textContent = `Order #${data.order} sent to the kitchen for ${data.table} — ${Number(data.total).toFixed(2)}`;\r\n    window.scrollTo(0, 0);\r\n  } else alert(data.error || 'Order failed.');\r\n};\r\nfillRooms(); render(); updateTrack();\r\n</script>\r\n</body>\r\n</html>";
			string QueryVal(string key)
			{
				string[] array = query.Split(new char[1] { '&' }, StringSplitOptions.RemoveEmptyEntries);
				for (int i = 0; i < array.Length; i++)
				{
					string[] array2 = array[i].Split(new char[1] { '=' }, 2);
					if (array2.Length == 2 && array2[0] == key)
					{
						return Uri.UnescapeDataString(array2[1].Replace('+', ' '));
					}
				}
				return "";
			}
		}

		private void ShowKioskOrderReview(PendingKioskOrder order)
		{
			using KioskOrderReviewForm dlg = new KioskOrderReviewForm(order, store.RegisterSettings.Currency, () =>
			{
				store.PendingKioskOrders.Remove(order);
				store.PendingKioskOrders.Add(order with { Status = "Confirmed", Note = $"Confirmed by {currentOperator.Name}" });
				store.SavePendingKioskOrders();
				store.DismissGuestAlerts("Kiosk", $"#{order.OrderNumber}", "kiosk_order");

				string room = "Kiosk";
				string table = string.IsNullOrEmpty(order.Table) ? $"Kiosk #{order.OrderNumber}" : order.Table;
				OpenOrder oo = new OpenOrder(room, table, currentOperator.Name, DateTime.Now, order.Items, order.Note, order.OrderNumber, order.OrderNumber, order.OrderType, order.CustomerName, 0, Ready: false, 0, "Kiosk");
				store.AddOpenOrder(oo);

				PrintTickets(order.Items, order.OrderNumber, 0, order.OrderType, room, table, currentOperator.Name);
				if (store.Features.AuditLog)
				{
					store.LogAudit(currentOperator.Name, "Kiosk order confirmed", $"Order #{order.OrderNumber} confirmed & fired to kitchen");
				}
				UpdateQrBanner();
				MessageBox.Show(string.Format(Tr.T("Order #{0} confirmed and sent to kitchen."), order.OrderNumber), Tr.T("Kiosk order"), MessageBoxButtons.OK, MessageBoxIcon.Information);
			}, (reason) =>
			{
				store.RejectPendingKioskOrder(order.OrderNumber, $"{reason} (by {currentOperator.Name})");
				UpdateQrBanner();
			});
			dlg.ShowDialog(this);
		}

