		private void PrintQrLabels(List<(string Room, string Table, string Url)> tables)
		{
			int perPage = 4;
			int pages = (int)Math.Ceiling((double)tables.Count / (double)perPage);
			using PrintDocument printDocument = new PrintDocument();
			int page = 0;
			printDocument.DocumentName = "Table QR labels";
			printDocument.PrintPage += (object _, PrintPageEventArgs e) =>
			{
				if (e.Graphics == null)
				{
					e.HasMorePages = false;
				}
				else
				{
					Rectangle marginBounds = e.MarginBounds;
					int num = marginBounds.Width / 2;
					int num2 = marginBounds.Height / 2;
					for (int i = 0; i < perPage; i++)
					{
						int num3 = page * perPage + i;
						if (num3 >= tables.Count)
						{
							break;
						}
						(string Room, string Table, string Url) tuple = tables[num3];
						string item = tuple.Room;
						string item2 = tuple.Table;
						string item3 = tuple.Url;
						int num4 = i % 2;
						int num5 = i / 2;
						Rectangle rect = new Rectangle(marginBounds.X + num4 * num, marginBounds.Y + num5 * num2, num, num2);
						e.Graphics.DrawRectangle(Pens.Gray, rect);
						try
						{
							using Bitmap image = QrCode.ToBitmap(item3, 6);
							int num6 = Math.Min(num - 24, num2 - 90);
							e.Graphics.DrawImage(image, rect.X + (num - num6) / 2, rect.Y + 10, num6, num6);
						}
						catch
						{
						}
						using Font font = new Font("Segoe UI Semibold", 16f);
						using Font font2 = new Font("Segoe UI", 10f);
						using Font font3 = new Font("Segoe UI", 7.5f);
						e.Graphics.DrawString(item2, font, Brushes.Black, rect.X, rect.Y + num2 - 72);
						e.Graphics.DrawString(item, font2, Brushes.Gray, rect.X, rect.Y + num2 - 46);
						e.Graphics.DrawString(item3, font3, Brushes.DarkGray, new RectangleF(rect.X + 2, rect.Y + num2 - 28, num - 8, 26f));
					}
					page++;
					e.HasMorePages = page < pages;
				}
			};
			using PrintPreviewDialog printPreviewDialog = new PrintPreviewDialog
			{
				Document = printDocument,
				Width = 900,
				Height = 700
			};
			printPreviewDialog.ShowDialog();
		}

