					Button button2 = new Button
					{
						Text = Tr.T("+"),
						Location = new Point(300, 200),
						Size = new Size(40, 28),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						FlatStyle = FlatStyle.Flat
					};
					button2.FlatAppearance.BorderSize = 0;
					button2.Click += (object obj, EventArgs e) =>
					{
						if (!string.IsNullOrWhiteSpace(optName.Text))
						{
							optList.Items.Add($"{optName.Text}|{optPrice.Value}");
							optName.Text = "";
						}
					};
					Button button3 = new Button
					{
						Text = Tr.T("Save"),
						Location = new Point(20, 240),
						Size = new Size(100, 34),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat
					};
					button3.FlatAppearance.BorderSize = 0;
					button3.Click += (object obj, EventArgs e) =>
					{
						List<ModifierOption> options = optList.Items.Cast<string>().Select((string s) =>
						{
							string[] array = s.Split('|');
							return new ModifierOption(array[0], decimal.Parse(array[1]));
						}).ToList();
						store.ModifierGroups.Add(new ModifierGroup(gn.Text, options));
						store.SaveModifiers(store.ModifierGroups);
						f.DialogResult = DialogResult.OK;
					};
					f.Controls.AddRange(new Control[7]
					{
						new Label
						{
							Text = Tr.T("Group name"),
							AutoSize = true,
							Location = new Point(20, 12)
						},
						gn,
						optList,
						optName,
						optPrice,
						button2,
						button3
					});
					if (f.ShowDialog() == DialogResult.OK)
					{
						ShowModifierManager();
					}
				}
				finally
				{
					if (f != null)
					{
						((IDisposable)f).Dispose();
					}
				}
			};
			panel.Controls.Add(listView);
			panel.Controls.Add(button);
			ShowView(panel, "Modifier Groups", ShowSettings);
		}

