				button4.Font = new Font("Segoe UI Semibold", 9.5f);
				button4.FlatAppearance.BorderSize = 0;
				return button4;
			}
			void Rebuild()
			{
				lv.Items.Clear();
				foreach (Customer customer2 in store.Customers)
				{
					List<string> list = new List<string>
					{
						customer2.Name,
						customer2.Phone,
						customer2.Email,
						customer2.Points.ToString()
					};
					if (store.Features.ChargeTabs)
					{
						list.AddRange(new string[3]
						{
							customer2.Balance.ToString("C"),
							customer2.TabDue.ToString("C"),
							(customer2.CreditLimit > 0m) ? customer2.CreditLimit.ToString("C") : "—"
					});
					}
					ListViewItem listViewItem = new ListViewItem(list.ToArray());
					if (store.Features.ChargeTabs && customer2.TabDue > 0m)
					{
						listViewItem.ForeColor = Skin.Warning;
					}
					lv.Items.Add(listViewItem);
				}
			}
		}

