						ShowUpDown = true
					};
					DateTimePicker ed = new DateTimePicker
					{
						Location = new Point(170, 70),
						Size = new Size(140, 28),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						Format = DateTimePickerFormat.Time,
						ShowUpDown = true
					};
					NumericUpDown disc = new NumericUpDown
					{
						Location = new Point(20, 110),
						Size = new Size(100, 28),
						BackColor = panelLight,
						ForeColor = Skin.Text,
						Minimum = 1m,
						Maximum = 100m,
						Value = 10m
					};
					List<CheckBox> dayChecks = new List<CheckBox>();
					int num = 20;
					string[] array = new string[7] { "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday" };
					foreach (string text in array)
					{
						CheckBox item = new CheckBox
						{
							Text = text.Substring(0, 2),
							AutoSize = true,
							Location = new Point(num, 150),
							ForeColor = Skin.Text
						};
						dayChecks.Add(item);
						num += 45;
					}
					Button button2 = new Button
					{
						Text = Tr.T("Save"),
						Location = new Point(20, 190),
						Size = new Size(100, 34),
						BackColor = mint,
						ForeColor = Skin.OnAccent,
						FlatStyle = FlatStyle.Flat
					};
					button2.FlatAppearance.BorderSize = 0;
					button2.Click += (object obj, EventArgs e) =>
					{
						List<string> days = (from cb in dayChecks
							where cb.Checked
							select cb.Text switch
							{
								"Mo" => "Monday", 
								"Tu" => "Tuesday", 
								"We" => "Wednesday", 
								"Th" => "Thursday", 
								"Fr" => "Friday", 
								"Sa" => "Saturday", 
								"Su" => "Sunday", 
								_ => cb.Text, 
							}).ToList();
						store.HappyHourRules.Add(new HappyHourRule(rn.Text, sd.Value.TimeOfDay, ed.Value.TimeOfDay, disc.Value, days));
						store.SaveHappyHours(store.HappyHourRules);
						f.DialogResult = DialogResult.OK;
					};
					f.Controls.AddRange(new Control[9]
					{
						new Label
						{
							Text = Tr.T("Name"),
							AutoSize = true,
							Location = new Point(20, 12)
						},
						rn,
						new Label
						{
							Text = Tr.T("Start"),
							AutoSize = true,
							Location = new Point(20, 55)
						},
						sd,
						new Label
						{
							Text = Tr.T("End"),
							AutoSize = true,
							Location = new Point(170, 55)
						},
						ed,
						new Label
						{
							Text = Tr.T("Discount %"),
							AutoSize = true,
							Location = new Point(20, 95)
						},
						disc,
						button2
					});
					foreach (CheckBox item2 in dayChecks)
					{
						f.Controls.Add(item2);
					}
					if (f.ShowDialog() == DialogResult.OK)
					{
						ShowHappyHourManager();
					}
				}
				finally
				{
					if (f != null)
					{
						((IDisposable)f).Dispose();
					}
				}
			};
			panel.Controls.Add(listView);
			panel.Controls.Add(button);
			ShowView(panel, "Happy Hour Rules", ShowSettings);
		}

