internal static class OnScreenKeyboard
	{
		public static Func<bool> IsEnabled = () => false;

		public static void Register()
		{
			Application.AddMessageFilter(new KeyboardMessageFilter());
		}
	}

internal sealed class KeyboardMessageFilter : IMessageFilter
	{
		public bool PreFilterMessage(ref Message m)
		{
			if (m.Msg != 513 && m.Msg != 515)
			{
				return false;
			}
			if (KeyboardForm.IsOpen || !OnScreenKeyboard.IsEnabled())
			{
				return false;
			}
			if (!(Control.FromHandle(m.HWnd) is TextBox textBox))
			{
				return false;
			}
			if (textBox.IsDisposed || !textBox.Enabled || !textBox.Visible || textBox.ReadOnly)
			{
				return false;
			}
			if (textBox.FindForm() is KeyboardForm)
			{
				return false;
			}
			if (!textBox.IsHandleCreated)
			{
				return false;
			}
			int num = (int)m.LParam;
			Point pt = new Point((short)(num & 0xFFFF), (short)((num >> 16) & 0xFFFF));
			if (!textBox.ClientRectangle.Contains(pt))
			{
				return false;
			}
			KeyboardForm.ShowFor(textBox);
			return false;
		}
	}

internal sealed class KeyboardForm : Form
	{
		private readonly TextBox target;

		private readonly bool numericOnly;

		private readonly Label preview;

		private readonly Panel abcPanel = new Panel();

		private readonly Panel symPanel = new Panel();

		private readonly Panel numPanel = new Panel();

		private readonly List<(Button Button, char Character)> letterKeys = new List<(Button, char)>();

		private Button shiftButton = new Button();

		private bool shift;

		private static Color background => Skin.Background;

		private static Color mint => Skin.Accent;

		private static Color dimText => Skin.TextDim;

		private static Color darkKey => Skin.PanelPressed;

		private static Color darkKey2 => Skin.PanelPressed;

		public static bool IsOpen { get; private set; }

		public static void ShowFor(TextBox textBox)
		{
			if (IsOpen || textBox.IsDisposed)
			{
				return;
			}
			using KeyboardForm keyboardForm = new KeyboardForm(textBox);
			IsOpen = true;
			try
			{
				if (textBox.TopLevelControl is Form { IsDisposed: false } form)
				{
					keyboardForm.ShowDialog(form);
				}
				else
				{
					keyboardForm.ShowDialog();
				}
			}
			finally
			{
				IsOpen = false;
				ReleaseStaleCapture(textBox);
			}
		}

		private static void ReleaseStaleCapture(TextBox textBox)
		{
			if (textBox.IsDisposed || !textBox.IsHandleCreated)
			{
				return;
			}
			try
			{
				textBox.BeginInvoke((Action)(() =>
				{
					if (!textBox.IsDisposed && textBox.IsHandleCreated)
					{
						textBox.Capture = false;
					}
				}));
			}
			catch (InvalidOperationException)
			{
			}
		}

		private KeyboardForm(TextBox textBox)
		{
			target = textBox;
			numericOnly = IsNumericTarget(textBox);
			Text = Tr.T("Keyboard");
			StartPosition = FormStartPosition.Manual;
			FormBorderStyle = FormBorderStyle.None;
			ShowInTaskbar = false;
			KeyPreview = true;
			BackColor = background;
			ForeColor = Skin.Text;
			Font = new Font("Segoe UI", 10f);
			Size = new Size(780, 344);
			string text = (string.IsNullOrWhiteSpace(target.Name) ? "Text" : target.Name);
			text = char.ToUpperInvariant(text[0]) + text.Substring(1);
			Label label = new Label
			{
				Text = text,
				AutoSize = true,
				Location = new Point(12, 16),
				ForeColor = mint,
				Font = new Font("Segoe UI Semibold", 11f)
			};
			preview = new Label
			{
				Text = target.Text,
				Location = new Point(120, 10),
				Size = new Size(520, 32),
				BorderStyle = BorderStyle.FixedSingle,
				BackColor = Skin.InputDeep,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 12f),
				TextAlign = ContentAlignment.MiddleLeft,
				AutoEllipsis = true
			};
			Button button = new Button
			{
				Text = Tr.T("✓ Done"),
				Location = new Point(654, 10),
				Size = new Size(114, 32),
				BackColor = mint,
				ForeColor = Skin.OnAccent,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 11f)
			};
			button.FlatAppearance.BorderSize = 0;
			button.Click += (object _, EventArgs _) =>
			{
				DialogResult = DialogResult.OK;
			};
			AcceptButton = button;
			Panel[] array = new Panel[3] { abcPanel, symPanel, numPanel };
			foreach (Panel obj in array)
			{
				obj.SetBounds(0, 46, 780, 298);
				obj.BackColor = background;
			}
			BuildAbcPanel();
			BuildSymbolsPanel();
			BuildNumericPanel();
			Controls.AddRange(new Control[6] { label, preview, button, abcPanel, symPanel, numPanel });
			abcPanel.Visible = !numericOnly;
			symPanel.Visible = false;
			numPanel.Visible = numericOnly;
		}

		protected override void OnShown(EventArgs e)
		{
			base.OnShown(e);
			Rectangle workingArea = Screen.FromControl(target).WorkingArea;
			Location = new Point(workingArea.Left + (workingArea.Width - Width) / 2, workingArea.Top + workingArea.Height - Height);
		}

		protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
		{
			Keys keys = keyData & Keys.KeyCode;
			char c;
			switch (keys)
			{
			case Keys.Escape:
				Close();
				return true;
			case Keys.Return:
				DialogResult = DialogResult.OK;
				return true;
			case Keys.Back:
				Backspace();
				return true;
			case Keys.A:
			case Keys.B:
			case Keys.C:
			case Keys.D:
			case Keys.E:
			case Keys.F:
			case Keys.G:
			case Keys.H:
			case Keys.I:
			case Keys.J:
			case Keys.K:
			case Keys.L:
			case Keys.M:
			case Keys.N:
			case Keys.O:
			case Keys.P:
			case Keys.Q:
			case Keys.R:
			case Keys.S:
			case Keys.T:
			case Keys.U:
			case Keys.V:
			case Keys.W:
			case Keys.X:
			case Keys.Y:
			case Keys.Z:
				c = (char)(97 + (keys - 65));
				break;
			default:
				if (keys >= Keys.D0 && keys <= Keys.D9)
				{
					c = (char)(48 + (keys - 48));
					break;
				}
				if (keys >= Keys.NumPad0 && keys <= Keys.NumPad9)
				{
					c = (char)(48 + (keys - 96));
					break;
				}
				switch (keys)
				{
				case Keys.Space:
					c = ' ';
					break;
				case Keys.Decimal:
				case Keys.OemPeriod:
					c = '.';
					break;
				case Keys.Oemcomma:
					c = ',';
					break;
				default:
					return base.ProcessCmdKey(ref msg, keyData);
				}
				break;
			}
			if (char.IsLetter(c) && (Control.ModifierKeys.HasFlag(Keys.Shift) || Control.IsKeyLocked(Keys.Capital)))
			{
				c = char.ToUpperInvariant(c);
			}
			if (!numericOnly || char.IsDigit(c) || c == '.')
			{
				Insert(c);
			}
			return true;
		}

		private static bool IsNumericTarget(TextBox textBox)
		{
			for (Control control = textBox.Parent; control != null; control = control.Parent)
			{
				if (control is NumericUpDown)
				{
					return true;
				}
			}
			return false;
		}

		private Button MakeKey(Panel panel, string text, int col, int row, int span, Color back, int fontSize = 14)
		{
			Button button = new Button
			{
				Text = text,
				Location = new Point(8 + col * 76, 8 + row * 56),
				Size = new Size(span * 76 - 4, 52),
				BackColor = back,
				ForeColor = Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", fontSize)
			};
			button.FlatAppearance.BorderSize = 0;
			panel.Controls.Add(button);
			return button;
		}

		private void BuildAbcPanel()
		{
			AddCharRow(abcPanel, "1234567890", 0);
			AddLetterRow(abcPanel, "qwertyuiop", 1);
			AddLetterRow(abcPanel, "asdfghjkl'", 2);
			shiftButton = MakeKey(abcPanel, "⇧", 0, 3, 2, darkKey2, 16);
			shiftButton.Click += (object _, EventArgs _) =>
			{
				ToggleShift();
			};
			char[] array = "zxcvbnm".ToCharArray();
			for (int num = 0; num < array.Length; num++)
			{
				char character = array[num];
				Button button = MakeKey(abcPanel, character.ToString(), 2 + num, 3, 1, darkKey);
				letterKeys.Add((button, character));
				button.Click += (object _, EventArgs _) =>
				{
					InsertLetter(character);
				};
			}
			MakeKey(abcPanel, "⌫", 9, 3, 1, darkKey2, 16).Click += (object _, EventArgs _) =>
			{
				Backspace();
			};
			BuildFooter(abcPanel, "123", 4, () =>
			{
				abcPanel.Visible = false;
				symPanel.Visible = true;
			});
		}

		private void BuildSymbolsPanel()
		{
			AddCharRow(symPanel, "1234567890", 0);
			AddCharRow(symPanel, "@#$%&*()-_", 1);
			AddCharRow(symPanel, "=+;:\"'~`\\/", 2);
			AddCharRow(symPanel, "!?{}[]<>|", 3);
			MakeKey(symPanel, "⌫", 9, 3, 1, darkKey2, 16).Click += (object _, EventArgs _) =>
			{
				Backspace();
			};
			BuildFooter(symPanel, "ABC", 4, () =>
			{
				symPanel.Visible = false;
				abcPanel.Visible = true;
			});
		}

		private void BuildNumericPanel()
		{
			(string, string)[] array = new (string, string)[12]
			{
				("7", "7"),
				("8", "8"),
				("9", "9"),
				("4", "4"),
				("5", "5"),
				("6", "6"),
				("1", "1"),
				("2", "2"),
				("3", "3"),
				("0", "0"),
				(".", "."),
				("⌫", "<")
			};
			for (int i = 0; i < array.Length; i++)
			{
				(string, string) tuple = array[i];
				string item = tuple.Item1;
				string value = tuple.Item2;
				int num = i % 3;
				int num2 = i / 3;
				Button button = new Button
				{
					Text = item,
					Location = new Point(8 + num * 256, 8 + num2 * 56),
					Size = new Size(252, 52),
					BackColor = ((value == "<") ? darkKey2 : darkKey),
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat,
					Font = new Font("Segoe UI Semibold", (value == "<") ? 16f : 18f)
				};
				button.FlatAppearance.BorderSize = 0;
				if (value == "<")
				{
					button.Click += (object _, EventArgs _) =>
					{
						Backspace();
					};
				}
				else
				{
					button.Click += (object _, EventArgs _) =>
					{
						Insert(value[0]);
					};
				}
				numPanel.Controls.Add(button);
			}
			Button button2 = new Button
			{
				Text = Tr.T("Clear"),
				Location = new Point(8, 232),
				Size = new Size(376, 52),
				BackColor = darkKey2,
				ForeColor = Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 12f)
			};
			button2.FlatAppearance.BorderSize = 0;
			button2.Click += (object _, EventArgs _) =>
			{
				target.Clear();
				UpdatePreview();
			};
			Button button3 = new Button
			{
				Text = Tr.T("✓ Done"),
				Location = new Point(388, 232),
				Size = new Size(376, 52),
				BackColor = mint,
				ForeColor = Skin.OnAccent,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 14f)
			};
			button3.FlatAppearance.BorderSize = 0;
			button3.Click += (object _, EventArgs _) =>
			{
				DialogResult = DialogResult.OK;
			};
			numPanel.Controls.AddRange(new Control[2] { button2, button3 });
		}

		private void AddCharRow(Panel panel, string keys, int row)
		{
			for (int i = 0; i < keys.Length; i++)
			{
				char character = keys[i];
				MakeKey(panel, character.ToString(), i, row, 1, darkKey).Click += (object _, EventArgs _) =>
				{
					Insert(character);
				};
			}
		}

		private void AddLetterRow(Panel panel, string keys, int row)
		{
			for (int i = 0; i < keys.Length; i++)
			{
				char character = keys[i];
				if (char.IsLetter(character))
				{
					Button button = MakeKey(panel, character.ToString(), i, row, 1, darkKey);
					letterKeys.Add((button, character));
					button.Click += (object _, EventArgs _) =>
					{
						InsertLetter(character);
					};
				}
				else
				{
					MakeKey(panel, character.ToString(), i, row, 1, darkKey).Click += (object _, EventArgs _) =>
					{
						Insert(character);
					};
				}
			}
		}

		private void ToggleShift()
		{
			shift = !shift;
			RefreshLetters();
		}

		private void RefreshLetters()
		{
			shiftButton.BackColor = (shift ? mint : darkKey2);
			foreach (var letterKey in letterKeys)
			{
				Button item = letterKey.Button;
				char item2 = letterKey.Character;
				item.Text = (shift ? char.ToUpperInvariant(item2).ToString() : item2.ToString());
			}
		}

		private void InsertLetter(char character)
		{
			Insert(shift ? char.ToUpperInvariant(character) : character);
			if (shift)
			{
				shift = false;
				RefreshLetters();
			}
		}

		private void BuildFooter(Panel panel, string switchText, int row, Action onSwitch)
		{
			MakeKey(panel, switchText, 0, row, 1, darkKey2, 11).Click += (object _, EventArgs _) =>
			{
				onSwitch();
			};
			MakeKey(panel, ",", 1, row, 1, darkKey).Click += (object _, EventArgs _) =>
			{
				Insert(',');
			};
			MakeKey(panel, ".", 2, row, 1, darkKey).Click += (object _, EventArgs _) =>
			{
				Insert('.');
			};
			MakeKey(panel, "space", 3, row, 3, darkKey, 11).Click += (object _, EventArgs _) =>
			{
				Insert(' ');
			};
			MakeKey(panel, "Clear", 6, row, 2, darkKey2, 11).Click += (object _, EventArgs _) =>
			{
				target.Clear();
				UpdatePreview();
			};
			Button button = MakeKey(panel, "✓ Done", 8, row, 2, mint, 11);
			button.ForeColor = Skin.OnAccent;
			button.Click += (object _, EventArgs _) =>
			{
				DialogResult = DialogResult.OK;
			};
		}

		private void Insert(char character)
		{
			if (target.IsDisposed || !target.IsHandleCreated)
			{
				Close();
				return;
			}
			target.SelectedText = character.ToString();
			UpdatePreview();
		}

		private void Backspace()
		{
			if (target.IsDisposed || !target.IsHandleCreated)
			{
				Close();
				return;
			}
			if (target.SelectionLength > 0)
			{
				target.SelectedText = "";
			}
			else if (target.SelectionStart > 0)
			{
				int selectionStart = target.SelectionStart;
				target.Text = target.Text.Remove(selectionStart - 1, 1);
				target.SelectionStart = selectionStart - 1;
			}
			UpdatePreview();
		}

		private void UpdatePreview()
		{
			preview.Text = target.Text;
		}
	}

internal sealed class OperatorPickerForm : Form
	{
		private readonly List<OperatorAccount> operators;

		private readonly TextBox passwordBox = new TextBox();

		private OperatorAccount? pendingOperator;

		public event Action<OperatorAccount>? OperatorSelected;

		public OperatorPickerForm(Color background, Color panelLight, Color mint, List<OperatorAccount> operators)
		{
			this.operators = operators;
			Text = Tr.T("Choose operator");
			StartPosition = FormStartPosition.CenterParent;
			ClientSize = new Size(430, 420);
			BackColor = background;
			ForeColor = Skin.Text;
			Font = new Font("Segoe UI", 10f);
			FormBorderStyle = FormBorderStyle.FixedDialog;
			MaximizeBox = false;
			AutoScroll = true;
			AutoScrollMinSize = new Size(430, 420);
			Label label = new Label
			{
				Text = Tr.T("Who is using the register?"),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 17f),
				Location = new Point(26, 24)
			};
			FlowLayoutPanel flowLayoutPanel = new FlowLayoutPanel
			{
				Location = new Point(26, 72),
				Size = new Size(378, 200),
				FlowDirection = FlowDirection.TopDown,
				WrapContents = false,
				AutoScroll = true
			};
			foreach (OperatorAccount op in operators)
			{
				Button button = new Button
				{
					Text = op.Name,
					Size = new Size(350, 44),
					BackColor = panelLight,
					ForeColor = Skin.Text,
					FlatStyle = FlatStyle.Flat,
					TextAlign = ContentAlignment.MiddleLeft
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					SelectOperator(op);
				};
				flowLayoutPanel.Controls.Add(button);
			}
			Label label2 = new Label
			{
				Text = Tr.T("Password"),
				AutoSize = true,
				Location = new Point(26, 282),
				Visible = false
			};
			label2.Name = "pwLabel";
			passwordBox.Location = new Point(26, 308);
			passwordBox.Size = new Size(378, 30);
			passwordBox.BackColor = panelLight;
			passwordBox.ForeColor = Skin.Text;
			passwordBox.BorderStyle = BorderStyle.FixedSingle;
			passwordBox.UseSystemPasswordChar = true;
			passwordBox.Visible = false;
			passwordBox.Name = "pwBox";
			passwordBox.KeyDown += (object _, KeyEventArgs e) =>
			{
				if (e.KeyCode == Keys.Return)
				{
					ConfirmLogin();
				}
			};
			Button button2 = new Button
			{
				Text = Tr.T("Login"),
				Location = new Point(26, 350),
				Size = new Size(378, 40),
				BackColor = mint,
				ForeColor = Skin.OnAccent,
				FlatStyle = FlatStyle.Flat,
				Visible = false
			};
			button2.FlatAppearance.BorderSize = 0;
			button2.Name = "loginBtn";
			button2.Click += (object _, EventArgs _) =>
			{
				ConfirmLogin();
			};
			Controls.AddRange(new Control[5] { label, flowLayoutPanel, label2, passwordBox, button2 });
		}

		private void SelectOperator(OperatorAccount op)
		{
			if (string.IsNullOrWhiteSpace(op.Password))
			{
				OperatorSelected?.Invoke(op);
				return;
			}
			pendingOperator = op;
			Controls["pwLabel"].Visible = true;
			passwordBox.Visible = true;
			passwordBox.Text = "";
			Controls["loginBtn"].Visible = true;
			passwordBox.Focus();
		}

		private void ConfirmLogin()
		{
			if (!(pendingOperator == null))
			{
				if (pendingOperator.Password != passwordBox.Text)
				{
					MessageBox.Show(Tr.T("Incorrect password."), Tr.T("Login"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				}
				else
				{
					OperatorSelected?.Invoke(pendingOperator);
				}
			}
		}
	}

