			doneBtn.Click += (object _, EventArgs _) =>
			{
				SaveSelected();
				DialogResult = DialogResult.OK;
				Close();
			};
			ShiftBodyDown(72);
			AutoScrollMinSize = new Size(760, 662);
		}

		private Button ManagerButton(string text, int x, int y, int width, Color color)
		{
			Button button = new Button();
			button.Text = text;
			button.Location = new Point(x, y);
			button.Size = new Size(width, 38);
			button.BackColor = color;
			button.ForeColor = Skin.Text;
			button.FlatStyle = FlatStyle.Flat;
			button.Cursor = Cursors.Hand;
			button.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(button);
			return button;
		}

		private void LoadSelected()
		{
			if (selectedIndex >= 0 && selectedIndex < operators.Count && selectedIndex != this.list.SelectedIndex)
			{
				List<string> list = (from pair in permissionBoxes
					where pair.Value.Checked
					select pair.Key).ToList();
				List<OperatorAccount> list2 = operators;
				int index = selectedIndex;
				OperatorAccount operatorAccount = operators[selectedIndex]._003CClone_003E_0024();
				operatorAccount.Name = name.Text.Trim();
				operatorAccount.Permissions = list;
				operatorAccount.Password = password.Text;
				operatorAccount.Wage = wage.Value;
				list2[index] = operatorAccount;
				this.list.Items[selectedIndex] = operators[selectedIndex].Name;
			}
			if (this.list.SelectedIndex >= 0 && this.list.SelectedIndex < operators.Count)
			{
				selectedIndex = this.list.SelectedIndex;
				OperatorAccount operatorAccount2 = operators[selectedIndex];
				name.Text = operatorAccount2.Name;
				password.Text = operatorAccount2.Password;
				wage.Value = Math.Max(wage.Minimum, Math.Min(wage.Maximum, operatorAccount2.Wage));
				string[] permissionNames = PermissionNames;
				foreach (string text in permissionNames)
				{
					permissionBoxes[text].Checked = operatorAccount2.Permissions.Contains("All permissions") || operatorAccount2.Permissions.Contains(text);
				}
			}
		}

		private void NewOperator()
		{
			operators.Add(new OperatorAccount("New operator", new List<string>()));
			list.Items.Add("New operator");
			list.SelectedIndex = operators.Count - 1;
		}

		private void DeleteOperator()
		{
			if (selectedIndex >= 0 && operators.Count > 1)
			{
				operators.RemoveAt(selectedIndex);
				list.Items.RemoveAt(selectedIndex);
				list.SelectedIndex = Math.Min(selectedIndex, operators.Count - 1);
			}
		}

		private void SaveSelected()
		{
			if (selectedIndex >= 0)
			{
				List<string> list = (from pair in permissionBoxes
					where pair.Value.Checked
					select pair.Key).ToList();
				List<OperatorAccount> list2 = operators;
				int index = selectedIndex;
				OperatorAccount operatorAccount = operators[selectedIndex]._003CClone_003E_0024();
				operatorAccount.Name = name.Text.Trim();
				operatorAccount.Permissions = list;
				operatorAccount.Password = password.Text;
				operatorAccount.Wage = wage.Value;
				list2[index] = operatorAccount;
				this.list.Items[selectedIndex] = operators[selectedIndex].Name;
				save(operators);
			}
		}

		protected override void Back()
		{
			SaveSelected();
			base.Back();
		}
	}

internal sealed class FeatureCard : Panel
{
	private readonly Label titleLabel = new Label();
	private readonly Label descLabel = new Label();
	private readonly Button toggleBtn;
	private readonly Button actionBtn;
	private readonly Button actionBtn2;
	private bool hovering;
	private bool isToggled;

	public FeatureCard(string title, string description, string toggleKey = null, bool currentToggle = false, Action<bool> onToggle = null, string actionText = null, Action onAction = null, Func<bool> isActionVisible = null, string actionText2 = null, Action onAction2 = null, Func<bool> isAction2Visible = null)
	{
		Size = new Size(640, 68);
		BackColor = Skin.Panel;
		Margin = new Padding(0, 0, 0, 10);

		titleLabel.Text = title;
		titleLabel.AutoSize = true;
		titleLabel.Font = new Font("Segoe UI Semibold", 11f);
		titleLabel.ForeColor = Skin.Text;
		titleLabel.Location = new Point(16, 12);
		Controls.Add(titleLabel);

		descLabel.Text = description;
		descLabel.AutoSize = true;
		descLabel.Font = new Font("Segoe UI", 9f);
		descLabel.ForeColor = Skin.TextDim;
		descLabel.Location = new Point(16, 36);
		Controls.Add(descLabel);

		if (actionText != null && onAction != null)
		{
			actionBtn = new Button
			{
				Text = actionText,
				Size = new Size(130, 34),
				BackColor = Skin.PanelLight,
				ForeColor = Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 9.5f),
				Cursor = Cursors.Hand
			};
			actionBtn.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(actionBtn);
			actionBtn.Click += (s, e) => onAction();
			if (isActionVisible != null)
			{
				actionBtn.Visible = isActionVisible();
			}
			Controls.Add(actionBtn);
		}

		if (actionText2 != null && onAction2 != null)
		{
			actionBtn2 = new Button
			{
				Text = actionText2,
				Size = new Size(130, 34),
				BackColor = Skin.PanelLight,
				ForeColor = Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 9.5f),
				Cursor = Cursors.Hand
			};
			actionBtn2.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(actionBtn2);
			actionBtn2.Click += (s, e) => onAction2();
			if (isAction2Visible != null)
			{
				actionBtn2.Visible = isAction2Visible();
			}
			Controls.Add(actionBtn2);
		}

		if (toggleKey != null && onToggle != null)
		{
			toggleBtn = new Button
			{
				Text = currentToggle ? Tr.T("ON") : Tr.T("OFF"),
				Size = new Size(64, 34),
				BackColor = currentToggle ? Skin.Accent : Skin.PanelLight,
				ForeColor = currentToggle ? Skin.OnAccent : Skin.TextDim,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 10f),
				Cursor = Cursors.Hand,
			};
			isToggled = currentToggle;
			toggleBtn.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(toggleBtn);
			toggleBtn.Click += (s, e) =>
			{
				isToggled = !isToggled;
				toggleBtn.Text = isToggled ? Tr.T("ON") : Tr.T("OFF");
				Skin.SetFlatBase(toggleBtn, isToggled ? Skin.Accent : Skin.PanelLight);
				toggleBtn.ForeColor = isToggled ? Skin.OnAccent : Skin.TextDim;
				onToggle(isToggled);
				if (actionBtn != null && isActionVisible != null)
				{
					actionBtn.Visible = isActionVisible();
				}
				if (actionBtn2 != null && isAction2Visible != null)
				{
					actionBtn2.Visible = isAction2Visible();
				}
				LayoutRightButtons();
			};
			Controls.Add(toggleBtn);
		}

		LayoutRightButtons();
		Resize += (s, e) => LayoutRightButtons();

		Paint += (s, e) =>
		{
			using Pen pen = new Pen(hovering ? Skin.Accent : Skin.Border, 1f);
			e.Graphics.DrawRectangle(pen, 0, 0, Width - 1, Height - 1);
		};
		MouseEnter += (s, e) => { hovering = true; Invalidate(); };
		MouseLeave += (s, e) => { hovering = false; Invalidate(); };
	}

	private void LayoutRightButtons()
	{
		int curR = Width - 16;
		if (toggleBtn != null)
		{
			curR -= toggleBtn.Width;
			toggleBtn.Location = new Point(curR, 17);
			curR -= 8;
		}
		if (actionBtn != null && actionBtn.Visible)
		{
			curR -= actionBtn.Width;
			actionBtn.Location = new Point(curR, 17);
			curR -= 8;
		}
		if (actionBtn2 != null && actionBtn2.Visible)
		{
			curR -= actionBtn2.Width;
			actionBtn2.Location = new Point(curR, 17);
			curR -= 8;
		}
		int availTextWidth = Math.Max(200, curR - 16 - 8);
		descLabel.AutoSize = false;
		descLabel.Size = new Size(availTextWidth, 24);
		descLabel.AutoEllipsis = true;
		titleLabel.MaximumSize = new Size(availTextWidth, 24);
		titleLabel.AutoEllipsis = true;
	}
}

