	private static void ApplyNavPillRegion(Control c, int radius)
	{
		Region region = c.Region;
		c.Region = new Region(Skin.RoundRect(new Rectangle(0, 0, c.Width, c.Height), radius));
		region?.Dispose();
	}

	private void BuildNavRail()
	{
		navRail.Controls.Clear();
		navPills.Clear();

		int curY = 10;

		void AddGroup(string groupTitle, (string key, string label)[] items)
		{
			Label header = new Label
			{
				Text = groupTitle.ToUpperInvariant(),
				Font = new Font("Segoe UI Bold", 8.5f),
				ForeColor = Skin.TextDim,
				Location = new Point(16, curY),
				Size = new Size(196, 20),
				TextAlign = ContentAlignment.BottomLeft
			};
			navRail.Controls.Add(header);
			curY += 24;

			foreach (var (key, label) in items)
			{
				Button pill = new Button
				{
					Text = label,
					Tag = key,
					Size = new Size(200, 38),
					Location = new Point(12, curY),
					BackColor = Skin.SidebarItem,
					ForeColor = Skin.TextMuted,
					FlatStyle = FlatStyle.Flat,
					TextAlign = ContentAlignment.MiddleLeft,
					Font = new Font("Segoe UI Semibold", 9.5f),
					Cursor = Cursors.Hand,
					Padding = new Padding(12, 0, 0, 0)
				};
				pill.FlatAppearance.BorderSize = 0;
				Skin.FlatStates(pill);
				ApplyNavPillRegion(pill, 10);
				pill.Click += (s, e) => ShowPage(key);
				navRail.Controls.Add(pill);
				navPills[key] = pill;
				curY += 42;
			}
			curY += 10;
		}

		AddGroup(Tr.T("Setup"), new[]
		{
			("profiles", Tr.T("Business Profiles")),
			("appearance", Tr.T("Appearance")),
			("system", Tr.T("System & General")),
			("devices", Tr.T("Devices & Hardware")),
			("tax", Tr.T("Tax & Currency"))
		});

		AddGroup(Tr.T("Service"), new[]
		{
			("ordering", Tr.T("Ordering & Rooms")),
			("kitchen", Tr.T("Kitchen & Kiosk")),
			("receipts", Tr.T("Receipts & Display"))
		});

		AddGroup(Tr.T("Team & Stock"), new[]
		{
			("staff", Tr.T("Staff & Access")),
			("inventory", Tr.T("Inventory & Stock")),
			("customers", Tr.T("Customers & CRM"))
		});

		AddGroup(Tr.T("Insight"), new[]
		{
			("reports", Tr.T("Reports & Analytics")),
			("operations", Tr.T("Operations & Cash"))
		});

		Button exitBtn = new Button
		{
			Text = Tr.T("Exit app"),
			Size = new Size(200, 36),
			Location = new Point(12, curY + 6),
			BackColor = Skin.DangerStrong,
			ForeColor = Skin.OnFill,
			FlatStyle = FlatStyle.Flat,
			Font = new Font("Segoe UI Semibold", 9.5f),
			Cursor = Cursors.Hand
		};
		exitBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(exitBtn);
		ApplyNavPillRegion(exitBtn, 10);
		exitBtn.Click += (s, e) => Application.Exit();
		navRail.Controls.Add(exitBtn);
	}

	public void GoBack()
	{
		if (pageHistory.Count > 0)
		{
			string prev = pageHistory.Pop();
			ShowPage(prev, recordHistory: false);
		}
		else
		{
			if (_onDone != null)
			{
				_onDone();
			}
			else
			{
				DialogResult = DialogResult.OK;
				Close();
			}
		}
	}

	public void ShowPage(string key, bool recordHistory = true)
	{
		if (recordHistory && !string.IsNullOrEmpty(currentCategory) && currentCategory != key)
		{
			pageHistory.Push(currentCategory);
		}
		currentCategory = key;

		foreach (var kv in navPills)
		{
			bool active = kv.Key == key;
			Skin.SetFlatBase(kv.Value, active ? Skin.Accent : Skin.SidebarItem);
			kv.Value.ForeColor = active ? Skin.OnAccent : Skin.TextMuted;
		}

		contentPanel.SuspendLayout();
		contentPanel.Controls.Clear();

		switch (key)
		{
			case "profiles":
				PopulateProfiles();
				break;
			case "appearance":
				PopulateAppearance();
				break;
			case "system":
				PopulateSystem();
				break;
			case "devices":
				PopulateDevices();
				break;
			case "tax":
				PopulateTax();
				break;
			case "ordering":
				PopulateOrdering();
				break;
			case "kitchen":
				PopulateKitchen();
				break;
			case "receipts":
				PopulateReceipts();
				break;
			case "staff":
				PopulateStaff();
				break;
			case "inventory":
				PopulateInventory();
				break;
			case "customers":
				PopulateCustomers();
				break;
			case "reports":
				PopulateReports();
				break;
			case "operations":
				PopulateOperations();
				break;
		}

		contentPanel.ResumeLayout(true);
	}

	private void SetPageHeader(string title, string subtitle)
	{
		pageTitleLabel.Text = title;
		pageSubtitleLabel.Text = subtitle;
		breadcrumbLabel.Text = "Settings / " + title;
	}

	private void AddToggleCard(string title, string desc, string featurePropName, Action onAction = null, string actionText = null, Func<bool> isActionVisible = null, Action onAction2 = null, string actionText2 = null, Func<bool> isAction2Visible = null)
	{
		var prop = typeof(FeatureSettings).GetProperty(featurePropName);
		bool curVal = prop != null && (bool)prop.GetValue(features);

		FeatureCard card = new FeatureCard(
			title, desc,
			toggleKey: featurePropName,
			currentToggle: curVal,
			onToggle: (v) =>
			{
				if (prop != null)
				{
					prop.SetValue(features, v);
					features.ActiveProfile = BusinessProfiles.Custom;
					features.CustomProfileJson = JsonSerializer.Serialize(features, PosStore.JsonOptions);
					saveFeatures(features);
				}
			},
			actionText: actionText,
			onAction: onAction,
			isActionVisible: isActionVisible,
			actionText2: actionText2,
			onAction2: onAction2,
			isAction2Visible: isAction2Visible
		);
		contentPanel.Controls.Add(card);
	}

	private void AddActionCard(string title, string desc, string actionText, Action onAction, string actionText2 = null, Action onAction2 = null)
	{
		FeatureCard card = new FeatureCard(
			title, desc,
			actionText: actionText,
			onAction: onAction,
			actionText2: actionText2,
			onAction2: onAction2
		);
		contentPanel.Controls.Add(card);
	}

	private void PopulateProfiles()
	{
		SetPageHeader(Tr.T("Business Profiles"), Tr.T("Select a preconfigured store model or customize your setup"));

		bool isCustomActive = string.Equals(features.ActiveProfile, BusinessProfiles.Custom, StringComparison.OrdinalIgnoreCase);
		bool hasSavedCustom = !string.IsNullOrEmpty(features.CustomProfileJson);

		// 1. Customized Setup Safeguard Card
		Panel customCard = new Panel
		{
			Size = new Size(640, 116),
			BackColor = Skin.Panel,
			Margin = new Padding(0, 0, 0, 14)
		};

		Label starLabel = new Label
		{
			Text = "★",
			Font = new Font("Segoe UI", 16f, FontStyle.Bold),
			ForeColor = Skin.Accent,
			Location = new Point(14, 12),
			AutoSize = true
		};
		customCard.Controls.Add(starLabel);

		Label customTitle = new Label
		{
			Text = Tr.T("My Customized Setup"),
			Font = new Font("Segoe UI Semibold", 12f),
			ForeColor = Skin.Text,
			Location = new Point(42, 14),
			AutoSize = true
		};
		customCard.Controls.Add(customTitle);

		if (isCustomActive)
		{
			Label activeBadge = new Label
			{
				Text = Tr.T("ACTIVE"),
				Font = new Font("Segoe UI Bold", 8f),
				BackColor = Skin.Accent,
				ForeColor = Skin.OnAccent,
				TextAlign = ContentAlignment.MiddleCenter,
				Size = new Size(64, 22),
				Location = new Point(customTitle.Right + 12, 15)
			};
			customCard.Controls.Add(activeBadge);
		}

		Label customDesc = new Label
		{
			Text = Tr.T("Your personalized feature toggles and custom setup. Any modification in settings is remembered here."),
			Font = new Font("Segoe UI", 9f),
			ForeColor = Skin.TextDim,
			Location = new Point(16, 42),
			Size = new Size(430, 36)
		};
		customCard.Controls.Add(customDesc);

		Label customStatus = new Label
		{
			Text = isCustomActive 
				? Tr.T("✔ Active custom profile in use") 
				: (hasSavedCustom ? Tr.T("💾 Saved custom setup available to restore") : Tr.T("No custom modifications saved yet")),
			Font = new Font("Segoe UI Semibold", 8.5f),
			ForeColor = isCustomActive ? Skin.Accent : Skin.TextMuted,
			Location = new Point(16, 84),
			AutoSize = true
		};
		customCard.Controls.Add(customStatus);

		Button restoreBtn = new Button
		{
			Text = Tr.T("Restore Setup"),
			Size = new Size(130, 34),
			Location = new Point(494, 20),
			BackColor = hasSavedCustom ? Skin.Accent : Skin.PanelLight,
			ForeColor = hasSavedCustom ? Skin.OnAccent : Skin.TextMuted,
			FlatStyle = FlatStyle.Flat,
			Font = new Font("Segoe UI Semibold", 9.5f),
			Cursor = hasSavedCustom ? Cursors.Hand : Cursors.Default,
			Enabled = hasSavedCustom
		};
		restoreBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(restoreBtn);
		restoreBtn.Click += (s, e) =>
		{
			if (string.IsNullOrEmpty(features.CustomProfileJson)) return;
			try
			{
				var saved = JsonSerializer.Deserialize<FeatureSettings>(features.CustomProfileJson, PosStore.JsonOptions);
				if (saved != null)
				{
					PosStore.CopyFeatures(saved, features);
					features.ActiveProfile = BusinessProfiles.Custom;
					saveFeatures(features);
					PopulateProfiles();
					MessageBox.Show(Tr.T("Your customized setup has been restored successfully."), Tr.T("Customized Setup"), MessageBoxButtons.OK, MessageBoxIcon.Information);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show(ex.Message, Tr.T("Error"), MessageBoxButtons.OK, MessageBoxIcon.Error);
			}
		};
		customCard.Controls.Add(restoreBtn);

		Button saveCustomBtn = new Button
		{
			Text = Tr.T("Save Current"),
			Size = new Size(130, 34),
			Location = new Point(494, 62),
			BackColor = Skin.PanelLight,
			ForeColor = Skin.Text,
			FlatStyle = FlatStyle.Flat,
			Font = new Font("Segoe UI Semibold", 9f),
			Cursor = Cursors.Hand
		};
		saveCustomBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(saveCustomBtn);
		saveCustomBtn.Click += (s, e) =>
		{
			features.ActiveProfile = BusinessProfiles.Custom;
			features.CustomProfileJson = JsonSerializer.Serialize(features, PosStore.JsonOptions);
			saveFeatures(features);
			PopulateProfiles();
			MessageBox.Show(Tr.T("Current configuration has been saved as your custom setup."), Tr.T("Customized Setup"), MessageBoxButtons.OK, MessageBoxIcon.Information);
		};
		customCard.Controls.Add(saveCustomBtn);

		contentPanel.Controls.Add(customCard);

		Label modelsHeader = new Label
		{
			Text = Tr.T("PRECONFIGURED STORE MODELS"),
			Font = new Font("Segoe UI Bold", 9f),
			ForeColor = Skin.TextDim,
			Margin = new Padding(0, 10, 0, 8),
			AutoSize = true
		};
		contentPanel.Controls.Add(modelsHeader);

		void AddProfileCard(string key, string icon, string title, string description, string featuresList, Action applyAction)
		{
			bool isActive = string.Equals(features.ActiveProfile, key, StringComparison.OrdinalIgnoreCase);

			Panel card = new Panel
			{
				Size = new Size(640, 108),
				BackColor = Skin.Panel,
				Margin = new Padding(0, 0, 0, 10)
			};

			Label iconLbl = new Label
			{
				Text = icon,
				Font = new Font("Segoe UI Emoji", 14f),
				Location = new Point(14, 12),
				Size = new Size(30, 30),
				TextAlign = ContentAlignment.MiddleCenter
			};
			card.Controls.Add(iconLbl);

			Label titleLbl = new Label
			{
				Text = title,
				Font = new Font("Segoe UI Semibold", 11.5f),
				ForeColor = Skin.Text,
				Location = new Point(48, 14),
				AutoSize = true
			};
			card.Controls.Add(titleLbl);

			if (isActive)
			{
				Label badge = new Label
				{
					Text = Tr.T("ACTIVE"),
					Font = new Font("Segoe UI Bold", 8f),
					BackColor = Skin.Accent,
					ForeColor = Skin.OnAccent,
					TextAlign = ContentAlignment.MiddleCenter,
					Size = new Size(64, 22),
					Location = new Point(titleLbl.Right + 10, 14)
				};
				card.Controls.Add(badge);
			}

			Label descLbl = new Label
			{
				Text = description,
				Font = new Font("Segoe UI", 9f),
				ForeColor = Skin.TextDim,
				Location = new Point(16, 42),
				Size = new Size(460, 32)
			};
			card.Controls.Add(descLbl);

			Label featLbl = new Label
			{
				Text = featuresList,
				Font = new Font("Segoe UI Semibold", 8f),
				ForeColor = Skin.Accent,
				Location = new Point(16, 78),
				Size = new Size(460, 20),
				AutoEllipsis = true
			};
			card.Controls.Add(featLbl);

			Button applyBtn = new Button
			{
				Text = isActive ? Tr.T("Active") : Tr.T("Apply Setup"),
				Size = new Size(116, 36),
				Location = new Point(508, 36),
				BackColor = isActive ? Skin.PanelLight : Skin.Accent,
				ForeColor = isActive ? Skin.TextDim : Skin.OnAccent,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 9.5f),
				Cursor = Cursors.Hand
			};
			applyBtn.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(applyBtn);
			applyBtn.Click += (s, e) =>
			{
				string confirmText = string.Format(Tr.T("Apply {0} setup?\n\nThis will configure all feature switches for {0}.\n\nYour customized configuration is safely backed up and can be restored at any time."), title);
				if (MessageBox.Show(confirmText, Tr.T("Business Profiles"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
				{
					if (features.ActiveProfile == BusinessProfiles.Custom || string.IsNullOrEmpty(features.CustomProfileJson))
					{
						features.CustomProfileJson = JsonSerializer.Serialize(features, PosStore.JsonOptions);
					}
					applyAction();
					features.ActiveProfile = key;
					saveFeatures(features);
					PopulateProfiles();
					MessageBox.Show(string.Format(Tr.T("{0} setup applied successfully."), title), Tr.T("Business Profiles"), MessageBoxButtons.OK, MessageBoxIcon.Information);
				}
			};
			card.Controls.Add(applyBtn);

			contentPanel.Controls.Add(card);
		}

		AddProfileCard(
			BusinessProfiles.Supermarket,
			"🛒",
			Tr.T("Supermarket & Grocery"),
			Tr.T("High-speed retail for grocery stores, mini-markets, and convenience shops."),
			Tr.T("✔ Barcode scan  ✔ Quick sale  ✔ Scales (kg/g)  ✔ Stock alerts  ✖ Tables hidden"),
			() => BusinessProfiles.ApplySupermarket(features)
		);

		AddProfileCard(
			BusinessProfiles.Boutique,
			"👗",
			Tr.T("Boutique & Fashion Retail"),
			Tr.T("Apparel, footwear, cosmetics, and specialty retail stores."),
			Tr.T("✔ Size/color variants  ✔ Barcode labels  ✔ Customer loyalty  ✔ Refunds  ✖ Tables hidden"),
			() => BusinessProfiles.ApplyBoutique(features)
		);

		AddProfileCard(
			BusinessProfiles.Cafe,
			"☕",
			Tr.T("Café & Bakery"),
			Tr.T("Coffee shops, bakeries, juice bars, and quick counter service."),
			Tr.T("✔ Quick sale  ✔ Drink modifiers  ✔ Combo deals  ✔ Barista screen  ✔ Cash rounding"),
			() => BusinessProfiles.ApplyCafe(features)
		);

		AddProfileCard(
			BusinessProfiles.Restaurant,
			"🍽️",
			Tr.T("Restaurant & Dine-In"),
			Tr.T("Full service dining, bistros, lounges, and fine dining establishments."),
			Tr.T("✔ Floor plan tables  ✔ Waiter tablet sync  ✔ Courses  ✔ Split bill  ✔ KDS kitchen"),
			() => BusinessProfiles.ApplyRestaurant(features)
		);

		AddProfileCard(
			BusinessProfiles.FastFood,
			"🍕",
			Tr.T("Pizzeria & Fast Food"),
			Tr.T("Counter service takeaway, pizza shops, burger joints, and delivery."),
			Tr.T("✔ Quick counter checkout  ✔ Delivery orders  ✔ Pizza modifiers  ✔ KDS kitchen  ✔ Combos"),
			() => BusinessProfiles.ApplyFastFood(features)
		);

		AddProfileCard(
			BusinessProfiles.Pharmacy,
			"💊",
			Tr.T("Pharmacy & Health Care"),
			Tr.T("Pharmacies, health stores, drugstores, and medical supply retail."),
			Tr.T("✔ Fast barcode scan  ✔ Patient/client notes  ✔ Batch stock alerts  ✔ Price checker"),
			() => BusinessProfiles.ApplyPharmacy(features)
		);
	}

	private void PopulateAppearance()
	{
		SetPageHeader(Tr.T("Appearance"), Tr.T("Theme, graphics quality, animations & font size"));

		// Theme card
		Panel themeCard = new Panel { Size = new Size(640, 72), BackColor = Skin.Panel, Margin = new Padding(0, 0, 0, 10) };
		themeCard.Controls.Add(new Label { Text = Tr.T("Color Theme"), Font = new Font("Segoe UI Semibold", 11f), ForeColor = Skin.Text, Location = new Point(16, 12), AutoSize = true });
		themeCard.Controls.Add(new Label { Text = Tr.T("Switch between Dark and Light palette (contrast checked)"), Font = new Font("Segoe UI", 9f), ForeColor = Skin.TextDim, Location = new Point(16, 36), Size = new Size(410, 24), AutoEllipsis = true });

		Button darkBtn = new Button { Text = Tr.T("Dark"), Size = new Size(84, 34), Location = new Point(448, 18), BackColor = Skin.PanelLight, ForeColor = Skin.Text, FlatStyle = FlatStyle.Flat, Font = new Font("Segoe UI Semibold", 9.5f), Cursor = Cursors.Hand };
		darkBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(darkBtn);
		Button lightBtn = new Button { Text = Tr.T("Light"), Size = new Size(84, 34), Location = new Point(540, 18), BackColor = Skin.PanelLight, ForeColor = Skin.Text, FlatStyle = FlatStyle.Flat, Font = new Font("Segoe UI Semibold", 9.5f), Cursor = Cursors.Hand };
		lightBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(lightBtn);

		void RefreshTheme()
		{
			bool isDark = (features.Theme ?? "dark") == "dark";
			Skin.SetFlatBase(darkBtn, isDark ? Skin.Accent : Skin.PanelLight);
			darkBtn.ForeColor = isDark ? Skin.OnAccent : Skin.Text;
			Skin.SetFlatBase(lightBtn, !isDark ? Skin.Accent : Skin.PanelLight);
			lightBtn.ForeColor = !isDark ? Skin.OnAccent : Skin.Text;
		}

		void SetPosTheme(string theme)
		{
			if (string.Equals(features.Theme, theme, StringComparison.OrdinalIgnoreCase)) return;
			features.Theme = theme;
			saveFeatures(features);
			Skin.Apply(features);
			RefreshTheme();
			if (MessageBox.Show(Tr.T("Theme changed. Vectron POS will now restart to apply the new theme."), Tr.T("Theme"), MessageBoxButtons.OK, MessageBoxIcon.Information) == DialogResult.OK)
			{
				Program.SafeRestart();
			}
		}

		darkBtn.Click += (s, e) => { SetPosTheme("dark"); };
		lightBtn.Click += (s, e) => { SetPosTheme("light"); };
		RefreshTheme();
		themeCard.Controls.Add(darkBtn);
		themeCard.Controls.Add(lightBtn);
		contentPanel.Controls.Add(themeCard);

		// Graphics Quality card
		Panel gqCard = new Panel { Size = new Size(640, 96), BackColor = Skin.Panel, Margin = new Padding(0, 0, 0, 10) };
		gqCard.Controls.Add(new Label { Text = Tr.T("Graphics Quality"), Font = new Font("Segoe UI Semibold", 11f), ForeColor = Skin.Text, Location = new Point(16, 12), AutoSize = true });
		gqCard.Controls.Add(new Label { Text = Tr.T("Auto machine detection, High (with animations) or Lite (flat 0-timer, Win7 safe)"), Font = new Font("Segoe UI", 9f), ForeColor = Skin.TextDim, Location = new Point(16, 36), Size = new Size(355, 24), AutoEllipsis = true });

		Label gqResolved = new Label { Text = string.Format(Tr.T("Resolved: {0} ({1})"), Skin.Quality, Skin.QualityReason), Font = new Font("Segoe UI Semibold", 9f), ForeColor = Skin.Accent, Location = new Point(16, 62), AutoSize = true };
		gqCard.Controls.Add(gqResolved);

		Button autoBtn = new Button { Text = Tr.T("Auto"), Size = new Size(74, 34), Location = new Point(386, 18), BackColor = Skin.PanelLight, ForeColor = Skin.Text, FlatStyle = FlatStyle.Flat, Font = new Font("Segoe UI Semibold", 9.5f), Cursor = Cursors.Hand };
		autoBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(autoBtn);
		Button highBtn = new Button { Text = Tr.T("High"), Size = new Size(74, 34), Location = new Point(468, 18), BackColor = Skin.PanelLight, ForeColor = Skin.Text, FlatStyle = FlatStyle.Flat, Font = new Font("Segoe UI Semibold", 9.5f), Cursor = Cursors.Hand };
		highBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(highBtn);
		Button liteBtn = new Button { Text = Tr.T("Lite"), Size = new Size(74, 34), Location = new Point(550, 18), BackColor = Skin.PanelLight, ForeColor = Skin.Text, FlatStyle = FlatStyle.Flat, Font = new Font("Segoe UI Semibold", 9.5f), Cursor = Cursors.Hand };
		liteBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(liteBtn);

		void RefreshGq()
		{
			string gq = (features.GraphicsQuality ?? "auto").ToLowerInvariant();
			Skin.SetFlatBase(autoBtn, gq == "auto" ? Skin.Accent : Skin.PanelLight);
			autoBtn.ForeColor = gq == "auto" ? Skin.OnAccent : Skin.Text;
			Skin.SetFlatBase(highBtn, gq == "high" ? Skin.Accent : Skin.PanelLight);
			highBtn.ForeColor = gq == "high" ? Skin.OnAccent : Skin.Text;
			Skin.SetFlatBase(liteBtn, gq == "lite" ? Skin.Accent : Skin.PanelLight);
			liteBtn.ForeColor = gq == "lite" ? Skin.OnAccent : Skin.Text;
			gqResolved.Text = string.Format(Tr.T("Resolved: {0} ({1})"), Skin.Quality, Skin.QualityReason);
		}

		autoBtn.Click += (s, e) => { features.GraphicsQuality = "auto"; saveFeatures(features); RefreshGq(); };
		highBtn.Click += (s, e) => { features.GraphicsQuality = "high"; saveFeatures(features); RefreshGq(); };
		liteBtn.Click += (s, e) => { features.GraphicsQuality = "lite"; saveFeatures(features); RefreshGq(); };
		RefreshGq();
		gqCard.Controls.Add(autoBtn);
		gqCard.Controls.Add(highBtn);
		gqCard.Controls.Add(liteBtn);
		contentPanel.Controls.Add(gqCard);

		// Language card
		Panel langCard = new Panel { Size = new Size(640, 72), BackColor = Skin.Panel, Margin = new Padding(0, 0, 0, 10) };
		langCard.Controls.Add(new Label { Text = Tr.T("Interface Language"), Font = new Font("Segoe UI Semibold", 11f), ForeColor = Skin.Text, Location = new Point(16, 12), AutoSize = true });
		langCard.Controls.Add(new Label { Text = Tr.T("Language / Langue / اللغة"), Font = new Font("Segoe UI", 9f), ForeColor = Skin.TextDim, Location = new Point(16, 36), Size = new Size(300, 24), AutoEllipsis = true });

		int lx = 330;
		string[] langs = { "en", "fr", "ar" };
		string[] langNames = { "English", "Français", "العربية" };
		for (int i = 0; i < langs.Length; i++)
		{
			string code = langs[i];
			Button lBtn = new Button
			{
				Text = langNames[i],
				Size = new Size(94, 34),
				Location = new Point(lx, 18),
				BackColor = (code == Tr.Lang) ? Skin.Accent : Skin.PanelLight,
				ForeColor = (code == Tr.Lang) ? Skin.OnAccent : Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Font = new Font("Segoe UI Semibold", 9.5f),
				Cursor = Cursors.Hand
			};
			lBtn.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(lBtn);
			lBtn.Click += (s, e) => SetLanguage(code);
			langCard.Controls.Add(lBtn);
			lx += 102;
		}
		contentPanel.Controls.Add(langCard);

		// Virtual touch keyboard
		AddToggleCard(Tr.T("On-Screen Touch Keyboard"), Tr.T("Show virtual keyboard on touch inputs and editable text fields"), "OnScreenKeyboard");
	}

	private void SetLanguage(string code)
	{
		if (code != Tr.Lang)
		{
			features.Language = code;
			saveFeatures(features);
			if (MessageBox.Show(Tr.T("Language changed. Vectron POS will now restart."), Tr.T("Language"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk) == DialogResult.OK)
			{
				Program.SafeRestart();
			}
		}
	}

