internal sealed class KitchenDisplayForm : Form
	{
		private readonly PosStore store;

		private readonly Color panelLight;

		private readonly Color mint;

		private readonly FlowLayoutPanel tickets = new FlowLayoutPanel
		{
			Dock = DockStyle.Fill,
			AutoScroll = true,
			FlowDirection = FlowDirection.TopDown,
			WrapContents = false,
			Padding = new Padding(6)
		};

		private readonly Timer tick = new Timer
		{
			Interval = 1000
		};

		private readonly List<(OpenOrder Order, Label Timer)> cards = new List<(OpenOrder, Label)>();

		private bool stopped;

		private bool wasAttached;

		private readonly HashSet<(int Order, long Created)> alarmed = new HashSet<(int, long)>();

		private bool flashPhase;

		public KitchenDisplayForm(Color background, Color panelLight, Color mint, PosStore store)
		{
			this.store = store;
			this.panelLight = panelLight;
			this.mint = mint;
			BackColor = background;
			ForeColor = Skin.Text;
			Controls.Add(tickets);
			Render();
			store.DataChanged += OnStoreChanged;
			tick.Tick += (object _, EventArgs _) =>
			{
				OnTick();
			};
			tick.Start();
			HandleDestroyed += (object _, EventArgs _) =>
			{
				Stop();
			};
		}

		private void Stop()
		{
			if (!stopped)
			{
				stopped = true;
				tick.Stop();
				tick.Dispose();
				store.DataChanged -= OnStoreChanged;
			}
		}

		private bool CheckAttached()
		{
			if (stopped || IsDisposed)
			{
				return false;
			}
			if (Parent != null)
			{
				wasAttached = true;
				return true;
			}
			if (wasAttached)
			{
				Stop();
				return false;
			}
			return false;
		}

		private void OnStoreChanged()
		{
			if (!CheckAttached() || !IsHandleCreated)
			{
				return;
			}
			if (InvokeRequired)
			{
				try
				{
					BeginInvoke(new Action(Render));
					return;
				}
				catch (InvalidOperationException)
				{
					Stop();
					return;
				}
			}
			Render();
		}

		private void OnTick()
		{
			if (!CheckAttached())
			{
				return;
			}
			flashPhase = !flashPhase;
			foreach (var (order, timer) in cards)
			{
				UpdateTimer(order, timer);
			}
			if (!store.Features.KdsLateAlarm)
			{
				return;
			}
			foreach (var card in cards)
			{
				OpenOrder item = card.Order;
				if (!item.Ready && (DateTime.Now - item.Created).TotalMinutes >= (double)store.Features.KdsPrepMinutes && alarmed.Add((item.OrderNumber, item.Created.Ticks)))
				{
					try
					{
						Console.Beep(950, 350);
					}
					catch
					{
					}
				}
			}
			HashSet<(int OrderNumber, long Ticks)> live = store.OpenOrders.Select((OpenOrder o) => (OrderNumber: o.OrderNumber, Ticks: o.Created.Ticks)).ToHashSet();
			foreach (var item2 in alarmed.Where(((int Order, long Created) k) => !live.Contains(k)).ToList())
			{
				alarmed.Remove(item2);
			}
		}

		private void UpdateTimer(OpenOrder order, Label timer)
		{
			TimeSpan timeSpan = DateTime.Now - order.Created;
			timer.Text = $"{(int)timeSpan.TotalMinutes:00}:{timeSpan.Seconds:00}";
			bool flag = store.Features.KdsLateAlarm && !order.Ready && timeSpan.TotalMinutes >= (double)store.Features.KdsPrepMinutes;
			Label label = timer;
			Color foreColor;
			if (order.Ready)
			{
				foreColor = Skin.TextFaded;
			}
			else if (flag)
			{
				foreColor = (flashPhase ? Skin.DangerText : Skin.Warning);
			}
			else if (timeSpan.TotalMinutes < 10.0)
			{
				foreColor = Skin.SuccessText;
			}
			else
			{
				foreColor = ((timeSpan.TotalMinutes < 20.0) ? Skin.Warning : Skin.DangerText);
			}
			label.ForeColor = foreColor;
			if (timer.Parent is Panel panel)
			{
				Panel panel2 = panel;
				Color backColor;
				if (flag && flashPhase)
				{
					backColor = Skin.DangerStrong;
				}
				else
				{
					backColor = (order.Ready ? Skin.SuccessSurface : panelLight);
				}
				panel2.BackColor = backColor;
			}
		}

		private void Render()
		{
			cards.Clear();
			tickets.SuspendLayout();
			tickets.Controls.Clear();
			List<OpenOrder> list = (from o in store.OpenOrders
				where !o.Delivered
				orderby o.Created
				select o).ToList();
			if (list.Count == 0)
			{
				tickets.Controls.Add(new Label
				{
					Text = Tr.T("No active orders"),
					Font = new Font("Segoe UI Semibold", 16f),
					ForeColor = Skin.TextDim,
					AutoSize = true,
					Margin = new Padding(14, 24, 0, 0)
				});
			}
			foreach (OpenOrder item in list)
			{
				tickets.Controls.Add(BuildCard(item));
			}
			tickets.ResumeLayout();
		}

		private IEnumerable<(string Text, bool IsSub)> ItemLines(OpenOrder order)
		{
			bool courseOn = store.Features.CourseManagement;
			IEnumerable<SoldLine> enumerable;
			if (!courseOn)
			{
				IEnumerable<SoldLine> items = order.Items;
				enumerable = items;
			}
			else
			{
				enumerable = order.Items.Where((SoldLine i) => i.Course == 0 || i.Course <= order.FiredCourse);
			}
			IEnumerable<SoldLine> source = enumerable;
			foreach (IGrouping<(string, string, string, int, int), SoldLine> g in from i in source
				group i by (Product: i.Product, Note: i.Note, Modifiers: i.Modifiers, Seat: i.Seat, Course: i.Course))
			{
				string text = ((g.Key.Item4 > 0) ? $"[S{g.Key.Item4}] " : "");
				string text2 = ((courseOn && g.Key.Item5 > 0) ? TicketLayout.CourseTag(g.Key.Item5) : "");
				yield return (Text: $"{text}{text2}{g.Sum((SoldLine x) => x.Quantity)}×  {g.Key.Item1}", IsSub: false);
				if (!string.IsNullOrWhiteSpace(g.Key.Item3))
				{
					yield return (Text: "+ " + g.Key.Item3, IsSub: true);
				}
				if (!string.IsNullOrWhiteSpace(g.Key.Item2))
				{
					yield return (Text: "• " + g.Key.Item2, IsSub: true);
				}
			}
		}

		private int UnfiredCount(OpenOrder order)
		{
			if (!store.Features.CourseManagement)
			{
				return 0;
			}
			return Enumerable.Count(order.Items, (SoldLine i) => i.Course > order.FiredCourse);
		}

		private Panel BuildCard(OpenOrder order)
		{
			Color backColor = (order.Ready ? Skin.SuccessSurface : Skin.PanelLight);
			Color backColor2 = (order.Ready ? Skin.SuccessSurface : panelLight);
			Panel panel = new Panel
			{
				Size = new Size(280, 340),
				Margin = new Padding(8),
				BackColor = backColor
			};
			Label label = new Label
			{
				Text = ((order.OrderNumber > 0) ? $"#{order.OrderNumber}  {order.Table}" : order.Table),
				Font = new Font("Segoe UI Semibold", 13f),
				ForeColor = Skin.Text,
				AutoSize = true,
				Location = new Point(10, 8)
			};
			int num = UnfiredCount(order);
			Label label2 = new Label();
			label2.Text = string.Format("{0}  ·  {1}{2}  ·  {3} items{4}", order.Room, order.OrderType, (order.Source.Length > 0) ? ("  ·  " + order.Source) : "", order.Items.Sum((SoldLine i) => i.Quantity), (num > 0) ? $"  ·  {num} waiting fire" : "");
			label2.Font = new Font("Segoe UI", 9f);
			label2.ForeColor = ((num > 0) ? Skin.Warning : Skin.TextMuted);
			label2.AutoSize = true;
			label2.Location = new Point(11, 34);
			Label label3 = label2;
			Label label4 = new Label
			{
				Font = new Font("Segoe UI Semibold", 15f),
				TextAlign = ContentAlignment.MiddleRight,
				Location = new Point(174, 10),
				Size = new Size(96, 44)
			};
			Panel panel2 = new Panel
			{
				Location = new Point(0, 0),
				Size = new Size(280, 64),
				BackColor = backColor2
			};
			panel2.Controls.AddRange(new Control[3] { label, label3, label4 });
			FlowLayoutPanel flowLayoutPanel = new FlowLayoutPanel
			{
				Location = new Point(0, 64),
				Size = new Size(280, 234),
				AutoScroll = true,
				FlowDirection = FlowDirection.TopDown,
				WrapContents = false,
				BackColor = backColor,
				Padding = new Padding(10, 6, 10, 6)
			};
			foreach (var (text, flag) in ItemLines(order))
			{
				flowLayoutPanel.Controls.Add(new Label
				{
					Text = text,
					AutoSize = true,
					Font = (flag ? new Font("Segoe UI", 9f) : new Font("Segoe UI", 10.5f)),
					ForeColor = (flag ? Skin.TextMuted : Skin.Text),
					Margin = new Padding(flag ? 16 : 0, 1, 0, flag ? 5 : 2)
				});
			}
			panel.Controls.AddRange(new Control[2] { flowLayoutPanel, panel2 });
			if (!order.Ready)
			{
				Button readyBtn = new Button
				{
					Text = "✓  " + Tr.T("READY"),
					Location = new Point(0, 296),
					Size = new Size(280, 44),
					FlatStyle = FlatStyle.Flat,
					ForeColor = Skin.OnAccent,
					Font = new Font("Segoe UI Semibold", 11.5f),
					BackColor = mint,
					Cursor = Cursors.Hand
				};
				readyBtn.FlatAppearance.BorderSize = 0;
				readyBtn.Click += (s, e) => ToggleReady(order);
				panel.Controls.Add(readyBtn);
			}
			else
			{
				Panel readyActions = new Panel
				{
					Location = new Point(0, 296),
					Size = new Size(280, 44),
					BackColor = Skin.SuccessSurface
				};
				Button deliverBtn = new Button
				{
					Text = "✓  " + Tr.T("Deliver"),
					Location = new Point(0, 0),
					Size = new Size(185, 44),
					FlatStyle = FlatStyle.Flat,
					ForeColor = Skin.OnFill,
					BackColor = Skin.Success,
					Font = new Font("Segoe UI Semibold", 11f),
					Cursor = Cursors.Hand
				};
				deliverBtn.FlatAppearance.BorderSize = 0;
				deliverBtn.Click += (s, e) =>
				{
					store.MarkOrderDelivered(order.Room, order.Table, order.OrderNumber);
					Render();
				};

				Button revertBtn = new Button
				{
					Text = "↩ " + Tr.T("In prep"),
					Location = new Point(187, 0),
					Size = new Size(93, 44),
					FlatStyle = FlatStyle.Flat,
					ForeColor = Skin.TextDim,
					BackColor = panelLight,
					Font = new Font("Segoe UI", 9.5f),
					Cursor = Cursors.Hand
				};
				revertBtn.FlatAppearance.BorderSize = 0;
				revertBtn.Click += (s, e) => ToggleReady(order);

				readyActions.Controls.Add(deliverBtn);
				readyActions.Controls.Add(revertBtn);
				panel.Controls.Add(readyActions);
			}
			UpdateTimer(order, label4);
			cards.Add((order, label4));
			return panel;
		}

		private void ToggleReady(OpenOrder order)
		{
			alarmed.Remove((order.OrderNumber, order.Created.Ticks));
			store.MarkOrderReady(order.Room, order.Table, order.OrderNumber, !order.Ready);
			Render();
		}
	}

internal sealed class KioskOrderReviewForm : Form
{
	public KioskOrderReviewForm(PendingKioskOrder order, string currency, Action onConfirm, Action<string> onReject)
	{
		Text = $"{Tr.T("Kiosk order")} #{order.OrderNumber}";
		FormBorderStyle = FormBorderStyle.FixedDialog;
		MaximizeBox = false;
		MinimizeBox = false;
		StartPosition = FormStartPosition.CenterParent;
		ClientSize = new Size(580, 560);
		BackColor = Skin.Background;
		ForeColor = Skin.Text;
		Font = new Font("Segoe UI", 10f);

		Panel header = new Panel
		{
			Dock = DockStyle.Top,
			Height = 70,
			BackColor = Skin.Panel,
			Padding = new Padding(16, 12, 16, 12)
		};
		Label title = new Label
		{
			Text = $"🛎  {Tr.T("Order")} #{order.OrderNumber}  •  {order.OrderType.ToUpperInvariant()}",
			Font = new Font("Segoe UI Semibold", 14f),
			ForeColor = Skin.Accent,
			AutoSize = true,
			Location = new Point(14, 12)
		};
		int limit = 10;
		int minsLeft = Math.Max(0, (int)Math.Round((double)limit - (DateTime.Now - order.Created).TotalMinutes));
		Label subtitle = new Label
		{
			Text = string.Format(Tr.T("Received at {0:HH:mm} ({1} min ago) • Auto-voids in {2} min"), order.Created, (int)(DateTime.Now - order.Created).TotalMinutes, minsLeft),
			Font = new Font("Segoe UI", 9f),
			ForeColor = Skin.TextMuted,
			AutoSize = true,
			Location = new Point(16, 40)
		};
		header.Controls.AddRange(new Control[] { title, subtitle });

		ListView lv = new ListView
		{
			Dock = DockStyle.Fill,
			View = View.Details,
			FullRowSelect = true,
			BackColor = Skin.PanelLight,
			ForeColor = Skin.Text,
			BorderStyle = BorderStyle.None,
			Font = new Font("Segoe UI", 10.5f),
			HeaderStyle = ColumnHeaderStyle.Nonclickable
		};
		lv.Columns.Add(Tr.T("Item"), 270);
		lv.Columns.Add(Tr.T("Qty"), 60);
		lv.Columns.Add(Tr.T("Price"), 100);
		lv.Columns.Add(Tr.T("Total"), 110);

		foreach (var item in order.Items)
		{
			var lvi = new ListViewItem(item.Product);
			lvi.SubItems.Add(item.Quantity.ToString());
			lvi.SubItems.Add(item.UnitPrice.ToString("0.00") + " " + currency);
			lvi.SubItems.Add((item.UnitPrice * (decimal)item.Quantity).ToString("0.00") + " " + currency);
			lv.Items.Add(lvi);
			if (!string.IsNullOrEmpty(item.Note) || !string.IsNullOrEmpty(item.Modifiers))
			{
				string details = string.Join(" • ", new[] { item.Modifiers, item.Note }.Where(s => !string.IsNullOrEmpty(s)));
				var noteLvi = new ListViewItem("   ↳ " + details)
				{
					ForeColor = Skin.TextMuted,
					Font = new Font("Segoe UI", 9f, FontStyle.Italic)
				};
				noteLvi.SubItems.Add("");
				noteLvi.SubItems.Add("");
				noteLvi.SubItems.Add("");
				lv.Items.Add(noteLvi);
			}
		}

		Panel footer = new Panel
		{
			Dock = DockStyle.Bottom,
			Height = 110,
			BackColor = Skin.Panel,
			Padding = new Padding(16, 10, 16, 12)
		};

		Label totalLbl = new Label
		{
			Text = string.Format(Tr.T("Total: {0:0.00} {1}"), order.Total, currency),
			Font = new Font("Segoe UI Semibold", 14f),
			ForeColor = Skin.Accent,
			AutoSize = true,
			Location = new Point(16, 10)
		};

		Button confirmBtn = new Button
		{
			Text = Tr.T("✓  Confirm & Fire to Kitchen"),
			Location = new Point(210, 48),
			Size = new Size(230, 46),
			FlatStyle = FlatStyle.Flat,
			BackColor = Skin.Accent,
			ForeColor = Skin.OnAccent,
			Font = new Font("Segoe UI Semibold", 10.5f),
			Cursor = Cursors.Hand
		};
		confirmBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(confirmBtn);
		confirmBtn.Click += (s, e) =>
		{
			onConfirm?.Invoke();
			DialogResult = DialogResult.OK;
			Close();
		};

		Button rejectBtn = new Button
		{
			Text = Tr.T("✕  Reject"),
			Location = new Point(16, 48),
			Size = new Size(110, 46),
			FlatStyle = FlatStyle.Flat,
			BackColor = Skin.Danger,
			ForeColor = Skin.OnFill,
			Font = new Font("Segoe UI Semibold", 10.5f),
			Cursor = Cursors.Hand
		};
		rejectBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(rejectBtn);
		rejectBtn.Click += (s, e) =>
		{
			if (MessageBox.Show(string.Format(Tr.T("Are you sure you want to reject Order #{0}? (Fake order / customer left)"), order.OrderNumber), Tr.T("Reject order"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
			{
				onReject?.Invoke("Rejected by staff");
				DialogResult = DialogResult.Cancel;
				Close();
			}
		};

		Button closeBtn = new Button
		{
			Text = Tr.T("Close"),
			Location = new Point(450, 48),
			Size = new Size(110, 46),
			FlatStyle = FlatStyle.Flat,
			BackColor = Skin.SidebarItem,
			ForeColor = Skin.Text,
			Font = new Font("Segoe UI", 10f),
			Cursor = Cursors.Hand
		};
		closeBtn.FlatAppearance.BorderSize = 0;
		Skin.FlatStates(closeBtn);
		closeBtn.Click += (s, e) => Close();

		footer.Controls.AddRange(new Control[] { totalLbl, confirmBtn, rejectBtn, closeBtn });

		Controls.Add(lv);
		Controls.Add(footer);
		Controls.Add(header);
	}
}

internal sealed class KioskForm : Form
	{
		private readonly List<(Product P, int Qty)> cart = new List<(Product, int)>();

		private readonly List<Product> products;

		private readonly Color background;

		private readonly Color panelLight;

		private readonly Color mint;

		private readonly Func<Product, string> resolvePrinter;

		private readonly Action<List<SoldLine>> onSend;

		private readonly FlowLayoutPanel tiles = new FlowLayoutPanel
		{
			Dock = DockStyle.Fill,
			AutoScroll = true,
			WrapContents = true,
			FlowDirection = FlowDirection.LeftToRight,
			Padding = new Padding(14)
		};

		private readonly FlowLayoutPanel tabsFlow = new FlowLayoutPanel
		{
			Dock = DockStyle.Top,
			Height = 54,
			AutoScroll = false,
			WrapContents = false,
			Padding = new Padding(10, 8, 10, 8)
		};

		private readonly FlowLayoutPanel cartList = new FlowLayoutPanel
		{
			Dock = DockStyle.Fill,
			AutoScroll = true,
			WrapContents = false,
			FlowDirection = FlowDirection.TopDown,
			Padding = new Padding(8)
		};

		private readonly Label totalLabel = new Label
		{
			Dock = DockStyle.Bottom,
			Height = 64,
			Font = new Font("Segoe UI Semibold", 22f),
			TextAlign = ContentAlignment.MiddleRight,
			Padding = new Padding(0, 0, 16, 0)
		};

		private readonly Label overlay = new Label
		{
			Dock = DockStyle.Fill,
			Font = new Font("Segoe UI Semibold", 24f),
			ForeColor = Skin.AccentBright,
			TextAlign = ContentAlignment.MiddleCenter,
			Visible = false,
			BackColor = Skin.Sidebar
		};

		private string currentCategory = "";

		private readonly Timer hideOverlay = new Timer
		{
			Interval = 5000
		};

		private readonly Func<string, bool>? is86;

		public KioskForm(Color background, Color panelLight, Color mint, List<Product> products, Func<Product, string> resolvePrinter, Action<List<SoldLine>> onSend, Func<string, bool>? is86 = null)
		{
			this.background = background;
			this.panelLight = panelLight;
			this.mint = mint;
			this.products = products;
			this.is86 = is86;
			this.resolvePrinter = resolvePrinter;
			this.onSend = onSend;
			totalLabel.ForeColor = mint;
			Text = Tr.T("Self ordering");
			FormBorderStyle = FormBorderStyle.None;
			WindowState = FormWindowState.Maximized;
			StartPosition = FormStartPosition.CenterScreen;
			BackColor = background;
			ForeColor = Skin.Text;
			Font = new Font("Segoe UI", 11f);
			KeyPreview = true;
			KeyDown += (object _, KeyEventArgs e) =>
			{
				if (e.KeyCode == Keys.Escape || (e.Alt && e.KeyCode == Keys.Left))
				{
					e.Handled = true;
					Close();
				}
			};
			hideOverlay.Tick += (object _, EventArgs _) =>
			{
				overlay.Visible = false;
				hideOverlay.Stop();
			};
			Panel panel = new Panel
			{
				Dock = DockStyle.Top,
				Height = 74,
				BackColor = Skin.HeaderPanel
			};
			Button backBtn = new Button
			{
				Text = Tr.T("← Back"),
				Location = new Point(16, 17),
				Size = new Size(96, 40),
				FlatStyle = FlatStyle.Flat,
				BackColor = Skin.SidebarItem,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI Semibold", 11f),
				Cursor = Cursors.Hand
			};
			backBtn.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(backBtn);
			backBtn.Click += (object _, EventArgs _) => Close();
			Label label = new Label
			{
				Text = Tr.T("TAP TO ORDER  •  Pay at the counter"),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 18f),
				ForeColor = mint,
				Location = new Point(126, 22)
			};
			Button button = new Button
			{
				Text = Tr.T("Exit kiosk"),
				Dock = DockStyle.Right,
				Width = 130,
				FlatStyle = FlatStyle.Flat,
				ForeColor = Skin.OnFill,
				BackColor = Skin.Danger,
				Font = new Font("Segoe UI", 10f)
			};
			button.FlatAppearance.BorderSize = 0;
			button.Click += (object _, EventArgs _) =>
			{
				Close();
			};
			panel.Controls.AddRange(new Control[3] { backBtn, label, button });
			Panel panel2 = new Panel
			{
				Dock = DockStyle.Right,
				Width = 360,
				BackColor = Skin.Panel,
				Padding = new Padding(10)
			};
			Label value = new Label
			{
				Text = Tr.T("Your order"),
				Dock = DockStyle.Top,
				Height = 40,
				Font = new Font("Segoe UI Semibold", 14f),
				ForeColor = Skin.TextDim
			};
			Button button2 = new Button
			{
				Text = Tr.T("SEND ORDER TO KITCHEN"),
				Dock = DockStyle.Bottom,
				Height = 74,
				FlatStyle = FlatStyle.Flat,
				BackColor = mint,
				ForeColor = Skin.OnAccent,
				Font = new Font("Segoe UI Semibold", 14f)
			};
			button2.FlatAppearance.BorderSize = 0;
			button2.Click += (object _, EventArgs _) =>
			{
				SendOrder();
			};
			Button button3 = new Button
			{
				Text = Tr.T("Clear"),
				Dock = DockStyle.Bottom,
				Height = 40,
				FlatStyle = FlatStyle.Flat,
				BackColor = Skin.Neutral,
				ForeColor = Skin.OnFill
			};
			button3.FlatAppearance.BorderSize = 0;
			button3.Click += (object _, EventArgs _) =>
			{
				cart.Clear();
				RenderCart();
			};
			panel2.Controls.Add(cartList);
			panel2.Controls.Add(totalLabel);
			panel2.Controls.Add(button3);
			panel2.Controls.Add(button2);
			panel2.Controls.Add(value);
			Panel panel3 = new Panel
			{
				Dock = DockStyle.Fill,
				BackColor = background
			};
			panel3.Controls.Add(tiles);
			panel3.Controls.Add(tabsFlow);
			panel3.Controls.Add(overlay);
			Controls.Add(panel3);
			Controls.Add(panel2);
			Controls.Add(panel);
			currentCategory = products.Select((Product p) => p.Category).FirstOrDefault() ?? "";
			RenderTabs();
			RenderTiles();
			RenderCart();
		}

		private void RenderTabs()
		{
			tabsFlow.Controls.Clear();
			foreach (string item in products.Select((Product p) => p.Category).Distinct())
			{
				string c = item;
				Button button = new Button
				{
					Text = c,
					AutoSize = true,
					MinimumSize = new Size(110, 38),
					FlatStyle = FlatStyle.Flat,
					Margin = new Padding(0, 0, 8, 0),
					BackColor = ((c == currentCategory) ? mint : panelLight),
					ForeColor = ((c == currentCategory) ? Skin.OnAccent : Skin.Text),
					Font = new Font("Segoe UI Semibold", 10f)
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					currentCategory = c;
					RenderTabs();
					RenderTiles();
				};
				tabsFlow.Controls.Add(button);
			}
		}

		private void RenderTiles()
		{
			tiles.SuspendLayout();
			tiles.Controls.Clear();
			foreach (Product item in products.Where((Product p) => p.Category == currentCategory))
			{
				Product product = item;
				ProductTile productTile = new ProductTile(product, 230, 160)
				{
					Margin = new Padding(0, 0, 14, 14)
				};
				productTile.OutOfStock = false;
				productTile.Click += (object _, EventArgs _) =>
				{
					AddToCart(product);
				};
				tiles.Controls.Add(productTile);
			}
			tiles.ResumeLayout();
		}

		private void AddToCart(Product p)
		{
			int num = cart.FindIndex(((Product P, int Qty) c) => c.P.Name == p.Name);
			if (num >= 0)
			{
				cart[num] = (cart[num].P, cart[num].Qty + 1);
			}
			else
			{
				cart.Add((p, 1));
			}
			RenderCart();
		}

		private void RenderCart()
		{
			cartList.SuspendLayout();
			cartList.Controls.Clear();
			foreach (var item2 in cart)
			{
				Product p = item2.P;
				int item = item2.Qty;
				Panel panel = new Panel
				{
					Width = 330,
					Height = 56,
					BackColor = panelLight,
					Margin = new Padding(0, 0, 0, 8)
				};
				Label label = new Label
				{
					Text = p.Name,
					AutoSize = true,
					Location = new Point(10, 6),
					Font = new Font("Segoe UI", 9.5f)
				};
				Label label2 = new Label
				{
					Text = (p.Price * (decimal)item).ToString("C"),
					AutoSize = true,
					Location = new Point(10, 28),
					ForeColor = mint,
					Font = new Font("Segoe UI", 9f)
				};
				Button button = new Button
				{
					Text = Tr.T("−"),
					Size = new Size(30, 34),
					Location = new Point(224, 11),
					FlatStyle = FlatStyle.Flat,
					BackColor = Skin.InfoAlt,
					ForeColor = Skin.OnFill
				};
				button.FlatAppearance.BorderSize = 0;
				button.Click += (object _, EventArgs _) =>
				{
					int num = cart.FindIndex(((Product P, int Qty) c) => c.P.Name == p.Name);
					if (num >= 0)
					{
						if (cart[num].Qty <= 1)
						{
							cart.RemoveAt(num);
						}
						else
						{
							cart[num] = (cart[num].P, cart[num].Qty - 1);
						}
						RenderCart();
					}
				};
				Label label3 = new Label
				{
					Text = item.ToString(),
					AutoSize = true,
					Location = new Point(262, 18),
					Font = new Font("Segoe UI Semibold", 11f)
				};
				Button button2 = new Button
				{
					Text = Tr.T("+"),
					Size = new Size(30, 34),
					Location = new Point(290, 11),
					FlatStyle = FlatStyle.Flat,
					BackColor = mint,
					ForeColor = Skin.OnAccent
				};
				button2.FlatAppearance.BorderSize = 0;
				button2.Click += (object _, EventArgs _) =>
				{
					AddToCart(p);
				};
				panel.Controls.AddRange(new Control[5] { label, label2, button, label3, button2 });
				cartList.Controls.Add(panel);
			}
			totalLabel.Text = cart.Sum(((Product P, int Qty) c) => c.P.Price * (decimal)c.Qty).ToString("C");
			cartList.ResumeLayout();
		}

		private void SendOrder()
		{
			if (cart.Count == 0)
			{
				MessageBox.Show(Tr.T("Add something first."), Tr.T("Kiosk"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			List<SoldLine> obj = (from p in cart.SelectMany(((Product P, int Qty) c) => Enumerable.Repeat(c.P, c.Qty))
				group p by p.Name into g
				select new SoldLine(g.Key, g.First().Family, g.Count(), g.First().Price, g.First().Category, resolvePrinter(g.First()))).ToList();
			onSend(obj);
			cart.Clear();
			RenderCart();
			overlay.Text = "✓  Order sent!\n\nPay at the counter.\n\nOrder # confirmed";
			overlay.Visible = true;
			overlay.BringToFront();
			hideOverlay.Stop();
			hideOverlay.Start();
		}
	}

internal sealed class CustomerDisplayForm : Form
	{
		private readonly Panel listPanel = new Panel
		{
			Dock = DockStyle.Fill,
			AutoScroll = true,
			BackColor = Skin.Sidebar,
			Padding = new Padding(18, 10, 18, 10)
		};

		private readonly Label contextLabel = new Label
		{
			Dock = DockStyle.Top,
			Height = 54,
			Font = new Font("Segoe UI Semibold", 13f),
			ForeColor = Skin.TextDim,
			TextAlign = ContentAlignment.MiddleLeft,
			Padding = new Padding(14, 0, 0, 0),
			BackColor = Skin.Panel
		};

		private readonly Label totalValue = new Label
		{
			Dock = DockStyle.Bottom,
			Height = 96,
			Font = new Font("Segoe UI Semibold", 34f),
			ForeColor = Skin.Accent,
			TextAlign = ContentAlignment.MiddleRight,
			Padding = new Padding(0, 0, 22, 0),
			BackColor = Skin.Panel
		};

		private readonly Label totalCaption = new Label
		{
			Dock = DockStyle.Bottom,
			Height = 34,
			Text = Tr.T("TOTAL"),
			Font = new Font("Segoe UI Semibold", 11f),
			ForeColor = Skin.TextDim,
			TextAlign = ContentAlignment.MiddleRight,
			Padding = new Padding(0, 0, 24, 0),
			BackColor = Skin.Panel
		};

		private readonly Label thanks = new Label
		{
			Dock = DockStyle.Fill,
			Font = new Font("Segoe UI Semibold", 26f),
			ForeColor = Skin.AccentBright,
			TextAlign = ContentAlignment.MiddleCenter,
			Visible = false,
			BackColor = Skin.Sidebar
		};

		private readonly Timer thanksTimer = new Timer
		{
			Interval = 5000
		};

		public CustomerDisplayForm(Color background, Color mint)
		{
			Text = Tr.T("Customer display");
			Size = new Size(520, 780);
			StartPosition = FormStartPosition.Manual;
			Location = new Point(Screen.PrimaryScreen?.Bounds.Width ?? 1280, 80);
			BackColor = background;
			ForeColor = Skin.Text;
			Font = new Font("Segoe UI", 11f);
			thanksTimer.Tick += (object _, EventArgs _) =>
			{
				thanks.Visible = false;
				thanksTimer.Stop();
			};
			Controls.Add(listPanel);
			Controls.Add(contextLabel);
			Controls.Add(thanks);
			Controls.Add(totalValue);
			Controls.Add(totalCaption);
			SetOrder("", new List<(string, decimal)>(), 0m);
		}

		public void SetOrder(string context, List<(string Text, decimal Amount)> rows, decimal total)
		{
			if (IsDisposed)
			{
				return;
			}
			if (InvokeRequired)
			{
				try
				{
					BeginInvoke((Action)(() =>
					{
						SetOrder(context, rows, total);
					}));
					return;
				}
				catch
				{
					return;
				}
			}
			contextLabel.Text = "  " + context;
			listPanel.SuspendLayout();
			listPanel.Controls.Clear();
			foreach (var row in rows)
			{
				string item = row.Text;
				decimal item2 = row.Amount;
				Panel panel = new Panel
				{
					Dock = DockStyle.Top,
					Height = 44,
					Padding = new Padding(4, 6, 4, 6)
				};
				Label value = new Label
				{
					Text = item,
					AutoSize = false,
					Size = new Size(330, 32),
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI", 11f)
				};
				Label value2 = new Label
				{
					Text = item2.ToString("C"),
					AutoSize = false,
					Size = new Size(130, 32),
					ForeColor = Skin.Accent,
					TextAlign = ContentAlignment.MiddleRight,
					Font = new Font("Segoe UI Semibold", 11f),
					Dock = DockStyle.Right
				};
				panel.Controls.Add(value);
				panel.Controls.Add(value2);
				listPanel.Controls.Add(panel);
			}
			listPanel.ResumeLayout();
			totalValue.Text = total.ToString("C");
		}

		public void ShowThankYou(decimal paid)
		{
			if (IsDisposed)
			{
				return;
			}
			if (InvokeRequired)
			{
				try
				{
					BeginInvoke((Action)(() =>
					{
						ShowThankYou(paid);
					}));
					return;
				}
				catch
				{
					return;
				}
			}
			thanks.Text = $"✓  PAID\n\n{paid:C}\n\nThank you!";
			thanks.Visible = true;
			thanks.BringToFront();
			thanksTimer.Stop();
			thanksTimer.Start();
		}

		protected override void OnFormClosed(FormClosedEventArgs e)
		{
			thanksTimer.Stop();
			thanksTimer.Dispose();
			base.OnFormClosed(e);
		}
	}

