		private void UpdateRefundButton()
		{
			Button button = refundButton;
			Sale sale = selectedTransaction;
			int enabled;
			if ((object)sale != null && !sale.IsRefund)
			{
				List<SoldLine> items = sale.Items;
				if (items != null && items.Count > 0)
				{
					enabled = ((onRefund != null) ? 1 : 0);
					goto IL_0037;
				}
			}
			enabled = 0;
			goto IL_0037;
			IL_0037:
			button.Enabled = (byte)enabled != 0;
		}

		private void ShowYears()
		{
			selectedYear = 0;
			selectedMonth = 0;
			dateButtons.Controls.Clear();
			selectionLabel.Text = "Choose a year";
			backButton.Enabled = false;
			List<int> list = (from result in sales.Select((Sale sale) => sale.Time.Year).Distinct()
				orderby result descending
				select result).ToList();
			if (list.Count == 0)
			{
				list.Add(DateTime.Today.Year);
			}
			foreach (int year in list)
			{
				Button button = DateButton(year.ToString());
				button.Click += (object _, EventArgs _) =>
				{
					ShowMonths(year);
				};
				dateButtons.Controls.Add(button);
			}
			ShowDetails("All years", sales);
		}

		private void ShowMonths(int year)
		{
			selectedYear = year;
			selectedMonth = 0;
			dateButtons.Controls.Clear();
			selectionLabel.Text = $"Year {year}  /  choose a month";
			backButton.Enabled = true;
			foreach (int item in from month in (from sale in sales
					where sale.Time.Year == year
					select sale.Time.Month).Distinct()
				orderby month
				select month)
			{
				int monthNumber = item;
				Button button = DateButton(new DateTime(year, item, 1).ToString("MMMM"));
				button.Click += (object _, EventArgs _) =>
				{
					ShowDays(year, monthNumber);
				};
				dateButtons.Controls.Add(button);
			}
			ShowDetails(year.ToString(), sales.Where((Sale sale) => sale.Time.Year == year).ToList());
		}

		private void ShowDays(int year, int month)
		{
			selectedYear = year;
			selectedMonth = month;
			dateButtons.Controls.Clear();
			selectionLabel.Text = $"{new DateTime(year, month, 1):MMMM yyyy}  /  choose a day";
			backButton.Enabled = true;
			foreach (int item in from day in (from sale in sales
					where sale.Time.Year == year && sale.Time.Month == month
					select sale.Time.Day).Distinct()
				orderby day
				select day)
			{
				int dayNumber = item;
				Button button = DateButton(item.ToString());
				button.Click += (object _, EventArgs _) =>
				{
					ShowDetails(new DateTime(year, month, dayNumber).ToString("dd MMMM yyyy"), sales.Where((Sale sale) => sale.Time.Date == new DateTime(year, month, dayNumber)).ToList());
				};
				dateButtons.Controls.Add(button);
			}
			ShowDetails(new DateTime(year, month, 1).ToString("MMMM yyyy"), sales.Where((Sale sale) => sale.Time.Year == year && sale.Time.Month == month).ToList());
		}

		private void GoBack()
		{
			if (selectedYear != 0)
			{
				if (selectedMonth == 0)
				{
					ShowYears();
				}
				else
				{
					ShowMonths(selectedYear);
				}
			}
		}

		private Button DateButton(string text)
		{
			Button button = new Button();
			button.Text = text;
			button.Size = new Size(120, 36);
			button.BackColor = panelLight;
			button.ForeColor = Skin.Text;
			button.FlatStyle = FlatStyle.Flat;
			button.Cursor = Cursors.Hand;
			button.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(button);
			return button;
		}

		private void PrintReport()
