				MessageBox.Show(Tr.T("No sales to print."), Tr.T("Print"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			using (PrintDocument printDocument = new PrintDocument())
			{
				printDocument.PrintPage += (object _, PrintPageEventArgs args) =>
				{
					if (args.Graphics == null)
					{
						return;
					}
					Graphics g = args.Graphics;
					int y = 30;
					int margin = 40;
					int width = args.PageBounds.Width - margin * 2;
					Font headerFont;
					using (Font font = new Font("Consolas", 14f, FontStyle.Bold))
					{
						headerFont = new Font("Consolas", 10f, FontStyle.Bold);
						try
						{
							using Font f = new Font("Consolas", 9f);
							using Font font2 = new Font("Consolas", 8f);
							g.DrawString("VECTRON POS - Sales Report", font, Brushes.Black, margin, y);
							y += 30;
							g.DrawString(summaryLabel.Text, headerFont, Brushes.Black, margin, y);
							y += 25;
							g.DrawLine(Pens.Black, margin, y, margin + width, y);
							y += 10;
							string text = tabs.SelectedTab?.Text ?? "By product";
							g.DrawString("Report: " + text, headerFont, Brushes.Black, margin, y);
							y += 22;
							if (text == "Transactions")
							{
								DrawHeader(new string[5] { "Time", "Table", "Operator", "Items", "Total" }, FiveCol());
								foreach (Sale item4 in currentFilteredSales.OrderByDescending((Sale sale) => sale.Time))
								{
									if (y > args.PageBounds.Height - 60)
									{
										args.HasMorePages = true;
										return;
									}
									List<SoldLine>? items = item4.Items;
									int num = ((items != null) ? items.Sum((SoldLine soldLine) => soldLine.Quantity) : 0);
									DrawRow(new string[5]
									{
										item4.Time.ToString("dd/MM HH:mm"),
										item4.Table,
										item4.Operator,
										num.ToString(),
										P(item4.Total)
									}, FiveCol(), f, Brushes.Black);
								}
								DrawFooter();
							}
							else if (text == "Financial")
							{
								decimal num2 = currentFilteredSales.Sum((Sale sale) => sale.Total);
								int num3 = currentFilteredSales.SelectMany((Sale sale) => sale.Items ?? new List<SoldLine>()).Sum((SoldLine soldLine) => soldLine.Quantity);
								decimal amount = ((currentFilteredSales.Count > 0) ? (num2 / (decimal)currentFilteredSales.Count) : 0m);
								IGrouping<string, SoldLine> grouping = (from soldLine in currentFilteredSales.SelectMany((Sale sale) => sale.Items ?? new List<SoldLine>())
									group soldLine by soldLine.Product into source2
									orderby source2.Sum((SoldLine i) => i.UnitPrice * (decimal)i.Quantity) descending
									select source2).FirstOrDefault();
								IGrouping<string, Sale> grouping2 = (from sale in currentFilteredSales
									group sale by sale.Table into source2
									orderby source2.Sum((Sale s) => s.Total) descending
									select source2).FirstOrDefault();
								IGrouping<string, Sale> grouping3 = (from sale in currentFilteredSales
									group sale by sale.Operator into source2
									orderby source2.Sum((Sale s) => s.Total) descending
									select source2).FirstOrDefault();
								IGrouping<int, Sale> grouping4 = (from sale in currentFilteredSales
									group sale by sale.Time.Hour into source2
									orderby source2.Sum((Sale s) => s.Total) descending
									select source2).FirstOrDefault();
								DrawHeader(new string[2] { "Metric", "Value" }, TwoCol());
								DrawRow(new string[2]
								{
									"Total Revenue",
									P(num2)
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Transactions",
									currentFilteredSales.Count.ToString()
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Items Sold",
									num3.ToString()
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Average Sale",
									P(amount)
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2] { "", "" }, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Top Product",
									(grouping != null) ? $"{grouping.Key} ({grouping.Sum((SoldLine i) => i.Quantity)}x)" : "N/A"
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Top Table",
									(grouping2 != null) ? $"{grouping2.Key} ({grouping2.Count()} sales)" : "N/A"
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Top Operator",
									(grouping3 != null) ? $"{grouping3.Key} ({grouping3.Count()} sales)" : "N/A"
								}, TwoCol(), f, Brushes.Black);
								DrawRow(new string[2]
								{
									"Peak Hour",
									(grouping4 != null) ? $"{grouping4.Key:D2}:00 ({grouping4.Count()} sales)" : "N/A"
								}, TwoCol(), f, Brushes.Black);
								DrawFooter();
							}
							else
							{
								DrawHeader(new string[3] { "Name", "Qty", "Total" }, ThreeCol());
								IEnumerable<(string, int, decimal)> source = text switch
								{
									"By product" => currentFilteredSales.SelectMany((Sale sale) =>
									{
										List<SoldLine>? items2 = sale.Items;
										return ((items2 != null) ? items2.Select((SoldLine soldLine) => (Product: soldLine.Product, Quantity: soldLine.Quantity, soldLine.UnitPrice * (decimal)soldLine.Quantity)) : null) ?? Array.Empty<(string, int, decimal)>();
									}), 
									"By family" => currentFilteredSales.SelectMany((Sale sale) =>
									{
										List<SoldLine>? items2 = sale.Items;
										return ((items2 != null) ? items2.Select((SoldLine soldLine) => ((soldLine.Family == "General") ? soldLine.Category : soldLine.Family, Quantity: soldLine.Quantity, soldLine.UnitPrice * (decimal)soldLine.Quantity)) : null) ?? Array.Empty<(string, int, decimal)>();
									}), 
									"By operator" => currentFilteredSales.SelectMany((Sale sale) =>
									{
										(string, int, decimal)[] array2 = new (string, int, decimal)[1];
										string item3 = sale.Operator;
										List<SoldLine>? items2 = sale.Items;
										array2[0] = (item3, (items2 != null) ? items2.Sum((SoldLine i) => i.Quantity) : 0, sale.Total);
										return array2;
									}), 
									"By table" => currentFilteredSales.SelectMany((Sale sale) =>
									{
										(string, int, decimal)[] array2 = new (string, int, decimal)[1];
										string table = sale.Table;
										List<SoldLine>? items2 = sale.Items;
										array2[0] = (table, (items2 != null) ? items2.Sum((SoldLine i) => i.Quantity) : 0, sale.Total);
										return array2;
									}), 
									"By hour" => from sale in currentFilteredSales
										group sale by sale.Time.Hour into grouping5
										select ($"{grouping5.Key:D2}:00", grouping5.Count(), grouping5.Sum((Sale s) => s.Total)), 
									_ => Array.Empty<(string, int, decimal)>(), 
								};
								foreach (var item5 in ((text == "By hour") ? source.Select(((string Name, int Quantity, decimal Total) x) => (Name: x.Name, Quantity: x.Quantity, Total: x.Total)) : source.GroupBy(((string Name, int Quantity, decimal Total) x) => x.Name).Select((IGrouping<string, (string Name, int Quantity, decimal Total)> grouping5) => (Name: grouping5.Key, Quantity: grouping5.Sum(((string Name, int Quantity, decimal Total) x) => x.Quantity), Total: grouping5.Sum(((string Name, int Quantity, decimal Total) x) => x.Total)))).OrderByDescending(((string Name, int Quantity, decimal Total) x) => x.Total))
								{
									if (y > args.PageBounds.Height - 60)
									{
										args.HasMorePages = true;
										return;
									}
									string[] array = new string[3] { item5.Name, null, null };
									int item = item5.Quantity;
									array[1] = item.ToString();
									decimal item2 = item5.Total;
									array[2] = item2.ToString("N2") + " " + currency;
									DrawRow(array, ThreeCol(), f, Brushes.Black);
								}
								DrawFooter();
							}
							y += 10;
							g.DrawString($"Printed: {DateTime.Now:dd/MM/yyyy HH:mm}", font2, Brushes.Gray, margin, y);
						}
						finally
						{
							if (headerFont != null)
							{
								((IDisposable)headerFont).Dispose();
							}
						}
					}
					void DrawFooter()
					{
						g.DrawLine(Pens.Black, margin, y, margin + width, y);
						y += 4;
					}
					void DrawHeader(string[] headers, int[] colX)
					{
						for (int i = 0; i < headers.Length; i++)
						{
							g.DrawString(headers[i], headerFont, Brushes.Black, colX[i], y);
						}
						y += 18;
						g.DrawLine(Pens.Black, margin, y, margin + width, y);
						y += 4;
					}
					void DrawRow(string[] cells, int[] colX, Font font3, Brush b)
					{
						for (int i = 0; i < cells.Length; i++)
						{
							g.DrawString(cells[i], font3, b, colX[i], y);
						}
						y += 16;
					}
					int[] FiveCol()
					{
						return new int[5]
						{
							margin,
							margin + 95,
							margin + 180,
							margin + 280,
							margin + 360
						};
					}
					int[] ThreeCol()
					{
						return new int[3]
						{
							margin,
							margin + 220,
							margin + 340
						};
					}
					int[] TwoCol()
					{
						return new int[2]
						{
							margin,
							margin + 300
						};
					}
				};
				using PrintDialog printDialog = new PrintDialog
				{
					Document = printDocument,
					UseEXDialog = true
				};
				if (printDialog.ShowDialog(this) == DialogResult.OK)
				{
					printDocument.Print();
				}
			}
			string P(decimal amount)
			{
				return amount.ToString("N2") + " " + currency;
			}
		}

		private void ShowDetails(string period, List<Sale> selectedSales)
		{
			currentFilteredSales = selectedSales;
			selectedTransaction = null;
			UpdateRefundButton();
			decimal num = selectedSales.Sum((Sale sale) => sale.Total);
			int num2 = selectedSales.SelectMany((Sale sale) => sale.Items ?? new List<SoldLine>()).Sum((SoldLine item) => item.Quantity);
			decimal num3 = ((selectedSales.Count > 0) ? (num / (decimal)selectedSales.Count) : 0m);
			summaryLabel.Text = $"{period}  •  {num:C}  •  {selectedSales.Count} transactions  •  {num2} items  •  avg {num3:C}";
			tabs.TabPages.Clear();
			tabs.TabPages.Add(BuildPage("By product", selectedSales, (Sale sale) =>
			{
				List<SoldLine>? items = sale.Items;
				return ((items != null) ? items.Select((SoldLine item) => (Product: item.Product, Quantity: item.Quantity, item.UnitPrice * (decimal)item.Quantity)) : null) ?? Array.Empty<(string, int, decimal)>();
			}, panelLight, mint));
			tabs.TabPages.Add(BuildPage("By family", selectedSales, (Sale sale) =>
			{
				List<SoldLine>? items = sale.Items;
				return ((items != null) ? items.Select((SoldLine item) => ((item.Family == "General") ? item.Category : item.Family, Quantity: item.Quantity, item.UnitPrice * (decimal)item.Quantity)) : null) ?? Array.Empty<(string, int, decimal)>();
			}, panelLight, mint));
			tabs.TabPages.Add(BuildPage("By operator", selectedSales.Select((Sale sale) =>
			{
				Sale sale2 = sale._003CClone_003E_0024();
				sale2.Items = new List<SoldLine>(1)
				{
					new SoldLine(sale.Operator, "Operator", 1, sale.Total)
				};
				return sale2;
			}).ToList(), (Sale sale) =>
			{
				List<SoldLine>? items = sale.Items;
				return ((items != null) ? items.Select((SoldLine item) => (Product: item.Product, Quantity: item.Quantity, item.UnitPrice * (decimal)item.Quantity)) : null) ?? Array.Empty<(string, int, decimal)>();
			}, panelLight, mint));
			tabs.TabPages.Add(BuildPage("By table", selectedSales.Select((Sale sale) =>
			{
				Sale sale2 = sale._003CClone_003E_0024();
				sale2.Items = new List<SoldLine>(1)
				{
					new SoldLine(sale.Table, "Table", 1, sale.Total)
				};
				return sale2;
			}).ToList(), (Sale sale) =>
			{
				List<SoldLine>? items = sale.Items;
				return ((items != null) ? items.Select((SoldLine item) => (Product: item.Product, Quantity: item.Quantity, item.UnitPrice * (decimal)item.Quantity)) : null) ?? Array.Empty<(string, int, decimal)>();
			}, panelLight, mint));
			tabs.TabPages.Add(BuildHourlyPage(selectedSales));
			tabs.TabPages.Add(BuildTransactionPage(selectedSales));
			tabs.TabPages.Add(BuildFinancialPage(selectedSales));
		}

		private static TabPage BuildPage(string text, List<Sale> sales, Func<Sale, IEnumerable<(string Name, int Quantity, decimal Total)>> selector, Color panelLight, Color mint)
		{
			TabPage tabPage = new TabPage(text)
			{
				BackColor = Skin.Background,
				ForeColor = Skin.Text
			};
			ListView listView = new ListView
			{
				Dock = DockStyle.Fill,
				View = View.Details,
				FullRowSelect = true,
				GridLines = true,
				BackColor = panelLight,
				ForeColor = Skin.Text
			};
			listView.Columns.Add("Name", 300);
			listView.Columns.Add("Quantity", 120);
			listView.Columns.Add("Total", 160);
			foreach (IGrouping<string, (string, int, decimal)> item in from item in sales.SelectMany(selector)
				group item by item.Name into @group
				orderby @group.Sum(((string Name, int Quantity, decimal Total) item) => item.Total) descending
				select @group)
			{
				listView.Items.Add(new ListViewItem(new string[3]
				{
					item.Key,
					item.Sum(((string Name, int Quantity, decimal Total) item) => item.Quantity).ToString(),
