		private TabPage BuildFinancialPage(List<Sale> selectedSales)
		{
			TabPage tabPage = new TabPage("Financial")
			{
				BackColor = Skin.Background,
				ForeColor = Skin.Text
			};
			FlowLayoutPanel panel = new FlowLayoutPanel
			{
				Dock = DockStyle.Fill,
				FlowDirection = FlowDirection.TopDown,
				Padding = new Padding(20),
				AutoScroll = true
			};
			decimal num = selectedSales.Sum((Sale sale) => sale.Total);
			int num2 = selectedSales.SelectMany((Sale sale) => sale.Items ?? new List<SoldLine>()).Sum((SoldLine item) => item.Quantity);
			decimal num3 = ((selectedSales.Count > 0) ? (num / (decimal)selectedSales.Count) : 0m);
			decimal num4 = ((selectedSales.Count > 0) ? ((decimal)num2 / (decimal)selectedSales.Count) : 0m);
			IGrouping<string, SoldLine> grouping = (from item in selectedSales.SelectMany((Sale sale) => sale.Items ?? new List<SoldLine>())
				group item by item.Product into g
				orderby g.Sum((SoldLine i) => i.UnitPrice * (decimal)i.Quantity) descending
				select g).FirstOrDefault();
			IGrouping<string, Sale> grouping2 = (from sale in selectedSales
				group sale by sale.Table into g
				orderby g.Sum((Sale s) => s.Total) descending
				select g).FirstOrDefault();
			IGrouping<string, Sale> grouping3 = (from sale in selectedSales
				group sale by sale.Operator into g
				orderby g.Sum((Sale s) => s.Total) descending
				select g).FirstOrDefault();
			IGrouping<int, Sale> grouping4 = (from sale in selectedSales
				group sale by sale.Time.Hour into g
				orderby g.Sum((Sale s) => s.Total) descending
				select g).FirstOrDefault();
			AddLine("Total Revenue", num.ToString("C"));
			AddLine("Total Transactions", selectedSales.Count.ToString());
			AddLine("Total Items Sold", num2.ToString());
			AddLine("Average Sale", num3.ToString("C"));
			AddLine("Average Items/Sale", num4.ToString("F1"));
			panel.Controls.Add(new Label
			{
				Text = "",
				AutoSize = true,
				Margin = new Padding(0, 8, 0, 8)
			});
			AddLine("Top Product", (grouping != null) ? $"{grouping.Key} ({grouping.Sum((SoldLine i) => i.Quantity)}x)" : "N/A");
			AddLine("Top Table", (grouping2 != null) ? $"{grouping2.Key} ({grouping2.Count()} sales)" : "N/A");
			AddLine("Top Operator", (grouping3 != null) ? $"{grouping3.Key} ({grouping3.Count()} sales)" : "N/A");
			AddLine("Peak Hour", (grouping4 != null) ? $"{grouping4.Key:D2}:00 ({grouping4.Count()} sales)" : "N/A");
			tabPage.Controls.Add(panel);
			return tabPage;
			void AddLine(string label, string value)
			{
				FlowLayoutPanel flowLayoutPanel = new FlowLayoutPanel
				{
					FlowDirection = FlowDirection.LeftToRight,
					WrapContents = false,
					AutoSize = true,
					Margin = new Padding(0, 4, 0, 4)
				};
				flowLayoutPanel.Controls.Add(new Label
				{
					Text = label,
					AutoSize = true,
					ForeColor = Skin.TextDim,
					MinimumSize = new Size(200, 0)
				});
				flowLayoutPanel.Controls.Add(new Label
				{
					Text = value,
					AutoSize = true,
					ForeColor = Skin.Text,
					Font = new Font("Segoe UI Semibold", 10f)
				});
				panel.Controls.Add(flowLayoutPanel);
			}
		}
	}

