internal static class CatalogImageStore
	{
		private const int ThumbMaxWidth = 480;
		private static readonly Dictionary<string, (long Ticks, byte[] Bytes)> thumbCache = new Dictionary<string, (long, byte[])>();
		private static readonly Dictionary<string, (long Ticks, Bitmap Bmp)> bmpCache = new Dictionary<string, (long, Bitmap)>();

		public static string Root { get; private set; } = Path.Combine(AppContext.BaseDirectory, "images");
		public static string LegacyRoot { get; } = Path.Combine(AppContext.BaseDirectory, "images");

		public static void Configure(string dataFolder)
		{
			Root = Path.Combine(dataFolder, "images");
			try
			{
				Directory.CreateDirectory(Root);
			}
			catch
			{
			}
		}

		public static string? Import()
		{
			using OpenFileDialog openFileDialog = new OpenFileDialog
			{
				Title = "Import catalog image",
				Filter = "Image files|*.png;*.jpg;*.jpeg;*.bmp;*.gif|All files|*.*",
				CheckFileExists = true
			};
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return null;
			}
			string fileName = Guid.NewGuid().ToString("N") + Path.GetExtension(openFileDialog.FileName);
			string destDir = Root;
			try
			{
				Directory.CreateDirectory(destDir);
			}
			catch
			{
				destDir = LegacyRoot;
				Directory.CreateDirectory(destDir);
			}
			string targetPath = Path.Combine(destDir, fileName);
			File.Copy(openFileDialog.FileName, targetPath, overwrite: true);
			return fileName;
		}

		public static string? Resolve(string? stored)
		{
			if (string.IsNullOrWhiteSpace(stored))
			{
				return null;
			}
			if (Path.IsPathRooted(stored) && File.Exists(stored))
			{
				return stored;
			}
			string fileName = Path.GetFileName(stored);
			if (fileName.Length == 0)
			{
				return null;
			}
			string candidate = Path.Combine(Root, fileName);
			if (File.Exists(candidate))
			{
				return candidate;
			}
			candidate = Path.Combine(LegacyRoot, fileName);
			if (File.Exists(candidate))
			{
				return candidate;
			}
			return null;
		}

		public static string Name(string? stored)
		{
			if (string.IsNullOrWhiteSpace(stored))
			{
				return "";
			}
			string? resolved = Resolve(stored);
			return (resolved != null) ? Path.GetFileName(resolved) : "";
		}

		public static Bitmap? LoadBitmap(string? stored)
		{
			string? path = Resolve(stored);
			if (path == null)
			{
				return null;
			}
			lock (bmpCache)
			{
				try
				{
					FileInfo fi = new FileInfo(path);
					if (!fi.Exists)
					{
						return null;
					}
					if (bmpCache.TryGetValue(path, out var hit) && hit.Ticks == fi.LastWriteTimeUtc.Ticks)
					{
						return hit.Bmp;
					}
					using Image original = Image.FromFile(path);
					Bitmap bmp = new Bitmap(original);
					bmpCache[path] = (fi.LastWriteTimeUtc.Ticks, bmp);
					if (bmpCache.Count > 64)
					{
						bmpCache.Clear();
					}
					return bmp;
				}
				catch
				{
					return null;
				}
			}
		}

		public static byte[]? Thumbnail(string fileOrName)
		{
			string? file = Resolve(fileOrName) ?? (File.Exists(fileOrName) ? fileOrName : null);
			if (file == null)
			{
				return null;
			}
			lock (thumbCache)
			{
				try
				{
					FileInfo fileInfo = new FileInfo(file);
					if (!fileInfo.Exists)
					{
						return null;
					}
					if (thumbCache.TryGetValue(file, out (long, byte[]) value) && value.Item1 == fileInfo.LastWriteTimeUtc.Ticks)
					{
						return value.Item2;
					}
					using Image image = Image.FromFile(file);
					int num = image.Width;
					int num2 = image.Height;
					if (num > 480)
					{
						num2 = Math.Max(1, (int)((double)num2 * (480.0 / (double)num)));
						num = 480;
					}
					using Bitmap bitmap = new Bitmap(num, num2);
					using (Graphics graphics = Graphics.FromImage(bitmap))
					{
						graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
						graphics.SmoothingMode = SmoothingMode.HighQuality;
						graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;
						graphics.DrawImage(image, 0, 0, num, num2);
					}
					using MemoryStream memoryStream = new MemoryStream();
					bitmap.Save(memoryStream, ImageFormat.Jpeg);
					byte[] array = memoryStream.ToArray();
					thumbCache[file] = (fileInfo.LastWriteTimeUtc.Ticks, array);
					if (thumbCache.Count > 128)
					{
						thumbCache.Clear();
					}
					return array;
				}
				catch
				{
					return null;
				}
			}
		}
	}
internal static class RawPrinter
	{
		[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
		internal sealed class DocumentInfo
		{
			[MarshalAs(UnmanagedType.LPWStr)]
			public string DocumentName = string.Empty;

			[MarshalAs(UnmanagedType.LPWStr)]
			public string? OutputFile;

			[MarshalAs(UnmanagedType.LPWStr)]
			public string? DataType;
		}

		internal static byte[] ImageToEscPosBytes(Bitmap bmp)
		{
			int width = bmp.Width;
			int height = bmp.Height;
			int num = (width + 7) / 8;
			List<byte> list = new List<byte>();
			list.AddRange(new byte[4] { 29, 118, 48, 0 });
			list.Add((byte)(num & 0xFF));
			list.Add((byte)((num >> 8) & 0xFF));
			list.Add((byte)(height & 0xFF));
			list.Add((byte)((height >> 8) & 0xFF));
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < num; j++)
				{
					byte b = 0;
					for (int k = 0; k < 8; k++)
					{
						int num2 = j * 8 + k;
						if (num2 < width && bmp.GetPixel(num2, i).GetBrightness() < 0.5f)
						{
							b |= (byte)(128 >> k);
						}
					}
					list.Add(b);
				}
			}
			return list.ToArray();
		}

		[DllImport("winspool.drv", CharSet = CharSet.Unicode, EntryPoint = "OpenPrinterW", SetLastError = true)]
		internal static extern bool OpenPrinterLocal(string printerName, out IntPtr printer, IntPtr defaults);

		[DllImport("winspool.drv", SetLastError = true)]
		internal static extern bool ClosePrinter(IntPtr printer);

		[DllImport("winspool.drv", SetLastError = true)]
		internal static extern bool StartDocPrinter(IntPtr printer, int level, [In] DocumentInfo documentInfo);

		[DllImport("winspool.drv", SetLastError = true)]
		internal static extern bool EndDocPrinter(IntPtr printer);

		[DllImport("winspool.drv", SetLastError = true)]
		internal static extern bool StartPagePrinter(IntPtr printer);

		[DllImport("winspool.drv", SetLastError = true)]
		internal static extern bool EndPagePrinter(IntPtr printer);

		[DllImport("winspool.drv", SetLastError = true)]
		internal static extern bool WritePrinter(IntPtr printer, byte[] data, int count, out int written);

		public static void PrintTicket(PrinterDestination destination, string room, string table, string operatorName, List<SoldLine> lines, string? printerName = null, int orderNumber = 0, int billNumber = 0, int paymentNumber = 0, string orderType = "", decimal discountPercent = 0m, decimal discountAmount = 0m)
		{
			string text = printerName ?? destination.WindowsPrinter;
			if (!OpenPrinterLocal(text, out var printer, (IntPtr)0))
			{
				throw new InvalidOperationException("Windows printer '" + text + "' could not be opened.");
			}
			DocumentInfo documentInfo = new DocumentInfo
			{
				DocumentName = "Vectron POS ticket",
				OutputFile = null,
				DataType = null
			};
			try
			{
				if (!StartDocPrinter(printer, 1, documentInfo))
				{
					throw new InvalidOperationException($"The printer rejected the raw ticket job (Windows error {Marshal.GetLastWin32Error()}).");
				}
				if (!StartPagePrinter(printer))
				{
					throw new InvalidOperationException("The printer page could not be started.");
				}
				MemoryStream stream = new MemoryStream();
				try
				{
					Write("\u001b@");
					foreach (TicketComponentStyle item in TicketLayout.Components(destination))
					{
						if (item.Component == "Cutter")
						{
							Write("\u001bd\u0005\u001dV\0");
						}
						else if (item.Component == "Blank line")
						{
							stream.WriteByte(10);
						}
						else
						{
							if (item.Component == "Logo" && (string.IsNullOrWhiteSpace(destination.LogoPath) || !File.Exists(destination.LogoPath)))
							{
								continue;
							}
							string text2 = null;
							if (item.Component != "Logo")
							{
								text2 = TicketLayout.Text(item.Component, destination, room, table, operatorName, lines, orderNumber, billNumber, paymentNumber, orderType, discountPercent, discountAmount);
								if (string.IsNullOrWhiteSpace(text2))
								{
									continue;
								}
							}
							string alignment = item.Alignment;
							string s;
							if (alignment == "Center")
							{
								s = "\u001ba\u0001";
							}
							else
							{
								s = ((!(alignment == "Right")) ? "\u001ba\0" : "\u001ba\u0002");
							}
							Write(s);
							int fontSize = item.FontSize;
							var (b, b2) = ((byte, byte))((fontSize >= 22) ? ((fontSize >= 32) ? (4, 4) : ((fontSize < 26) ? (3, 2) : (3, 3))) : ((fontSize >= 15) ? ((fontSize < 18) ? (2, 1) : (2, 2)) : ((fontSize < 12) ? (1, 1) : (1, 2))));
							Write($"\u001d!{(char)b2}{(char)b}");
							Write("\u001b-" + (item.Underline ? '\u0001' : '\0'));
							if (item.Bold)
							{
								Write("\u001bE\u0001");
							}
							stream.WriteByte(10);
							if (item.Component == "Logo")
							{
								using Image image = Image.FromFile(destination.LogoPath);
								int num = ((item.FontSize >= 32) ? 576 : 384);
								double num2 = (double)num / (double)image.Width;
								int width = Math.Min((int)((double)image.Width * num2), num);
								int height = (int)((double)image.Height * num2);
								using Bitmap bmp = new Bitmap(image, new Size(width, height));
								byte[] array = ImageToEscPosBytes(bmp);
								stream.Write(array, 0, array.Length);
							}
							else
							{
								Write(text2);
							}
							stream.WriteByte(10);
							if (item.Bold)
							{
								Write("\u001bE\0");
							}
							Write("\u001b-\0");
							Write("\u001d!\u0001\u0001");
							Write("\u001ba\0");
						}
					}
					if (!TicketLayout.Components(destination).Any((TicketComponentStyle ticketComponentStyle) => ticketComponentStyle.Component == "Cutter") && destination.CutAfterPrint)
					{
						Write("\u001bd\u0005\u001dV\0");
					}
					byte[] array2 = stream.ToArray();
					if (!WritePrinter(printer, array2, array2.Length, out var written) || written != array2.Length)
					{
						throw new InvalidOperationException("The printer did not accept the complete ticket.");
					}
					EndPagePrinter(printer);
					EndDocPrinter(printer);
				}
				finally
				{
					if (stream != null)
					{
						((IDisposable)stream).Dispose();
					}
				}
				void Write(string s2)
				{
					stream.Write(Encoding.ASCII.GetBytes(s2), 0, Encoding.ASCII.GetByteCount(s2));
				}
			}
			finally
			{
				ClosePrinter(printer);
			}
		}
	}

internal static class TcpPrintServer
	{
		private static TcpListener? listener;

		private static CancellationTokenSource? cts;

		public static bool IsRunning { get; private set; }

		public static string LocalIp { get; private set; } = "";

		public static void Start(int port = 9100)
		{
			Stop();
			try
			{
				LocalIp = GetLocalIpAddress();
			}
			catch
			{
			}
			try
			{
				cts = new CancellationTokenSource();
				listener = new TcpListener(IPAddress.Any, port);
				try
				{
					listener.Server.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, true);
				}
				catch { }
				listener.Start();
				IsRunning = true;
				Task.Run(() => AcceptLoop(cts.Token));
			}
			catch
			{
				IsRunning = false;
			}
		}

		public static void Stop()
		{
			cts?.Cancel();
			listener?.Stop();
			listener = null;
			IsRunning = false;
		}

		private static string GetLocalIpAddress()
		{
			try
			{
				using Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
				socket.Connect("8.8.8.8", 80);
				return ((IPEndPoint)socket.LocalEndPoint).Address.ToString();
			}
			catch
			{
				return "127.0.0.1";
			}
		}

		private static async Task AcceptLoop(CancellationToken token)
		{
			while (!token.IsCancellationRequested)
			{
				try
				{
					TcpClient client = await listener.AcceptTcpClientAsync();
					Task.Run(() => HandleClient(client), token);
				}
				catch (OperationCanceledException)
				{
					break;
				}
				catch
				{
				}
			}
		}

		private static async Task HandleClient(TcpClient client)
		{
			try
			{
				BinaryReader binaryReader = new BinaryReader(client.GetStream(), Encoding.UTF8, leaveOpen: true);
				while (client.Connected)
				{
					string printerName = binaryReader.ReadString();
					int count = binaryReader.ReadInt32();
					byte[] array = binaryReader.ReadBytes(count);
					if (RawPrinter.OpenPrinterLocal(printerName, out var printer, (IntPtr)0))
					{
						RawPrinter.DocumentInfo documentInfo = new RawPrinter.DocumentInfo
						{
							DocumentName = "Remote print",
							OutputFile = null,
							DataType = null
						};
						try
						{
							RawPrinter.StartDocPrinter(printer, 1, documentInfo);
							RawPrinter.StartPagePrinter(printer);
							RawPrinter.WritePrinter(printer, array, array.Length, out var _);
							RawPrinter.EndPagePrinter(printer);
							RawPrinter.EndDocPrinter(printer);
						}
						finally
						{
							RawPrinter.ClosePrinter(printer);
						}
					}
				}
			}
			catch
			{
			}
			finally
			{
				client.Close();
			}
		}
	}

internal static class TcpPrintClient
	{
		private static TcpClient? persistentClient;

		private static NetworkStream? persistentStream;

		private static BinaryWriter? persistentWriter;

		private static readonly object lockObj = new object();

		private static string lastHost = "";

		private static void EnsureConnected(string serverHost)
		{
			if (persistentClient != null && persistentClient.Connected && lastHost == serverHost)
			{
				return;
			}
			lock (lockObj)
			{
				persistentClient?.Close();
				persistentClient = new TcpClient();
				persistentClient.NoDelay = true;
				persistentClient.Connect(serverHost, 9100);
				persistentStream = persistentClient.GetStream();
				persistentWriter = new BinaryWriter(persistentStream, Encoding.UTF8, leaveOpen: true);
				lastHost = serverHost;
			}
		}

		public static void SendPrintJob(string serverHost, string printerName, byte[] data)
		{
			lock (lockObj)
			{
				try
				{
					EnsureConnected(serverHost);
					persistentWriter.Write(printerName);
					persistentWriter.Write(data.Length);
					persistentWriter.Write(data);
					persistentWriter.Flush();
				}
				catch
				{
					persistentClient?.Close();
					persistentClient = null;
					throw;
				}
			}
		}
	}

