		private void LoadDestination()
		{
			if (selectedIndex >= 0 && selectedIndex < destinations.Count && selectedIndex != this.list.SelectedIndex)
			{
				PrinterDestination printerDestination = destinations[selectedIndex];
				string text = windowsPrinter.SelectedItem?.ToString() ?? printerDestination.WindowsPrinter;
				if (printerDestination.Name == "Cancel")
				{
					destinations[selectedIndex] = new PrinterDestination("Cancel", "", ticketHeader.Text.Trim(), ticketFooter.Text.Trim(), cutAfterPrint.Checked, printerDestination.Layout, printerDestination.LogoPath);
				}
				else if (printerDestination.Name == "Payment")
				{
					destinations[selectedIndex] = new PrinterDestination("Payment", text, ticketHeader.Text.Trim(), ticketFooter.Text.Trim(), cutAfterPrint.Checked, printerDestination.Layout, printerDestination.LogoPath);
				}
				else if (printerDestination.Name == "Refund")
				{
					List<PrinterDestination> list = destinations;
					int index = selectedIndex;
					PrinterDestination printerDestination2 = printerDestination._003CClone_003E_0024();
					printerDestination2.Header = ticketHeader.Text.Trim();
					printerDestination2.Footer = ticketFooter.Text.Trim();
					printerDestination2.CutAfterPrint = cutAfterPrint.Checked;
					list[index] = printerDestination2;
				}
				else
				{
					string text2 = ((name.Enabled && !string.IsNullOrWhiteSpace(name.Text)) ? name.Text.Trim() : printerDestination.Name);
					destinations[selectedIndex] = new PrinterDestination(text2, text, ticketHeader.Text.Trim(), ticketFooter.Text.Trim(), cutAfterPrint.Checked, printerDestination.Layout, printerDestination.LogoPath);
				}
				this.list.Items[selectedIndex] = destinations[selectedIndex].Name;
				if (printerDestination.Name == "Payment")
				{
					MirrorRefundFromPayment();
				}
			}
			if (this.list.SelectedIndex >= 0 && this.list.SelectedIndex < destinations.Count)
			{
				selectedIndex = this.list.SelectedIndex;
				if (destinations[selectedIndex].Name == "Refund")
				{
					MirrorRefundFromPayment();
				}
				PrinterDestination printerDestination3 = destinations[selectedIndex];
				bool flag = printerDestination3.Name == "Cancel";
				name.Text = printerDestination3.Name;
				TextBox textBox = name;
				bool flag2;
				switch (printerDestination3.Name)
				{
				case "Cancel":
				case "Bill":
				case "Payment":
				case "Refund":
					flag2 = true;
					break;
				default:
					flag2 = false;
					break;
				}
				textBox.Enabled = !flag2;
				windowsPrinter.Enabled = printerDestination3.Name != "Refund";
				printerLabel.Visible = !flag;
				windowsPrinter.Visible = !flag;
				headerLabel.Visible = true;
				ticketHeader.Visible = true;
				footerLabel.Visible = true;
				ticketFooter.Visible = true;
				cutAfterPrint.Visible = true;
				if (!flag)
				{
					int num = (string.IsNullOrWhiteSpace(printerDestination3.WindowsPrinter) ? (-1) : windowsPrinter.Items.IndexOf(printerDestination3.WindowsPrinter));
					windowsPrinter.SelectedIndex = ((num >= 0) ? num : (-1));
				}
				ticketHeader.Text = printerDestination3.Header;
				ticketFooter.Text = printerDestination3.Footer;
				cutAfterPrint.Checked = printerDestination3.CutAfterPrint;
				editLayout.Enabled = this.list.SelectedIndex >= 0;
			}
		}

		private void AddDestination()
		{
			string text = ((windowsPrinter.Items.Count > 0) ? (Convert.ToString(windowsPrinter.Items[0]) ?? "") : "");
