		private void DeleteDestination()
		{
			if (selectedIndex < 0)
			{
				return;
			}
			bool flag;
			switch (destinations[selectedIndex].Name)
			{
			case "Cancel":
			case "Bill":
			case "Payment":
			case "Refund":
				flag = true;
				break;
			default:
				flag = false;
				break;
			}
			if (!flag)
			{
				destinations.RemoveAt(selectedIndex);
				list.Items.RemoveAt(selectedIndex);
				selectedIndex = -1;
				if (destinations.Count > 0)
				{
					list.SelectedIndex = 0;
				}
			}
		}

		private void SaveDestination()
		{
			if (selectedIndex >= 0 && selectedIndex < destinations.Count)
			{
				PrinterDestination printerDestination = destinations[selectedIndex];
				if (printerDestination.Name == "Cancel")
				{
					destinations[selectedIndex] = new PrinterDestination("Cancel", "", ticketHeader.Text.Trim(), ticketFooter.Text.Trim(), cutAfterPrint.Checked, printerDestination.Layout, printerDestination.LogoPath);
				}
				else if (printerDestination.Name == "Payment")
				{
