				}
				else
				{
					string text = ((name.Enabled && !string.IsNullOrWhiteSpace(name.Text)) ? name.Text.Trim() : printerDestination.Name);
					destinations[selectedIndex] = new PrinterDestination(text, windowsPrinter.SelectedItem?.ToString() ?? printerDestination.WindowsPrinter, ticketHeader.Text.Trim(), ticketFooter.Text.Trim(), cutAfterPrint.Checked, printerDestination.Layout, printerDestination.LogoPath);
				}
				this.list.Items[selectedIndex] = destinations[selectedIndex].Name;
			}
			MirrorRefundFromPayment();
			save(destinations);
		}

		private void MirrorRefundFromPayment()
		{
			PrinterDestination printerDestination = destinations.FirstOrDefault((PrinterDestination d) => d.Name == "Payment");
			if (!(printerDestination == null))
			{
				int num = destinations.FindIndex((PrinterDestination d) => d.Name == "Refund");
				if (num >= 0)
				{
					List<PrinterDestination> list = destinations;
					PrinterDestination printerDestination2 = destinations[num]._003CClone_003E_0024();
					printerDestination2.WindowsPrinter = printerDestination.WindowsPrinter;
					list[num] = printerDestination2;
				}
			}
		}

