		{
			if (selectedIndex < 0)
			{
				return;
			}
			PrinterDestination current = destinations[selectedIndex];
			Control control = Parent;
			while (control != null && (!(control is Panel) || control.Dock != DockStyle.Fill || !control.Visible))
			{
				control = control.Parent;
