			Panel viewPanel = control as Panel;
			if (viewPanel == null)
			{
				using (TicketDesignerForm ticketDesignerForm = new TicketDesignerForm(BackColor, Skin.PanelLight, Skin.Accent, current, (List<TicketComponentStyle> components, string logo) =>
				{
					List<PrinterDestination> list = destinations;
					int index = selectedIndex;
					PrinterDestination printerDestination = current._003CClone_003E_0024();
					printerDestination.Layout = components;
					printerDestination.LogoPath = logo;
					list[index] = printerDestination;
					save(destinations);
					saveLayout(current, components);
				}))
				{
					ticketDesignerForm.ShowDialog(this);
					return;
				}
			}
			Panel panel = new Panel
			{
				Dock = DockStyle.Fill
			};
			TicketDesignerForm ticketDesignerForm2 = new TicketDesignerForm(BackColor, Skin.PanelLight, Skin.Accent, current, (List<TicketComponentStyle> components, string logo) =>
			{
				List<PrinterDestination> list = destinations;
				int index = selectedIndex;
				PrinterDestination printerDestination = current._003CClone_003E_0024();
				printerDestination.Layout = components;
				printerDestination.LogoPath = logo;
				list[index] = printerDestination;
				save(destinations);
				saveLayout(current, components);
				viewPanel.Controls.Clear();
				viewPanel.Controls.Add(this);
				Dock = DockStyle.Fill;
			});
			ticketDesignerForm2.TopLevel = false;
			ticketDesignerForm2.FormBorderStyle = FormBorderStyle.None;
			ticketDesignerForm2.Dock = DockStyle.Fill;
			panel.Controls.Add(ticketDesignerForm2);
			ticketDesignerForm2.Show();
			viewPanel.Controls.Clear();
			Panel panel2 = new Panel
			{
				Dock = DockStyle.Top,
				Height = 56,
				BackColor = Skin.Panel,
				Padding = new Padding(16, 0, 16, 0)
			};
			Label value = new Label
			{
				Text = Tr.T("Edit ticket layout"),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 16f),
				ForeColor = Skin.Text,
				Location = new Point(16, 14)
			};
			Button button = new Button
			{
				Text = Tr.T("← Back"),
				Size = new Size(100, 34),
				BackColor = Skin.PanelLight,
				ForeColor = Skin.Text,
				FlatStyle = FlatStyle.Flat,
				Anchor = (AnchorStyles.Top | AnchorStyles.Right)
			};
			button.FlatAppearance.BorderSize = 0;
			button.Click += (object _, EventArgs _) =>
			{
				viewPanel.Controls.Clear();
				viewPanel.Controls.Add(this);
				Dock = DockStyle.Fill;
			};
			panel2.Controls.Add(value);
			panel2.Controls.Add(button);
			viewPanel.Controls.Add(panel);
			viewPanel.Controls.Add(panel2);
		}

