		private void LoadComponents()
		{
			componentList.Items.Clear();
			selectedComponentIndex = -1;
			if (destinationPicker.SelectedIndex < 0 || destinationPicker.SelectedIndex >= destinations.Count)
			{
				return;
			}
			foreach (TicketComponentStyle style in TicketLayout.Components(destinations[destinationPicker.SelectedIndex]))
			{
				(string, int) tuple = Array.Find(FontSizes, ((string Name, int Size) s) => s.Size == style.FontSize);
				componentList.Items.Add(string.Format("[{0}] {1}{2}{3}  {4}", style.Alignment[0], style.Bold ? "B " : "", style.Underline ? "U " : "", tuple.Item1 ?? "Small", style.Component));
			}
			if (componentList.Items.Count > 0)
			{
				componentList.SelectedIndex = 0;
			}
		}

		private void LoadComponentStyle()
		{
			if (destinationPicker.SelectedIndex < 0 || destinationPicker.SelectedIndex >= destinations.Count)
			{
				return;
			}
			if (componentList.SelectedIndex < 0)
			{
				selectedComponentIndex = -1;
				return;
			}
			selectedComponentIndex = componentList.SelectedIndex;
			List<TicketComponentStyle> list = TicketLayout.Components(destinations[destinationPicker.SelectedIndex]);
			if (selectedComponentIndex < list.Count)
			{
				TicketComponentStyle style = list[selectedComponentIndex];
				int num = Array.FindIndex(FontSizes, ((string Name, int Size) s) => s.Size == style.FontSize);
				fontSize.SelectedIndex = ((num >= 0) ? num : 0);
				boldBox.Checked = style.Bold;
				underlineBox.Checked = style.Underline;
				alignmentBox.SelectedItem = style.Alignment;
				previewPanel.Invalidate();
			}
		}

		private void ApplyStyle()
		{
			if (selectedComponentIndex >= 0 && destinationPicker.SelectedIndex >= 0 && destinationPicker.SelectedIndex < destinations.Count)
			{
				PrinterDestination printerDestination = destinations[destinationPicker.SelectedIndex];
				List<TicketComponentStyle> list = TicketLayout.Components(printerDestination).ToList();
				if (selectedComponentIndex < list.Count)
				{
					TicketComponentStyle ticketComponentStyle = list[selectedComponentIndex];
					int num = ((fontSize.SelectedIndex >= 0) ? FontSizes[fontSize.SelectedIndex].Size : 10);
					string text = ((fontSize.SelectedIndex >= 0) ? FontSizes[fontSize.SelectedIndex].Name : "Small");
					list[selectedComponentIndex] = new TicketComponentStyle(ticketComponentStyle.Component, num, boldBox.Checked, underlineBox.Checked, alignmentBox.SelectedItem?.ToString() ?? "Left");
					List<PrinterDestination> list2 = destinations;
					int selectedIndex = destinationPicker.SelectedIndex;
					PrinterDestination printerDestination2 = printerDestination._003CClone_003E_0024();
					printerDestination2.Layout = list;
					list2[selectedIndex] = printerDestination2;
					componentList.Items[selectedComponentIndex] = string.Format("[{0}] {1}{2}{3}  {4}", (alignmentBox.SelectedItem?.ToString() ?? "Left")[0], boldBox.Checked ? "B " : "", underlineBox.Checked ? "U " : "", text, ticketComponentStyle.Component);
					previewPanel.Invalidate();
				}
			}
		}

		private void DrawPreview(object? sender, PaintEventArgs e)
		{
			Graphics graphics = e.Graphics;
			graphics.Clear(Color.White);
			if (selectedComponentIndex < 0 || destinationPicker.SelectedIndex < 0 || destinationPicker.SelectedIndex >= destinations.Count)
			{
				return;
			}
			PrinterDestination destination = destinations[destinationPicker.SelectedIndex];
			List<TicketComponentStyle> list = TicketLayout.Components(destination);
			if (selectedComponentIndex >= list.Count)
			{
				return;
			}
			TicketComponentStyle ticketComponentStyle = list[selectedComponentIndex];
			List<SoldLine> lines = new List<SoldLine>
			{
				new SoldLine("Margherita", "Food", 2, 12.50m, "Mains")
			};
			string text = TicketLayout.Text(ticketComponentStyle.Component, destination, "Room 1", "Table 5", "Manager", lines, 0, 0, 0, "", 10m, 2.50m);
			if (string.IsNullOrEmpty(text))
			{
				graphics.DrawString("(empty)", new Font("Consolas", 9f), Brushes.Gray, 10f, 10f);
				return;
			}
			FontStyle fontStyle = FontStyle.Regular;
			if (ticketComponentStyle.Bold)
			{
				fontStyle |= FontStyle.Bold;
			}
			if (ticketComponentStyle.Underline)
			{
				fontStyle |= FontStyle.Underline;
			}
			using Font font = new Font("Consolas", Math.Min(ticketComponentStyle.FontSize, 20), fontStyle);
			SizeF sizeF = graphics.MeasureString(text, font, previewPanel.ClientSize.Width - 20);
			string alignment = ticketComponentStyle.Alignment;
			float num;
			if (alignment == "Center")
			{
				num = ((float)previewPanel.ClientSize.Width - sizeF.Width) / 2f;
			}
			else
			{
				num = ((!(alignment == "Right")) ? 10f : ((float)previewPanel.ClientSize.Width - sizeF.Width - 10f));
			}
			float num2 = num;
			graphics.DrawString(text, font, Brushes.Black, new RectangleF(num2, 10f, previewPanel.ClientSize.Width - 20, sizeF.Height));
		}

		protected override void Back()
		{
			save(destinations);
			base.Back();
		}
	}

