    private void PopulateList()
    {
        lv.Items.Clear();
        string q = searchBox.Text.Trim().ToLowerInvariant();
        var items = store.Ingredients
            .Where(i => string.IsNullOrEmpty(q) || i.Name.ToLowerInvariant().Contains(q) || i.Supplier.ToLowerInvariant().Contains(q))
            .ToList();

        foreach (var ing in items)
        {
            var lvi = new ListViewItem(new[]
            {
                ing.Name,
                ing.Unit,
                ing.Stock.ToString("0.##"),
                ing.MinStock.ToString("0.##"),
                ing.Cost.ToString("C"),
                ing.Supplier
            });
            lvi.Tag = ing;
            if (ing.MinStock > 0m && ing.Stock <= ing.MinStock)
            {
                lvi.ForeColor = Skin.Warning;
            }
            if (ing.Expiry.HasValue && ing.Expiry.Value.Date < DateTime.Today)
            {
                lvi.ForeColor = Skin.DangerText;
            }
            lv.Items.Add(lvi);
        }
    }

    private void LoadSelected()
    {
        if (lv.SelectedItems.Count == 0) return;
        if (lv.SelectedItems[0].Tag is Ingredient ing)
        {
            selectedIndex = store.Ingredients.FindIndex(i => string.Equals(i.Name, ing.Name, StringComparison.OrdinalIgnoreCase));
            nameBox.Text = ing.Name;
            unitCombo.SelectedItem = ing.Unit;
            if (unitCombo.SelectedIndex < 0 && unitCombo.Items.Count > 0) unitCombo.SelectedIndex = 0;
            stockNum.Value = ing.Stock;
            minStockNum.Value = ing.MinStock;
            costNum.Value = ing.Cost;
            supplierCombo.Text = ing.Supplier;
            locationCombo.Text = ing.Location;
            barcodeBox.Text = ing.Barcode;
            if (ing.Expiry.HasValue)
            {
                hasExpiry.Checked = true;
                expiryPicker.Value = ing.Expiry.Value;
            }
            else
            {
                hasExpiry.Checked = false;
            }
            statusLabel.Text = "";
        }
    }

    private void NewIngredient()
    {
        selectedIndex = -1;
        nameBox.Text = Tr.T("New ingredient");
        unitCombo.SelectedIndex = 0;
        stockNum.Value = 0m;
        minStockNum.Value = 0m;
        costNum.Value = 0m;
        supplierCombo.Text = "";
        locationCombo.Text = "";
        barcodeBox.Text = "";
        hasExpiry.Checked = false;
        nameBox.Focus();
        nameBox.SelectAll();
    }

    private void SaveIngredient()
    {
        string name = nameBox.Text.Trim();
        if (string.IsNullOrWhiteSpace(name)) return;

        string unit = unitCombo.SelectedItem?.ToString() ?? "pcs";
        decimal stock = stockNum.Value;
        decimal min = minStockNum.Value;
        decimal cost = costNum.Value;
        string supplier = supplierCombo.Text.Trim();
        string location = locationCombo.Text.Trim();
        string barcode = barcodeBox.Text.Trim();
        DateTime? expiry = hasExpiry.Checked ? expiryPicker.Value.Date : (DateTime?)null;

        if (selectedIndex >= 0 && selectedIndex < store.Ingredients.Count)
        {
            var old = store.Ingredients[selectedIndex];
            decimal delta = stock - old.Stock;
            if (delta != 0m)
            {
                store.StockMovements.Add(new StockMovement(DateTime.Now, "adjust", name, delta, stock, "Manual edit", "Admin"));
                store.SaveStockMovements(store.StockMovements);
            }
            store.Ingredients[selectedIndex] = new Ingredient(name, unit, stock, min, cost, expiry, supplier, location, barcode);
        }
        else
        {
            if (store.Ingredients.Any(i => string.Equals(i.Name, name, StringComparison.OrdinalIgnoreCase)))
            {
                MessageBox.Show(Tr.T("An ingredient with this name already exists."), Tr.T("Ingredient"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                return;
            }
            store.Ingredients.Add(new Ingredient(name, unit, stock, min, cost, expiry, supplier, location, barcode));
            if (stock > 0m)
            {
                store.StockMovements.Add(new StockMovement(DateTime.Now, "adjust", name, stock, stock, "Initial count", "Admin"));
                store.SaveStockMovements(store.StockMovements);
            }
        }

        store.SaveIngredients(store.Ingredients);
        onStockChanged?.Invoke();
        statusLabel.Text = Tr.T("Saved successfully!");
        PopulateList();
    }

    private void DeleteIngredient()
    {
        if (selectedIndex < 0 || selectedIndex >= store.Ingredients.Count) return;
        var ing = store.Ingredients[selectedIndex];

        // Check if ingredient is used in any recipes
        var usedIn = store.Recipes
            .Where(kv => kv.Value.Any(ri => string.Equals(ri.Ingredient, ing.Name, StringComparison.OrdinalIgnoreCase)))
            .Select(kv => kv.Key)
            .ToList();

        if (usedIn.Count > 0)
        {
            MessageBox.Show(Tr.T("Cannot delete this ingredient because it is used in recipes:") + "\n• " + string.Join("\n• ", usedIn),
                Tr.T("Ingredient in use"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        if (MessageBox.Show(Tr.T("Delete ingredient") + $" \"{ing.Name}\"?", Tr.T("Confirm delete"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
        {
            store.Ingredients.RemoveAt(selectedIndex);
            store.SaveIngredients(store.Ingredients);
            onStockChanged?.Invoke();
            selectedIndex = -1;
            NewIngredient();
            PopulateList();
        }
    }

    private void QuickAdjust()
    {
        if (selectedIndex < 0 || selectedIndex >= store.Ingredients.Count) return;
        var ing = store.Ingredients[selectedIndex];

        using (Form f = new Form())
        {
            f.Text = Tr.T("Stock adjust") + " — " + ing.Name;
            f.Size = new Size(360, 240);
            f.StartPosition = FormStartPosition.CenterParent;
            f.BackColor = Skin.Background;
            f.ForeColor = Skin.Text;
            f.Font = new Font("Segoe UI", 10f);
            f.FormBorderStyle = FormBorderStyle.FixedDialog;
            f.MaximizeBox = false;
            f.MinimizeBox = false;

            Label l1 = new Label { Text = Tr.T("Adjustment delta (+/-):"), Location = new Point(20, 20), AutoSize = true };
            NumericUpDown num = new NumericUpDown
            {
                Location = new Point(20, 46),
                Size = new Size(180, 28),
                DecimalPlaces = 2,
                Minimum = -999999m,
                Maximum = 999999m,
                Value = 0m,
                BackColor = Skin.PanelLight,
                ForeColor = Skin.Text
            };

            Label l2 = new Label { Text = Tr.T("Reason / Note:"), Location = new Point(20, 84), AutoSize = true };
            TextBox reason = new TextBox
            {
                Location = new Point(20, 108),
                Size = new Size(300, 28),
                Text = "Inventory correction",
                BackColor = Skin.PanelLight,
                ForeColor = Skin.Text,
                BorderStyle = BorderStyle.FixedSingle
            };

            Button ok = new Button
            {
                Text = Tr.T("Apply"),
                Location = new Point(20, 150),
                Size = new Size(100, 32),
                BackColor = Skin.Accent,
                ForeColor = Skin.OnAccent,
                FlatStyle = FlatStyle.Flat
            };
            ok.FlatAppearance.BorderSize = 0;
            ok.Click += (s, e) =>
            {
                if (num.Value != 0m)
                {
                    decimal newStock = Math.Max(0m, ing.Stock + num.Value);
                    ing.Stock = newStock;
                    store.StockMovements.Add(new StockMovement(DateTime.Now, "adjust", ing.Name, num.Value, newStock, reason.Text.Trim(), "Admin"));
                    store.SaveStockMovements(store.StockMovements);
                    store.SaveIngredients(store.Ingredients);
                    onStockChanged?.Invoke();
                }
                f.DialogResult = DialogResult.OK;
            };

            f.Controls.AddRange(new Control[] { l1, num, l2, reason, ok });
            f.AcceptButton = ok;
            if (f.ShowDialog() == DialogResult.OK)
            {
                stockNum.Value = ing.Stock;
                PopulateList();
            }
        }
    }
}


internal sealed class RecipeEditorForm : SettingsSubForm
{
