        kpiRow.Controls.AddRange(new Control[] { costLabel, foodCostPctLabel, marginLabel });
        editor.Controls.Add(kpiRow);

        // Ingredient items list
        linesList.Location = new Point(16, 130);
        linesList.Size = new Size(600, 260);
        linesList.BackColor = Skin.PanelLight;
        linesList.ForeColor = Skin.Text;
        linesList.View = View.Details;
        linesList.FullRowSelect = true;
        linesList.MultiSelect = false;
        linesList.BorderStyle = BorderStyle.None;
        linesList.Columns.Add(Tr.T("Ingredient"), 200);
        linesList.Columns.Add(Tr.T("Quantity"), 90);
        linesList.Columns.Add(Tr.T("Unit"), 70);
        linesList.Columns.Add(Tr.T("Unit Cost"), 90);
        linesList.Columns.Add(Tr.T("Line Cost"), 90);
        editor.Controls.Add(linesList);

        // Add line controls row
        Label lblAddIng = new Label { Text = Tr.T("Ingredient:"), Location = new Point(16, 400), AutoSize = true, Font = new Font("Segoe UI Semibold", 9f), ForeColor = Skin.TextDim };
        editor.Controls.Add(lblAddIng);

        ingCombo.Location = new Point(16, 422);
        ingCombo.Size = new Size(200, 28);
        ingCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        ingCombo.BackColor = Skin.PanelLight;
        ingCombo.ForeColor = Skin.Text;
        foreach (var ing in store.Ingredients) ingCombo.Items.Add(ing.Name);
        ingCombo.SelectedIndexChanged += (s, e) => UpdateUnitCombo();
