        Label lblQty = new Label { Text = Tr.T("Qty:"), Location = new Point(224, 400), AutoSize = true, Font = new Font("Segoe UI Semibold", 9f), ForeColor = Skin.TextDim };
        editor.Controls.Add(lblQty);

        qtyNum.Location = new Point(224, 422);
        qtyNum.Size = new Size(80, 28);
