        Label lblUnit = new Label { Text = Tr.T("Unit:"), Location = new Point(312, 400), AutoSize = true, Font = new Font("Segoe UI Semibold", 9f), ForeColor = Skin.TextDim };
        editor.Controls.Add(lblUnit);

        unitCombo.Location = new Point(312, 422);
        unitCombo.Size = new Size(80, 28);
        unitCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        unitCombo.BackColor = Skin.PanelLight;
        unitCombo.ForeColor = Skin.Text;
        unitCombo.SelectedIndexChanged += (s, e) => UpdateLineCostPreview();
        editor.Controls.Add(unitCombo);

        lineCostLabel.Location = new Point(400, 425);
        lineCostLabel.Size = new Size(80, 24);
        lineCostLabel.Font = new Font("Segoe UI", 9.5f);
        lineCostLabel.ForeColor = Skin.TextDim;
        lineCostLabel.Text = "";
        editor.Controls.Add(lineCostLabel);

        Button btnAdd = new Button
        {
            Text = Tr.T("+ Add"),
            Location = new Point(490, 420),
            Size = new Size(60, 30),
            BackColor = Skin.Accent,
            ForeColor = Skin.OnAccent,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI Semibold", 9.5f),
            Cursor = Cursors.Hand
        };
        btnAdd.FlatAppearance.BorderSize = 0;
        btnAdd.Click += (s, e) => AddLine();
        editor.Controls.Add(btnAdd);

        Button btnRemove = new Button
        {
            Text = Tr.T("Remove"),
            Location = new Point(555, 420),
            Size = new Size(65, 30),
            BackColor = Skin.SidebarItem,
            ForeColor = Skin.Text,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI Semibold", 9f),
            Cursor = Cursors.Hand
        };
        btnRemove.FlatAppearance.BorderSize = 0;
        btnRemove.Click += (s, e) => RemoveSelectedLine();
        editor.Controls.Add(btnRemove);

        // Status and Action buttons
        statusLabel.Location = new Point(16, 468);
        statusLabel.Size = new Size(340, 24);
        statusLabel.Font = new Font("Segoe UI Semibold", 9.5f);
        statusLabel.ForeColor = Skin.Accent;
        editor.Controls.Add(statusLabel);

        Button btnClear = new Button
        {
            Text = Tr.T("Clear recipe"),
            Location = new Point(370, 505),
            Size = new Size(110, 36),
            BackColor = Skin.DangerStrong,
            ForeColor = Skin.OnFill,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI Semibold", 9.5f),
            Cursor = Cursors.Hand
        };
        btnClear.FlatAppearance.BorderSize = 0;
        btnClear.Click += (s, e) => ClearRecipe();
        editor.Controls.Add(btnClear);

        Button btnSave = new Button
        {
            Text = Tr.T("Save recipe"),
            Location = new Point(490, 505),
            Size = new Size(130, 36),
            BackColor = Skin.Accent,
            ForeColor = Skin.OnAccent,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI Semibold", 10f),
            Cursor = Cursors.Hand
        };
        btnSave.FlatAppearance.BorderSize = 0;
        btnSave.Click += (s, e) => SaveRecipe();
        editor.Controls.Add(btnSave);

        Controls.AddRange(new Control[] { searchBox, productList, editor });

        if (ingCombo.Items.Count > 0) ingCombo.SelectedIndex = 0;
        PopulateProducts();

        if (!string.IsNullOrEmpty(selectProduct))
        {
            for (int i = 0; i < productList.Items.Count; i++)
            {
                if (productList.Items[i].ToString()?.StartsWith(selectProduct) == true)
                {
                    productList.SelectedIndex = i;
                    break;
                }
            }
        }
        else if (productList.Items.Count > 0)
        {
            productList.SelectedIndex = 0;
        }

        doneBtn.Click += (s, e) =>
        {
            SaveRecipe();
            Close();
        };

        ShiftBodyDown(72);
    }

    private void PopulateProducts()
    {
        productList.Items.Clear();
        string q = searchBox.Text.Trim().ToLowerInvariant();
        var prods = store.Products
            .Where(p => string.IsNullOrEmpty(q) || p.Name.ToLowerInvariant().Contains(q) || p.Category.ToLowerInvariant().Contains(q))
            .ToList();

        foreach (var p in prods)
        {
            bool hasRecipe = store.Recipes.TryGetValue(p.Name, out var rec) && rec.Count > 0;
            string prefix = hasRecipe ? "● " : "○ ";
            productList.Items.Add(prefix + p.Name);
        }
    }

    private void LoadSelectedProduct()
    {
        if (productList.SelectedIndex < 0) return;
        string itemText = productList.SelectedItem.ToString() ?? "";
        string name = itemText.StartsWith("● ") || itemText.StartsWith("○ ") ? itemText.Substring(2) : itemText;

        selectedProduct = store.Products.FirstOrDefault(p => string.Equals(p.Name, name, StringComparison.OrdinalIgnoreCase));
        if (selectedProduct == null) return;

        productTitle.Text = selectedProduct.Name;
        priceLabel.Text = Tr.T("Selling price:") + " " + selectedProduct.Price.ToString("C");
        portionsNum.Value = 1m;
        statusLabel.Text = "";

        currentLines.Clear();
        if (store.Recipes.TryGetValue(selectedProduct.Name, out var lines))
        {
            currentLines.AddRange(lines);
        }

        RenderLines();
        RecalculateSummary();
    }

    private void UpdateUnitCombo()
    {
        unitCombo.Items.Clear();
        string ingName = ingCombo.SelectedItem?.ToString() ?? "";
        var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ingName, StringComparison.OrdinalIgnoreCase));
        if (ing != null)
        {
            string[] comp = UnitMath.CompatibleUnits(ing.Unit);
            unitCombo.Items.AddRange(comp);
            unitCombo.SelectedItem = ing.Unit;
            if (unitCombo.SelectedIndex < 0 && unitCombo.Items.Count > 0) unitCombo.SelectedIndex = 0;
        }
        UpdateLineCostPreview();
    }

    private void UpdateLineCostPreview()
    {
        string ingName = ingCombo.SelectedItem?.ToString() ?? "";
        var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ingName, StringComparison.OrdinalIgnoreCase));
        if (ing != null)
        {
            decimal qty = qtyNum.Value;
            string u = unitCombo.SelectedItem?.ToString() ?? ing.Unit;
            var converted = UnitMath.Convert(qty, u, ing.Unit);
            decimal cost = (converted ?? qty) * ing.Cost;
            lineCostLabel.Text = cost.ToString("C");
        }
        else
        {
            lineCostLabel.Text = "";
        }
    }

    private void AddLine()
    {
        string ingName = ingCombo.SelectedItem?.ToString() ?? "";
        if (string.IsNullOrEmpty(ingName)) return;

        var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ingName, StringComparison.OrdinalIgnoreCase));
        if (ing == null) return;

        decimal qty = qtyNum.Value;
        string u = unitCombo.SelectedItem?.ToString() ?? ing.Unit;

        // Canonicalize to ingredient's unit
        var conv = UnitMath.Convert(qty, u, ing.Unit);
        if (conv.HasValue)
        {
            qty = conv.Value;
            u = ing.Unit;
        }

        int existing = currentLines.FindIndex(r => string.Equals(r.Ingredient, ingName, StringComparison.OrdinalIgnoreCase));
        if (existing >= 0)
        {
            currentLines[existing] = new RecipeItem(ingName, currentLines[existing].Quantity + qty, u);
        }
        else
        {
            currentLines.Add(new RecipeItem(ingName, qty, u));
        }

        RenderLines();
        RecalculateSummary();
    }

    private void RemoveSelectedLine()
    {
        if (linesList.SelectedIndices.Count == 0) return;
        int idx = linesList.SelectedIndices[0];
        if (idx >= 0 && idx < currentLines.Count)
        {
            currentLines.RemoveAt(idx);
            RenderLines();
            RecalculateSummary();
        }
    }

    private void ClearRecipe()
    {
        if (MessageBox.Show(Tr.T("Clear all recipe ingredients for this product?"), Tr.T("Clear recipe"), MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
        {
            currentLines.Clear();
            RenderLines();
            RecalculateSummary();
        }
    }

    private void RenderLines()
    {
        linesList.Items.Clear();
        foreach (var ri in currentLines)
        {
            var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ri.Ingredient, StringComparison.OrdinalIgnoreCase));
            decimal cost = ing != null ? (ri.Quantity * ing.Cost) : 0m;
            var lvi = new ListViewItem(new[]
            {
                ri.Ingredient,
                ri.Quantity.ToString("0.###"),
                string.IsNullOrEmpty(ri.Unit) ? (ing?.Unit ?? "") : ri.Unit,
                ing != null ? ing.Cost.ToString("C") : "—",
                cost.ToString("C")
            });
            linesList.Items.Add(lvi);
        }
    }

    private void RecalculateSummary()
    {
        if (selectedProduct == null) return;

        decimal totalCost = 0m;
        foreach (var ri in currentLines)
        {
            var ing = store.Ingredients.FirstOrDefault(i => string.Equals(i.Name, ri.Ingredient, StringComparison.OrdinalIgnoreCase));
            if (ing != null) totalCost += ri.Quantity * ing.Cost;
        }

        decimal portions = Math.Max(1m, portionsNum.Value);
        decimal perPortionCost = totalCost / portions;
        decimal price = selectedProduct.Price;

        costLabel.Text = Tr.T("Food Cost:") + " " + perPortionCost.ToString("C");

        if (price > 0m)
        {
            decimal fcPct = (perPortionCost / price) * 100m;
            decimal marginPct = Math.Max(0m, ((price - perPortionCost) / price) * 100m);

            foodCostPctLabel.Text = Tr.T("Food Cost %:") + " " + fcPct.ToString("0.#") + "%";
            if (fcPct <= 30m) foodCostPctLabel.ForeColor = Skin.SuccessText;
            else if (fcPct <= 40m) foodCostPctLabel.ForeColor = Skin.Warning;
            else foodCostPctLabel.ForeColor = Skin.DangerText;

            marginLabel.Text = Tr.T("Margin:") + " " + marginPct.ToString("0.#") + "%";
        }
        else
        {
            foodCostPctLabel.Text = Tr.T("Food Cost %:") + " 0%";
            marginLabel.Text = Tr.T("Margin:") + " 0%";
        }
    }

    private void SaveRecipe()
    {
        if (selectedProduct == null || string.IsNullOrWhiteSpace(selectedProduct.Name)) return;

        decimal portions = Math.Max(1m, portionsNum.Value);
        if (currentLines.Count == 0)
        {
            store.Recipes.Remove(selectedProduct.Name);
        }
        else
        {
            var normalized = currentLines
                .Select(ri => new RecipeItem(ri.Ingredient, ri.Quantity / portions, ri.Unit))
                .ToList();
            store.Recipes[selectedProduct.Name] = normalized;
        }

        store.SaveRecipes(store.Recipes);
        onRecipeChanged?.Invoke();
        statusLabel.Text = Tr.T("Recipe saved successfully!");

        int curIdx = productList.SelectedIndex;
        PopulateProducts();
        if (curIdx >= 0 && curIdx < productList.Items.Count) productList.SelectedIndex = curIdx;
    }
}

internal sealed class StockManagerForm : SettingsSubForm
{
    private readonly PosStore store;
    private readonly Action? openPurchases;
    private readonly Action? open86Board;
    private readonly Action? openRecipeEditor;
    private readonly Action? openIngredientManager;
    private readonly Panel tabsPanel = new Panel();
    private readonly Panel container = new Panel();
    private readonly List<Button> tabButtons = new List<Button>();
    private string currentTab = "overview";

    public StockManagerForm(PosStore store, Action? openPurchases = null, Action? open86Board = null, Action? openRecipeEditor = null, Action? openIngredientManager = null)
    {
        this.store = store;
        this.openPurchases = openPurchases;
        this.open86Board = open86Board;
        this.openRecipeEditor = openRecipeEditor;
        this.openIngredientManager = openIngredientManager;
        Text = Tr.T("Stock & Inventory Console");
        Breadcrumb = "Settings / Inventory / Console";
        ClientSize = new Size(980, 680);
        MinimumSize = new Size(860, 580);
        BackColor = Skin.Background;
        ForeColor = Skin.Text;
        Font = new Font("Segoe UI", 10f);
        FormBorderStyle = FormBorderStyle.Sizable;

        // Tabs panel below app bar
        tabsPanel.Location = new Point(24, 16);
        tabsPanel.Size = new Size(932, 44);
        tabsPanel.BackColor = Skin.Background;

        string[] tabs = new[] { "Overview", "Ingredients", "Products", "Recipes", "Movements" };
        int tx = 0;
        foreach (var t in tabs)
        {
            string key = t.ToLowerInvariant();
            Button b = new Button
            {
                Text = Tr.T(t),
                Tag = key,
                Location = new Point(tx, 4),
                Size = new Size(110, 34),
                FlatStyle = FlatStyle.Flat,
                Font = new Font("Segoe UI Semibold", 9.5f),
                Cursor = Cursors.Hand
            };
            b.FlatAppearance.BorderSize = 0;
            ApplyPillRegion(b, 16);
            b.Click += (s, e) => SwitchTab(key);
            tabButtons.Add(b);
            tabsPanel.Controls.Add(b);
            tx += 118;
        }

        container.Location = new Point(24, 68);
        container.Size = new Size(932, 530);
        container.BackColor = Skin.Background;

        Controls.AddRange(new Control[] { tabsPanel, container });

        doneBtn.Click += (s, e) => Close();
        SwitchTab("overview");
        ShiftBodyDown(72);
    }

    private void SwitchTab(string tabKey)
    {
        currentTab = tabKey;
        foreach (var b in tabButtons)
        {
            bool active = (b.Tag?.ToString() == tabKey);
            b.BackColor = active ? Skin.Accent : Skin.SidebarItem;
            b.ForeColor = active ? Skin.OnAccent : Skin.Text;
        }

        container.Controls.Clear();
        switch (tabKey)
        {
            case "overview":
                BuildOverviewTab();
                break;
            case "ingredients":
                BuildIngredientsTab();
                break;
            case "products":
                BuildProductsTab();
                break;
            case "recipes":
                BuildRecipesTab();
                break;
            case "movements":
                BuildMovementsTab();
                break;
        }
    }

    private void BuildOverviewTab()
    {
        Panel p = new Panel { Dock = DockStyle.Fill, BackColor = Skin.Background };

        // 4 KPI cards
        int lowCount = StockEngine.Low(store).Count;
        int auto86Count = store.Auto86.Count;
        decimal totalValue = store.Ingredients.Sum(i => i.Stock * i.Cost);
        int movementsCount = store.StockMovements.Count;

        int cw = 216;
        Panel kpi1 = MakeKpiCard(Tr.T("LOW STOCK ITEMS"), lowCount.ToString(), lowCount > 0 ? Skin.Warning : Skin.Text, 0, cw);
        Panel kpi2 = MakeKpiCard(Tr.T("86'D PRODUCTS"), auto86Count.ToString(), auto86Count > 0 ? Skin.DangerText : Skin.Text, 230, cw);
        Panel kpi3 = MakeKpiCard(Tr.T("TOTAL INVENTORY VALUE"), totalValue.ToString("C"), Skin.Accent, 460, cw);
        Panel kpi4 = MakeKpiCard(Tr.T("TOTAL MOVEMENTS"), movementsCount.ToString(), Skin.Text, 690, cw);

        p.Controls.AddRange(new Control[] { kpi1, kpi2, kpi3, kpi4 });

        // Low stock items table header
        Label lblLow = new Label
        {
            Text = Tr.T("Items at or below reorder threshold"),
            Location = new Point(0, 100),
            AutoSize = true,
            Font = new Font("Segoe UI Semibold", 12f),
            ForeColor = Skin.Text
        };
        p.Controls.Add(lblLow);

        ListView lowList = new ListView
        {
            Location = new Point(0, 130),
            Size = new Size(680, 390),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            View = View.Details,
            FullRowSelect = true,
            BorderStyle = BorderStyle.None
        };
        lowList.Columns.Add(Tr.T("Item / Ingredient"), 200);
        lowList.Columns.Add(Tr.T("On Hand"), 90);
        lowList.Columns.Add(Tr.T("Min Stock"), 90);
        lowList.Columns.Add(Tr.T("Unit"), 70);
        lowList.Columns.Add(Tr.T("Used By / Kind"), 210);

        var alerts = StockEngine.Low(store);
        foreach (var a in alerts)
        {
            var lvi = new ListViewItem(new[]
            {
                a.Ingredient,
                a.Remaining.ToString("0.##"),
                a.MinStock.ToString("0.##"),
                store.Ingredients.FirstOrDefault(i => i.Name == a.Ingredient)?.Unit ?? "pcs",
                a.ProductName
            });
            lvi.ForeColor = Skin.Warning;
            lowList.Items.Add(lvi);
        }
        if (alerts.Count == 0)
        {
            var lvi = new ListViewItem(new[] { Tr.T("All inventory items are well-stocked!"), "", "", "", "" });
            lvi.ForeColor = Skin.SuccessText;
            lowList.Items.Add(lvi);
        }
        p.Controls.Add(lowList);

        // Right side quick action buttons panel
