        {
            Location = new Point(700, 130),
            Size = new Size(226, 390),
            BackColor = Skin.Panel,
            Padding = new Padding(14)
        };

        Label lblAct = new Label
        {
            Text = Tr.T("Quick Actions"),
            Location = new Point(14, 14),
            AutoSize = true,
            Font = new Font("Segoe UI Semibold", 11f),
            ForeColor = Skin.Text
        };
        actions.Controls.Add(lblAct);

        int by = 48;
        Button MakeActBtn(string txt, Action act, Color bg, Color fg)
        {
            Button b = new Button
            {
                Text = Tr.T(txt),
                Location = new Point(14, by),
                Size = new Size(198, 38),
                BackColor = bg,
                ForeColor = fg,
                FlatStyle = FlatStyle.Flat,
                Font = new Font("Segoe UI Semibold", 9.5f),
                Cursor = Cursors.Hand
            };
            b.FlatAppearance.BorderSize = 0;
            b.Click += (s, e) => act();
            actions.Controls.Add(b);
            by += 48;
            return b;
        }

        MakeActBtn("+ Add ingredient", () => openIngredientManager?.Invoke(), Skin.Accent, Skin.OnAccent);
        MakeActBtn("Edit recipes →", () => openRecipeEditor?.Invoke(), Skin.SidebarItem, Skin.Text);
        MakeActBtn("86 Board →", () => open86Board?.Invoke(), Skin.SidebarItem, Skin.Text);
        MakeActBtn("Purchase orders →", () => openPurchases?.Invoke(), Skin.SidebarItem, Skin.Text);

        p.Controls.Add(actions);
        container.Controls.Add(p);
    }

