    private void BuildIngredientsTab()
    {
        Panel p = new Panel { Dock = DockStyle.Fill, BackColor = Skin.Background };

        TextBox search = new TextBox
        {
            Location = new Point(0, 0),
            Size = new Size(300, 30),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            BorderStyle = BorderStyle.FixedSingle,
            Font = new Font("Segoe UI", 10f)
        };

        ListView lv = new ListView
        {
            Location = new Point(0, 38),
            Size = new Size(740, 480),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            View = View.Details,
            FullRowSelect = true,
            BorderStyle = BorderStyle.None
        };
        lv.Columns.Add(Tr.T("Name"), 170);
        lv.Columns.Add(Tr.T("Unit"), 60);
        lv.Columns.Add(Tr.T("On Hand"), 80);
        lv.Columns.Add(Tr.T("Min Stock"), 80);
        lv.Columns.Add(Tr.T("Cost"), 80);
        lv.Columns.Add(Tr.T("Value"), 80);
        lv.Columns.Add(Tr.T("Supplier"), 110);

        void RefreshList()
        {
            lv.Items.Clear();
            string q = search.Text.Trim().ToLowerInvariant();
            var items = store.Ingredients
                .Where(i => string.IsNullOrEmpty(q) || i.Name.ToLowerInvariant().Contains(q) || i.Supplier.ToLowerInvariant().Contains(q))
                .ToList();
            foreach (var ing in items)
            {
                decimal val = ing.Stock * ing.Cost;
                var lvi = new ListViewItem(new[]
                {
                    ing.Name,
                    ing.Unit,
                    ing.Stock.ToString("0.##"),
                    ing.MinStock.ToString("0.##"),
                    ing.Cost.ToString("C"),
                    val.ToString("C"),
                    ing.Supplier
                });
                if (ing.MinStock > 0m && ing.Stock <= ing.MinStock) lvi.ForeColor = Skin.Warning;
                lv.Items.Add(lvi);
            }
        }

        search.TextChanged += (s, e) => RefreshList();
        RefreshList();

        Panel side = new Panel
        {
            Location = new Point(756, 0),
            Size = new Size(176, 518),
            BackColor = Skin.Panel,
            Padding = new Padding(12)
        };

        Button btnManage = new Button
        {
            Text = Tr.T("Manage Catalog →"),
            Location = new Point(12, 14),
            Size = new Size(152, 38),
            BackColor = Skin.Accent,
            ForeColor = Skin.OnAccent,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI Semibold", 9.5f),
            Cursor = Cursors.Hand
        };
        btnManage.FlatAppearance.BorderSize = 0;
        btnManage.Click += (s, e) =>
        {
            openIngredientManager?.Invoke();
            RefreshList();
        };
        side.Controls.Add(btnManage);

        p.Controls.AddRange(new Control[] { search, lv, side });
        container.Controls.Add(p);
    }

    private void BuildProductsTab()
    {
        Panel p = new Panel { Dock = DockStyle.Fill, BackColor = Skin.Background };

        ListView lv = new ListView
        {
            Location = new Point(0, 0),
            Size = new Size(932, 520),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            View = View.Details,
            FullRowSelect = true,
            BorderStyle = BorderStyle.None
        };
        lv.Columns.Add(Tr.T("Product"), 220);
        lv.Columns.Add(Tr.T("Category"), 120);
        lv.Columns.Add(Tr.T("Price"), 90);
        lv.Columns.Add(Tr.T("Stock Tracking"), 150);
        lv.Columns.Add(Tr.T("On Hand"), 90);
        lv.Columns.Add(Tr.T("Min Stock"), 90);
        lv.Columns.Add(Tr.T("Unit"), 70);

        foreach (var prod in store.Products)
        {
            bool hasRec = StockEngine.HasRecipe(store, prod.Name);
            var ps = store.ProductStocks.FirstOrDefault(s => string.Equals(s.Product, prod.Name, StringComparison.OrdinalIgnoreCase));

            string mode = hasRec ? Tr.T("Recipe") : ((ps?.Tracked ?? false) ? Tr.T("Direct quantity") : Tr.T("Untracked"));
            string onHand = hasRec ? "—" : (ps?.Stock.ToString("0.##") ?? "—");
            string min = hasRec ? "—" : (ps?.MinStock.ToString("0.##") ?? "—");
            string unit = hasRec ? "—" : (ps?.Unit ?? "pcs");

            var lvi = new ListViewItem(new[]
            {
                prod.Name,
                prod.Category,
                prod.Price.ToString("C"),
                mode,
                onHand,
                min,
                unit
            });
            if (hasRec) lvi.ForeColor = Skin.Accent;
            else if (ps?.Tracked ?? false)
            {
                if (ps.MinStock > 0m && ps.Stock <= ps.MinStock) lvi.ForeColor = Skin.Warning;
            }
            lv.Items.Add(lvi);
        }

        p.Controls.Add(lv);
        container.Controls.Add(p);
    }

    private void BuildRecipesTab()
    {
        Panel p = new Panel { Dock = DockStyle.Fill, BackColor = Skin.Background };

        ListView lv = new ListView
        {
            Location = new Point(0, 0),
            Size = new Size(740, 520),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            View = View.Details,
            FullRowSelect = true,
            BorderStyle = BorderStyle.None
        };
        lv.Columns.Add(Tr.T("Product"), 200);
        lv.Columns.Add(Tr.T("Ingredients"), 100);
        lv.Columns.Add(Tr.T("Food Cost"), 90);
        lv.Columns.Add(Tr.T("Selling Price"), 100);
        lv.Columns.Add(Tr.T("Food Cost %"), 100);
        lv.Columns.Add(Tr.T("Margin %"), 90);

        foreach (var (productName, items) in store.Recipes)
        {
            var prod = store.Products.FirstOrDefault(pr => string.Equals(pr.Name, productName, StringComparison.OrdinalIgnoreCase));
            decimal cost = StockEngine.RecipeCost(store, productName);
            decimal price = prod?.Price ?? 0m;
            decimal fcPct = price > 0m ? (cost / price * 100m) : 0m;
            decimal margin = price > 0m ? Math.Max(0m, (price - cost) / price * 100m) : 0m;

            var lvi = new ListViewItem(new[]
            {
                productName,
                items.Count.ToString(),
                cost.ToString("C"),
                price.ToString("C"),
                fcPct.ToString("0.#") + "%",
                margin.ToString("0.#") + "%"
            });
            if (fcPct > 40m) lvi.ForeColor = Skin.DangerText;
            else if (fcPct > 30m) lvi.ForeColor = Skin.Warning;
            else lvi.ForeColor = Skin.SuccessText;
            lv.Items.Add(lvi);
        }

        Panel side = new Panel
        {
            Location = new Point(756, 0),
            Size = new Size(176, 518),
            BackColor = Skin.Panel,
            Padding = new Padding(12)
        };

        Button btnEdit = new Button
        {
            Text = Tr.T("Recipe Editor →"),
            Location = new Point(12, 14),
            Size = new Size(152, 38),
            BackColor = Skin.Accent,
            ForeColor = Skin.OnAccent,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI Semibold", 9.5f),
            Cursor = Cursors.Hand
        };
        btnEdit.FlatAppearance.BorderSize = 0;
        btnEdit.Click += (s, e) => openRecipeEditor?.Invoke();
        side.Controls.Add(btnEdit);

        p.Controls.AddRange(new Control[] { lv, side });
        container.Controls.Add(p);
    }

    private void BuildMovementsTab()
    {
        Panel p = new Panel { Dock = DockStyle.Fill, BackColor = Skin.Background };

        Label lblFilter = new Label { Text = Tr.T("Filter by type:"), Location = new Point(0, 8), AutoSize = true, Font = new Font("Segoe UI Semibold", 9f), ForeColor = Skin.TextDim };
        ComboBox typeCombo = new ComboBox
        {
            Location = new Point(100, 4),
            Size = new Size(140, 26),
            DropDownStyle = ComboBoxStyle.DropDownList,
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text
        };
        typeCombo.Items.AddRange(new object[] { "All", "sale", "refund", "adjust", "waste", "transfer", "po" });
        typeCombo.SelectedIndex = 0;

        TextBox search = new TextBox
        {
            Location = new Point(260, 4),
            Size = new Size(220, 26),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            BorderStyle = BorderStyle.FixedSingle,
            Font = new Font("Segoe UI", 9.5f)
        };

        ListView lv = new ListView
        {
            Location = new Point(0, 38),
            Size = new Size(932, 482),
            BackColor = Skin.PanelLight,
            ForeColor = Skin.Text,
            View = View.Details,
            FullRowSelect = true,
            BorderStyle = BorderStyle.None
        };
        lv.Columns.Add(Tr.T("Date & Time"), 140);
        lv.Columns.Add(Tr.T("Type"), 70);
        lv.Columns.Add(Tr.T("Item"), 180);
        lv.Columns.Add(Tr.T("Delta"), 90);
        lv.Columns.Add(Tr.T("Balance"), 90);
        lv.Columns.Add(Tr.T("Ref"), 120);
        lv.Columns.Add(Tr.T("Operator"), 110);

        void RefreshMovements()
        {
            lv.Items.Clear();
            string selectedType = typeCombo.SelectedItem?.ToString() ?? "All";
            string q = search.Text.Trim().ToLowerInvariant();

            var list = store.StockMovements.AsEnumerable().Reverse();
            if (selectedType != "All")
            {
                list = list.Where(m => string.Equals(m.Kind, selectedType, StringComparison.OrdinalIgnoreCase));
            }
            if (!string.IsNullOrEmpty(q))
            {
                list = list.Where(m => m.Item.ToLowerInvariant().Contains(q) || m.Ref.ToLowerInvariant().Contains(q));
            }

            foreach (var m in list.Take(500))
            {
                string deltaStr = (m.Delta > 0 ? "+" : "") + m.Delta.ToString("0.##");
                var lvi = new ListViewItem(new[]
                {
                    m.When.ToString("dd/MM/yyyy HH:mm"),
                    m.Kind,
                    m.Item,
                    deltaStr,
                    m.Balance.ToString("0.##"),
                    m.Ref,
                    m.By
                });
                if (m.Kind == "refund" || m.Delta > 0) lvi.ForeColor = Skin.SuccessText;
                else if (m.Kind == "waste" || m.Kind == "sale") lvi.ForeColor = Skin.Text;
                else if (m.Kind == "adjust") lvi.ForeColor = Skin.Warning;
                lv.Items.Add(lvi);
            }
        }

        typeCombo.SelectedIndexChanged += (s, e) => RefreshMovements();
        search.TextChanged += (s, e) => RefreshMovements();
        RefreshMovements();

        p.Controls.AddRange(new Control[] { lblFilter, typeCombo, search, lv });
        container.Controls.Add(p);
    }
}


