		private Label FieldLabel(string text, int x, int y)
		{
			return new Label
			{
				Text = Tr.T(text),
				AutoSize = true,
				Location = new Point(x, y)
			};
		}

		private static void StyleField(Control control, Color background)
		{
			control.BackColor = background;
			control.ForeColor = Skin.Text;
			if (control is TextBox textBox)
			{
				textBox.BorderStyle = BorderStyle.FixedSingle;
			}
		}

		private Button CatalogButton(string text, int x, int y, int width, Color background)
		{
			Button button = new Button();
			button.Text = Tr.T(text);
			button.Location = new Point(x, y);
			button.Size = new Size(width, 38);
			button.BackColor = background;
			button.ForeColor = Skin.Text;
			button.FlatStyle = FlatStyle.Flat;
			button.Cursor = Cursors.Hand;
			button.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(button);
			return button;
		}

		private void LoadProduct()
		{
			if (selectedIndex >= 0 && selectedIndex < products.Count && selectedIndex != this.list.SelectedIndex)
			{
				List<Product> list = products;
				int index = selectedIndex;
				Product product = products[selectedIndex]._003CClone_003E_0024();
				product.Name = name.Text.Trim();
				product.Category = category.SelectedItem?.ToString() ?? "Popular";
				product.Price = price.Value;
				product.Color = color.Text.Trim();
				product.ImagePath = imagePath.Text.Trim();
				product.Barcode = barcode.Text.Trim();
				product.Weighted = weighted.Checked;
				list[index] = product;
				this.list.Items[selectedIndex] = products[selectedIndex].Name;
			}
			if (this.list.SelectedIndex >= 0 && this.list.SelectedIndex < products.Count)
			{
				selectedIndex = this.list.SelectedIndex;
				Product product2 = products[selectedIndex];
				name.Text = product2.Name;
				category.SelectedItem = product2.Category;
				price.Value = product2.Price;
				color.Text = product2.Color;
				imagePath.Text = product2.ImagePath;
				barcode.Text = product2.Barcode;
				weighted.Checked = product2.Weighted;
				if (store != null)
				{
					if (StockEngine.HasRecipe(store, product2.Name))
					{
						recipeCard.Visible = true;
						stockCard.Visible = false;
						int count = store.Recipes[product2.Name].Count;
						decimal cost = StockEngine.RecipeCost(store, product2.Name);
						decimal pct = product2.Price > 0m ? (cost / product2.Price * 100m) : 0m;
						recipeInfo.Text = $"{count} ing. · {cost:C} ({pct:0.#}%)";
					}
					else
					{
						recipeCard.Visible = false;
						stockCard.Visible = true;
						var ps = store.ProductStocks.FirstOrDefault(s => string.Equals(s.Product, product2.Name, StringComparison.OrdinalIgnoreCase));
						trackStockChk.Checked = ps?.Tracked ?? false;
						stockQty.Value = ps?.Stock ?? 0m;
						minStockQty.Value = ps?.MinStock ?? 0m;
						stockUnitCombo.SelectedItem = ps?.Unit ?? "pcs";
						if (stockUnitCombo.SelectedIndex < 0 && stockUnitCombo.Items.Count > 0) stockUnitCombo.SelectedIndex = 0;
					}
				}
				else
				{
					recipeCard.Visible = false;
					stockCard.Visible = false;
				}
			}
		}

		private void AddProduct()
		{
			products.Add(new Product("New product", "Popular", 0m, "#70C1B3"));
			list.Items.Add("New product");
			list.SelectedIndex = products.Count - 1;
		}

		private void DeleteProduct()
		{
			if (selectedIndex >= 0 && products.Count > 1)
			{
				string deletedName = products[selectedIndex].Name;
				if (store != null)
				{
					if (store.Recipes.Remove(deletedName))
					{
						store.SaveRecipes(store.Recipes);
					}
					int removed = store.ProductStocks.RemoveAll(p => string.Equals(p.Product, deletedName, StringComparison.OrdinalIgnoreCase));
					if (removed > 0)
					{
						store.SaveProductStocks(store.ProductStocks);
					}
				}
				products.RemoveAt(selectedIndex);
				list.Items.RemoveAt(selectedIndex);
				list.SelectedIndex = Math.Min(selectedIndex, products.Count - 1);
			}
		}

		private void SaveProduct()
		{
			if (selectedIndex >= 0 && selectedIndex < products.Count)
			{
				string oldName = products[selectedIndex].Name;
				string newName = name.Text.Trim();
				if (store != null)
				{
					if (!string.Equals(oldName, newName, StringComparison.OrdinalIgnoreCase))
					{
						if (store.Recipes.TryGetValue(oldName, out var recItems))
						{
							store.Recipes.Remove(oldName);
							store.Recipes[newName] = recItems;
							store.SaveRecipes(store.Recipes);
						}
						var psOld = store.ProductStocks.FirstOrDefault(p => string.Equals(p.Product, oldName, StringComparison.OrdinalIgnoreCase));
						if (psOld != null)
						{
							psOld.Product = newName;
							store.SaveProductStocks(store.ProductStocks);
						}
					}
					if (stockCard.Visible)
					{
						var ps = store.ProductStocks.FirstOrDefault(p => string.Equals(p.Product, newName, StringComparison.OrdinalIgnoreCase));
						if (trackStockChk.Checked)
						{
							if (ps == null)
							{
								ps = new ProductStock(newName, stockQty.Value, minStockQty.Value, stockUnitCombo.SelectedItem?.ToString() ?? "pcs", price.Value, true);
								store.ProductStocks.Add(ps);
							}
							else
							{
								ps.Stock = stockQty.Value;
								ps.MinStock = minStockQty.Value;
								ps.Unit = stockUnitCombo.SelectedItem?.ToString() ?? "pcs";
								ps.Tracked = true;
							}
						}
						else if (ps != null)
						{
							ps.Tracked = false;
						}
						store.SaveProductStocks(store.ProductStocks);
					}
				}
				List<Product> list = products;
				int index = selectedIndex;
				Product product = products[selectedIndex]._003CClone_003E_0024();
				product.Name = name.Text.Trim();
				product.Category = category.SelectedItem?.ToString() ?? "Popular";
				product.Price = price.Value;
				product.Color = color.Text.Trim();
				product.ImagePath = imagePath.Text.Trim();
				product.Barcode = barcode.Text.Trim();
				product.Weighted = weighted.Checked;
				list[index] = product;
				this.list.Items[selectedIndex] = products[selectedIndex].Name;
			}
			save(products);
		}

		private Product? CurrentProduct()
		{
			if (selectedIndex < 0 || selectedIndex >= products.Count)
			{
				return null;
			}
			List<Product> list = products;
			int index = selectedIndex;
			Product product = products[selectedIndex]._003CClone_003E_0024();
			product.Name = name.Text.Trim();
			product.Category = category.SelectedItem?.ToString() ?? "Popular";
			product.Price = price.Value;
			product.Color = color.Text.Trim();
			product.ImagePath = imagePath.Text.Trim();
			product.Barcode = barcode.Text.Trim();
			product.Weighted = weighted.Checked;
			list[index] = product;
			this.list.Items[selectedIndex] = products[selectedIndex].Name;
			return products[selectedIndex];
		}

