		private void ImportCsv()
		{
			using OpenFileDialog openFileDialog = new OpenFileDialog
			{
				Filter = "CSV files|*.csv|All files|*.*"
			};
			if (openFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			try
			{
				string[] array = File.ReadAllLines(openFileDialog.FileName);
				char sep = ((array.Length != 0 && array[0].Count((char c) => c == ';') > array[0].Count((char c) => c == ',')) ? ';' : ',');
				int num = 0;
				int num2 = 0;
				int num3 = 0;
				foreach (string item in array.Skip(1))
				{
					if (string.IsNullOrWhiteSpace(item))
					{
						continue;
					}
					string[] array2 = SplitCsv(item, sep);
					if (array2.Length < 3)
					{
						num3++;
						continue;
					}
					if (!decimal.TryParse(array2[2], NumberStyles.Any, CultureInfo.InvariantCulture, out var result) && !decimal.TryParse(array2[2], out result))
					{
						num3++;
						continue;
					}
					string pname = array2[0].Trim();
					if (pname.Length != 0)
					{
						string text = ((array2.Length > 1 && array2[1].Trim().Length > 0) ? array2[1].Trim() : "Popular");
						string text2 = ((array2.Length > 3 && array2[3].Trim().Length > 0) ? array2[3].Trim() : "#70C1B3");
						string family = ((array2.Length > 4 && array2[4].Trim().Length > 0) ? array2[4].Trim() : "General");
						string text3 = ((array2.Length > 5) ? array2[5].Trim() : "");
						bool flag = array2.Length > 6 && array2[6].Trim().Equals("weighted", StringComparison.OrdinalIgnoreCase);
						int num4 = products.FindIndex((Product x) => string.Equals(x.Name, pname, StringComparison.OrdinalIgnoreCase));
						if (num4 >= 0)
						{
							List<Product> list = products;
							Product product = products[num4]._003CClone_003E_0024();
							product.Category = text;
							product.Price = result;
							product.Color = text2;
							product.Family = family;
							product.Barcode = text3;
							product.Weighted = flag;
							list[num4] = product;
							num2++;
						}
						else
						{
							products.Add(new Product(pname, text, result, text2, family, "", "", text3, flag));
							num++;
						}
					}
				}
				save(products);
				this.list.Items.Clear();
				foreach (Product product2 in products)
				{
					this.list.Items.Add(product2.Name);
				}
				if (products.Count > 0)
				{
					this.list.SelectedIndex = 0;
				}
				MessageBox.Show(string.Format("{0}{1} {2} {3} {4} {5} {6}", Tr.T("CSV imported:\n"), num, Tr.T("new product(s),"), num2, Tr.T("updated,"), num3, Tr.T("skipped.")), Tr.T("Import CSV"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
			}
			catch (Exception ex)
			{
				MessageBox.Show(Tr.T("Import failed: ") + ex.Message, Tr.T("Import CSV"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
			}
		}

		private static string[] SplitCsv(string line, char sep)
		{
			List<string> list = new List<string>();
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = false;
			foreach (char c in line)
			{
				if (c == '"')
				{
					flag = !flag;
				}
				else if (c == sep && !flag)
				{
					list.Add(stringBuilder.ToString());
					stringBuilder.Clear();
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			list.Add(stringBuilder.ToString());
			return list.ToArray();
		}

		private void ExportCsv()
		{
			using SaveFileDialog saveFileDialog = new SaveFileDialog
			{
				Filter = "CSV files|*.csv",
				FileName = $"products-{DateTime.Now:yyyyMMdd}.csv"
			};
			if (saveFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("Name,Category,Price,Color,Family,Barcode,Weighted");
			foreach (Product product in products)
			{
				stringBuilder.AppendLine(string.Join(",", "\"" + product.Name.Replace("\"", "\"\"") + "\"", product.Category, product.Price.ToString(CultureInfo.InvariantCulture), product.Color, product.Family, product.Barcode, product.Weighted ? "weighted" : ""));
			}
			File.WriteAllText(saveFileDialog.FileName, stringBuilder.ToString());
			MessageBox.Show(string.Format("{0} {1} {2}{3}", Tr.T("Exported"), products.Count, Tr.T("product(s) to:\n"), saveFileDialog.FileName), Tr.T("Export CSV"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
		}

		private void PrintLabels()
		{
			Product product = CurrentProduct();
			if (product == null)
			{
				MessageBox.Show(Tr.T("Select a product first."), Tr.T("Labels"), MessageBoxButtons.OK, MessageBoxIcon.Asterisk);
				return;
			}
			if (string.IsNullOrWhiteSpace(product.Barcode) || !Code39.CanEncode(product.Barcode))
			{
				MessageBox.Show(Tr.T("This product has no valid barcode for printing.\nAllowed: 0-9, A-Z, '-', '.' and spaces.\nSet it in the Barcode field first."), Tr.T("Labels"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				return;
			}
			Form qtyForm = new Form
			{
				Text = Tr.T("How many labels?"),
				Size = new Size(300, 170),
				StartPosition = FormStartPosition.CenterParent,
				BackColor = bg,
				ForeColor = Skin.Text,
				Font = new Font("Segoe UI", 10f),
				FormBorderStyle = FormBorderStyle.FixedDialog,
				MaximizeBox = false,
				MinimizeBox = false
			};
			try
			{
				NumericUpDown numericUpDown = new NumericUpDown
				{
					Location = new Point(20, 40),
					Size = new Size(100, 30),
					Minimum = 1m,
					Maximum = 500m,
					Value = 1m,
					BackColor = panelLightOf(),
					ForeColor = Skin.Text
				};
				Button button = new Button
				{
					Text = Tr.T("Print"),
					Location = new Point(20, 84),
					Size = new Size(100, 32),
					BackColor = mintC,
					ForeColor = Skin.OnAccent,
					FlatStyle = FlatStyle.Flat
				};
				button.FlatAppearance.BorderSize = 0;
				qtyForm.Controls.AddRange(new Control[3]
				{
					new Label
					{
						Text = Tr.T("Label count:"),
						AutoSize = true,
						Location = new Point(20, 14)
					},
					numericUpDown,
					button
				});
				qtyForm.AcceptButton = button;
				button.Click += (object _, EventArgs _) =>
				{
					qtyForm.DialogResult = DialogResult.OK;
				};
				if (qtyForm.ShowDialog() != DialogResult.OK)
				{
					return;
				}
				using PrintDialog printDialog = new PrintDialog
				{
					AllowSomePages = false
				};
				using PrintDocument printDocument = new PrintDocument
				{
					DocumentName = "Labels " + product.Name
				};
				int count = (int)numericUpDown.Value;
				Bitmap barcodeBmp = Code39.Render(product.Barcode);
				int done = 0;
				printDocument.PrintPage += (object _, PrintPageEventArgs e) =>
				{
					if (e.Graphics == null)
					{
						e.HasMorePages = false;
					}
					else
					{
						Graphics graphics = e.Graphics;
						int num = 20;
						int num2 = 20;
						for (int i = 0; i < 5; i++)
						{
							if (done >= count)
							{
								break;
							}
							for (int j = 0; j < 3; j++)
							{
								if (done >= count)
								{
									break;
								}
								int num3 = num + j * 310;
								int num4 = num2 + i * 170;
								if ((float)(num4 + 160) > graphics.VisibleClipBounds.Height)
								{
									break;
								}
								using (Pen pen = new Pen(Skin.TextFaint))
								{
									graphics.DrawRectangle(pen, num3, num4, 300, 160);
								}
								using (Font font = new Font("Segoe UI Semibold", 11f))
								{
									using Font font2 = new Font("Segoe UI", 10f);
									using Font font3 = new Font("Consolas", 8f);
									using SolidBrush brush = new SolidBrush(Color.Black);
									graphics.DrawString(product.Name, font, brush, num3 + 8, num4 + 6);
									graphics.DrawString(product.Price.ToString("C"), font2, brush, num3 + 8, num4 + 28);
									int num5 = Math.Min(284, 200);
									float num6 = (float)num5 / (float)barcodeBmp.Width;
									int num7 = Math.Min(60, (int)((float)barcodeBmp.Height * num6));
									graphics.DrawImage(barcodeBmp, new RectangleF(num3 + 8, num4 + 54, num5, num7));
									graphics.DrawString(product.Barcode, font3, brush, num3 + 8, num4 + 54 + num7 + 2);
								}
								done++;
							}
							if ((float)(num2 + (i + 1) * 170) > graphics.VisibleClipBounds.Height)
							{
								break;
							}
						}
						e.HasMorePages = done < count;
					}
				};
				printDialog.Document = printDocument;
				if (printDialog.ShowDialog() == DialogResult.OK)
				{
					try
					{
						printDocument.Print();
					}
					catch (Exception ex)
					{
						MessageBox.Show(Tr.T("Print failed: ") + ex.Message, Tr.T("Labels"), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
				}
				barcodeBmp.Dispose();
			}
			finally
			{
				if (qtyForm != null)
				{
					((IDisposable)qtyForm).Dispose();
				}
			}
		}

		protected override void Back()
		{
			SaveProduct();
			base.Back();
		}
	}

