				Text = Tr.T("Assign a product to a family"),
				AutoSize = true,
				Font = new Font("Segoe UI Semibold", 12f),
				Location = new Point(280, 260)
			};
			productList.Location = new Point(280, 290);
			productList.Size = new Size(220, 180);
			StyleList(productList, panelLight);
			productList.SelectedIndexChanged += (object _, EventArgs _) =>
			{
				LoadProductFamily();
			};
			foreach (Product product in products)
			{
				productList.Items.Add(product.Name);
			}
			productFamily.Location = new Point(520, 290);
			productFamily.Size = new Size(160, 30);
			productFamily.DropDownStyle = ComboBoxStyle.DropDownList;
			productFamily.BackColor = panelLight;
			productFamily.ForeColor = Skin.Text;
			RefreshFamilyChoices();
			productFamily.SelectedIndexChanged += (object _, EventArgs _) =>
			{
				AssignProductFamily();
			};
			Button button2 = FamilyButton("New family", 24, 390, 120, panelLight);
			button2.Click += (object _, EventArgs _) =>
			{
				AddFamily();
			};
			Button button3 = FamilyButton("Delete", 154, 390, 90, panelLight);
			button3.Click += (object _, EventArgs _) =>
			{
				DeleteFamily();
			};
			Button button4 = FamilyButton("Save changes", 550, 390, 130, mint);
			button4.ForeColor = Skin.OnAccent;
			button4.Click += (object _, EventArgs _) =>
			{
				SaveChanges();
			};
			Controls.AddRange(new Control[15]
			{
				label, familyList, label2, familyName, label3, familyImagePath, button, label4, familyPrinter, label5,
				productList, productFamily, button2, button3, button4
			});
			if (families.Count > 0)
			{
				familyList.SelectedIndex = 0;
			}
			doneBtn.Click += (object _, EventArgs _) =>
			{
				SaveChanges();
				DialogResult = DialogResult.OK;
				Close();
			};
			ShiftBodyDown(72);
		}

		private static void StyleList(ListBox list, Color background)
		{
			list.BackColor = background;
			list.ForeColor = Skin.Text;
			list.BorderStyle = BorderStyle.None;
		}

		private static void StyleField(TextBox field, Color background)
		{
			field.BackColor = background;
			field.ForeColor = Skin.Text;
			field.BorderStyle = BorderStyle.FixedSingle;
		}

		private Button FamilyButton(string text, int x, int y, int width, Color background)
		{
			Button button = new Button();
			button.Text = text;
			button.Location = new Point(x, y);
			button.Size = new Size(width, 38);
			button.BackColor = background;
			button.ForeColor = Skin.Text;
			button.FlatStyle = FlatStyle.Flat;
			button.Cursor = Cursors.Hand;
			button.FlatAppearance.BorderSize = 0;
			Skin.FlatStates(button);
			return button;
		}

		private void LoadFamily()
		{
			if (selectedFamily >= 0 && selectedFamily < families.Count && selectedFamily != familyList.SelectedIndex)
			{
				string text = familyPrinter.SelectedItem?.ToString();
				string printerDestination;
				if (text == "No printer")
				{
					printerDestination = "";
				}
				else
				{
					printerDestination = ((!string.IsNullOrWhiteSpace(text)) ? text : families[selectedFamily].PrinterDestination);
				}
				families[selectedFamily] = new ProductFamily(familyName.Text.Trim(), familyImagePath.Text.Trim(), printerDestination);
				familyList.Items[selectedFamily] = families[selectedFamily].Name;
			}
			if (familyList.SelectedIndex >= 0 && familyList.SelectedIndex < families.Count)
			{
				selectedFamily = familyList.SelectedIndex;
				familyName.Text = families[selectedFamily].Name;
				familyImagePath.Text = families[selectedFamily].ImagePath;
				familyPrinter.SelectedItem = (string.IsNullOrWhiteSpace(families[selectedFamily].PrinterDestination) ? "No printer" : families[selectedFamily].PrinterDestination);
			}
		}

		private void RefreshFamilyChoices()
		{
			productFamily.Items.Clear();
			foreach (ProductFamily family in families)
			{
				productFamily.Items.Add(family.Name);
			}
		}

		private void LoadProductFamily()
		{
			selectedProduct = productList.SelectedIndex;
			if (selectedProduct >= 0 && selectedProduct < products.Count)
			{
				productFamily.SelectedItem = products[selectedProduct].Family;
			}
		}

		private void AssignProductFamily()
		{
			if (selectedProduct >= 0 && productFamily.SelectedItem != null)
			{
				Product product = products[selectedProduct];
				List<Product> list = products;
				int index = selectedProduct;
				Product product2 = product._003CClone_003E_0024();
				product2.Family = productFamily.SelectedItem.ToString();
				list[index] = product2;
			}
		}

		private void AddFamily()
		{
			families.Add(new ProductFamily("New family"));
			familyList.Items.Add("New family");
			familyList.SelectedIndex = families.Count - 1;
			RefreshFamilyChoices();
		}

		private void DeleteFamily()
		{
			if (selectedFamily >= 0 && families.Count > 1)
			{
				families.RemoveAt(selectedFamily);
				familyList.Items.RemoveAt(selectedFamily);
				familyList.SelectedIndex = Math.Min(selectedFamily, families.Count - 1);
				RefreshFamilyChoices();
			}
		}

		private void SaveChanges()
		{
			if (selectedFamily >= 0)
			{
				string text = familyPrinter.SelectedItem?.ToString();
				string printerDestination;
				if (text == "No printer")
				{
					printerDestination = "";
				}
				else
				{
					printerDestination = ((!string.IsNullOrWhiteSpace(text)) ? text : families[selectedFamily].PrinterDestination);
				}
				families[selectedFamily] = new ProductFamily(familyName.Text.Trim(), familyImagePath.Text.Trim(), printerDestination);
				familyList.Items[selectedFamily] = families[selectedFamily].Name;
				RefreshFamilyChoices();
			}
			save(families, products);
		}

		protected override void Back()
		{
			SaveChanges();
			base.Back();
		}
	}

internal sealed class ProductTile : Panel
	{
		private readonly Product product;

		private Image? image;

		public bool OutOfStock;

		private bool hovering;

		private bool pressed;

		private static Color BgNormal => Skin.Panel;

		private static Color BgHover => Skin.PanelHover;

		private static Color BgPressed => Skin.PanelPressed;

		private static Color BorderNormal => Skin.Border;

		private static Color BorderHover => Skin.BorderHover;

		private static Color BorderPressed => Skin.BorderPressed;

		private int Radius => Math.Max(6, Width / 24);

		public ProductTile(Product product, int width = 220, int height = 175)
		{
			this.product = product;
			image = CatalogImageStore.LoadBitmap(product.ImagePath);
			Size = new Size(width, height);
			BackColor = BgNormal;
			Cursor = Cursors.Hand;
			Paint += Draw;
			Region region = new Region(RoundedRect(new Rectangle(0, 0, width, height), Radius));
			Region = region;
			MouseEnter += (object _, EventArgs _) =>
			{
				hovering = true;
				BackColor = BgHover;
				Invalidate();
			};
			MouseLeave += (object _, EventArgs _) =>
			{
				hovering = false;
				pressed = false;
				BackColor = BgNormal;
				Invalidate();
			};
			MouseDown += (object _, MouseEventArgs e) =>
			{
				if (e.Button == MouseButtons.Left)
				{
					pressed = true;
					BackColor = BgPressed;
					Invalidate();
				}
			};
			MouseUp += (object _, MouseEventArgs _) =>
			{
				pressed = false;
				BackColor = (hovering ? BgHover : BgNormal);
				Invalidate();
			};
		}

		private static GraphicsPath RoundedRect(Rectangle r, int radius)
		{
			int num = Math.Min(radius * 2, Math.Min(r.Width, r.Height));
			GraphicsPath graphicsPath = new GraphicsPath();
			if (num <= 0)
			{
				graphicsPath.AddRectangle(r);
				return graphicsPath;
			}
			graphicsPath.AddArc(r.X, r.Y, num, num, 180f, 90f);
			graphicsPath.AddArc(r.Right - num, r.Y, num, num, 270f, 90f);
			graphicsPath.AddArc(r.Right - num, r.Bottom - num, num, num, 0f, 90f);
			graphicsPath.AddArc(r.X, r.Bottom - num, num, num, 90f, 90f);
			graphicsPath.CloseFigure();
			return graphicsPath;
		}

		private static string Ellipsize(Graphics g, string text, Font font, float maxWidth)
		{
			if (maxWidth <= 0f)
			{
				return "";
			}
			if (g.MeasureString(text, font).Width <= maxWidth)
			{
				return text;
			}
			string text2 = text;
			while (text2.Length > 1 && g.MeasureString(text2 + "…", font).Width > maxWidth)
			{
				string text3 = text2;
				text2 = text3.Substring(0, text3.Length - 1);
			}
			return text2 + "…";
		}

		private void Draw(object? sender, PaintEventArgs e)
		{
			Graphics graphics = e.Graphics;
			graphics.SmoothingMode = SmoothingMode.AntiAlias;
			int num = Math.Max(5, Width / 30);
			float num2 = Math.Max(8f, (float)Width / 22f);
			using Font font = new Font("Segoe UI Semibold", num2);
			using Font font2 = new Font("Segoe UI Semibold", Math.Max(7f, num2 - 1f));
			using SolidBrush brush = new SolidBrush(OutOfStock ? Skin.TextFaded : Skin.Text);
			using SolidBrush brush2 = new SolidBrush(OutOfStock ? Skin.TextFaint : Skin.Accent);
			string s = product.Price.ToString("C");
			SizeF sizeF = graphics.MeasureString(s, font2);
			SizeF sizeF2 = graphics.MeasureString(product.Name, font);
			float num3 = Math.Max(sizeF.Height, sizeF2.Height);
			int num4 = num;
			int num5 = Width - 2 * num;
			float num6 = (float)(Height - num) - num3;
			int num7 = Math.Max(20, Math.Min((int)((double)Height * 0.8), (int)(num6 - (float)num4 - 4f)));
			Rectangle rectangle = new Rectangle(num, num4, num5, num7);
			using (GraphicsPath graphicsPath = RoundedRect(rectangle, Radius))
			{
				graphics.SetClip(graphicsPath);
				if (image != null)
				{
					float num8 = Math.Max((float)num5 / (float)image.Width, (float)num7 / (float)image.Height);
					if (num8 > 0f)
					{
						int num9 = Math.Max(1, Math.Min(image.Width, (int)Math.Round((float)num5 / num8)));
						int num10 = Math.Max(1, Math.Min(image.Height, (int)Math.Round((float)num7 / num8)));
						graphics.DrawImage(image, rectangle, (image.Width - num9) / 2, (image.Height - num10) / 2, num9, num10, GraphicsUnit.Pixel);
					}
				}
				else
				{
					using SolidBrush brush3 = new SolidBrush(ColorTranslator.FromHtml(product.Color));
					graphics.FillRectangle(brush3, rectangle);
				}
				graphics.ResetClip();
				using Pen pen = new Pen(Color.FromArgb(28, 255, 255, 255));
				graphics.DrawPath(pen, graphicsPath);
			}
			int num11 = rectangle.Bottom + 4;
			float num12 = (float)(Width - num) - sizeF.Width;
			string s2 = Ellipsize(maxWidth: Math.Max(20f, num12 - (float)num - 8f), g: graphics, text: product.Name, font: font);
			float num13 = (float)num11 + (num3 - sizeF2.Height) / 2f;
			float num14 = (float)num11 + (num3 - sizeF.Height) / 2f;
			graphics.DrawString(s2, font, brush, num, num13);
			graphics.DrawString(s, font2, brush2, num12, num14);
			if (OutOfStock)
			{
				SizeF sizeF3 = graphics.MeasureString(s2, font);
				using Pen pen2 = new Pen(Skin.DangerText, 2f);
				graphics.DrawLine(pen2, num, num13 + sizeF3.Height / 2f, (float)num + sizeF3.Width, num13 + sizeF3.Height / 2f);
				using Font font3 = new Font("Segoe UI Semibold", Math.Max(9f, num2));
				SizeF sizeF4 = graphics.MeasureString("86", font3);
				using SolidBrush brush4 = new SolidBrush(Skin.Danger);
				RectangleF rect = new RectangleF((float)(Width - num) - sizeF4.Width - 8f, num4 + 3, sizeF4.Width + 8f, sizeF4.Height + 2f);
				graphics.FillRectangle(brush4, rect);
				graphics.DrawString("86", font3, Brushes.White, rect.X + 4f, rect.Y + 1f);
				return;
			}
			int num15 = Math.Max(10, Width / 18);
			int num16 = Width - num - num15 - 3;
			int num17 = num4 + num15 + 3;
			using (SolidBrush brush5 = new SolidBrush(Color.FromArgb(210, Skin.Accent)))
			{
				graphics.FillEllipse(brush5, num16 - num15, num17 - num15, num15 * 2, num15 * 2);
			}
			using Font font4 = new Font("Segoe UI Semibold", (float)num15 * 1.15f);
			using SolidBrush brush6 = new SolidBrush(Skin.OnAccent);
			SizeF sizeF5 = graphics.MeasureString("+", font4);
			graphics.DrawString("+", font4, brush6, (float)num16 - sizeF5.Width / 2f, (float)num17 - sizeF5.Height / 2f);
		}

		protected override void OnPaintBackground(PaintEventArgs e)
		{
			if (!Skin.IsHigh)
			{
				base.OnPaintBackground(e);
			}
			else
			{
				Skin.FillSurface(e.Graphics, ClientRectangle, BackColor, Radius);
			}
		}

		protected override void OnPaint(PaintEventArgs e)
		{
			base.OnPaint(e);
			Color color;
			if (pressed)
			{
				color = BorderPressed;
			}
			else
			{
				color = (hovering ? BorderHover : BorderNormal);
			}
			using Pen pen = new Pen(color);
			using GraphicsPath path = RoundedRect(new Rectangle(0, 0, Width - 1, Height - 1), Radius);
			e.Graphics.DrawPath(pen, path);
			if (Skin.IsHigh)
			{
				Skin.CardDepth(e.Graphics, ClientRectangle, Radius);
			}
		}
	}

internal sealed class QrOrderServer : IDisposable
	{
		private readonly Func<string, string, string, string?> handle;

		private TcpListener? listener;

		private Thread? thread;

		private volatile bool running;

		public int Port { get; }

		public QrOrderServer(int port, Func<string, string, string, string?> handle)
		{
			Port = port;
			this.handle = handle;
		}

		public void Start()
		{
			if (!running)
			{
				listener = new TcpListener(IPAddress.Any, Port);
				try
				{
					listener.Server.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, true);
				}
				catch { }
				listener.Start();
				running = true;
				thread = new Thread(ListenLoop)
				{
					IsBackground = true
				};
				thread.Start();
			}
		}

		private void ListenLoop()
		{
			while (running)
			{
				TcpClient tcpClient;
				try
				{
					tcpClient = listener.AcceptTcpClient();
				}
				catch
				{
					break;
				}
				TcpClient captured = tcpClient;
				Task.Run(() =>
				{
					HandleClient(captured);
				});
			}
		}

		private void HandleClient(TcpClient client)
		{
			using (client)
			{
				try
				{
					client.ReceiveTimeout = 60000;
					client.SendTimeout = 60000;
					NetworkStream stream = client.GetStream();
					stream.ReadTimeout = 60000;
					(string, string, string)? tuple = ReadRequest(stream);
					if (tuple.HasValue)
					{
						string s = handle(tuple.Value.Item1, tuple.Value.Item2, tuple.Value.Item3) ?? "HTTP/1.1 503 Service Unavailable\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
						byte[] bytes = Encoding.UTF8.GetBytes(s);
						stream.Write(bytes, 0, bytes.Length);
					}
				}
				catch
				{
				}
			}
		}

		private static (string Method, string Path, string Body)? ReadRequest(NetworkStream stream)
		{
			byte[] array = new byte[8192];
			MemoryStream memoryStream = new MemoryStream();
			int num = -1;
			while (true)
			{
				int num2 = stream.Read(array, 0, array.Length);
				if (num2 <= 0)
				{
					return null;
				}
				memoryStream.Write(array, 0, num2);
				num = IndexOfHeaderEnd(memoryStream.ToArray());
				if (num >= 0)
				{
					break;
				}
				if (memoryStream.Length > 131072)
				{
					return null;
				}
			}
			byte[] array2 = memoryStream.ToArray();
			string[] array3 = Encoding.UTF8.GetString(array2, 0, num).Split(new string[1] { "\r\n" }, StringSplitOptions.None);
			string[] array4 = array3[0].Split(new char[1] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
			if (array4.Length < 2)
			{
				return null;
			}
			string item = array4[0];
			string item2 = array4[1];
			int result = 0;
			for (int i = 1; i < array3.Length; i++)
			{
				int num3 = array3[i].IndexOf(':');
				if (num3 > 0 && array3[i].Substring(0, num3).Trim().Equals("Content-Length", StringComparison.OrdinalIgnoreCase))
				{
					int.TryParse(array3[i].Substring(num3 + 1).Trim(), out result);
				}
			}
			List<byte> list = new List<byte>();
			for (int j = num + 4; j < array2.Length; j++)
			{
				if (list.Count >= result)
				{
					break;
				}
				list.Add(array2[j]);
			}
			while (list.Count < result)
			{
				int num4 = stream.Read(array, 0, Math.Min(array.Length, result - list.Count));
				if (num4 <= 0)
				{
					break;
				}
				for (int k = 0; k < num4; k++)
				{
					list.Add(array[k]);
				}
			}
			return (item, item2, Encoding.UTF8.GetString(list.ToArray()));
		}

		private static int IndexOfHeaderEnd(byte[] arr)
		{
			for (int i = 0; i + 3 < arr.Length; i++)
			{
				if (arr[i] == 13 && arr[i + 1] == 10 && arr[i + 2] == 13 && arr[i + 3] == 10)
				{
					return i;
				}
			}
			return -1;
		}

		public void Stop()
		{
			running = false;
			try
			{
				listener?.Stop();
			}
			catch
			{
			}
			listener = null;
			thread = null;
		}

		public void Dispose()
		{
			Stop();
		}
	}

